-- Auto-generated by scripts/stoberscript/refresh_faction_bio_backstory_subset.py
BEGIN;
WITH target_factions(faction) AS (
    VALUES
        ('Anti-Slavers'),
        ('Band of Bones'),
        ('Berserkers'),
        ('Blackshifters'),
        ('Bloodraiders'),
        ('Cannibal Hunters'),
        ('Catun'),
        ('Clownsteaders'),
        ('Crab Raiders'),
        ('Deadcat'),
        ('Dust Bandits'),
        ('Empire Peasants'),
        ('Flotsam Ninjas'),
        ('Grass Pirates'),
        ('Grayflayers'),
        ('Holy Nation Outlaws'),
        ('Inaba Ronin'),
        ('Kral''s Chosen'),
        ('Machinists'),
        ('Manhunters'),
        ('Mercenary Guild'),
        ('Messenger'),
        ('Missionaries'),
        ('Mongrel'),
        ('Nomadic Bandits'),
        ('Nomads'),
        ('Preacher Cult'),
        ('Reavers'),
        ('Rebel Farmers'),
        ('Red Sabres'),
        ('Sand Ninjas'),
        ('Second Empire Exile'),
        ('Shek Kingdom'),
        ('Shinobi Thieves'),
        ('Shrieking Bandits'),
        ('Skeleton Bandits'),
        ('Skeleton Legion'),
        ('Skin Bandits'),
        ('South Exiles'),
        ('Southern Hive'),
        ('Starving Bandits'),
        ('Stone Rats'),
        ('Swamp Ninjas'),
        ('Swampers'),
        ('Tech Hunters'),
        ('The Gorrillo Bandits'),
