DELETE FROM bio_random
WHERE LOWER(type) = 'backstory'
  AND COALESCE(name, '') = ''
  AND COALESCE(race, '') = ''
  AND LOWER(COALESCE(faction, '')) IN (SELECT LOWER(faction) FROM target_factions);

WITH source_rows(faction, description, gender) AS (
    VALUES
        ('Anti-Slavers', 'Born into a Holy Nation mining camp, they spent twelve years hauling ore until a collapse buried their overseers. They crawled out through the rubble and never stopped running, eventually finding others who shared their hatred for the chain.', ''),
        ('Anti-Slavers', 'A former trader who moved goods between cities and saw the slave markets firsthand, watching families torn apart for coin. The math never sat right in their head, and one night they abandoned their caravan to take up arms against the flesh trade.', ''),
        ('Anti-Slavers', 'Rescued from a Reaver slave ship by an Anti-Slaver raid, they had nowhere to go once the fighting ended. They picked up a fallen sword and asked to stay, deciding that saving others was the only way to repay being saved themselves.', ''),
        ('Anti-Slavers', 'A Shek exile who lost their clan to a Holy Nation crusade and was dragged south in iron collars alongside the survivors. Freedom came at the cost of everything they once knew, and now they fight so no other clan endures the same fate.', ''),
        ('Anti-Slavers', 'They grew up in a border village where slave catchers prowled the roads and people vanished without warning. When the Anti-Slavers passed through recruiting, they left their home behind without a second thought, knowing staying silent meant staying complicit.', ''),
        ('Anti-Slavers', 'Once a low-level enforcer for a slave syndicate, they collected debts and broke limbs until a child''s screams broke something inside them. They walked away that same night, carrying guilt like a stone, and have spent years trying to balance the scales.', ''),
        ('Anti-Slavers', 'A desert wanderer who stumbled across a dying escaped slave in the wastes and carried them three days to reach an Anti-Slaver outpost. The effort changed them, turning aimless survival into purpose, and they swore themselves to the cause before the rescued slave even regained consciousness.', ''),
        ('Anti-Slavers', 'Their mother was taken by United City bounty hunters when they were still young enough to barely remember her face. They spent adulthood learning to track and fight, searching for any organization that targeted the systems that stole her away.', ''),
        ('Anti-Slavers', 'A former Holy Nation farmer who watched their neighbor dragged away for owning a skeleton, unable to speak up without risking the same fate. The silence gnawed at them until they fled north, joining the only group willing to burn the system down.', ''),
        ('Anti-Slavers', 'Mutilated by a slaver''s brand that still scars their shoulder, they carry the mark as both wound and oath. Every raid against a slave camp is a small repayment for the years they spent under another person''s ownership.', ''),
        ('Anti-Slavers', 'Spent five years in a Holy Nation labor camp before a rainstorm allowed a desperate escape through the mud. Survived on river rats and stolen grain until stumbling across an Anti-Slaver patrol near the border. Now carries a deep hatred for the paladins and a scar across the back that reminds of the whip every morning.', ''),
        ('Anti-Slavers', 'Was a guard for the Traders Guild before being ordered to lock children in a transport cage. Could not stomach the crying that night and opened the door instead, knowing it meant a death mark. Fled south with nothing but a rusty blade and the clothes on their back, finding purpose with the only people who would take them.', ''),
        ('Anti-Slavers', 'Lost a sibling to a slaver raid on their farmstead in the borderlands. Tracked the traders for weeks but arrived too late, finding only a shallow grave by the road. Swore an oath on that dirt to spend every remaining breath making sure no other family endures the same loss.', ''),
        ('Anti-Slavers', 'Grew up in the Flats lugging water for copper miners, watching friends disappear into slave caravans. Never had the coin to buy safety, only the muscle to survive. Joined the Anti-Slavers after they busted a cage wagon passing through town, deciding it was better to die fighting than living kneeling.', ''),
        ('Anti-Slavers', 'A former Holy Nation peasant who questioned the teachings and was branded a heretic. Escaped the pyre with burns along their arms and a certainty that the nation''s slaves were the lucky ones. Took up the sword against their former masters, using knowledge of patrols and supply routes to aid the cause.', ''),
        ('Anti-Slavers', 'Shek by birth but exiled from the clan for refusing to execute a captured slave as a coward. Wandered the wasteland alone, hungry, and angry at the stupidity of honor that meant killing the helpless. Found real purpose when an Anti-Slaver cell welcomed a strong arm without asking about past loyalties.', ''),
        ('Anti-Slavers', 'Used to run supplies for the Slave Traders, telling themselves it was just business and just cargo. Quit the day they saw a friend from their home village locked in the back of their own wagon. Has been trying to balance that guilt with blood ever since, taking risky missions nobody else wants.', ''),
        ('Anti-Slavers', 'A hiveless drone who woke alone in the desert with no connection to the queen and no memory of separation. Was captured by slavers and nearly sold before a raid freed the entire cage. Followed the liberators back to camp and learned to fight simply because they had nowhere else to go.', ''),
        ('Anti-Slavers', 'Born into slavery inside a United Cities work camp and never knew a day of freedom until age twenty. Escaped during a dust storm that blinded the overseers and choked the hounds. Spent years learning to read, fight, and survive on their own terms before seeking out others who shared the burning need to tear the system down.', ''),
        ('Anti-Slavers', 'Once a respected surgeon in the United Cities until refusing to treat a noble who had beaten a slave to the edge of death. Stripped of rank and exiled, nearly starved in the badlands before an Anti-Slaver squad found them half-dead by a dried riverbed. Now patches up wounded fighters and never asks for payment, only targets.', ''),
        ('Anti-Slavers', 'Lost everything when slavers burned their fishing village along the coast, taking the strong and leaving the old to starve. Survived on shellfish and rage for a full season before making contact with resistance fighters in the hills. Specializes in nighttime sabotage operations against slave caravans and sleeps soundly afterward.', ''),
        ('Anti-Slavers', 'A reformed bandit who used to rob refugees fleeing the Holy Nation, until the night they robbed a mother carrying an infant and saw the same desperation they once felt. Turned their blade on their own gang and barely escaped alive. Walked for weeks to find the Anti-Slavers, offering their skills in ambush and tracking as penance for years of cruelty.', ''),
        ('Anti-Slavers', 'Grew up in a Holy Nation village where neighbors vanished in the night for the slightest offense against the holy text. Watched a close friend dragged away for questioning a priest and realized faith was just another chain. Fled north with nothing but a stolen sword and found purpose cutting actual chains instead.', ''),
        ('Anti-Slavers', 'Was purchased at auction by a wealthy merchant who treated their property with unusual kindness, even teaching them to read and fight. When the merchant died, the will freed all household slaves, but freedom without purpose felt hollow. Sought out the Anti-Slavers because fighting was the only trade they knew and the only cause that made sense.', ''),
        ('Anti-Slavers', 'Spent three years as a hired guard for a slave processing outpost, telling themselves it was honest coin. The breaking point came when a child asked why they wouldn''t help, and they had no answer. Deserted that same night with a stolen crossbow and never looked back, riding until they found people who fought for something worth fighting for.', ''),
        ('Anti-Slavers', 'A Shek exile whose clan was raided by slavers who dared to take Shek warriors as property. Tracked the caravan for weeks, freeing their kin and killing every guard who didn''t run. Joined the Anti-Slavers because they offered what the Shek Kingdom could not, a war without politics and enemies worth killing.', ''),
        ('Anti-Slavers', 'Served as a body servant to a United Cities noble house and witnessed every cruelty hidden behind polished walls. Poisoned their master''s wine the night he ordered a pregnant slave beaten for spilling tea. Fled with a bag of stolen silver and never stopped running until they found a place where their particular skills were needed.', ''),
        ('Anti-Slavers', 'Lived as a hermit in the borderlands, trading skins and herbs to passing caravans without a care for the world''s troubles. Found a group of escaped slaves half-dead in a canyon and spent weeks nursing them back to health. Something fundamental changed in those weeks, and now the hermit guides runaways through the very passes they once walked alone.', ''),
        ('Anti-Slavers', 'Forged shackles and collars for the Slave Traders for over a decade, never questioning the iron that passed through their hands. Stopped when they recognized their own work clamped around the wrist of a captive who looked just like their dead sibling. Now puts that same skill into crafting blades and armor for those who dismantle what the smith once built.', ''),
        ('Anti-Slavers', 'A former overseer who managed slaves in the United Cities mines and convinced themselves they were firm but fair. Collapsed during a cave-in and the very slaves they commanded dug them out while the guards fled. Could not return to that life after seeing who showed humanity and who did not, and has spent the years since trying to earn what was given freely.', ''),
        ('Band of Bones', 'Starvation took everyone else in the starving camp, but the bones offered a different path. Eating the dead of the wastes seemed cursed at first, but survival cured that delusion quickly. Now the ritual of bone-wearing is the only faith left.', ''),
        ('Band of Bones', 'A slaver''s chain left marks on the wrists and a deep hatred for soft city-dwellers. The Band of Bones offered freedom and a blade to repay the world''s cruelty. Their raids bring the only justice this land understands.', ''),
        ('Band of Bones', 'Born into the band, the old ways are the only ways that make sense. The bone armor is crafted from the first catch, a rite of passage earned at fourteen summers. The wastes provide for those strong enough to take.', ''),
        ('Band of Bones', 'Once a farmer in the borderlands, dust and beak thing raids left nothing to harvest. Hunger drove desperate hands to the dead, and the taste of survival washed away the shame. The band found a willing recruit in that hollow field.', ''),
        ('Band of Bones', 'The Holy Nation burns heretics, but they never found the one who slipped their pyres. Hatred of their false pharaoh fuels every raid against their outposts. Bones worn on the outside match the death carried within.', ''),
        ('Band of Bones', 'Exiled from the Shek Kingdom for cowardice, wandering the desert stripped away every remaining scrap of honor. The Band of Bones asked no questions about courage, only hunger and willingness to kill. Service among the bone-wearers demands no pride, only obedience.', ''),
        ('Band of Bones', 'A merchant caravan ambush left only one survivor bleeding in the sand. The band found them dying and offered a choice: become the hunter or become the meal. The choice was never truly a choice at all.', ''),
        ('Band of Bones', 'Years of skimmer attacks hardened this one to the sight of mangled flesh. Joining the band was just a continuation of the brutal arithmetic of survival. Their bone armor includes a few skimmer plates mixed in with the rest.', ''),
        ('Band of Bones', 'The swamp never gave up its hold on this drifter, but the Band of Bones wanders farther than any swamp rat. Acid and ruin are familiar companions on the long patrols. The bone mask hides a face the swamp already half-melted away.', ''),
        ('Band of Bones', 'Running with the band for a decade has dulled every memory of life before. There is only the raid, the feast, and the long walk between. Older bones creak now, but experience makes for a cunning ambush fighter.', ''),
        ('Band of Bones', 'Starvation took everything from this one, leaving only hunger and hatred. The Band of Bones offered meat and purpose, and neither was refused. Now the old life is just a faded dream buried under the taste of blood.', ''),
        ('Band of Bones', 'Born into the Band, this raider has never known any other way to live. The weak are meat, the strong are family, and the desert takes the rest. It is a simple existence that has kept them alive this long.', ''),
        ('Band of Bones', 'A former slave who escaped their chains only to find the wasteland just as cruel. The Band found them half-dead and offered a choice: eat or be eaten. They chose to survive, no matter what it required.', ''),
        ('Band of Bones', 'Once a farmer in the borderlands, they watched their family wither and die when the wells dried up. The Band of Bones took them in during the madness that followed. The fields they tend now are made of flesh.', ''),
        ('Band of Bones', 'This one was a skimmer for another gang before a failed raid left them bleeding in the dust. The Band of Bones patched the wounds and claimed the loyalty. Old allegiances mean nothing when you owe your life to cannibals.', ''),
        ('Band of Bones', 'Exiled from a holy city for crimes against the scriptures, they wandered the wastes until the hunger became unbearable. The Band does not judge what a person eats, only that they are strong enough to take it. Faith was replaced by appetite long ago.', ''),
        ('Band of Bones', 'A survivor of a Band raid who was too broken to flee and too stubborn to die. Years of captivity dulled the horror and sharpened the instinct to belong. Now they raid the same roads where they were once taken.', ''),
        ('Band of Bones', 'This one followed a lover into the Band, thinking it was temporary. The lover is long dead, picked clean by the very family they joined, but the habit of belonging remains. There is nowhere else to go.', ''),
        ('Band of Bones', 'Trained as a guard for a trade caravan, they learned how to kill but not how to starve quietly. When the caravan disbanded, the Band offered better pay in the form of whatever they could take. The transition was surprisingly easy.', ''),
        ('Band of Bones', 'Mute since birth, this raider was always treated as lesser by the world outside. The Band of Bones only cares if your blade is sharp and your stomach is full. Here, silence is not a weakness.', ''),
        ('Band of Bones', 'They joined seeking revenge against a rival faction that destroyed their home. The Band provided the numbers and the cruelty needed to see that vengeance done. Now the debt is paid, but the taste for violence lingers.', ''),
        ('Band of Bones', 'A former scavenger who always found the best pickings on fresh corpses. It was a short step from robbing the dead to helping the dead become available. The Band appreciates someone with practical skills and no squeamishness.', ''),
        ('Band of Bones', 'Born into slavery in the United Cities, they killed their master during a sandstorm and fled into the wastes. The Band found them half-dead and offered a simple choice: join or become food. They chose the chain that lets them hold the whip.', ''),
        ('Band of Bones', 'Dust choked their fields three seasons in a row, and the tax collectors still came anyway. When the Band raided their starving village, they picked up a fallen blade and joined the looters rather than die with the rest. The soil was dead, but the roads were rich with blood.', ''),
        ('Band of Bones', 'They owed a fortune to the Traders Guild after a bad deal cost them everything. Fleeing into the Badlands, they found the Band took no interest in debts, only in what you could take. Now they rob the very caravans they once traded with.', ''),
        ('Band of Bones', 'Once a soldier for a minor lord whose fortress crumbled to cannibals, they wandered aimlessly until the Band offered purpose. The discipline is looser and the pay is theft, but at least the orders make sense. Kill. Take.', ''),
        ('Band of Bones', 'The Holy Nation declared them unclean for the metal arm that replaced the one lost to a beak thing. Cast out from their home, they found the Band cared only for what the arm could grip. A prosthetic is just another weapon here.', ''),
        ('Band of Bones', 'They do not remember a time before the Band, only the smell of blood and the sound of screaming. Raised on raids and weaned on stolen meat, this is the only family they have ever known. The outside world is just prey that has not been caught yet.', ''),
        ('Band of Bones', 'Years of backbreaking labor in a copper mine left them with nothing but scars and a crippled spine. When the mine collapsed and the owners abandoned the survivors, the Band took them in and handed them a sword. Taking from others hurts less than the earth ever did.', ''),
        ('Band of Bones', 'Their entire village was put to the sword by the Band in a single night. They survived by hiding under the bodies of their neighbors until the raiders moved on. When hunger drove them out, they tracked the Band down and begged to join, because the alternative was dying alone.', ''),
        ('Berserkers', 'Grew up tending crops in the Holy Lands until tax collectors took everything and left the family to starve. Walked into the wilderness with nothing but a rusty blade and a promise to never bow to laws again. Found kin among the Berserkers who taught that rage is the only honest answer to a broken world.', ''),
        ('Berserkers', 'Born under the open sky to a mother who never spoke of life before the wild. Learned to track and kill before ever seeing a walled city. The pack is family, the forest is home, and anything built of stone is a cage to be torn apart.', ''),
        ('Berserkers', 'Spent years hauling scrap for the Traders Guild until a overseer''s whip scarred the back for the last time. Snapped during a shift and beat the overseer bloody with a iron bar before fleeing into the borderlands. The Berserkers welcomed the fury and gave it purpose.', ''),
        ('Berserkers', 'Once a servant in a United City noble house where humiliation was daily bread. Escaped into the badlands with stolen food and a seething grudge against anyone who wears silk. Now measures worth only in strength and the willingness to strike first.', ''),
        ('Berserkers', 'A Shek outcast who dishonored the warrior code by fleeing a losing battle rather than dying. Wandered alone until Berserker raiders found and offered a place where survival matters more than honor. Fights with the desperation of someone who has nothing left to prove.', ''),
        ('Berserkers', 'Lost a spouse and child to a Skimmer attack while the town guards watched from their walls. Burned the house down themselves and walked away from everything soft and civilized. The Berserkers understand that grief and rage are the same fire.', ''),
        ('Berserkers', 'Raised by a paranoid hermit who taught that all machines are traps set by long-dead hands. Joined the Berserkers after the hermit died of rotgang because there was no one left to trust. Destroys every scrap of ancient metal found as a ritual of survival.', ''),
        ('Berserkers', 'Former Stone Rat who got betrayed by fellow thieves over a meager loot split. Crawled out of a shallow grave with a shattered wrist that healed crooked and wrong. Swore off schemes and cunning in favor of honest brute violence among the Berserkers.', ''),
        ('Berserkers', 'A Hiver drone separated from the hive during a Beak Thing attack and left to wander without purpose. The Berserkers were the first group that accepted the drone without demanding obedience to a queen. Now guards the pack''s flanks with a loyalty born of gratitude.', ''),
        ('Berserkers', 'Escaped from a Reaver slave ship during a storm and washed ashore with nothing but chains still on the wrists. A Berserker patrol cut the irons and handed over a weapon instead. Follows the pack to repay the debt in blood.', ''),
        ('Berserkers', 'Born in the dust and raised by the blade, this one knows only the tribe''s way. The weak cities with their stone walls and iron chains hold nothing but disgust. Blood and freedom are the only truths worth following.', ''),
        ('Berserkers', 'Escaped from a Holy Nation labor camp with nothing but stolen iron and rage. The Berserkers took in a scarred, starving wretch and forged a hunter from the wreckage. Now the holy fires burn only in the past, replaced by the primal joy of the raid.', ''),
        ('Berserkers', 'Once a trader''s guard in the Border Zone, until the pay stopped and the hunger grew. Walked away from the caravans and into the wild, where strength alone decides who eats. Has never looked back since the first camp welcomed another pair of willing hands.', ''),
        ('Berserkers', 'Born under the open sky to a Berserker mother who taught the blade before the word. The tribe is family, the wild is home, and the soft ones who hide behind walls are prey. Knows every root and water source for miles around the camp.', ''),
        ('Berserkers', 'A farmer''s child who watched Reavers burn the homestead and take the harvest. Wandered starving until the Berserkers found another set of empty hands and hungry eyes. Now fire answers fire, and the crops grown are the ones taken by force.', ''),
        ('Berserkers', 'Left the Shek Kingdom after growing tired of endless drills and commanders who never bled. The Berserkers offered something purer: no ranks, no orders, just survival and the thrill of the fight. The only law here is the strength to enforce it.', ''),
        ('Berserkers', 'A desert wanderer who nearly died of thirst before a raiding party shared their water. Repaid the debt in blood during the next raid and found the life suited an empty soul. The tribe provides what the barren wastes never could.', ''),
        ('Berserkers', 'Once a skilled laborer in the United Cities, until taxes and slavers took everything twice over. The Berserkers need no coin and recognize no emperor. Here, a strong arm is the only currency that matters.', ''),
        ('Berserkers', 'Lost a mate and children to skinners in the Leviathan Coast. The grief curdled into something feral, and the Berserkers recognized the look in those hollow eyes. Now every raid is a chance to make the world bleed the way it deserves.', ''),
        ('Berserkers', 'Trained as a Hiver soldier, but the Queen''s orders meant nothing when the hive fell. Drifted south in a fog of purposelessness until the primal campfires called. The tribe doesn''t care about antennae or hive-minds, only whether you can swing a blade.', ''),
        ('Berserkers', 'Raised in a Cannibal camp but could never stomach the flesh of thinking prey. Fled into the wilderness and found the Berserkers, who raid but do not feast on the dead. It is a small mercy, but enough to sleep at night.', ''),
        ('Berserkers', 'A former swamp resident who watched the Fog Isle settlement fall to the Fogmen. Swam through muck and rot to reach dry land, where the Berserkers found another survivor of the world''s cruelty. The fog no longer haunts these dreams, only the open sky and the hunt.', ''),
        ('Berserkers', 'Born into the tribe and knows no other life. Learned to track prey before learning to read the winds. The old ways are the only ways, and the iron cities are just places to raid.', ''),
        ('Berserkers', 'Once a Holy Nation farmer, beaten for questioning the scriptures. Fled north with nothing but farm tools, which made fine weapons once sharpened. The Berserkers ask no prayers and demand no purity, only loyalty to the pack.', ''),
        ('Berserkers', 'A former caravan guard who watched merchants haggle over slave prices one too many times. Threw away the uniform and walked into the wastes. Now takes what is needed instead of protecting those who hoard it.', ''),
        ('Berserkers', 'A Shek exile who found the Berserkers more honest than the Kingdom''s endless posturing. Here, strength speaks without the burden of honor or tradition. Blood is blood, whether taken in formal duel or midnight raid.', ''),
        ('Berserkers', 'Survived three years in a slaver camp before a Beak Thing attack broke the walls. Ran until the legs nearly gave out, and the Berserkers found a body still willing to fight. Freedom tastes like ash and copper, but it is sweet nonetheless.', ''),
        ('Berserkers', 'A child of the Flats who watched the Holy Nation purge an entire village for heresy. The sight of burning homes never left, but neither did the understanding that civilization is a lie. The tribe burns too, but only what needs burning.', ''),
        ('Berserkers', 'Once a Tech Hunter, cataloging the ruins of dead empires for scholars who never leave their towers. Realized the ancients were fools and the new empires are no better. Now lives by tooth and blade, far from the seductive poison of old machines.', ''),
        ('Berserkers', 'A fisherman from the coast whose boat was shattered by a Leviathan. Washed ashore half-dead and wandered inland until the tribe took in another stray. The sea takes and gives, but the land only takes unless you are strong enough to take first.', ''),
        ('Blackshifters', 'A former copper miner who fled the Holy Mine after a tunnel collapse took his crew. The Blackshifters found him half-dead in the wastes, and he decided that taking from others beat digging for scraps.', ''),
        ('Blackshifters', 'Born into a starving village on the border of the Hook, this bandit learned early that the weak are meat. The Blackshifters offered a blade and a gang, which was more than the farms ever gave.', ''),
        ('Blackshifters', 'A runaway slave from Rebirth who stumbled into a Blackshifter camp while fleeing Holy Nation patrols. The gang became a crude family, and now this freed person robs the very caravans that once traded in human flesh.', ''),
        ('Blackshifters', 'Once a respected guard for a merchant house in the United Cities, this one was cast out after being framed for theft by a corrupt noble. The Blackshifters welcomed a fighter with grudges, and the desert taught the rest.', ''),
        ('Blackshifters', 'A Skinner exile who found the Blackshifters more welcoming than the cannibal clans of the deep wastes. The hunger remains, but now it is sated on travelers instead of kin.', ''),
        ('Blackshifters', 'This bandit grew up in a Blackshifter camp, knowing nothing else but the ebb and flow of raiding season. Loyalty to the gang is instinct, and the outside world is just a collection of targets and supplies.', ''),
        ('Blackshifters', 'A failed adventurer who came to the wastelands seeking fortune and found only dehydration and despair. The Blackshifters offered water and purpose, and the transition from victim to predator was surprisingly brief.', ''),
        ('Blackshifters', 'Once a craftsman in a border town, this one watched everything burn during a Shek raid and decided civilization is a lie. The Blackshifters agree, and their camp is the only home left.', ''),
        ('Blackshifters', 'A former Hound who grew tired of taking orders for meager pay and struck out alone. The Blackshifters picked up a skilled fighter, and the desert provided plenty of opportunities to put those skills to use.', ''),
        ('Blackshifters', 'Starved half to death after a failed farming attempt in the acid wastes, this survivor was dragged into a Blackshifter camp as potential loot. Impressed by the sheer stubborn will to live, the gang offered membership instead.', ''),
        ('Blackshifters', 'A former scavenger from the Border Zone who grew tired of scraping by on copper dust and skeleton scraps. After a Blackshifter patrol pulled them out of a ruin collapse, they swore the oath and took the tattoo. Now they probe deeper than they ever dared alone, sending most of their cut back to a sick sibling in Squin.', ''),
        ('Blackshifters', 'Trained as an apprentice mechanic in a United Cities workshop until a noble seized the business over unpaid taxes. With nothing but a wrench and a grudge, they wandered the wastes until a Blackshifter crew recognized their talent for identifying pre-fall alloys. They still dream of rebuilding something of their own, one engine component at a time.', ''),
        ('Blackshifters', 'Born to a poor fishing family on the coast, they left home after a Skinners raid left them the only survivor. The Blackshifters found them half-dead from dehydration and gave them a canteen and a choice. They chose to live, and now they patrol the dunes with a quiet, focused intensity that unnerves newer recruits.', ''),
        ('Blackshifters', 'An ex-mercenary from the Hounds who deserted after a contract forced them to raid a peaceful village. They spent months drifting between outposts before a Blackshifter elder offered redemption through honest salvage work. They still flinch at loud noises and sleep with a blade under their pillow, but the steady rhythm of excavation has begun to quiet their demons.', ''),
        ('Blackshifters', 'A Scorchlander who spent years as a guide for trade caravans crossing the great desert. When a sandstorm buried their last clients alive, they walked into Blackshifter territory seeking a life that didn''t depend on other people''s schedules. Their knowledge of desert routes and water caches made them invaluable within the season.', ''),
        ('Blackshifters', 'Sold into the Holy Mines as a child for their parents'' unpaid tithes, they learned to read structural weaknesses in rock by watching tunnels collapse. They escaped during a cave-in that killed three guards and disappeared into the wastes. The Blackshifters value their instinct for which ruins are stable and which are death traps, though they rarely speak of where they learned the skill.', ''),
        ('Blackshifters', 'A farmer''s child from the fertile lands who watched the United Cities tax collectors take everything during a drought year. They tried to fight back and earned a bounty on their head for striking an officer. The Blackshifters were the first group that didn''t ask questions about the brand on their wrist, only about whether they could carry their weight.', ''),
        ('Blackshifters', 'Once a respected scholar at the Great Library in Stack before the Holy Nation burned their research on pre-fall engineering. Disgraced and exiled as a heretic, they wandered south with nothing but a cache of salvaged schematics. The Blackshifters took them in, and now they serve as the crew''s primary identifier of valuable artifacts amid the rubble.', ''),
        ('Blackshifters', 'A Shek warrior who failed their initiation rites and was cast out from their clan in disgrace. Too proud to beg and too ashamed to return, they wandered the borderlands until hunger drove them to a Blackshifter camp. They''ve found that the discipline of salvage work suits them better than raiding ever did, though they still sharpen their blade every dawn.', ''),
        ('Blackshifters', 'The child of a ruined trader from Mongrel who grew up listening to stories of ancient caches that could restore the family fortune. After their parent died of rotworms, they tracked down the Blackshifters to learn the trade properly. They still carry their parent''s broken compass as a reminder of why they descend into the dark places of the world.', ''),
        ('Blackshifters', 'A former slave in Rebirth whose only duty was hauling skeleton limbs from the deeper excavations for the overseers. They memorized the layout of those ancient passages during years of forced labor. When the Blackshifters raided the site, they grabbed their chains and ran toward the attackers rather than away, offering everything they knew in exchange for a new chain to wear.', ''),
        ('Blackshifters', 'A Greenlander who spent a decade as a barkeeper in Heft, pouring drinks for off-duty samurai and listening to their stories of far-flung ruins. When the empire drafted them into a penal legion for failing to pay protection fees, they deserted at the first opportunity. The Blackshifters don''t care about their past, only that they can spot a valuable find from across a rubble-strewn room.', ''),
        ('Blackshifters', 'A Hiveless drone severed from their queen during a fogger attack in the Fog Islands who spent months wandering the borderlands in a daze. A Blackshifter patrol found them picking through a pre-fall bunker with mechanical persistence. The crew became their new hive, and their tireless work ethic in tight ruins makes them worth the rations they consume.', ''),
        ('Blackshifters', 'A former Tech Hunter who got blacklisted for selling recovered artifacts to Skin Bandit brokers instead of turning them in to the guild. Stripped of their credentials and hunted by former colleagues, they crawled into the black market salvage trade. The Blackshifters were the only crew that would take a known thief, provided they share a cut of every score.', ''),
        ('Blackshifters', 'A Scorchlander fisher from the Swamps whose village was wiped out by a Beak Thing pack that nested in a sunken ruin nearby. They survived by hiding in the muck for three days, watching the beasts pick apart everyone they loved. Now they hunt ruins instead of fish, driven by a need to probe the dark places that breed monsters.', ''),
        ('Blackshifters', 'An old Skeleton who spent centuries buried under rubble in the Ashlands before a Blackshifter dig team excavated them. Their memory banks are corrupted beyond recovery, leaving only fragments of pre-fall architecture and a compulsive need to dig. The crew keeps them around because those fragments lead to caches no one else could find, even if they sometimes wander off mid-conversation.', ''),
        ('Blackshifters', 'A Holy Nation born laborer who discovered through a hidden family record that their grandmother was a Shek, making them impure by the very laws they once enforced as a farm overseer. They burned their own homestead and fled south before the inquisitors could arrive. The Blackshifters ask no questions about the burns on their hands or the holy book pages stuffed in their boots.', ''),
        ('Blackshifters', 'A one-armed scavenger who lost their limb to a Blood Spider in the Leviathan Coast while running salvage for a rival crew. Abandoned by their partners as dead weight, they dragged themselves to a Blackshifter encampment and refused to die at the gate. They work the surface digs now, sorting through rubble with their remaining hand and a rusted hook they forged themselves.', ''),
        ('Blackshifters', 'A former United Cities samurai who drew their blade against a noble''s tax collector when the man tried to claim a farmer''s daughter as payment. Branded a traitor with a price on their head, they fled the cities and abandoned the code that demanded such obedience. Among the Blackshifters they found rough comrades who value action over rank, and they guard the crew''s camps with the vigilance of someone who knows what hunters look like.', ''),
        ('Blackshifters', 'A cannibal child taken from the Fog Islands by passing traders and sold into servitude in the Holy Nation, raised as a laborer but never quite shedding the old hungers. When the farm was raided by bandits, they ate the overseer who had beaten them for years and fled into the wilderness. The Blackshifters tolerate them because they will enter any ruin no matter how foul, though no one shares a sleeping mat with them.', ''),
        ('Bloodraiders', 'Escaped from a Holy Mine with nothing but a pickaxe and a burning hatred for authority. Found kindred spirits among the Bloodraiders who value violence over laws. Now patrols the wastes eager to introduce that pickaxe to any passing trader.', ''),
        ('Bloodraiders', 'Failed harvests and starving bellies drove this peasant to the ultimate taboo just to see another sunrise. The taste of human flesh broke whatever sanity remained, making the Bloodraiders the only welcoming home. They fight with the desperate fury of someone who knows the alternative is starvation.', ''),
        ('Bloodraiders', 'Dishonored and cast out of the United Cities military for excessive brutality against civilians. The Bloodraiders offered a place where such tendencies are a virtue rather than a crime. They serve as a brutal enforcer, enjoying the chaos they inflict during raids.', ''),
        ('Bloodraiders', 'Born in a bloodstained tent to a raider mother who died in a skirmish with samurai. Raised on stolen food and tales of conquest, they know no other life but the blade. The gang is their family, and the wasteland is their hunting ground.', ''),
        ('Bloodraiders', 'A severe head injury from a falling ruin left them unable to remember their past or speak properly. All that remains is a lingering impulse to swing a weapon and an insatiable hunger for meat. The Bloodraiders took them in as a feral attack dog, pointing them at caravans and letting instinct take over.', ''),
        ('Bloodraiders', 'Once a humble scavenger who got pinned down by spiders, only to be rescued by a passing raider patrol. Repaying the life debt required joining the gang and adopting their bloody customs. They still hesitate at the cannibalism, but the wasteland leaves no room for a weak stomach.', ''),
        ('Bloodraiders', 'Disillusioned by the hypocrisy of the Holy Nation, this former servant turned their back on Okran entirely. Embracing the dark path of the Bloodraiders felt like the only honest response to a world of lies. They take particular pleasure in hunting down passing paladin patrols.', ''),
        ('Bloodraiders', 'Addiction to hashish drained this citizen''s wealth and eventually got them exiled from the cities. The Bloodraiders provide the only steady supply of the drug in exchange for muscle during raids. Their mind is constantly fogged, making them unpredictable and dangerously violent.', ''),
        ('Bloodraiders', 'Scarred by a beak thing attack that killed their entire family, they wandered the desert half-mad. The Bloodraiders found them raving and gave them a new target for their rage. They fight with reckless abandon, caring little if they live or die as long as they can bleed someone else.', ''),
        ('Bloodraiders', 'Kicked out of a lesser bandit gang for trying to usurp the boss, they crawled to the Bloodraiders for a second chance. Here, ambition is tolerated so long as it is backed by raw strength and spilled blood. They are constantly watching for an opportunity to climb the ranks through brute force.', ''),
        ('Bloodraiders', 'Starvation took everyone else in the farming village, but the raiders offered scraps in exchange for a sharp blade and a quiet conscience. Now the hunger is a distant memory, replaced by the warmth of fresh meat and the camaraderie of the campfire.', ''),
        ('Bloodraiders', 'Captured during a raid on a trade caravan, the choice was simple: join or become the evening meal. Proving useful with a cleaver earned a place among the band, and the old life as a wandering scavenger faded into an ugly but sustainable present.', ''),
        ('Bloodraiders', 'Born into the raider life, the taste of longpig was normal before ever knowing it was taboo. The wasteland teaches that the weak become food, and strength is measured by who stands at the carving table rather than on it.', ''),
        ('Bloodraiders', 'Debt to the Hounds drove them into the deepest badlands, where the Bloodraiders found them half-dead and desperate. A quick oath and a bloody initiation later, the creditors are the least of their worries.', ''),
        ('Bloodraiders', 'Once a respected guard in a United Cities outpost, the corruption became too much and the pay too little. The raiders don''t ask for bribes, and they share the spoils evenly enough to keep everyone loyal and well-fed.', ''),
        ('Bloodraiders', 'A bad leg ended the drifting life, and the Bloodraiders were the only group willing to carry dead weight. Cooking and tanning skills keep them off the front lines, turning the gruesome harvest into serviceable leather and stew.', ''),
        ('Bloodraiders', 'The Skinners took an arm before the Bloodraiders took the rest, adopting the survivor out of respect for sheer grit. A makeshift hook and a deep grudge make for a dangerous combination on the battlefield.', ''),
        ('Bloodraiders', 'Recruited from the ruins of a destroyed Holy Farm, the promise of revenge against the zealots was tempting enough. The dietary adjustments took time, but hatred is a powerful seasoning.', ''),
        ('Bloodraiders', 'After the mine collapsed and the overseers fled, starvation crept in within a week. The raiders arrived like vultures, but one of them tossed a ration pack instead of a blade, and loyalty was born from that strange mercy.', ''),
        ('Bloodraiders', 'A former student of the Machinists who grew disillusioned with useless ancient schematics while people starved. The Bloodraiders practice a much older and more reliable technology: the strong eat, the weak are eaten.', ''),
        ('Bloodraiders', 'Exiled from the Flotsam Ninjas for unsanctioned brutality, the Bloodraiders welcomed the excessive violence with open arms. There is a certain honesty to their savagery that the so-called righteous factions lack.', ''),
        ('Bloodraiders', 'The desert swallowed the caravan whole, leaving nothing but cracked lips and delirium. Waking in a raider camp with a bowl of suspicious stew was a second chance, never mind the price of admission.', ''),
        ('Bloodraiders', 'Born into the raid and never knowing anything else, this raider learned to butcher before learning to read. The old ways are the only ways that matter, and the weak exist solely to keep the strong fed through the lean seasons.', ''),
        ('Bloodraiders', 'Condemned as a heretic by the Holy Nation for daring to treat a skeleton''s wounds, escape came at the cost of everything familiar. The Bloodraiders ask no questions about faith or gods, only whether you can swing a blade when the meat runs low.', ''),
        ('Bloodraiders', 'Left bleeding in the dust after a failed assault on a United Cities caravan, the Bloodraiders found value in a survivor who still had fight left. Now the same warrior leads charges against those wealthy trade routes with intimate knowledge of their guard rotations.', ''),
        ('Bloodraiders', 'The southern swamps took everything when the fogmen came pouring out of the ruins, leaving nothing but rage and an empty belly. The Bloodraiders were the first group that didn''t run, and their iron stomachs proved useful against things that crawl in the dark.', ''),
        ('Bloodraiders', 'Sold to the slavers at twelve for stealing bread, years of chains bred a hunger that ordinary food could never satisfy. Freedom came with blood on its hands, and the Bloodraiders offered a place where that blood would never go to waste.', ''),
        ('Bloodraiders', 'A former guard for a noble house who watched one too many innocents fed to the slave markets for unpaid taxes. The code among the Bloodraiders is simple and honest: no masters, no taxes, and the nobles taste just fine roasted.', ''),
        ('Bloodraiders', 'The skin bandits took the face but somehow missed the spirit underneath, leaving behind something harder and colder than before. The Bloodraiders don''t care about scars or missing features, only that the blade arm still works and the stomach stays full.', ''),
        ('Bloodraiders', 'Grew up scavenging the border zones between Heng and the desert, where survival meant eating things most would refuse out of delicacy. Joining was less a choice and more an acknowledgment that the lifestyle had already chosen them years ago.', ''),
        ('Cannibal Hunters', 'Watched a cannibal feast on their younger sibling in the Fog Islands years ago. Now they track raiding parties back to their camps, making sure the hunters become the hunted. They sleep with a worn bone club across their chest as a grim reminder of their vow.', ''),
        ('Cannibal Hunters', 'Started as a standard bounty hunter in the United Cities but found the pay for cannibal ears was far better on the frontier. They treat the hunts like a business, efficient and detached, caring only about the weight of the bounties. The stench of the fog means nothing but coin to them.', ''),
        ('Cannibal Hunters', 'Spent three weeks tied to a post in a cannibal village, waiting for the cooking pot before escaping into the night. The experience left them with deep scars and an intimate knowledge of cannibal patrol routes. They guide other hunters through the mist, seeking to dismantle the tribes from within.', ''),
        ('Cannibal Hunters', 'Believes the cannibals are a plague sent by Okran to test the faithful, and their eradication is a holy duty. They venture into the fog to cleanse the impure with fire and iron, never resting as long as a single savage draws breath. Their fervor makes them reckless, but incredibly dangerous.', ''),
        ('Cannibal Hunters', 'Was a fisher on the coast until cannibal raiders burned their village and dragged away half the survivors. They traded their nets for a heavy weapon and joined the hunters to prevent anyone else from losing everything. They specialize in ambushing cannibal patrols near the shoreline.', ''),
        ('Cannibal Hunters', 'Grew up as a street rat in Sho-Battai, learning to fight dirty just to survive another day. The Cannibal Hunters offered a steady meal and a chance to legally kill, which suited their violent temperament perfectly. They care little for saving others, reveling only in the brutal skirmishes.', ''),
        ('Cannibal Hunters', 'Lost an arm to a cannibal trap in the fog, replacing it with a crude but effective iron prosthetic. They refused to let the injury end their career, instead using themselves as bait to lure cannibals into crossfire. The mechanical limb makes a terrifying clanging sound as they crush skulls.', ''),
        ('Cannibal Hunters', 'Followed their spouse into the Hunter ranks after a cannibal warparty butchered their farmstead. When their partner fell in an ambush, they kept hunting alone, unable to return to the empty homestead. The fog feels more like home than any settlement ever could now.', ''),
        ('Cannibal Hunters', 'A former Imperial samurai who fled the falling cities and found purpose in the lawless borderlands. They apply strict military discipline to their hunting parties, treating the cannibals like a hostile army to be outmaneuvered. Their tactical mind has saved countless novice hunters from deadly mistakes.', ''),
        ('Cannibal Hunters', 'Works primarily as a scout, mapping out the shifting territories of the various cannibal tribes. They prefer to avoid direct combat, instead marking camps for larger hunter groups to raid at dawn. Their maps are highly valued by anyone foolish enough to travel near the Fog Islands.', ''),
        ('Cannibal Hunters', 'A survivor of a cannibal raid on their farming village, they joined the hunters to ensure no one else experiences the same horror. The scars on their arms serve as a constant reminder of the night they barely escaped the cooking pot.', ''),
        ('Cannibal Hunters', 'A former mercenary from the United Cities who grew disillusioned with protecting corrupt nobles. Hunting cannibals offers cleaner work and the satisfaction of protecting innocent lives rather than serving greed.', ''),
        ('Cannibal Hunters', 'Born to a Cannibal Hunter mother and a Skinner father, they learned to track and fight before they could read. The borderlands are the only home they have ever known, and the tribe camps are just another hazard of daily life.', ''),
        ('Cannibal Hunters', 'Once a captive of the cannibal tribes, they spent three months in a bone cage watching others be taken away one by one. Rescued by a passing patrol, they vowed to dedicate their remaining years to exterminating every last tribe in the foglands.', ''),
        ('Cannibal Hunters', 'A retired Holy Nation paladin who left the service after questioning the faith but retained their hatred for the cannibal hordes. They bring disciplined combat training and an unshakeable conviction that the tribes are an abomination to be purged.', ''),
        ('Cannibal Hunters', 'A young wanderer from the swamps who watched a cannibal party drag their sibling into the fog. With no body to bury and no closure, they roam the northern reaches searching for the specific tribe that took their family.', ''),
        ('Cannibal Hunters', 'An aging tracker who spent decades guiding caravans safely through cannibal territory. Now too slow to outrun a war party, they work with the hunters to share their knowledge of tribe movements and migration patterns.', ''),
        ('Cannibal Hunters', 'A former slave who discovered that some captives were sold to the cannibal tribes as meat. The realization broke something inside them, and they now channel their rage into a crusade against the tribes and anyone who trades with them.', ''),
        ('Cannibal Hunters', 'A Shek warrior who left the warrior clans seeking a more meaningful fight than petty border disputes. Cannibals offer a worthy enemy that no one disputes deserves the blade, and the constant danger keeps their warrior spirit satisfied.', ''),
        ('Cannibal Hunters', 'A former fisherman from the coast whose entire village was wiped out in a single night raid. They sold everything they owned for a sword and armor, walking inland until they found others who shared their mission of vengeance.', ''),
        ('Cannibal Hunters', 'A scavenger who made the mistake of looting a cannibal camp and finding proof that the missing travelers were still alive when they were butchered. The discovery haunts their dreams, and they hunt cannibals to quiet the voices of those they failed to save.', ''),
        ('Cannibal Hunters', 'A former trader who ran supplies to the northern outposts until a cannibal ambush cost them their leg and their entire crew. Fitted with a prosthetic and fueled by survivor''s guilt, they coordinate hunting parties from the rear while yearning for the day they can fight on the front lines again.', ''),
        ('Cannibal Hunters', 'A former captive who escaped the cooking pots during a territorial dispute between rival tribes. The months of enslavement left scars across their back and an intimate knowledge of cannibal camp routines. They hunt now to ensure no one else endures what they survived.', ''),
        ('Cannibal Hunters', 'A mercenary who discovered that cannibal bounties pay better than most contracts and carry no moral ambiguity. They treat the work as a profession, keeping careful tallies of tribes eliminated and territories cleared. Some hunters distrust their detached approach, but none dispute their results.', ''),
        ('Cannibal Hunters', 'A young survivor pulled from a cannibal feast by a hunting party that arrived moments before the blade fell. The experience left them unable to return to normal settlement life, so they followed their rescuers back to camp. They see every dead cannibal as proof the world can be made safer.', ''),
        ('Cannibal Hunters', 'A former Holy Nation paladin who grew disillusioned with burning heretics and sought a clearer evil to fight. Cannibals offer an enemy that truly deserves no mercy, allowing them to wield their blade without doubt or guilt. They still pray before each hunt, but the prayers feel honest now.', ''),
        ('Cannibal Hunters', 'A parent whose child was taken in a raid years ago and never seen again. They patrol the borderlands season after season, searching every camp and cave for any trace of their lost family. Other hunters know better than to ask if they ever found what they were looking for.', ''),
        ('Cannibal Hunters', 'A former field surgeon who grew exhausted stitching up the same horrific wounds from cannibal attacks again and again. They realized that prevention was more effective than treatment, took up a blade, and joined the hunters. Their anatomical knowledge proves disturbingly useful for tracking wounded cannibals through the wilderness.', ''),
        ('Cannibal Hunters', 'A follower of Okran who believes cannibals are the ultimate manifestation of darkness that must be purged from the world. Their faith drives them to hunt with a fervor that unsettles even their companions, and they must sometimes be restrained from charging into suicidal odds. They consider martyrdom an acceptable outcome if it takes more of the enemy with them.', ''),
        ('Cannibal Hunters', 'A farmer whose homestead was pushed to the edge of cannibal territory by expanding tribes. After losing livestock and neighbors to raids, they realized waiting for help was futile and learned to fight back. They still tend a small garden at the hunters'' camp, a quiet reminder of the peaceful life they are fighting to protect.', ''),
        ('Catun', 'Grew up working the rice paddies outside the walls before the swamp took both parents to a blood spider raid. Now hires out as a farmhand wherever the work is steady, sleeping with a rusted machete close at hand. Dreams of saving enough cats to move somewhere drier, but the debt to local traders keeps deepening.', ''),
        ('Catun', 'Arrived in Catun with a trade caravan that was picked apart by swamp ninjas on the road out. Took up residence in an abandoned shack and started brewing cheap grog from whatever scraps could be salvaged. The locals tolerate the smell because the drink numbs the misery of swamp rot and bad harvests.', ''),
        ('Catun', 'Former Hounds grunt who washed out after a botched raid left half the crew dead or dragged off by spiders. Catun was the nearest hole to crawl into, and the cheap rent made it permanent. Does odd jobs and occasional muscle work, careful never to ask who is paying.', ''),
        ('Catun', 'Born in the swamp and expects to die in it, same as three generations before. Knows which paths flood and which water is safe to drink, knowledge that keeps the settlement alive. Carries no illusions about the future, only a quiet resolve to see tomorrow.', ''),
        ('Catun', 'Escaped from Reaver territory with nothing but a stolen pickaxe and a head full of bad memories. The rock yields around Catun are poor but steady enough to earn a bowl of rice and a corner to sleep in. Still checks the horizon every morning, certain the past will catch up eventually.', ''),
        ('Catun', 'Lost a leg below the knee to a swamp ninja ambush on the road and now works the market stall selling dried fish. The prosthetic is poorly fitted and the pain is constant, but at least the spiders are too slow to catch a cripple behind walls. Counts every cat twice and trusts nobody under forty.', ''),
        ('Catun', 'Came to Catun as a child refugee when the Holy Nation burned the old village. Learned to read the swamp''s moods early, avoiding the quickmud and the nesting grounds during season. Now serves as a guide for caravans foolish enough to take the low roads.', ''),
        ('Catun', 'Once ran a modest distillery in the borderlands before tax collectors and bandits took everything in the same week. Restarted in Catun with a single copper pot and a recipe cut with swamp water to stretch the yield. The regulars do not complain because the alternative is worse.', ''),
        ('Catun', 'Raised by a scavenger who dragged salvage from the flooded ruins to sell in town. Took over the trade when the old back gave out, wading into places others consider cursed or poisoned. Has found enough working tech to stay fed, but also enough corpses to know when to turn back.', ''),
        ('Catun', 'Deserted a United Cities labor detail and vanished into the swamp before the slavers could give chase. Catun was the first place with walls and poor enough record-keeping to not ask questions. Works the fields from dawn to dusk, keeping a low profile and an ear to the ground for bounty hunters.', ''),
        ('Catun', 'Born to a family of ore haulers, this worker spent years dragging carts from the mines before earning enough to buy a small forge. Now they craft basic blades for the local garrison, though the work pays barely enough to keep food on the table. The constant soot and heat have left their lungs ragged, but quitting means starvation.', ''),
        ('Catun', 'Formerly a guard for United Cities caravans, this veteran settled in Catun after a skimmer attack left them with a permanent limp. They now work the watchtower shifts, scanning the horizon for bandits and beasts alike. The pay is meager, but the walls offer more safety than the open road ever did.', ''),
        ('Catun', 'Sold into servitude for unpaid taxes, this laborer spent a decade working the stone quarries before a sympathetic overseer quietly allowed their escape. Catun offered anonymity among its busy streets and smoke-choked workshops. They keep their head down and their past hidden, hauling crates for whatever trader will pay in food.', ''),
        ('Catun', 'Apprenticed to one of Catun''s renowned weaponsmiths at a young age, this crafter learned to fold steel before they could read. The quality of their work draws merchants from across the Border Zone, though most profits flow upward to the guild masters. They dream of opening their own shop, but the licensing fees are impossibly steep.', ''),
        ('Catun', 'Driven from their farming village by Spider raids, this refugee arrived in Catun with nothing but a rusted pickaxe. They now work the copper deposits outside the walls, trading raw ore for ration strips at the local bar. Every day in the mines is a gamble between a full belly and a cave-in.', ''),
        ('Catun', 'This former scavenger made a modest living picking through battlefield wreckage until a territorial clash with dust bandits cost them two fingers. They retreated to Catun for the relative safety of its fortified market. Now they mend broken tools and sharpen dulled edges for copper coins, too broken to roam far.', ''),
        ('Catun', 'Raised among the squalor of Catun''s outer shacks, this survivor learned to fight over scraps before they could hold a hammer. A local smith took pity and taught them the basics of metalwork, though their temper still flares when challenged. They work the bellows by day and nurse grudges by night.', ''),
        ('Catun', 'Once a prosperous trader along the Holy Nation border, this merchant lost everything to a corrupt samurai patrol that seized their goods under false pretense. They retreated to Catun to rebuild, operating a modest stall selling imported leather and cloth. Trust in authority is long gone, but commerce remains the only life they know.', ''),
        ('Catun', 'Conscripted into a doomed United Cities border garrison, this soldier watched their entire unit slaughtered by Beak Things in the Swamp. They deserted the ranks and vanished into Catun''s crowded streets, taking work as a farmhand on the outskirts. The nightmares persist, and the fear of being recognized by patrolling samurai never fades.', ''),
        ('Catun', 'A skilled tanner by trade, this worker processes the hides brought in by hunters and sells the leather to Catun''s armorers. The stench of the curing pits clings to them permanently, marking them as an outsider even among the town''s working poor. They endure the isolation because the craft pays better than most labor available to those without connections.', ''),
        ('Catun', 'This young porter carries shipments between the trading post and the city gates, earning just enough to share a cramped room with three other workers. They send what little surplus they have back to a sick parent in a distant village. The hope of one day affording proper medical care keeps their legs moving through the grueling shifts.', ''),
        ('Catun', 'Captured by slavers near the Sink, this unfortunate was sold to a Catun workshop owner and put to work maintaining the forges. After five years of obedient service, they were granted nominal freedom, though the debt for their release binds them to the same employer. They stoke the flames and watch the free citizens pass by, wondering if true liberty will ever come.', ''),
        ('Catun', 'The river provided for this fisher''s family for generations, but pollution from the workshops and raids by drifters have made the catches meager. They now spend longer hours on the water, risking Beak Thing attacks near the swampy banks. Each day they return with less, watching their children grow thinner.', ''),
        ('Catun', 'Captured by Skin Bandits during a journey through the wilderness, this survivor lost their original face and was fitted with one of the horrible masks before escaping during a bandit camp raid. They wandered half-mad into Catun, where the workshop smoke and crowds offered some anonymity. The mask remains fused to their flesh, and the whispers of other citizens follow them everywhere.', ''),
        ('Catun', 'This foreman oversees a crew of twenty workers in one of Catun''s armor workshops, enforcing production quotas with harsh discipline. The owners pay well enough to keep their loyalty, but the workers they punish each day share the same desperate poverty. They sleep poorly, knowing their authority exists only to serve profits they will never share.', ''),
        ('Catun', 'Moving goods past the samurai checkpoints requires bribes and nerve, both of which this smuggler has cultivated over years of quiet trade. They specialize in moving hashish from the Swamp and stolen United Cities equipment to buyers in the Flats. One wrong step means imprisonment or worse, but the coin keeps flowing as long as they stay sharp.', ''),
        ('Catun', 'Fleeing a Holy Nation purge that burned their village for harboring a Shek refugee, this survivor crossed into United Cities territory with nothing but the clothes on their back. Catun offered work in the workshops, though the locals eye their past with suspicion. They keep their head down and their origins hidden, knowing neither faction truly protects people like them.', ''),
        ('Catun', 'A crossbow bolt shattered this mercenary''s knee during a contract outside Catun''s walls, ending any chance of continued fighting work. They took a position as a night watchman at a trading post, the pay barely covering medicine for chronic pain. Every shift they stand watch on legs that scream, remembering when they were the one others feared.', ''),
        ('Catun', 'Orphaned by a slave raid that took their parents years ago, this street youth survives by running messages between the city''s criminal elements and picking pockets when opportunity arises. A local thief-taker has noticed their skills and is pressuring them to join a crew permanently. The streets offer freedom and danger in equal measure, and the choices narrow with each passing season.', ''),
        ('Catun', 'Decades of hammering blades at the forge have ruined this smith''s hands, the fingers gnarled and trembling too much for fine work. They teach apprentices now, but the pay is a fraction of what they once earned as a master. Retirement means starvation in Catun, so they continue demonstrating techniques they can no longer perform themselves.', ''),
        ('Clownsteaders', 'The tax collectors took the farm after three bad harvests, leaving nothing but the clothes on their back. Clownstead was the only place that didn''t ask questions about where they came from or what they owed. Now they tend a small garden plot and pray the raiders stay away another season.', ''),
        ('Clownsteaders', 'Twenty years of selling their sword left nothing but scars and a bad knee that clicks when it rains. The mercenary companies stopped calling when they couldn''t keep pace on forced marches. Clownstead offered a quiet corner to drink away the memories and die somewhere the bonedogs wouldn''t find them first.', ''),
        ('Clownsteaders', 'They fled the Holy Nation when the inquisitors started asking about their parentage. Half-Okran or not, the pyres don''t discriminate when suspicion falls. Clownstead doesn''t care about blood purity, only whether you can carry your weight.', ''),
        ('Clownsteaders', 'The slave brand on their wrist still itches years after they cut their chain during a dust storm. Tengu''s mines took five years of their life and left them with a healthy fear of enclosed spaces. They sleep with a weapon close and never plan further than tomorrow.', ''),
        ('Clownsteaders', 'A Starving Bandit patrol took everything outside Squin-inventory, pack beast, and both hired hands. The trader''s guild wrote off the debt, then wrote off the trader just as fast. Clownstead was where they crawled to lick their wounds and figure out how to start over with nothing.', ''),
        ('Clownsteaders', 'They left the Shek Kingdom after refusing a pointless death in some warrior''s proving ritual. The coward''s label still burns, but the speaker is still breathing. Clownstead lets them use their forge skills without demanding they die for honor.', ''),
        ('Clownsteaders', 'A Beak Thing nest wiped out their entire caravan in the Shun. They survived by playing dead under the bodies of their family. The silence of Clownstead suits them fine-they''ve heard enough screaming to last several lifetimes.', ''),
        ('Clownsteaders', 'The noble they served decided to clear his debts by selling his household staff to the slavers. They escaped during the transfer near Shark and ran until their legs gave out. Now they work for copper and keep their head down, trusting no one with authority.', ''),
        ('Clownsteaders', 'They came to Clownstead chasing a rumor of fertile soil and left the crumbling cities behind. The Border Zone isn''t forgiving, but at least here a person owns what they can defend. They''ve built a life from dust and stubbornness, and they''ll kill to keep it.', ''),
        ('Clownsteaders', 'Scavenging the battlefields of the Border Zone was profitable until the skin bandits moved in. They lost their partner and nearly their own hide before making it to Clownstead''s walls. The town is a place to recover and gather courage before heading back out into the wastes.', ''),
        ('Clownsteaders', 'Fled the Holy Nation after neighbors reported lingering doubts about Okran''s light. Found Clownsteady by accident while dodging slaver patrols in the Border Zone. Now tends a meager dustfield and tries not to think about the flames that took the old life.', ''),
        ('Clownsteaders', 'Was a United Cities drifter until tax collectors seized everything for a debt that was never proved. Stumbled into Clownsteady half-starved and has stayed ever since, trusting the community more than any empire. Spends most days patching the perimeter wall and arguing about rations.', ''),
        ('Clownsteaders', 'Born to squatters on the edge of the Border Zone and never knew any other life. Learned to fight off skinners before learning to read, if reading even matters out here. Figures Clownsteady is as good a patch of dirt as any to die on someday.', ''),
        ('Clownsteaders', 'Former mercenary who got too old and too slow for the trade companies. Took a wound in the Gut that never healed right and limped into Clownsteady looking for cheap bandages. Stayed because nobody asks questions about the blood on old armor.', ''),
        ('Clownsteaders', 'Escaped a slave camp in the Swamps with nothing but a stolen shiv and a lot of anger. Wandered for weeks before a Clownsteader patrol found her half-drowned at a watering hole. Has planted roots in the stubborn soil and vows never to be property again.', ''),
        ('Clownsteaders', 'Lost a fishing boat to Reavers and washed up somewhere south of the Floodlands. Walked for a month through the worst the continent had to offer before reaching Clownsteady. Now hauls water from the well and keeps a rusted polearm by the door.', ''),
        ('Clownsteaders', 'A onetime trader whose caravan was wiped out by Beak Things in the Leviathan Coast. The memory still wakes him some nights, the screaming and the snapping of bone. Clownsteady is the only place quiet enough to sleep, most of the time.', ''),
        ('Clownsteaders', 'Grew up a Shek outcast, too weak to earn a name in the warrior bands. Found more kinship among the misfits of Clownsteady than among the bone-helms. Works the anvil when iron is available and otherwise sharpens whatever blades the settlement can afford.', ''),
        ('Clownsteaders', 'Served as a low-ranking samurai in the United Cities before a superior''s corruption made the entire unit scapegoats. Deserted rather than face execution for crimes committed by the officers above. The shame still lingers, but Clownsteady asks nothing of the past.', ''),
        ('Clownsteaders', 'A Hiver who drifted away from the Western hive during a famine and never found the instinct to return. The other Clownsteaders were suspicious at first but warmed to a worker who never complains. Spends long hours in the fields, silent and industrious as the sun beats down.', ''),
        ('Clownsteaders', 'Was a barmaid in Sho-Battai until a noble''s son took offense to a refused advance. The beating left scars across her back and a deep hatred for anyone with money and power. Clownsteady has no nobles, which suits her fine.', ''),
        ('Clownsteaders', 'Came to Clownsteady as a child when parents fled the Holy Nation''s purges. Knows nothing of the old country except what the elders mutter about during drunken evenings. Figures they will probably die here, defending this dusty patch from whatever comes next.', ''),
        ('Clownsteaders', 'Escaped from a slave camp in the Swamps after a flood drowned the overseers in their sleep. Wandered half-starved for weeks before stumbling into Clownsteady. Now stands guard on the walls at night, watching the shadows for slaver torches.', ''),
        ('Clownsteaders', 'Spent years picking through Old Empire ruins for the Tech Hunters until a collapsed tunnel buried two friends and the desire to dig any deeper. Clownsteady offered a quiet place where the past stays buried. Tends the settlement''s meager water supply and avoids caves entirely.', ''),
        ('Clownsteaders', 'Farmed scrubland near the border until dust storms and United Cities tax collectors took everything in the same season. The land never gave much, but it gave enough to remember what hunger felt like when it was taken. Clownsteady''s soil is poor, but no one comes demanding a cut of the harvest.', ''),
        ('Clownsteaders', 'Ran with a mercenary company that dissolved after a botched contract against the Shek Kingdom. The survivors scattered rather than face the reprisals of angry warriors. Found Clownsteady by accident and stayed because no one asked questions about old allegiances.', ''),
        ('Clownsteaders', 'Worked the fishing villages along the coast until Reavers burned everything and pressed the survivors into rowing. Escaped during a storm when the hull cracked open on the rocks. The desert is strange, but at least the sand doesn''t have teeth.', ''),
        ('Clownsteaders', 'A Skin Bandit raid took home and family and the skin off one arm before a passing patrol drove them off. The healers did what they could, but the arm never worked right again. Clownsteady doesn''t stare at the scars the way other settlements do.', ''),
        ('Clownsteaders', 'Served the Holy Nation as a kitchen drudge, never devout enough for the priests and always one misstep from the flames. Slipped away during a holy day procession when the guards were deep in their cups. The old prayers still rise unbidden some mornings, which is the worst part.', ''),
        ('Clownsteaders', 'Was a pickpocket in the streets of Heft until the wrong pocket belonged to a samurai''s wife. The beating nearly killed her, and the city watch would have finished the job. Clownsteady has no long arm of the law, which is the only reason she still draws breath.', ''),
        ('Crab Raiders', 'Grew up scraping barnacles off hulls in a coastal slum until a Crab Raider crew offered better pay and thicker armor. Now raids inland settlements wearing shell-plate that still smells of the sea.', ''),
        ('Crab Raiders', 'Formerly a stone miner who lost everything to bandits and fled to the coast looking for revenge. The Crab Raiders gave her a rusted halberd and a purpose, and she has not looked back since.', ''),
        ('Crab Raiders', 'Born into the raiders and taught to fight before he could swim properly. Knows nothing of peace, only the tide of violence that brings food and loot back to camp.', ''),
        ('Crab Raiders', 'Escaped from a Holy Mine after ten years of backbreaking labor and stumbled half-starved into a Crab Raider patrol. They fed him and handed him a club, and now he takes his anger out on every caravan that passes.', ''),
        ('Crab Raiders', 'A former fisher whose boats were destroyed by Beak Thing raids, leaving her with nothing but debts. Joined the Crab Raiders to afford a new life, one bloody haul at a time.', ''),
        ('Crab Raiders', 'Crafted crab shell armor for the raiders as a captive artisan before being formally accepted into the crew. Still mends shells by the fire, but now fights alongside those she once armed.', ''),
        ('Crab Raiders', 'Lost a farm to tax collectors in the United Cities and wandered the wastes until the raiders found him. Took to their brutal lifestyle faster than expected, driven by bitterness and hunger.', ''),
        ('Crab Raiders', 'A disgraced samurai who abandoned Okran''s Shield when the orders contradicted her conscience. The Crab Raiders do not care about past allegiances, only that her blade swings true.', ''),
        ('Crab Raiders', 'Recruited from a starving village where the choices were slavery or the raiders. Has survived three seasons of coastal raids and earned enough respect to pick from the loot first.', ''),
        ('Crab Raiders', 'Once traveled the trade routes as a humble pack animal handler before raiders killed his employers. He picked up a fallen weapon and kept fighting, eventually wearing the crab shell himself.', ''),
        ('Crab Raiders', 'Grew up scraping barnacles off hulls in the Bonefields before a rival clan burned the family boat. Joined the Crab Raiders because they were the only ones who didn''t care about past allegiances, only present ruthlessness.', ''),
        ('Crab Raiders', 'Was a slave in the Holy Mines for eleven years before escaping into the swamps. The Crab Raiders found her half-drowned and offered a simple choice: serve or die. She chose to serve, and now takes particular pleasure in raiding Holy Nation caravans.', ''),
        ('Crab Raiders', 'Never knew any life outside the raiders, born to a mother who fought with a rusted crab claw until her dying day. Learned to swim before learning to walk, and considers the coastal storms a blessing rather than a curse.', ''),
        ('Crab Raiders', 'Former United Cities soldier who deserted after being ordered to execute starving peasants. Fled south and traded military tactics for shelter among the Crab Raiders, who value competence over loyalty to distant empires.', ''),
        ('Crab Raiders', 'Lost both legs below the knee to a skin spider attack in the swamp flats. The raiders fitted him with crude prosthetics and gave him work maintaining their armor stockpiles, a task he performs with quiet, methodical devotion.', ''),
        ('Crab Raiders', 'A Skimmers daughter who watched her family''s outpost get swallowed by the acidic tides. Wandered the coast for weeks before the Crab Raiders picked her up, half-starved but still clutching her father''s rusted blade.', ''),
        ('Crab Raiders', 'Spent a decade as a fisherman on the inland sea, until overfishing and pollution destroyed the catches. The transition to raiding felt natural, taking from those who still had something worth taking.', ''),
        ('Crab Raiders', 'Captured during a raid on a Tech Hunter caravan, she proved her worth by killing three of her captors'' enemies during a surprise attack by beak things. Earned her place through violence and has never looked back.', ''),
        ('Crab Raiders', 'Once a student at the University of Stack, expelled for stealing research materials to sell on the black market. The Crab Raiders tolerate his eccentricities because he can keep their crumbling equipment functioning.', ''),
        ('Crab Raiders', 'Survived a Holy Nation purge that claimed her entire village, wandering the wilderness for months with nothing but a sharpened bone. The raiders found her feral and near death, and she has since become one of their most ferocious fighters.', ''),
        ('Crab Raiders', 'Was a plantation overseer in the United Cities until a slave revolt left him scarred and disgraced. Fled to the Crab Raiders where his cruelty could flourish without pretense of civilization or law.', ''),
        ('Crab Raiders', 'A cripple from birth, abandoned at the swamp''s edge by parents who couldn''t afford another mouth. The Crab Raiders raised him as one of their own, and he repays them with fanatical devotion and an intimate knowledge of the coastal tide patterns.', ''),
        ('Crab Raiders', 'Born into the raiders, she has never known any life beyond the stench of the swamp and the thrill of the raid. Her mother taught her to wield a blade before she could walk properly, and she has claimed more bounties than she can count.', ''),
        ('Crab Raiders', 'A former Shinobi Thief who botched a high-profile assassination and fled into the swamps to escape retribution. The Crab Raiders offered sanctuary in exchange for her skills in stealth and infiltration, an arrangement that has served both parties well.', ''),
        ('Crab Raiders', 'Lost his entire family to a skimmer attack while traveling the coast, the survivors guilt gnawing at him until he found purpose with the raiders. The violence of raiding silences the memories, if only temporarily.', ''),
        ('Crab Raiders', 'Once a skilled mechanic in the Machinists guild, she grew tired of fixing the same ancient machinery for ungrateful clients. The Crab Raiders pay better and actually appreciate someone who can keep their crab armor from falling apart mid-battle.', ''),
        ('Crab Raiders', 'A desert dweller from the borderlands who wandered into the swamp half-dead from thirst and starvation. The raiders took pity on him, and he discovered that the wetlands suited him far better than the arid wastes ever did.', ''),
        ('Crab Raiders', 'Sold into slavery as a child for debts inherited from a dead father, he escaped during a transport through the swamp. The Crab Raiders found him half-drowned and offered vengeance against a world that had only ever taken from him.', ''),
        ('Crab Raiders', 'A former guard for the Traders Guild who watched her employers sell out their own caravans to save their profits. Disillusioned with the so-called civilization of the cities, she found honesty in the raiders straightforward predation.', ''),
        ('Crab Raiders', 'Grew up as a swamp rat, scavenging ruins and dodging blood spiders since before she could speak properly. The Crab Raiders were simply the next logical step for someone who had been surviving by taking what she could find anyway.', ''),
        ('Deadcat', 'Grew up in the Floodlands learning to trap bloodspiders before they could trap you. The tribe took what they needed from drowned ruins and kept moving. Now stands watch at the outpost, spear ready, waiting for the next meal to wander close.', ''),
        ('Deadcat', 'Former Hired Sword who got sick of dying for merchants too cheap to pay a proper wage. Found the Deadcat when a job went bad and the swamp swallowed the rest of the squad. Stays because nobody asks questions about what you did before the water took everything.', ''),
        ('Deadcat', 'Born after the fall, never knew the old cities as anything but skeleton and silt. Learned to read the water currents to find salvage before the skimmers did. Keeps a mental map of every useful wreck within two days'' walk.', ''),
        ('Deadcat', 'Escaped a Holy Nation labor camp with nothing but the brand on the chest and a stolen sword. The Deadcat found half-drowned on the riverbank and dragged the body ashore. Earned the place among them by cutting down a pack of river raptors the very next week.', ''),
        ('Deadcat', 'Used to run supplies for the Trader''s Guild until the tolls ate all the profit. Started walking the flood routes alone, selling to whoever had the most cats. The Deadcat respected a person who showed up dry and armed, so the arrangement stuck.', ''),
        ('Deadcat', 'Lost the family farm to tax collectors, then lost the family to a Beak Thing raid. Walked into the Floodlands expecting to die and instead found people just as angry and broken. Hunts the big birds now with a personal grudge that pays for everyone''s dinner.', ''),
        ('Deadcat', 'Was a skin-bandit''s captive for three months before chewing through the rope. Stumbled into Deadcat territory half-mad and raving. The mind never quite healed but the hands still grip a machete well enough to earn a share of the kill.', ''),
        ('Deadcat', 'Served on a barque hauling iron until it sank in a storm and the crew ate each other waiting for rescue. Swam ashore and swore off boats forever. The Floodlands are dry land compared to that hell, and the Deadcat ask nothing of the past.', ''),
        ('Deadcat', 'Learned to fight in the Shek Kingdom but lacked the stature for respect among the warriors. Drifted south seeking a place where survival mattered more than glory. The Deadcat don''t care about strength, only whether you pull your weight when the water rises.', ''),
        ('Deadcat', 'Spent years as a ruins-diver, pulling ancient tech from flooded basements for any buyer. Got tired of selling everything for a fraction of its worth to fence bosses. Joined the Deadcat to keep what gets pulled from the muck and shoot anyone who disagrees.', ''),
        ('Deadcat', 'Born in the dust of the Border Zone, this survivor learned to spot cannibal trails before learning to read. After losing two siblings to the fogmen, they carry a bone-handled machete and sleep with one eye open. They stay with Deadcat because the alternative is becoming meat.', ''),
        ('Deadcat', 'A former Holy Nation peasant who fled when the inquisitors came for their neighbor. They found Deadcat''s indifference to gods and purity laws a relief after years of enforced zealotry. Now they scrape by salvaging copper and trying to forget the pyre they witnessed.', ''),
        ('Deadcat', 'Sold to slavers as a child for debts they never understood, this one earned their freedom after a raid scattered their captors. Wandering half-starved into Deadcat territory, they were taken in on the condition of pulling their weight. They guard the camp''s perimeter with obsessive vigilance.', ''),
        ('Deadcat', 'This old scavenger has crawled through more ruins than most Deadcat members have seen. They remember when the Border Zone had a few more standing structures and a few less cannibals. Age has slowed their hands but sharpened their instincts for finding salvage others overlook.', ''),
        ('Deadcat', 'A former mercenary who got too old and too injured for proper company work. Deadcat offered no wages but asked no questions about the things done in service to wealthy employers. They teach the younger members which end of a sword to hold and which way to run.', ''),
        ('Deadcat', 'Raised by Deadcat after being found wandering the wastes as a toddler, this member knows no other life. They have never traveled beyond sight of the camp''s watchfires and feel a superstitious dread about leaving. Their loyalty to the group is absolute, born of knowing nothing else.', ''),
        ('Deadcat', 'Once a trader running goods between the Shek Kingdom and the Holy Nation, bandits took everything and left them for dead. Deadcat found them half-eaten by wolves and patched them together with salvaged medical supplies. They dream of rebuilding their caravan but know the wastes have no place for dreams.', ''),
        ('Deadcat', 'This fisherman''s hands are calloused from gutting the meager catch pulled from polluted waters. They joined Deadcat after their riverside village was swallowed by Beak Thing territory. The group tolerates them because even terrible fish is better than no food at all.', ''),
        ('Deadcat', 'A reformed cannibal who still struggles with the hunger, they came to Deadcat seeking a way to live without preying on others. The group watches them carefully and keeps them away from the cooking fires. They fight with a ferocity born of self-loathing and desperate gratitude.', ''),
        ('Deadcat', 'Escaped from a United Cities work camp after a sandstorm buried the guards, this survivor walked three weeks without food. Deadcat was the first group that didn''t try to enslave or eat them on sight. They harbor deep resentment toward nobles and their hired swords.', ''),
        ('Deadcat', 'This young scavenger lost both parents to a skin spider nest and was raised by the community collectively. They possess an unnatural calm around corpses and ruins that unsettles even fellow Deadcat members. They believe the Old Empire left something beneath the Border Zone worth finding.', ''),
        ('Deadcat', 'A disgraced Shek warrior who fled rather than face ritual scarring for cowardice, they found Deadcat''s lack of honor culture strangely comforting. They still train daily with old habits hard to break. The others tolerate their foreign ways because their strength has saved the camp twice over.', ''),
        ('Deadcat', 'A former Holy Nation farmer who was branded a heretic for questioning the teachings after their family died of plague while praying. They fled before the inquisitors could claim them and stumbled into Deadcat half-starved. They still whisper old prayers at night but no longer believe anyone is listening.', ''),
        ('Deadcat', 'This mechanic spent years maintaining machinery in a United Cities slave camp until a faulty lock gave them a chance to disappear. Deadcat values their ability to keep ancient generators running and patch ruined armor with scrap metal. They never talk about the scars on their back but work tirelessly to ensure no one else wears chains.', ''),
        ('Deadcat', 'Born in the Fog Islands, this survivor watched fogmen drag away their siblings one by one before fleeing south. The Border Zone felt almost safe by comparison and Deadcat offered shelter without demanding tribute. They sleep with one eye open and a rusted blade beneath their pillow.', ''),
        ('Deadcat', 'A failed Hiver prince whose hive rejected them for weakness, they wandered the wilderness until Deadcat took pity on the starving drone. They have no skills beyond menial labor but work without complaint. Sometimes they stand at the edge of camp staring north as if hearing a call they cannot answer.', ''),
        ('Deadcat', 'This aging fighter once served as a guard for a minor UC trading house until their employer sold them out to slavers to cover a debt. They killed two guards escaping and have been running ever since. Deadcat provides anonymity and they ask for nothing more.', ''),
        ('Deadcat', 'A Skin Bandit victim who lost an arm to the raiders and barely escaped with their life. Deadcat found them delirious from blood loss and fashioned a crude hook to replace the missing limb. They volunteer for every patrol hoping to cross paths with their attackers again.', ''),
        ('Deadcat', 'This former worker from a UC pleasure house bought their freedom only to discover freedom meant starving without protection. They joined Deadcat after a samurai patrol beat them for lacking travel papers. They have learned to fight dirty and trust no one in authority.', ''),
        ('Deadcat', 'A Greenlander who fled the Holy Nation after being caught sheltering a skeleton traveler. The experience shattered their faith in the flame and left them bitter toward all religious certainty. They keep their head down in camp but argue violently against any mention of Okran.', ''),
        ('Dust Bandits', 'Grew up a sharecropper in the borderlands until tax collectors took everything. Took to the dunes with a stolen sword and never looked back. Survives by hitting supply caravans before vanishing into the sandstorm trails.', ''),
        ('Dust Bandits', 'Once a guard for a minor trading house, let a bribe slip and got a hand cut off for the mistake. The desert bandits took in the cripple when no one else would. Now works the ambush lines, trusting the dust to cover what the missing hand cannot.', ''),
        ('Dust Bandits', 'Starved off a failed homestead in the great basin and wandered half-dead into a bandit camp. They fed the wasted stranger on one condition. Has been repaying that debt in blood and stolen goods ever since.', ''),
        ('Dust Bandits', 'Sold into bondage as a child for debts not theirs. Killed the owner with a rock during a sandstorm and ran blind into the wastes. The Dust Bandits found the half-mad wanderer and gave the broken soul a new family built on violence.', ''),
        ('Dust Bandits', 'A former mine worker who collapsed in the tunnels and was left for dead by the overseers. Crawled out days later with lungs full of dust and a permanent grudge. Now waylays any convoy flying a trader flag.', ''),
        ('Dust Bandits', 'Born to a bandit mother who died on a raid when the child was barely ten. Learned to fight by surviving the aftermath of failed ambushes. Knows every canyon and dead gulch in the dust belt, and uses that knowledge to corner prey.', ''),
        ('Dust Bandits', 'Ran away from a holy settlement after refusing to bear the brand. Lived off carrion and stolen rations for a season before a Dust Bandit scout saw the potential in a runner that never stopped. Specializes in flanking and cutting off escape routes during raids.', ''),
        ('Dust Bandits', 'Lost a sibling to slavers who raided their village in the dry season. Tracked the caravan for weeks but arrived too late, finding only bones. Joined the bandits to ensure no trader passes through the dust unmolested, viewing every haul as delayed justice.', ''),
        ('Dust Bandits', 'A disgraced soldier who fled a losing border skirmish rather than die for a forgotten cause. The desert stripped away rank and loyalty until only the instinct to survive remained. Fights with military precision but for no flag other than the next meal.', ''),
        ('Dust Bandits', 'Once cooked for a noble house until a poisoned dish killed a visiting diplomat. Fled into the wastelands with a price on their head, finding safety only among outlaws. Serves the camp as both cook and poisoner, tainting water supplies before raids.', ''),
        ('Dust Bandits', 'The farm dried up and the tax collectors still came. Took to the roads with nothing but a rusty blade and a grudge against anyone who still had food. Been taking from travelers ever since. The desert doesn''t forgive weakness, and neither does this crew.', ''),
        ('Dust Bandits', 'Escaped a slave camp in the Hook with iron still ringed around the wrists. The Dust Bandits found me half-dead from thirst and offered a simple choice: carry a sword or carry a pickaxe back in chains. I chose the sword. Now the only chains I wear are loyalty to the gang.', ''),
        ('Dust Bandits', 'Used to run trade routes between the border zones until a pack of Beak Things tore apart the caravan. Lost the goods, lost the guards, and the merchant guild sent collectors instead of condolences. Banditry pays better than honest work when honest work leaves you starving.', ''),
        ('Dust Bandits', 'Born into a Dust Bandit camp and never knew anything else. Ma taught me how to spot a weak traveler, and Pa taught me how to cut them down. The desert is home, and the road is a larder. Don''t know what I''d do if this life ever ended.', ''),
        ('Dust Bandits', 'Served in the United Cities army until a commander decided my squad was expendable. We were supposed to hold a pass against cannibal raiders with six men and dull spears. I was the only one who walked out. The Empire can burn, and I''ll help light the match from out here in the dust.', ''),
        ('Dust Bandits', 'The Holy Nation burned my village for the crime of existing near their borders. They called us heretics and drove us into the wastes to die. The Dust Bandits took me in when the so-called faithful cast me out. Now I show every passing pilgrim the same mercy I was shown.', ''),
        ('Dust Bandits', 'A Skin Spider nest took my family''s homestead. I came back from gathering water to find nothing but webs and bones. Wandered the desert for weeks until the bandits picked me up. Killing strangers fills the hole, but it never quite closes it.', ''),
        ('Dust Bandits', 'Ran with the Starving Bandits for a while but they were pathetic, always hungry, always dying. The Dust Bandits actually know how to set an ambush and strip a caravan clean. Switched crews two years ago and never looked back. Competent allies make for better survival.', ''),
        ('Dust Bandits', 'Was a mechanic in a border town until the shop got pressed into paying protection to the Traders Guild. Couldn''t afford the fees and couldn''t afford to leave. The Dust Bandits needed someone who could keep their gear from falling apart. My hammer serves two purposes now.', ''),
        ('Dust Bandits', 'Killed a noble''s son in a bar fight back in the cities. Didn''t matter that he drew first, didn''t matter that he was drunk. The price on my head left the roads as my only home. The bandits don''t care about bounties or bloodlines, only if you can fight.', ''),
        ('Dust Bandits', 'Spent years scavenging ruins and selling scraps to trading caravans for pennies. Watched the merchants grow fat while I crawled through collapsed towers for rusted copper. Eventually realized the real profit was in taking what others had already claimed. The dust treats everyone equally, but the strong take more.', ''),
        ('Dust Bandits', 'A drought killed the goats, and then the reavers killed the neighbors. There was nothing left in that border settlement but starvation and waiting for the next raid. The Dust Bandits rode through one evening and I simply followed them out. Better to be the one taking than the one being taken from.', ''),
        ('Dust Bandits', 'Was sold to the Holy Nation as a laborer after being caught crossing their borders. Spent three years breaking rocks until a Dust Bandit raid freed me along with the other workers. Didn''t hesitate when they offered me a blade instead of a chain. I''ll die before I wear shackles again.', ''),
        ('Dust Bandits', 'Served under a United Cities samurai captain who threw our squad into a suicide charge against Beak Things. Watched my friends get torn apart for a patrol route nobody cared about. Deserted that night and walked into the desert with nothing but my sword. The bandits respect strength, not titles, and that suits me fine.', ''),
        ('Dust Bandits', 'Grew millet on a plot my family worked for three generations until the tax collectors decided we owed a decade of back pay. They burned the farm when we couldn''t pay and dragged my father to the slave pits. I found the Dust Bandits by following the smoke from our fields. Now I collect taxes of my own, paid in blood.', ''),
        ('Dust Bandits', 'Used to run supplies between Waystations until my partners sold me out to slavers to cover their own debts. Escaped during a sandstorm that killed my captors, but my reputation and coin were gone forever. The Dust Bandits don''t ask about your past, only what you can carry. Commerce is simpler when you take what you need.', ''),
        ('Dust Bandits', 'Did time in a United Cities prison for stealing bread, which taught me more about crime than the streets ever did. Met thieves, killers, and outcasts who showed me how the world really works. Broke out during a riot and headed straight for the borderlands. Prison taught me one lesson: the weak get eaten, and the strong do the eating.', ''),
        ('Dust Bandits', 'Was a warrior in a minor Shek clan until I retreated from a battle we couldn''t win. My own people called me coward and cast me out, though I still walk with my life. The Dust Bandits don''t care about honor or dying gloriously. They care about surviving, and so do I.', ''),
        ('Dust Bandits', 'Don''t remember my parents, just the streets of a border town where I learned to steal before I could read. Got caught too many times and the town guard started hunting me. A Dust Bandit scout found me half-dead in a ditch and brought me to camp. These people are the closest thing to family I''ve ever known.', ''),
        ('Dust Bandits', 'Used to work the salt flats until a Beak Thing colony moved in and ate half the settlement. The survivors scattered and nobody came to help us. A Dust Bandit crew passed through and I offered my services in exchange for food. Never went back to the coast and never will.', ''),
        ('Empire Peasants', 'Born to a family of cactus farmers on the outskirts of the Empire''s territory, this peasant learned early that the tax collectors take regardless of the harvest yield. A bad season left them with nothing but a rusty tool and the choice between starvation or selling themselves to the mines.', ''),
        ('Empire Peasants', 'Once a relatively prosperous grain farmer, everything changed when Okran''s Blade demanded a tithe far beyond what the drought-stricken soil could provide. Now they scrape by on whatever scraps remain after the nobles and priests have taken their share, dreaming of a life beyond the Empire''s reach.', ''),
        ('Empire Peasants', 'Raised in the shadow of a noble estate, this peasant spent their youth watching servants come and go while their own family struggled to fill a single bowl each day. They know every back path and hidden water source in the district, knowledge that keeps them alive but marks them as suspicious to the guards.', ''),
        ('Empire Peasants', 'A former weaver who lost their workshop to a fire set during a tax riot, they now wander between settlements offering cheap labor. The memory of smoke and screaming still haunts their sleep, and they flinch whenever they see the Empire''s colors.', ''),
        ('Empire Peasants', 'Conscripted once into a militia force meant to repel a Shek raid, they survived the battle only to return home and find their village burned by the very raiders the militia was supposedly fighting. The Empire offered no compensation, only a new tax to rebuild the lord''s damaged estate.', ''),
        ('Empire Peasants', 'This elderly peasant has outlived three spouses and seven children, each taken by famine, disease, or the Empire''s endless demands. They continue to work the same cracked earth their grandparents tended, too stubborn and too tired to seek a better life elsewhere.', ''),
        ('Empire Peasants', 'Sold to a farmer as an indentured servant at the age of ten to pay off a family debt, this peasant finally earned their freedom after fifteen years of backbreaking labor. The world outside the farm was no kinder, and they now wonder whether freedom is just another word for a different kind of starvation.', ''),
        ('Empire Peasants', 'A devout follower of Okran who truly believes suffering in this life earns reward in the next, they endure every hardship with quiet prayer. Even when the tax collector takes the grain meant for their sick child, they whisper thanks to the flame and obey.', ''),
        ('Empire Peasants', 'Displaced by border skirmishes between the Empire and the Shek Kingdom, this refugee now huddles in the slums of an Empire city where citizens view them as a nuisance. They retain a few practical skills from their old life but have learned to hide anything that might attract a tax collector''s greedy eye.', ''),
        ('Empire Peasants', 'Once a fisher along the coast, bandits destroyed their boat and kidnapped their partner for the slave markets. They now work the dusty fields inland, far from the water they once loved, saving copper coins in the desperate hope of buying back what was stolen.', ''),
        ('Empire Peasants', 'Born to a family of grain farmers outside Sho-Battai, this peasant lost everything when the regional governor doubled the harvest tithe. Now they wander the imperial roads with nothing but a rusty hoe, searching for any work that pays in food rather than empty promises.', ''),
        ('Empire Peasants', 'A former dockworker in the capital, they fled the city after a Samurai officer accused them of stealing cargo to cover his own corruption. They survive by carrying water for caravans, always keeping their head down when armored patrols pass.', ''),
        ('Empire Peasants', 'Sold by their parents at age seven to pay off a gambling debt, they spent fifteen years laboring in a noble''s hemp plantation before escaping during a Holy Nation raid. The brand on their neck marks them as property, making every imperial checkpoint a potential death sentence.', ''),
        ('Empire Peasants', 'This peasant once owned a small rice patty near Brink, until slavers took their spouse and children for falling three seasons behind on taxes. They wander the wasteland now, half-starved and muttering prayers to Okran that nobody listens to.', ''),
        ('Empire Peasants', 'Raised in the gutters of Heft, they learned to read by stealing scraps of parchment from the nobles'' trash. They make a meager living writing letters for other peasants, though the Samurai view anyone with education among the lower classes with suspicion.', ''),
        ('Empire Peasants', 'A coppersmith''s apprentice who watched their master executed for failing to fulfill a weapons contract on time. With no guild protection and a price on their head for the unfinished debt, they fled to the remote villages hoping to vanish among the desperate.', ''),
        ('Empire Peasants', 'This aging peasant spent their entire life hauling stone blocks for imperial construction projects, their body now a map of old injuries and broken bones. Too worn down to continue manual labor, they beg in the shadow of the very walls they helped build.', ''),
        ('Empire Peasants', 'Once a proud owner of a small sake brewery, they were driven into destitution when a samurai clan demanded exclusive rights to their recipe without payment. They now scrap by gathering desert shrubs for medicinal tea traders, dreaming bitterly of revenge against the clan that ruined them.', ''),
        ('Empire Peasants', 'A survivor of a cannibal raid on their border village, they carry the physical and mental scars of watching their community devoured. The imperial garrison refused to send aid, citing the village''s failure to pay protection fees, leaving them with a deep hatred for the throne.', ''),
        ('Empire Peasants', 'This young peasant never knew their parents, raised instead by an aging prostitute in a border town brothel. When the madam sold them to a passing labor crew, they escaped into the desert and now survive by scavenging battlefield scraps left behind by Samurai patrols.', ''),
        ('Empire Peasants', 'A former fisher along the great river, they lost their boat and nets to a corrupt tax collector who claimed their fishing license was invalid without a costly renewal. Stranded far from water, they now work whatever fields will take them, their calloused hands still instinctively knotting invisible nets.', ''),
        ('Empire Peasants', 'Displaced by the endless wars between the Empire and the Holy Nation, this peasant has fled burning villages three times in as many years. They carry everything they own in a single worn sack, trusting no authority and sleeping with a sharpened farming sickle tucked beneath their thin blanket.', ''),
        ('Empire Peasants', 'This farmer''s fertile plot was seized by a provincial governor to build a private estate, leaving them with nothing but rocky hillside. They now work the very soil that was stolen from them, earning a pittance to grow food they will never taste.', ''),
        ('Empire Peasants', 'Once a skilled weaver in a thriving village, their loom was destroyed when samurai commandeered their workshop to quarter troops during a border skirmish. They now mend ragged clothing for other destitute peasants, their fine stitches wasted on fabric barely worth saving.', ''),
        ('Empire Peasants', 'This peasant lost two sons to imperial conscription, receiving only a sealed scroll of gratitude in return. They work their small field alone now, too hollowed by grief to weep and too stubborn to starve.', ''),
        ('Empire Peasants', 'A former kitchen servant in a regional governor''s household, they were cast into the street when age slowed their hands. Years of preparing lavish feasts left them with knowledge of fine cuisine but no coin to buy even a bowl of rice porridge.', ''),
        ('Empire Peasants', 'Born to a family of charcoal burners in the borderlands, they watched their forest home cleared for imperial timber operations. Without trees to carbonize, they wander between towns hauling scrub brush for meager copper.', ''),
        ('Empire Peasants', 'This peasant''s spouse was executed for poaching after catching a fish from the governor''s private stream to feed their feverish child. The child died anyway within the fortnight, and now they drift through imperial lands feeling nothing but a quiet, directionless rage.', ''),
        ('Empire Peasants', 'A former street vendor who sold herbal remedies until the Trader''s Guild demanded licensing fees far beyond their means. Branded a fraud by the authorities, they now trade small favors and rumors just to secure a dry corner to sleep in.', ''),
        ('Empire Peasants', 'They once maintained irrigation channels for a prosperous farming community until a rival village bribed imperial officials to redirect the water flow. Their neighbors scattered across the desert, and they remain alone trying to coax meager turnips from dust.', ''),
        ('Flotsam Ninjas', 'Escaped a Holy Nation labor camp after a storm broke the perimeter fence. Wandered half-starved through the Swamp until a Flotsam patrol found him. Now he repays that debt by teaching new recruits how to survive on nothing.', ''),
        ('Flotsam Ninjas', 'She was born into slavery inside Rebirth and never knew freedom until a Flotsam raid freed her. The ninjas became the family she never had. She fights fiercely because she knows exactly what awaits those who are recaptured.', ''),
        ('Flotsam Ninjas', 'A former thrall of the United Cities, he bought his freedom through years of pit fighting. The skills translated poorly to honest work but perfectly to the Flotsam cause. He specializes in ambushing slaver caravans in the mist.', ''),
        ('Flotsam Ninjas', 'Her parents were fisherfolk in the Swamp who sheltered escaped slaves until slavers burned their home. She joined Flotsam to continue their work with blade in hand. She trusts no one outside the village and sleeps with a crossbow within reach.', ''),
        ('Flotsam Ninjas', 'He served as a low-level Holy Nation overseer until he witnessed the butchery of a Skinner camp and could no longer pretend his faith was just. Deserted everything and fled south seeking redemption. Some in the village still eye him with suspicion.', ''),
        ('Flotsam Ninjas', 'Sold into bondage as a child over unpaid family debts in the UC. Spent years rowing a slaver barge before a Flotsam raid freed the entire crew. Took up the ninja arts late in life but her raw determination compensates for rough technique.', ''),
        ('Flotsam Ninjas', 'Grew up wild in the Swamp after being abandoned by a slave caravan that could not feed another mouth. Learned to move silently and live off the land long before Flotsam found her. She scouts the waterways and knows every safe path through the reeds.', ''),
        ('Flotsam Ninjas', 'He never knew a master but watched slavers take his siblings when he was small. Joined Flotsam as a teenager because they were the only ones who fought back. Now he risks his life guiding runaways through the dangerous border lands.', ''),
        ('Flotsam Ninjas', 'A former barmaid in a UC border town who overheard too many slaver dealings. When she reported them to the corrupt guards, they sold her instead. Flotsam freed her within a week and she vowed never to be helpless again.', ''),
        ('Flotsam Ninjas', 'Lost a hand to a Skinner trap while fleeing a collapsing mine. The village blacksmith fashioned a crude hook that serves well enough for climbing and fighting. He patrols the perimeter now, the first to spot trouble approaching through the fog.', ''),
        ('Flotsam Ninjas', 'Escaped a Holy Nation labor camp after watching her sisters sold off to Okranite farmers. Spent two years crossing the wasteland with nothing but a stolen sword before finding the Flotsam. She fights now so other women never have to endure what she did.', ''),
        ('Flotsam Ninjas', 'Born into the faction, she knows no other life than the struggle against the Holy Nation''s patrols. Learned to move silently through swamp water before she could read. The cause is not a choice for her, it is simply existence.', ''),
        ('Flotsam Ninjas', 'A former servant in a United Cities noble house who fled after killing a guard who got too comfortable with his assumptions. The Flotsam took her in when no one else would have a killer with no coin. She has learned to channel her anger into blade work rather than reckless violence.', ''),
        ('Flotsam Ninjas', 'Lost her farm to Holy Nation purgers who declared her land tainted by shek influence. Wandered the borderlands for months, half-starved and bitter, until a Flotsam patrol found her asleep against a rock. Now she raids Okranite supply lines with particular enthusiasm.', ''),
        ('Flotsam Ninjas', 'Trained as a thief in the Hook''s back alleys before a bad job left her bleeding in an alley. A Flotsam scout patched her wounds and offered purpose beyond mere survival. She still picks locks, but now it is for the faction''s needs rather than her own stomach.', ''),
        ('Flotsam Ninjas', 'Her mother was a Flotsam veteran who retired quietly to a border village, only to be dragged out and burned by passing Inquisitors. She tracked the patrol for three weeks before butchering them in their sleep. Has been with the Flotsam ever since, seeking no pardon and offering no quarter.', ''),
        ('Flotsam Ninjas', 'Defected from the Shek Kingdom after growing tired of being treated as a breeding asset rather than a warrior. The Flotsam offered something the Shek never could, a fight where she stood as equal rather than property. She still favors the heavy blade techniques of her homeland over stealth.', ''),
        ('Flotsam Ninjas', 'A former Holy Nation paladin who began reading forbidden texts and asking dangerous questions about Okran''s doctrine. Fled when her questions attracted the attention of an Inquisitor, leaving everything behind. She knows the enemy''s methods from the inside, which makes her both valuable and distrusted.', ''),
        ('Flotsam Ninjas', 'Survived a slave caravan wreck in the Grey Desert and walked for days with shackles still chafing her wrists. A Flotsam cell cut her free and gave her a blade the same day. She wears the scarred wrists openly as a reminder of what the Holy Nation does to people like her.', ''),
        ('Flotsam Ninjas', 'Once ran a small trading post that was burned to ash by Holy Nation fanatics for serving non-human customers. Had no combat skills and no money when the Flotsam found her begging in a border town. They taught her to fight, and she now handles supply logistics between cells.', ''),
        ('Flotsam Ninjas', 'Left the Swamp Ninjas after deciding their isolationist ways served no one but themselves. The Flotsam''s active resistance appealed to her sense that survival without purpose is merely slow death. She bridges the two factions'' techniques, blending swamp stealth with guerrilla warfare.', ''),
        ('Flotsam Ninjas', 'A fisherman''s daughter whose village was conscripted and drained by United Cities tax collectors until nothing remained. Fled west looking for freedom and found only different masters until the Flotsam took her in. She believes all empires are the same disease wearing different masks.', ''),
        ('Flotsam Ninjas', 'Escaped a Holy Nation work camp after a storm collapsed the perimeter wall and fled barefoot through the desert. A Flotsam patrol found her delirious from heat and half-dead from thirst. She now scouts the arid stretches between cells, reading the weather better than any map.', ''),
        ('Flotsam Ninjas', 'Grew up in a United City slum where girls disappeared into noble houses and were never seen again. Learned to use a blade defending herself in the gutter before the Flotsam ever found her. She treats every noble estate as a legitimate target and feels no remorse about lightening their coffers.', ''),
        ('Flotsam Ninjas', 'A former Holy Nation prayer maiden who realized the scriptures she memorized were tools of control, not paths to salvation. Slipped away during a pilgrimage and ran until her feet bled. She still knows the holy texts by heart and uses that knowledge to undermine the faith she once served.', ''),
        ('Flotsam Ninjas', 'Spent years as a caravan guard who watched her employer sell wounded travelers to slavers for extra coin. Objected loudly and got a knife across the ribs for her trouble. The Flotsam cell that nursed her back to health gave her a cause worth guarding.', ''),
        ('Flotsam Ninjas', 'Born to nomads who wandered the storms of the Stormgap Coast until bandits scattered the family. Survived alone for a full season before a Flotsam safehouse took her in. She navigates the storms like others navigate roads and volunteers for every supply run no one else dares attempt.', ''),
        ('Flotsam Ninjas', 'A former Blackshift washer who inhaled enough toxic fumes to scar her lungs and harden her resolve. Left the Swamp when the bosses started treating workers as disposable as the rags they cleaned. She fights with the grim patience of someone who expects nothing and endures everything.', ''),
        ('Flotsam Ninjas', 'Rescued from a Holy Nation pyre after being accused of witchcraft for knowing which herbs stop infection. The burns on her arms still ache when the weather turns cold. She serves as the cell''s herbalist and keeps meticulous notes on every remedy she encounters.', ''),
        ('Flotsam Ninjas', 'A canal farmer in Reaver territory whose crops were taken as tribute until her children starved. Walked north with nothing but a sharpened hoe and a hatred for anyone who preys on the weak. The Flotsam gave her real weapons and targets that deserve them.', ''),
        ('Grass Pirates', 'Grew up tending hemp fields for a Holy Nation landowner before the tithes grew so heavy that starvation became a certainty. Slipped away one night with nothing but a stolen sickle and joined the first band that would take a desperate farmer. The sickle is long gone, replaced by a rusted katana and a willingness to rob anyone who looks softer than the life left behind.', ''),
        ('Grass Pirates', 'Lost a leg below the knee to a skin spider while traveling the swamp roads as a merchant guard. The caravan left her behind and the Grass Pirates found her half-dead in the mud. They gave her a peg leg and a place in the ranks, and now she limps through the tall grass setting traps for passing traders.', ''),
        ('Grass Pirates', 'Never knew any life but the outlaw camps, born to a pirate woman who died raiding and raised by whichever band would feed a stray child. Learned to read the grasslands and spot dust clouds from miles off, a skill that keeps the band fed and occasionally wealthy. The closest thing to family is the gang itself, and betrayal is the only true crime left.', ''),
        ('Grass Pirates', 'Fled the United Cities after killing a tax collector who came for one levy too many from an already starving neighborhood. The Grass Pirates were the only faction that did not ask for papers or lineage, only a willingness to bleed and steal. Still carries guilt over those left behind in the city, buried under layers of necessary cruelty.', ''),
        ('Grass Pirates', 'A failed Holy Nation zealot who could not stomach the purges but knew nothing besides swinging a weapon. Wandered the border zones until hunger forced a choice between dying honest or living dirty. The Grass Pirates do not care about past sins or missing faith, only that a blade is steady when it matters.', ''),
        ('Grass Pirates', 'Once ran a modest rice farm in the borderlands until a Shek raid burned the fields and scattered the family across the wasteland. Spent two years searching for a missing daughter before the trail went cold and the money ran out. Now raids the same roads where the search ended, taking out grief on strangers who still have something to lose.', ''),
        ('Grass Pirates', 'Joined the Grass Pirates as a young runaway seeking freedom from a life of crushing labor in a United Cities mine. The romance of outlawry faded fast when the first ambush ended with a friend bleeding out from a crossbow bolt. Still, eating stolen bread beats dying underground, and there is no going back to the pits.', ''),
        ('Grass Pirates', 'A former street thief from Catun who graduated to highway robbery after a botched job made the city too hot to stay in. The Grass Pirates offered numbers and safety that a lone cutpurse could never manage. Specializes in scouting ahead and identifying which caravans are worth the risk and which hide guards too skilled to challenge.', ''),
        ('Grass Pirates', 'Escaped from a slave camp in the Hook with iron scars still wrapped around both wrists, barely surviving the desert march to the border zones. The Grass Pirates found a half-dead skeleton clutching a stolen food pouch and offered a place by the fire. Has vowed never to be taken alive again and fights with the frenzy of someone who has already survived the worst.', ''),
        ('Grass Pirates', 'Served as a low-ranking samurai in the United Cities until a corrupt superior framed the entire squad to cover his own extortion ring. Fled rather than face execution and found the Grass Pirates surprisingly democratic compared to the army. Maintains a soldier''s discipline in camp, which irritates the older members but keeps raids organized enough to avoid disaster.', ''),
        ('Grass Pirates', 'Grew up a peasant in the United Cities, taxed into starvation by the nobles until there was nothing left to give. Took to the grasslands with a stolen sword and never looked back, finding the pirate life far more honest than the Empire ever was.', ''),
        ('Grass Pirates', 'Once a respected caravan guard until a Skimmer attack left the convoy destroyed and the merchant blamed the survivors for the losses. Blacklisted from the guard guilds, this former sword-for-hire drifted until the Grass Pirates offered a new pack.', ''),
        ('Grass Pirates', 'Born into a nomadic tribe that was wiped out by Holy Nation crusaders passing through the borderlands. The only survivor, a child then, was taken in by the Grass Pirates and raised on raiding and survival in the tall grass.', ''),
        ('Grass Pirates', 'A failed farmer from the borderlands whose crops withered three seasons straight while tax collectors still demanded full payment. Left the farmstead at night with a rusty machete and joined the first band that would share their spoils.', ''),
        ('Grass Pirates', 'Sold into slavery as a debtor in the United Cities, escaped during a transport ambush by the very pirates they now call family. The chain scars on their wrists serve as a constant reminder never to trust authority again.', ''),
        ('Grass Pirates', 'Used to run a small trading post until a Shek raid burned it to the ground and killed their partner. With nothing left to lose, they took up with the Grass Pirates, finding purpose in taking from a world that took everything from them.', ''),
        ('Grass Pirates', 'A former Holy Nation peasant who questioned the scriptures one too many times and faced the pyre for it. Fled south into the lawless grasslands, shedding their old name and taking up the blade alongside fellow outcasts.', ''),
        ('Grass Pirates', 'Spent years as a lone scavenger picking through battlefields and abandoned outposts, barely scraping by. The Grass Pirates found them half-starved in the brush and offered a place by the fire in exchange for a sharp eye and quick hands.', ''),
        ('Grass Pirates', 'The child of a Grass Pirate who died in a botched raid on a well-armed caravan. Inherited the old rusted blade and a grudge against anyone who travels the grasslands with more than they need.', ''),
        ('Grass Pirates', 'A former mine worker in the Swamps who saw too many friends collapse from exhaustion and toxic fumes. Slipped away during a rainy night and wandered the wilderness until a Grass Pirate patrol took them in, teaching them to take rather than break their back for others.', ''),
        ('Grass Pirates', 'Once a low-level enforcer for a Trader''s Guild operation, until they refused to shake down a starving village and got a knife in the gut for their conscience. A Grass Pirate medic patched the wound and offered a different kind of employment.', ''),
        ('Grass Pirates', 'Deserted from a Shek warband after growing tired of suicidal charges for the glory of dead heroes. The Grass Pirates care nothing for glory, only survival and the next meal, which suits this runaway warrior just fine.', ''),
        ('Grass Pirates', 'A United Cities peasant whose farm was seized by a noble over unpaid taxes, leaving them with nothing but a rusty sickle and burning resentment. Took to the grasslands where the long grass hides the desperate, and learned to take food rather than grow it.', ''),
        ('Grass Pirates', 'Escaped from a Reaver slave chain during a chaos storm, wandering half-delirious into the open plains. The Grass Pirates found them tracking mud and blood, and the newly freed soul figured stealing was better than being stolen from.', ''),
        ('Grass Pirates', 'Born under a leaky roof in a Border Zone outpost that eventually starved into nothing. Grew up wild and feral in the tall grass, barely human until a Pirate crew showed them that packs survive longer than lone wolves.', ''),
        ('Grass Pirates', 'A failed Tech Hunter initiate who cracked under the horrors of the Floodlands and deserted before earning their badge. The Grass Pirates ask no questions about cowardice, only whether a body can hold a blade and stand a post.', ''),
        ('Grass Pirates', 'Once ran a quiet smuggling route through the Swamps until Hounds moved in and carved up the territory. Fled with whatever cargo could be carried and fell in with the Pirates, who appreciate someone who knows how to move goods quietly.', ''),
        ('Grass Pirates', 'A former Skin Bandit victim who woke up in a cage missing two fingers and most of their hope. Escaped into the grasslands and joined the Pirates more out of a desire to never be prey again than any love for raiding.', ''),
        ('Grass Pirates', 'Sold a bad batch of sake to a Samurai patrol and fled the city before the execution order could be signed. The Pirates welcomed a brewer who can turn grain into courage, even if the courage tastes like ditch water.', ''),
        ('Grass Pirates', 'A disowned son of a Holy Nation family caught in relations with a Hiver, cast out with nothing but shame and scars. The grasslands care nothing for scripture, and the Pirates offer a strange kind of acceptance for those with nowhere else.', ''),
        ('Grayflayers', 'Born to starving swamp farmers, this recruit joined the Grayflayers after a flood destroyed what little remained. The steady meals and coin from bounties beat scrabbling in the mud any day.', ''),
        ('Grayflayers', 'A former slave who earned freedom through brutal obedience, now enforcing the same chain on others. Survival left little room for conscience in the swamps.', ''),
        ('Grayflayers', 'Recruited from a dying Holy Mine, this one abandoned the faith when the priests sold congregants to cover tithes. The Grayflayers offered cleaner work and honest pay.', ''),
        ('Grayflayers', 'Grew up watching skinners drag bodies through the marsh and decided early to hold the chain rather than wear it. The Grayflayers were a natural fit for someone with steady hands and no qualms.', ''),
        ('Grayflayers', 'Left a failing fishing village after blood spiders took half the family. The Flayers taught survival means making others suffer first, a lesson learned well.', ''),
        ('Grayflayers', 'Once a wandering swordsman who lost everything to bandits, this survivor found purpose capturing those same criminal scum for profit. The Grayflayers pay better than vengeance alone.', ''),
        ('Grayflayers', 'Sold by parents at age seven to a Hiver caravan, worked the cages until earning a place among the captors. Knows both sides of every shackle and prefers the key side.', ''),
        ('Grayflayers', 'A disgraced United Cities soldier who fled desertion charges into the swamp. The Grayflayers asked no questions and offered a blade with which to start over.', ''),
        ('Grayflayers', 'Raised in a border outpost where slavers were the only law, this recruit sees the trade as honest work. The swamp reeks, but silver spends the same anywhere.', ''),
        ('Grayflayers', 'After a Beak Thing mangled a leg beyond full healing, this former scavenger took up slaving as the only trade left. Hobbles through patrols with a grin and a ready net.', ''),
        ('Grayflayers', 'Grew up a scrapper in the borderlands, learning to fight before learning to read. Joined the Grayflayers after a Hound patrol burned the squatter camp to the ground. Now takes particular pleasure in raiding Holy Nation outposts, though the pay is rarely worth the blood.', ''),
        ('Grayflayers', 'Formerly a laborer in a United Cities workshop until a overseer''s whip left a permanent scar across the back. Fled into the grey wastes with nothing but a rusted blade and a taste for vengeance. The Flayers accepted the anger without question, and the anger has only grown since.', ''),
        ('Grayflayers', 'Born into the Flayers and never knew any other life. Learned to strip armor from corpses before turning twelve. Does not question the lifestyle because there is nothing else to imagine.', ''),
        ('Grayflayers', 'Once ran a small trading post along the western route, until tax collectors demanded more than the profit could bear. Watched everything get seized, then picked through the wreckage for whatever remained. The Grayflayers offered a new economy, one where taking is the only tax that matters.', ''),
        ('Grayflayers', 'A failed Holy Nation peasant who could never meet the tithe demands of the Phoenix''s priests. Branded a heretic for missing too many prayer days while working the fields. Found the Flayers more honest than the zealots, as they admit they are thieves.', ''),
        ('Grayflayers', 'Served as a low-ranking samurai in the Traders Guild security forces before a botched protection racket left them holding the blame. Deserted rather than face execution and wandered the wastes until hunger forced a choice. The Grayflayers were the first group that did not ask for credentials, only competence.', ''),
        ('Grayflayers', 'Lost a family to Skin Bandits and spent years hunting machines with obsessive fury. Eventually realized the Flayers shared the same hatred for anything that moves and takes. They still keep a collection of severed robot limbs as trophies mounted on their belt.', ''),
        ('Grayflayers', 'A former barfighter who killed a merchant''s son in a drunken brawl and fled before the bounty could be collected. The grey desert swallowed the past, and the Flayers gave the future a shape. Violence remains the only language that feels fluent.', ''),
        ('Grayflayers', 'Escaped from a Reaver slave ship with nothing but a sharpened spoon and a lot of resentment. Crawled across the grey wastes for days before a Flayer patrol found the collapsed body. Now repays that debt by bringing back fresh captives for the camps.', ''),
        ('Grayflayers', 'Trained as a mechanic in a Border Zone workshop before the owner sold the business to slavers. The new owners decided the skilled staff were part of the inventory. Escaped during a sandstorm, and the Flayers value someone who can keep their gear running.', ''),
        ('Grayflayers', 'A shepherd from the Stenn Desert who watched their entire flock stolen by passing mercenaries. With no animals left to tend and no village left to feed them, they tracked the raiders for weeks. The Flayers found the tracker first and offered better odds than revenge alone.', ''),
        ('Grayflayers', 'Washed out of the Shinobi Academy after failing the final loyalty test. Too soft for assassination, too clever for menial labor, too angry to go home. The Grayflayers offered a middle path where cleverness and anger have equal weight.', ''),
        ('Grayflayers', 'The salted earth of a border farm taught harder lessons than any master could. When the soil died and the creditors came, the choice was between a noose or the grey wastes. The Flayers offered a third option that kept food in the belly and a weapon in the hand.', ''),
        ('Grayflayers', 'Born to a nomadic family that wandered the Grey Desert for generations, surviving on what others discarded. A drought killed the goats and scattered the survivors across the sands. The Flayers took in what the desert nearly finished, and the skills learned in the wastes make for an excellent scout.', ''),
        ('Grayflayers', 'Served the Holy Nation as a low-ranking paladin until questions about Phoenix''s edicts led to an accusation of heresy. Fled south with nothing but the armor on their back and a price on their head. The Flayers don''t care about sermons, only results, and a former soldier knows how to deliver them.', ''),
        ('Grayflayers', 'Made a living picking through ruins until a Beak Thing nest ended the partnership that had lasted years. The desert doesn''t forgive grief, only buries it under necessity. Found the Flayers while tracking a trade caravan and decided the company of killers beat dying alone.', ''),
        ('Grayflayers', 'Ran a trading post on the edge of the Border Zone until bandits burned it down with the inventory inside. The debt owed to the Traders Guild doesn''t disappear just because the goods did. The Flayers move goods of a different sort now, and the profit margin on flesh beats dried meat by a wide margin.', ''),
        ('Grayflayers', 'Never knew any life outside the camps and patrol routes of the Grayflayers. Raised on captured rations and stories of the weak who became merchandise. The desert is home, and the screaming of new catches is as familiar as the wind.', ''),
        ('Grayflayers', 'Lost connection to the Hive when a patrol strayed too far into the Grey Desert''s dead zones. The silence in the skull nearly drove them mad before a Flayer squad found them wandering. Now takes orders from the camp bosses instead of Queen pheromones, and the work is surprisingly similar.', ''),
        ('Grayflayers', 'Watched a Shek warband burn through a fishing village on the coast, taking what they wanted and killing what they didn''t. Learned that day that the strong take and the weak are taken. The Flayers offered strength without the honor codes that Shek warriors pretend to follow.', ''),
        ('Holy Nation Outlaws', 'Born a servant in the holy fields, she fled after being caught teaching other women to read the holy texts for themselves. The paladins took her brothers as penance while she escaped into the wasteland. She now fights against the theocracy that stole her family, using the very scriptures they weaponized against her people.', ''),
        ('Holy Nation Outlaws', 'A former paladin who witnessed the purging of a shek child and could no longer justify the Phoenix''s edicts. He discarded his armor in the river and walked away from everything he knew. The guilt of his past service drives him to protect those the Holy Nation would see burned.', ''),
        ('Holy Nation Outlaws', 'Caught sheltering a wounded hiver drone during a sermon on purity, his farm was razed and his family scattered to the winds. He survived by eating bark and vermin for weeks before finding others who shared his exile. Now he raids holy supply caravans with a fury that worries even his companions.', ''),
        ('Holy Nation Outlaws', 'She was a temple seamstress who noticed the priests hoarding fine cloth while the faithful wore rags. A careless word to the wrong person earned her a brand as a heretic and a one-way trip to the wastes. The betrayal taught her that piety is just another currency the powerful spend freely.', ''),
        ('Holy Nation Outlaws', 'His skill with machines made him useful until the paladins found his workshop full of forbidden old-world artifacts. He barely escaped the burning with his tools and the burns across his back as a reminder. Every mechanism he repairs for the outlaws is a small act of revenge against willful ignorance.', ''),
        ('Holy Nation Outlaws', 'A reformed drunk who once shouted blasphemies outside the temple gates, he was sentenced to labor in the holy mines. Ten years underground left him with a cough that never fades and a hatred that never dims. Freedom came when the mine collapsed, and he crawled through a mile of rubble to see open sky again.', ''),
        ('Holy Nation Outlaws', 'Sold to the priests as an orphan, she was raised to be a silent servant who never questioned her place. The discovery of a hidden library beneath the temple shattered the world they built for her. She fled with a head full of forbidden knowledge and a price on her scalp that ensures she can never stop running.', ''),
        ('Holy Nation Outlaws', 'A once-respected leather worker whose only crime was trading honestly with a skeleton merchant passing through town. The paladins made an example of him in the square while his neighbors watched in silence. He learned that compliance offers no protection when the faithful need a target for their righteousness.', ''),
        ('Holy Nation Outlaws', 'The third son of a minor priest, he knew he would never inherit anything but a life of groveling. He stole a blessed blade from the temple armory and ran before his father could consign him to the fields. The sword still hangs at his hip, a mockery of the faith that offered him nothing.', ''),
        ('Holy Nation Outlaws', 'Her healing herbs were welcomed until the priests decided her cures came from unholy sources rather than Okran''s light. They dragged her before the inquisitors and demanded she confess to witchcraft alongside her medicine. She escaped during the journey to the burning stake, her hands still bound with prayer rope she keeps as a reminder.', ''),
        ('Holy Nation Outlaws', 'Born a servant in a Holy Nation farm, he fled after killing a tax collector who demanded more than his family could give. He now scrapes by raiding Okranite supply lines with a bitterness that only grows with each scar.', ''),
        ('Holy Nation Outlaws', 'She was a devoted priestess until she uncovered records of the Inquisition''s purges being used to steal land. Her faith shattered, she fled into the wasteland with a price on her head and a mouth full of blasphemy.', ''),
        ('Holy Nation Outlaws', 'Conscripted into the Holy Army as a youth, he deserted after being ordered to burn a village of supposed heretics who were merely starving farmers. The guilt follows him still, sharper than any blade.', ''),
        ('Holy Nation Outlaws', 'A Hiver drone who wandered too close to Holy Nation territory and was captured for sport by a patrol. He escaped during a dust storm and now lurks at the fringes, stealing weapons to arm other outcasts.', ''),
        ('Holy Nation Outlaws', 'She ran a successful distillery in Stack until a Paladin decided her business was sinful and confiscated everything. With nothing left to lose, she took up with bandits and learned to fight with a bottle in one hand and a sword in the other.', ''),
        ('Holy Nation Outlaws', 'Raised in the temples of Okran, he began asking questions that his superiors found dangerous. Branded a heretic before he could flee properly, he survives by his wits and a deep knowledge of Holy Nation patrol routes.', ''),
        ('Holy Nation Outlaws', 'A Shek warrior exiled from her people for cowardice, she found no refuge among the Holy Nation zealots who tried to enslave her. She now leads a small gang of outcasts who hate the Okranites as much as she does.', ''),
        ('Holy Nation Outlaws', 'He was a scribe copying holy texts until his eyes weakened and he was deemed unfit for service. Cast out like refuse, he uses his literacy to forge travel papers and pass-along messages between outlaw camps.', ''),
        ('Holy Nation Outlaws', 'Her family was purged for harboring a wounded Skeleton traveler, and she alone survived by hiding in the cellar for a week. She does not care about the politics of the land, only that the Holy Nation burns for what it took from her.', ''),
        ('Holy Nation Outlaws', 'A former blacksmith who repaired Skeletons in secret until the Inquisition kicked down his door. He lost his forge, his apprentice, and his left hand to their justice, and now crafts crude weapons for anyone willing to fight the theocracy.', ''),
        ('Holy Nation Outlaws', 'Sold into Rebirth for stealing bread, she endured years of brutal labor before a prison riot gave her a chance to run. The scars on her back are a map of everything she owes the Holy Nation, payable in blood.', ''),
        ('Holy Nation Outlaws', 'He never believed in Okran but played the faithful citizen to survive, until a neighbor denounced him over a land dispute. Now living rough in the borderlands, he trusts no one and sleeps with a crossbow across his chest.', ''),
        ('Holy Nation Outlaws', 'The harvest failed and the tithes went unpaid, so the Inquisition seized the family farm and scattered its people to the wind. Starvation or banditry were the only choices left, and a rusty cleaver made the decision easy enough.', ''),
        ('Holy Nation Outlaws', 'He marched under the paladin banner for a decade until his unit burned a hive village for the crime of existing. That night he walked away from the campfire and never looked back, knowing the Inquisition would hunt him as a deserter.', ''),
        ('Holy Nation Outlaws', 'Born to slaves in Rebirth, she never knew freedom until a dust storm blew down the perimeter fence and she ran until her lungs bled. She fights now so that others might break their chains before the Okranite whips break them first.', ''),
        ('Holy Nation Outlaws', 'A trader who made the mistake of selling grain to a Shek outpost, earning a one-way ticket to the slave pits when the paladins found the receipt. Escaped during a transit ambush, she now runs supply lines between outlaw camps and anyone who hates the theocracy.', ''),
        ('Holy Nation Outlaws', 'His wife was taken for questioning and returned in pieces, the official explanation citing heretical research. He abandoned the prayer shrines that day and took up with the first outlaw band that would have him, seeking no justice but plenty of revenge.', ''),
        ('Holy Nation Outlaws', 'A Scorchlander who wandered into Holy Nation territory looking for work and quickly learned that outsiders serve only as examples. After being beaten half to death by a paladin patrol, a gang of outlaws found him and patched him up in exchange for a strong back and a willingness to kill.', ''),
        ('Holy Nation Outlaws', 'She grew up reciting the prayers and never questioned them until her brother was conscripted and died assaulting a far-flung ruin for relics that never existed. The faith died faster than he did, and she took to the hills with nothing but rage and a stolen sword.', ''),
        ('Holy Nation Outlaws', 'A cook in a paladin garrison who poisoned the evening meal after witnessing the public execution of a child for theft. The poison was weak and most survived, but the message was clear enough to earn a permanent death sentence from the high inquisitor.', ''),
        ('Inaba Ronin', 'Cast out after failing to protect a trade caravan from skin bandits, the shame of survival proved heavier than any sword. Wandering the wasteland alone taught lessons that dojo training never could. Now among the Inaba, that bitter experience serves as both shield and warning.', ''),
        ('Inaba Ronin', 'Once a proud retainer to a minor lord in the United Cities, political treachery left the master dead and the household dissolved overnight. With no clan name to speak of and a price on any who remained loyal, the roads became home. The Inaba offered something rare: purpose without fealty.', ''),
        ('Inaba Ronin', 'Disgraced by a dishonorable order refused, this warrior chose exile over butchery. The blade was kept; the uniform was burned. Years of drifting through the badlands hardened resolve into something quieter and far more dangerous.', ''),
        ('Inaba Ronin', 'Born to peasants who scraped meager lives from dusty soil, the way of the sword was never an inheritance but a desperate grasp at something better. A stolen katana and years of self-taught survival forged an unlikely fighter. The Inaba never asked about bloodline, only skill.', ''),
        ('Inaba Ronin', 'A former bodyguard for a Merchant''s Guild overseer who sold out the entire security detail to slavers as part of a deal. Only a desperate escape under cover of sandstorm avoided the chains. Trust is a luxury this ronin will never again afford so freely.', ''),
        ('Inaba Ronin', 'Maimed during a border skirmish with the Holy Nation and left for dead by retreating comrades, survival meant crawling through the desert for six agonizing days. The Inaba found a broken fighter and rebuilt something fiercer from the wreckage. The old wounds still ache when rain comes.', ''),
        ('Inaba Ronin', 'Trained from childhood in the sword arts, everything was lost when famine scattered the clan like dust. Hunger drove this blade to work for anyone with coin, moral or otherwise. The Inaba at least offers comrades who understand that survival rarely allows for clean hands.', ''),
        ('Inaba Ronin', 'An aging swordsman who watched every student and ally fall to war, age, or despair across decades of conflict. The techniques remain sharp even as the body protests each morning. Among the Inaba, hard-won wisdom compensates for fading stamina.', ''),
        ('Inaba Ronin', 'Conscripted into a samurai army as fodder during a territorial dispute, the truth of war shattered every romantic illusion. When the generals fled and the common soldiers died, desertion became the only sane choice. The Inaba understand that loyalty must be earned, not demanded.', ''),
        ('Inaba Ronin', 'Once married to a farmer outside the cities, bandits took everything in a single night of fire and steel. The surviving spouse learned the sword not for glory but for vengeance long since completed. Now only habit and the Inaba keep the blade sharp.', ''),
        ('Inaba Ronin', 'Once a sworn sword to a minor lord in the United Cities, fled when his master was purged by the Samurai Legions. Now walks the dusty roads with nothing but a rusted blade and a grudge against noble houses. Takes bounties where they come, caring little for the target''s crimes so long as the pay clears.', ''),
        ('Inaba Ronin', 'Disgraced after failing to protect a trade caravan from Holy Nation raiders, cast out by the merchant guild that employed her. Found refuge among the Inaba when there was nowhere else to go. Still wakes to the sound of screaming merchants she could not save.', ''),
        ('Inaba Ronin', 'Never held a master to begin with, born to a drifting swordsman who taught the blade before drinking himself to death. Fell in with the Inaba because they asked no questions about bloodline or lineage. Fights with a stolen katana and an empty stomach most days.', ''),
        ('Inaba Ronin', 'A former slave miner who earned freedom in the pits by killing an overseer with a pickaxe. Learned the sword from a dying ronin who saw raw potential in those calloused hands. The Inaba took him in when every city gate was shut to a brand-marked killer.', ''),
        ('Inaba Ronin', 'Lost her family farm to Shek raiders and tax collectors in the same season, left with nothing but bitter resolve. Traded the last of her inheritance for a cheap blade and walked until the Inaba found her half-starved on the road. Trusts no authority, feeds on spite as much as food.', ''),
        ('Inaba Ronin', 'Served as a bodyguard for a corrupt trader until the pay stopped and the knives came out from within. Escaped with a gut wound and a price on his head, limped into Inaba territory by chance. Now guards others for a fraction of what he once earned, wiser to the ways of treachery.', ''),
        ('Inaba Ronin', 'A young runaway from a Holy Nation outpost, rejected the flame and fled before the inquisitors could take interest. Learned to fight dirty in the borderlands, surviving on skimmer meat and stolen ration packs. The Inaba gave structure to an otherwise aimless rage against the zealots.', ''),
        ('Inaba Ronin', 'Deserted the Samurai Legions after being ordered to slaughter a starving village for unpaid taxes. Wandered the wastes for months with a blade too fine for a beggar and too bloody for a soldier. The Inaba ask no questions about past allegiances, only that the sword stays sharp.', ''),
        ('Inaba Ronin', 'Born to the road, never knew a settled home or a steady meal until the Inaba shared their campfire. Took up the sword because it was the only trade that kept the slavers at bay. Follows the old codes loosely, more out of habit than true conviction.', ''),
        ('Inaba Ronin', 'Once a respected duel instructor in a border town, until a student''s death in a practice match brought shame and vengeance upon the dojo. Fled under cover of night with nothing but the clothes on her back and the weapon that caused the ruin. The Inaba neither forgive nor condemn, simply accept another wandering blade.', ''),
        ('Inaba Ronin', 'Survived a Skimmer attack that killed his entire patrol unit in the Bonefields, left alone in the desert with a broken spear and a will of iron. Crafted a blade from salvaged metal and walked until civilization appeared on the horizon. Joined the Inaba because lone wolves die hungry in Kenshi.', ''),
        ('Inaba Ronin', 'A former barkeep who watched her establishment burn during a samurai crackdown, decided that serving drinks was a fool''s errand. Bought a sword from a passing trader and vowed never to be helpless again. The Inaba respect action over words, and she has both in ample supply.', ''),
        ('Inaba Ronin', 'Failed to protect a merchant caravan from cannibal raiders in the Leviathan Coast and lived while the employer died. The shame of survival gnawed worse than any wound until the Inaba offered a place where competence mattered more than past failures. Now guards the flanks without being asked.', ''),
        ('Inaba Ronin', 'An orphan raised by scavengers in the Floodlands who learned swordwork from ruined martial texts found in ancient debris. Never belonged anywhere until crossing paths with an Inaba patrol that tested skill instead of bloodline. Fights to ensure no other child grows up picking corpses for coin.', ''),
        ('Inaba Ronin', 'A former United Cities samurai who refused to execute a hungry child caught stealing grain and was stripped of rank for the defiance. Wandered the swamps with nothing but the blade still permitted by custom. The Inaba never asked why a samurai walks alone, only whether the arm remains steady.', ''),
        ('Inaba Ronin', 'Born to farmers enslaved by the Holy Nation for sheltering a Shek traveler during a storm. Escaped the mines at fourteen but could never return to the plow after tasting free air. The Inaba understand that some wounds can only be answered with steel.', ''),
        ('Inaba Ronin', 'Served as muscle for Reaver slavers until a raid on a Hiver village turned stomach and conscience alike. Deserted that night with stolen provisions and a bounty on the trail behind. The Inaba ask no questions about old allegiances so long as the sword swings true for them now.', ''),
        ('Inaba Ronin', 'A disgraced arena fighter in Catun who threw a match to pay gambling debts only to be betrayed by the bookmaker anyway. Fled the city with broken ribs and a stolen katana from the armory. Found among the Inaba that survival outweighs honor in the wasteland calculus.', ''),
        ('Inaba Ronin', 'A servant in a noble household who trained with wooden swords in secret until discovery brought a beating that healed crooked. The master broke fingers to ensure such delusions would end but the hands still grip a hilt. The Inaba welcomed a fighter with something to prove and nothing left to lose.', ''),
        ('Inaba Ronin', 'A fisherman from the coast whose village was destroyed by Beak Things while the samurai garrison stood idle. Took up a rusted blade from the wreckage and vowed never to wait for protection again. The Inaba share that bitter understanding of self-reliance.', ''),
        ('Kral''s Chosen', 'Born into starvation in the Border Zone, this warrior abandoned a dying farm to follow the Chosen. Survival meant proving worth with an iron club, and now the camp''s fire is the only home left. Kral''s promise of strength through struggle is the sole truth that makes sense anymore.', ''),
        ('Kral''s Chosen', 'Once a captive bound for Holy Nation mines, this fighter killed their guards during a dust storm and fled south. The Chosen found them half-dead and offered a blade instead of pity. Now they repay that debt by butchering any pale-skinned zealot who wanders too close.', ''),
        ('Kral''s Chosen', 'Raised among the Chosen since a starving child traded to the camp for a sack of raw meat. Years of brutal sparring forged a loyal enforcer who asks no questions. The Old World ruins are simply a proving ground where weakness is culled without sentiment.', ''),
        ('Kral''s Chosen', 'A former Slave Farm laborer who snapped during a punishment beating and beat their overseer to death with their own shackles. The Chosen took the bloodied runaway in without hesitation, seeing raw potential. Now they wear the scars proudly and preach Kral''s violent creed to every new recruit.', ''),
        ('Kral''s Chosen', 'Deserted a shattered mercenary company after watching the captain sell comrades to slavers for safe passage. Wandered the wasteland for weeks before the Chosen offered purpose behind a blade. Trust is no longer given freely, but the tribe''s strength cannot be denied.', ''),
        ('Kral''s Chosen', 'This warrior grew up in the shadow of the Burn, learning to fight skinners and cannibals before they could walk properly. The Chosen were the only group fierce enough to hold territory in this hellscape. Loyalty was earned through shared blood and survival, nothing more.', ''),
        ('Kral''s Chosen', 'A former Hiver who lost their prince and wandered the desert in a fog of purposeless rage until the Chosen welcomed them. The tribe does not care about hive politics, only the swing of the blade. Now they kill with the same single-minded dedication they once gave to the colony.', ''),
        ('Kral''s Chosen', 'Trained as a Skeleton repair tech in the Black Desert, this human grew tired of fixing machines that outlived everyone they loved. The Chosen offered a life where flesh matters more than metal. They still maintain the odd prosthetic limb around camp, but their true devotion is to Kral.', ''),
        ('Kral''s Chosen', 'Sold by starving parents to a trader at age six, this warrior passed through three slave markets before the Chosen liberated the caravan by force. Given the choice to leave or stay, they picked up a fallen sword and never looked back. Freedom is a blade in hand and an enemy at their feet.', ''),
        ('Kral''s Chosen', 'This aging fighter remembers a time before the Chosen grew so numerous, when every meal was a gamble and every stranger a threat. They helped fortify the camp with scrap metal and sheer stubbornness. Younger members seek their counsel, but they prefer demonstrating survival through action over words.', ''),
        ('Kral''s Chosen', 'Born into the Chosen, this warrior has never known a life outside the bloodstained sands of the Lost Isle. The teachings of Kral were milk and meat, and the weakness of outsiders was proven with every raid. They seek only to kill enough to earn a place at Kral''s side in the afterlife.', ''),
        ('Kral''s Chosen', 'A former slave in the Holy Nation mines, this one escaped south with nothing but scars and hatred for the zealots who held the whip. Kral''s Chosen offered a blade and a purpose, and the taste of Paladins proved sweeter than any revenge imagined. Now they hunt the faithful with particular enthusiasm.', ''),
        ('Kral''s Chosen', 'Hunger drove this one to the Chosen as a starving wanderer on the edge of the Swamp. The first meal shared around the fire was human, and survival demanded acceptance. Years later, they no longer remember the disgust, only the satisfaction of a full belly and the power of the pack.', ''),
        ('Kral''s Chosen', 'This warrior claims descent from the original followers of Kral, though no records exist to prove such lineage. The stories passed down speak of a greatness that must be reclaimed through strength and blood. They carry an old blade of strange metal and fight as though ancestral spirits watch every swing.', ''),
        ('Kral''s Chosen', 'Once a bandit in the Border Zone, this raider found the Chosen after a botched raid left half their crew dead. The survivors were taken in and given a simple choice: adapt or become meat. Adaptation came quickly, and the old life now seems soft and meaningless.', ''),
        ('Kral''s Chosen', 'A quiet believer who treats the butchery of the Chosen as sacred duty rather than pleasure. Every kill is an offering, every meal a communion with something older and hungrier than civilization. They are tolerated by the louder warriors but trusted to hold the line when discipline matters.', ''),
        ('Kral''s Chosen', 'This one was a fisher in the coastal ruins before the Chosen took their village and everyone in it. Rather than resist, they simply began living as the captors did, finding the transition shockingly easy. The sea still calls sometimes, but the taste of freedom is sharper than salt.', ''),
        ('Kral''s Chosen', 'Sick and abandoned by a passing slave caravan near the Lost Isle, this survivor crawled toward smoke and was found by a Chosen patrol. Nursed back to health on a diet that would have horrified their former self, they now patrol the same wastes looking for others to convert or consume.', ''),
        ('Kral''s Chosen', 'A veteran of dozens of raids, this warrior has collected scars from Shek, Hounds, and samurai alike. Each mark is a story, each story ends with the enemy feeding the camp. They train the young ones now, teaching that hesitation is death and mercy is starvation.', ''),
        ('Kral''s Chosen', 'Drawn to the Chosen by whispers of power and freedom from the laws of weaker peoples, this one left a life of petty thievery in the Hook for something more honest in its brutality. The code of Kral is simple and pure: take what you need, destroy what stands against you. No hypocrisy, no priests, no lies.', ''),
        ('Kral''s Chosen', 'This one barely speaks of the time before the Chosen found them half-dead in the desert. Whatever happened in that other life is buried under years of violence and the teachings of Kral. The past is meat for the present, and the present is a blade in the hand.', ''),
        ('Kral''s Chosen', 'The child of a Chosen warrior and a captive who did not survive the birth, this one has fought for every scrap of respect in a group that values strength above all. The doubt of others became fuel, and now few dare question their loyalty or ferocity. They intend to lead someday, if they live long enough.', ''),
        ('Kral''s Chosen', 'Born into the Chosen on the Lost Isle, this one has never known another life. The rituals of the flesh were lullabies, and the teachings of Kral were their first words. To them, the outside world is simply a feast that does not yet know it is a feast.', ''),
        ('Kral''s Chosen', 'Once a laborer in the Holy Nation mines, they escaped south and would have died of thirst if not for a Chosen hunting party. The irony of being saved by those the Okranites called monsters was not lost on them. Now they hunt the faithful with particular pleasure.', ''),
        ('Kral''s Chosen', 'This one came to the Chosen seeking spiritual truth after years of wandering through failed philosophies and dead gods. Kral''s wisdom cut through the noise like a cleaver through bone: flesh is truth, hunger is holy. They serve as something like a priest, interpreting the deeper meanings for those too simple to see.', ''),
        ('Kral''s Chosen', 'Captured in a raid on a desert outpost, this one watched their companions die one by one in the cooking pots. When offered the choice to join or join the menu, survival instincts overwhelmed any remaining morality. Three seasons later, and the memory barely troubles them anymore.', ''),
        ('Kral''s Chosen', 'A skilled tracker who once guided merchants through the wastes for coin, this one grew tired of leading the weak to safety. The Chosen offered a use for their talents that felt more natural: guiding raiding parties to ripe targets. The pay is worse, but the work is honest.', ''),
        ('Kral''s Chosen', 'This one was a loner even before the Chosen found them living in a ruin, talking to skulls and eating whatever they could catch. The group barely had to convince them of anything; they simply fit. Their madness has found a home among those who call it wisdom.', ''),
        ('Kral''s Chosen', 'Sold as a child to slavers in the Swamps, passed between owners for years, this one was finally taken in a Chosen raid. For the first time, no one owned them. They belong to Kral now, and the belonging tastes sweeter than any freedom the cities promise.', ''),
        ('Kral''s Chosen', 'A former Skin Bandit who found even their depravity too restrictive, this one drifted until the Chosen''s fires appeared on the horizon. Here was a group that understood the body is just meat and potential. They have finally found peers who do not flinch.', ''),
        ('Machinists', 'Grew up salvaging rusted husks in the borderzones, learning engine diagnostics before ever holding a weapon. Joined the Machinists after a Shek raid left their family workshop in ashes, figuring the old machines were the only allies that never betrayed them. Now they spend long hours in the libraries, piecing together fragmentary schematics that most scholars dismiss as junk data.', ''),
        ('Machinists', 'Lost a leg to a Skin Spider in the Swamps and nearly died of infection before a Machinist patrol found them. The replacement prosthetic changed everything, and they vowed to repay the debt by mastering the art of limb fabrication. They work the foundries now, crafting crude but functional prosthetics for the desperate souls who stumble into Black Scratch.', ''),
        ('Machinists', 'Spent twelve years as a Holy Mine slave, secretly studying the mechanical principles of the overseers'' irrigation pumps. Escaped during a dust storm and walked three weeks across the desert to reach Machinist territory. Their knowledge of ancient hydraulic systems earned them a place among the engineers, though the brand on their neck still draws suspicious glances.', ''),
        ('Machinists', 'A former Hiver drone who lost connection to the Queen and wandered the wasteland for months before encountering a Machinist excavation team. Fascinated by the intricate gears and motors they unearthed, they dedicated themselves to understanding the logic of dead machines. Other Machinists are uneasy around them, but their tireless work ethic and precise manipulators are undeniable assets.', ''),
        ('Machinists', 'Born into a wealthy Trader''s Guild family but abandoned the lucrative mercantile life after discovering a cache of First Empire blueprints in a ruined outpost. The perfection of those ancient designs made everything else feel hollow. They fled family obligations with the stolen documents and now serve as a translator of Old World technical scripts.', ''),
        ('Machinists', 'A desert nomad who traded water and salvage along the Great Desert until a Skimmer attack destroyed their caravan. Stumbled into Black Scratch half-dead and was nursed back to health by Machinist healers with strange medical devices. Convinced that rediscovering lost technology is the only path forward for humanity, they now guide expeditions into dangerous ruins.', ''),
        ('Machinists', 'Once a guard for the United Cities who witnessed corrupt officials selling ancient artifacts to slavers rather than studying them. Deserted their post and sought out the Machinists, believing that knowledge belongs to those who will use it wisely. They protect excavation sites with a fanatic''s devotion, knowing firsthand what happens when greed wins over curiosity.', ''),
        ('Machinists', 'A Greenlander who spent years as an itinerant tinkerer, fixing windmills and well pumps for isolated farming villages. The work was thankless and paid poorly until a Machinist recruiter recognized their talent for improvisational engineering. They now maintain the vital water systems that keep Black Scratch alive, quietly proud that thousands depend on their skill.', ''),
        ('Machinists', 'Raised by Scorchlander outlaws in the Burn, they learned to survive by stripping abandoned vehicles for anything tradeable. A chance discovery of a functioning Old World generator changed their perspective entirely. They turned their scavenger instincts toward preservation rather than profit, eventually finding their way to the Machinists where their ruthless efficiency is finally put to good use.', ''),
        ('Machinists', 'A former Skeleton who lost most of their memory banks in a catastrophic system failure, awakening with only fragments of engineering knowledge. The Machinists took them in, seeing value in even corrupted data from the ancient world. They serve as both student and reluctant teacher, sharing broken memories while struggling to reconstruct their own fractured identity.', ''),
        ('Machinists', 'Grew up scavenging rusted wreckage in the borderlands, learning to coax dead engines back to life through sheer trial and error. Joined the Machinists after a trade caravan recognized the value of a jury-rigged power generator built from scrap. Now maintains the cooling systems that keep the workshops from turning into ovens.', ''),
        ('Machinists', 'Spent years as an apprentice scribe in the Holy Nation, until inquisitors burned a cache of ancient schematics being studied in secret. Fled south with nothing but a stolen journal of engineering diagrams and a burning hatred for willful ignorance. The Machinists accepted both without question.', ''),
        ('Machinists', 'A former skin-bandit victim who lost both arms to the creatures before a Machinist patrol happened across the camp. Woke up fitted with crude but functional prosthetics, and stayed on to repay the debt through labor. Has since become one of the more adept limb-calibration specialists in the guild.', ''),
        ('Machinists', 'Walked out of the Fog Islands with no memory of a previous life, only an instinctive understanding of mechanical systems. The Machinists took the amnesiac in, finding the condition more curious than concerning. Works quietly in the machine pits, afraid that whatever past lurks behind the blank slate might be worse than the unknown.', ''),
        ('Machinists', 'Born to a scavenger family that picked through the Old Empire ruins along the coast, learning to identify valuable components before learning to read. Lost a sibling to a malfunctioning security drone, which fueled a determination to master ancient technology rather than fear it. Rose from apprentice to a respected field-recovery specialist within the guild.', ''),
        ('Machinists', 'Former barkeep in Sho-Battai who spent evenings picking apart broken clockwork toys instead of socializing. Left the bar behind after a Machinist customer paid for drinks with a functioning limb actuator and mentioned they needed people who understood small mechanisms. Now specializes in precision work on skeletal joint assemblies.', ''),
        ('Machinists', 'A Shepherd''s daughter who always preferred fixing broken water pumps to tending goats. The Machinists passing through the plateau offered a life that made use of calloused hands and a curious mind. Sends what shekels she can spare back to the village, though the old elders mutter about her meddling with things better left broken.', ''),
        ('Machinists', 'Escaped from a United Cities slave camp after disabling the lock mechanisms on the holding pens with a stolen wire. Tracked the Machinists to the Black Desert, figuring anyone who understood locks that well could teach more. Has become the guild''s quiet expert on security systems and their weaknesses.', ''),
        ('Machinists', 'Formerly a low-ranking Imperial soldier who deserted after watching incompetent officers waste lives and equipment through ignorance of basic maintenance. Wandered the wastes for months before encountering a Machinist expedition and offering mechanical skills in exchange for shelter. Found more purpose in repairing ancient machinery than ever felt in service to corrupt generals.', ''),
        ('Machinists', 'A starving refugee from the Flats who nearly died crossing the Black Desert before a Machinist patrol dragged the unconscious body inside. Woke up with a new purpose and a profound respect for the technology that keeps people alive in hostile places. Now handles supply logistics and water purification maintenance, ensuring no one else nearly perishes from thirst.', ''),
        ('Machinists', 'Spent a decade as a wandering tinker, trading repairs for food across the frontier settlements. The work was lonely and the pay terrible, but the Machinists offered a permanent workshop and colleagues who spoke the same language. Has grown fiercely protective of the guild, viewing it as the family never had.', ''),
        ('Machinists', 'Survived a Beak Thing attack that killed the entire trade caravan, saved only by a malfunctioning Skeleton who dragged the battered body to the nearest Machinist outpost. Spent months recovering and longer still helping repair the Skeleton''s damaged cognition unit out of gratitude. Stayed on because the Machinists alone treat machines and people with equal respect.', ''),
        ('Machinists', 'Born to a Machinist family inside the Black Desert outpost and grew up surrounded by whirring gears and the smell of machine oil. Learned to read schematics before most children learn to read words. Takes for granted what outsiders find miraculous, seeing the Old Empire''s ruins as puzzles waiting to be solved rather than relics to be feared.', ''),
        ('Machinists', 'Lost both legs to a Skin Spider attack in the Swamp and crawled for days before a Machinist salvage team found the broken body. The prosthetics they built work better than flesh ever did, and the debt of gratitude became a permanent oath. Specializes in limb fabrication now, determined to give others the same second chance.', ''),
        ('Machinists', 'Former tech hunter who spent years dragging artifacts to brokers for a fraction of their worth, until witnessing a priceless engine core sold to a noble who used it as a doorstop. Realized the Machinists alone value technology for what it does rather than what it fetches. Still knows every ruin in the Border Zone, but now explores for understanding instead of profit.', ''),
        ('Machinists', 'Grew up in a Holy Nation village where curiosity about the old machines was beaten out of children along with heresy. Escaped after the inquisitors came for a neighbor who kept a salvaged cog wheel as a good luck charm. Found the Machinists through whispered rumors and has never looked back, though still flinches at loud voices.', ''),
        ('Machinists', 'A Skeleton whose memory core was damaged in some forgotten conflict, leaving only fragmented knowledge of engineering principles. The Machinists were the first humans who did not try to scrap or enslave, but instead offered purpose and patience. Works alongside organic members as an equal, slowly recovering lost knowledge through study and application.', ''),
        ('Machinists', 'Spent years maintaining the pumps and filtration systems in a United Cities copper mine, watching workers die from toxic fumes when management refused proper maintenance. Sabotaged the overseer''s quarters and fled into the desert with nothing but a toolbox and the clothes on their back. The Machinists took in a skilled plumber and got a loyal member who knows exactly what oppression looks like.', ''),
        ('Machinists', 'Once a respectable trader running goods between the Flats and Waystations until bandits crippled the caravan and left nothing but debt. Took work as a mechanic''s assistant just to eat, discovering a talent for diagnosing engine failures. The Machinists offered better pay and actual respect for those skills, so the trading ledgers were abandoned for good.', ''),
        ('Machinists', 'A scavenger who made a meager living picking through the edges of the Black Desert, selling rusted scrap to anyone who would buy. Kept finding half-functional tech too complex to sell, until a Machinist patrol explained what the artifacts actually did. Now works the deep desert recovery missions, able to spot valuable components others would dismiss as junk.', ''),
        ('Manhunters', 'Escaped the Holy Mines as a youth and swore never to wear chains again, no matter the cost. Found that the easiest way to stay free was to put others in bondage instead. Tracks runaways with a cold efficiency born from knowing every trick a desperate slave will try.', ''),
        ('Manhunters', 'Former United Cities infantryman who deserted after pay stopped arriving and the food ran thin. Took up manhunting because the skills transfer directly and the pay arrives in coin rather than promises. Does not dwell on how little separates this work from the soldiering that came before.', ''),
        ('Manhunters', 'Grew up starving in the slums of Brink and learned early that people are just another commodity. Started by betraying hiding runaways for copper, then bought a polearm and never looked back. Counts shackles as more reliable than friendship ever was.', ''),
        ('Manhunters', 'Lost a leg to a Beak Thing in the Leviathan Coast and spent months dragging back to civilization. Could no longer run, but discovered that hunting people requires patience more than speed. Sits in ambush now and lets the desperate come to familiar ground.', ''),
        ('Manhunters', 'Once worked the fields alongside the enslaved, too poor to own even a slave of their own. Hated the masters but hated the escaping slaves more, seeing their flight as a slight against those left behind. Enjoys the moment a runaway realizes the one hunting them was once a neighbor.', ''),
        ('Manhunters', 'Former overseer for a minor noble house who was cast out when the estate fell to ruin and debt. Knew no trade besides managing human livestock, so went into business independently. Treats manhunting as a form of pastoral work and keeps meticulous records of every capture.', ''),
        ('Manhunters', 'Stormed out of the Shinobi after a job went bad and their partner vanished with the full payout. Decided that hunting bounties with the Manhunters meant never splitting proceeds with anyone again. Works alone by preference and trusts only the lock on their own cage wagon.', ''),
        ('Manhunters', 'Born to a Manhunter and raised in the trade like a herder raises a child to tend goats. Knows the routes, the water holes, and the hiding spots across the Border Zone better than most know their own homes. Feels nothing at the pleading, having heard it every day since earliest childhood.', ''),
        ('Manhunters', 'Came west after the Cannibal Plains claimed everyone else in the hunting party. Found the Manhunters less likely to eat their own and the prey easier to subdue than Cannibal Hunters. Still checks every meal for human teeth marks before eating.', ''),
        ('Manhunters', 'Learned tracking from a Skimmer trapper in the Shimmering and applied those same skills to bipedal prey. Tells themselves that slaves are better off captured than dead in the wastes, and the pay makes the lie easier to swallow. Works the edges of the Great Desert where runaways always think they can disappear.', ''),
        ('Manhunters', 'Grew up starving in the borderlands until a Manhunter patrol took him in as a tracker. He learned to read the dust and the trails, finding escaped slaves better than anyone in his crew. The pay keeps him fed, and he stopped questioning the work years ago.', ''),
        ('Manhunters', 'She lost her family farm to tax collectors and swore she would never be poor again. Hunting bounties started as a way to survive, but the coin from live captures bought her a decent blade and armor. Now she leads a small pack and sleeps with one eye open.', ''),
        ('Manhunters', 'Born into a slave camp, he earned his freedom by turning in runaways for the overseers. The Manhunters respected his nose for tracking and offered him a proper cut. He tells himself the people he catches deserve it somehow.', ''),
        ('Manhunters', 'A former Holy Nation footsoldier discharged after a shoulder injury left her unable to hold a pike properly. She found that herding humans required less upper body strength and paid better than guard duty ever did. The Holy Nation buys what she brings without asking questions.', ''),
        ('Manhunters', 'He started as a simple caravan guard moving between cities, but noticed the real money was in the chains. A run-in with Manhunters showed him the math, and he switched sides before the next sunrise. He still walks the same roads, just with different cargo.', ''),
        ('Manhunters', 'Her mother was a Manhunter and her grandmother before that, teaching her to read tracks before she could read words. She knows the desert flats and mountain passes where runaways think they can disappear. The family trade is all she has ever known.', ''),
        ('Manhunters', 'After his shop burned down in a city riot, he had nothing left but debt and anger. A Manhunter offered him coin to help corner some rioters who had bounties on their heads. The satisfaction of dragging them back hooked him worse than any drug.', ''),
        ('Manhunters', 'Once a respected miner in the United Cities, she was falsely accused of theft and sentenced to the mines as a slave herself. She escaped, tracked down the informant who betrayed her, and sold them to a slaver for revenge. That first sale felt so good she never went back to honest labor.', ''),
        ('Manhunters', 'He never intended to hunt people for a living, but a bad gambling debt left him working off what he owed to a Manhunter boss. Three years later the debt is paid, but the skills and the reputation remain. Nobody in his old life would recognize him now, and he prefers it that way.', ''),
        ('Manhunters', 'Recruited from the starving masses outside a United Cities outpost with the promise of steady meals and a share of profits. She discovered she had a talent for spotting the weak and the desperate, the ones who would not put up much of a fight. The job eats at her less than hunger ever did.', ''),
        ('Manhunters', 'A former slave who earned freedom through years of obedient service and a rare kind master. Rather than flee the system, he decided to profit from it, using his inside knowledge to predict where runaways hide. He knows every bolt hole and water cache between here and the border.', ''),
        ('Manhunters', 'Wounded in a skirmish with Shek raiders and left for dead by his old mercenary company, a Manhunter band patched him up and put him to work. He figured loyalty was cheaper than the outfit that abandoned him. Now he hunts with a limp and a grudge against anyone who runs.', ''),
        ('Manhunters', 'The dust swallowed his farm after the wells dried up, and the United Cities tax collectors still demanded their cut. A Manhunter caravan passed through looking for fresh hands, and he signed on rather than watch his children starve. He tells himself the people he catches deserve it somehow, otherwise the guilt would eat him alive.', ''),
        ('Manhunters', 'Born into the trade, she learned to track before she learned to read. Her mother carried her on raids against runaway camps, and by fourteen she was rigging nets and cages herself. The life is all she knows, and she feels no more guilt than a wolf does chasing rabbits.', ''),
        ('Manhunters', 'The army disbanded his unit when the local governor could no longer pay them, leaving him with a sword and no prospects. Manhunting paid better than farm work ever would, and he already knew how to end a fight quickly. He still marches in formation out of old habit.', ''),
        ('Manhunters', 'She discovered early that she enjoyed the fear in a captive''s eyes more than any coin. Other hunters work for profit, but she works for the moment the struggling stops and resignation sets in. The bosses know better than to ask questions about the ones who come back bruised.', ''),
        ('Manhunters', 'Caught poaching on noble game lands, he was given a choice by the magistrate: join the Manhunters or lose a hand. He chose the collar and the club, telling himself it was only temporary. Five years on, the temporary arrangement has become a comfortable routine he no longer questions.', ''),
        ('Manhunters', 'Bandits killed her brother and the city guards did nothing, so she took matters into her own hands and tracked them down for the bounties. The Manhunters noticed her initiative and offered her a permanent position. She still hunts bandits when she can, but a bounty is a bounty regardless of the crime.', ''),
        ('Manhunters', 'Cast out from the Holy Nation for some minor heresy, he wandered south until hunger drove him to the Manhunters. His religious zeal has been repurposed into a rigid sense of order and punishment. He sees every capture as righteous justice delivered unto the lawless.', ''),
        ('Manhunters', 'He treats manhunting like any other trade, no different from butchery or tanning. The job needs doing and someone has to do it, so he does it efficiently and without malice. He rarely speaks to captives and never raises his voice, which somehow makes him more unsettling than the loud ones.', ''),
        ('Mercenary Guild', 'A former United Cities soldier who deserted after a disastrous border skirmish left their squad slaughtered. The Guild offered anonymity and steady pay, which suited them just fine after losing everything.', ''),
        ('Mercenary Guild', 'Sold into slavery as a child, they earned their freedom in the gladiator pits of the Hook. Their survival instincts translated naturally into mercenary work, where killing pays better than dying.', ''),
        ('Mercenary Guild', 'A farmhand from the borderlands whose family was wiped out by Beak Thing raids. With no land to tend and nothing left to lose, they took up the sword and never looked back.', ''),
        ('Mercenary Guild', 'Born to a Mercenary Guild contract worker, they grew up watching caravans and learning blade work before they could read. The Guild is the only family they have ever known, and the only life they understand.', ''),
        ('Mercenary Guild', 'A disgraced samurai from the United Cities who fled a dishonorable command rather than commit seppuku. They strip the title from their tongue and let their blade speak instead, fighting for coin instead of loyalty.', ''),
        ('Mercenary Guild', 'A former scavenger from the Border Zone who realized swinging a sword pays better than picking through ruins. They still keep their trap-sense sharp, which makes them useful in ruin-exploration contracts.', ''),
        ('Mercenary Guild', 'Fleeing Holy Nation purges, this Shek exile found no welcome among their own kind after being branded a coward. The Guild asks no questions about past defeats, only that you fight when the contract demands it.', ''),
        ('Mercenary Guild', 'A retired arena fighter from the Hook whose body finally betrayed them in the ring. They took a Guild contract as a guard detail, preferring the slow patrol to the sudden violence of the pits.', ''),
        ('Mercenary Guild', 'A second-generation mercenary raised on the road between waystations. They learned to count pay by the scar and trust only those who bleed beside them.', ''),
        ('Mercenary Guild', 'An ex-thief from Bad teeth who got caught and chose Guild service over losing a hand. They still move quietly, which makes them valuable for reconnaissance contracts and night raids.', ''),
        ('Mercenary Guild', 'Lost a small farm in the Border Zone to Beak Thing raids, with nothing left but a rusty blade and a grudge. Took a few guard jobs to afford food, eventually finding the Guild offered steady work for those willing to bleed.', ''),
        ('Mercenary Guild', 'Spent twelve years in a United Cities slave camp before escaping during a dust storm. Picked up a sword and never looked back, figuring life as hired muscle beats life in chains.', ''),
        ('Mercenary Guild', 'Once served as a samurai in the United Cities before a false accusation ruined the family name. The Guild doesn''t care about honor or disgrace, only whether you can swing a blade and follow orders.', ''),
        ('Mercenary Guild', 'Marched with the United Cities army for a decade before the pay stopped coming and the commanders fled. Sold that military training to the highest bidder, and the Mercenary Guild offered the steadiest contracts around.', ''),
        ('Mercenary Guild', 'Grew up wandering the deserts with a nomad tribe that was scattered by Skinners. Learned to fight surviving the wastes alone, and the Guild pays better than scavenging ruins.', ''),
        ('Mercenary Guild', 'Fled the Holy Nation after being caught reading forbidden texts, knowing the pyre awaited any who questioned Okran''s light. The Guild never asks about your past, only your skill with a weapon.', ''),
        ('Mercenary Guild', 'Worked caravan routes for years, watching merchants grow fat while guards died protecting their cargo. Joined the Guild for a better cut and the chance to choose which jobs are worth the blood.', ''),
        ('Mercenary Guild', 'Defended a doomed outpost in the Leviathan Coast until the walls fell and only a handful escaped. The Guild offered a new banner to fight under, and a steady wage for those with nothing left to lose.', ''),
        ('Mercenary Guild', 'Fell deep into debt with the Traders Guild after a bad deal cost everything. The Mercenary Guild offered the only honest way to earn enough cats to clear the ledger and keep the collectors away.', ''),
        ('Mercenary Guild', 'Rode with a bandit crew for years before the boss got everyone killed in a botched raid. Went legitimate with the Guild, finding that killing for a contract pays better than killing for loot.', ''),
        ('Mercenary Guild', 'Has been swinging a sword for the Guild longer than most recruits have been alive. Too old to start over and too stubborn to quit, taking jobs that younger fighters wouldn''t touch.', ''),
        ('Mercenary Guild', 'Left a fishing village in the south seeking adventure and instead found starvation and hardship. The Guild taught that survival belongs to those who fight for it, and the coin keeps the belly full.', ''),
        ('Mercenary Guild', 'Born into bondage in the United Cities, earned freedom in the arena pits where handlers noticed a talent for violence. The Guild offered better wages and the right to walk away from any master, a freedom worth killing for.', ''),
        ('Mercenary Guild', 'Served in a Holy Nation garrison until questioning the scriptures brought the inquisitors to the barracks door. Fled south with nothing but a stolen paladin cross and a price on the head, selling the sword to whoever pays without asking about past sins.', ''),
        ('Mercenary Guild', 'Tended goats on the border ranges until beak things tore through the flock and the family alike. The Guild doesn''t ask why a recruit fights, only that they fight well, and the pay funds a slow hunt for every last monster in that nest.', ''),
        ('Mercenary Guild', 'Fought in the Shek Kingdom''s endless border wars until the bloodlust faded and only exhaustion remained. Left the highlands seeking paid work with fewer lectures about honor, finding the Guild''s straightforward contracts a welcome change from dying for glory.', ''),
        ('Mercenary Guild', 'Spent years running with the Skinners, taking what was needed from anyone weak enough to lose it. A bad wound left behind by the gang forced a choice between changing ways or bleeding out in the dirt, and the Guild takes anyone who can hold a weapon.', ''),
        ('Mercenary Guild', 'Cast out from a noble United Cities house after a scandal ruined the family name and emptied the coffers. The blade was the only trade left that doesn''t care about lineage, and the Guild pays well enough to fund a slow revenge against those who stole everything.', ''),
        ('Mercenary Guild', 'A skin spider attack in the Swamp left half a squad dead and the survivor carrying scars that still itch at night. Joined the Guild because fighting alongside paid companions beats sleeping alone with the nightmares, and every contract is one more creature dead.', ''),
        ('Mercenary Guild', 'Spent seasons digging through ancient ruins for the Tech Hunters until a collapse buried three friends and broke the taste for exploration. The Guild offered the same travel but with clearer rewards and the chance to kill what attacks instead of just running from it.', ''),
        ('Messenger', 'Grew up in a border outpost where the only reliable contact with civilization was the monthly messenger run. Took the job young after watching a veteran courier outrun a pack of bonedogs, deciding that speed and solitude beat starving behind walls.', ''),
        ('Messenger', 'Former slave in the Holy Mines who learned the desert routes by listening to guards complain about patrol schedules. Escaped during a sandstorm and leveraged that hard-won path knowledge into a messenger commission, carrying secrets instead of pickaxes.', ''),
        ('Messenger', 'Lost a sibling to bandits on the roads because word of the raid arrived too late to matter. Swore to ensure critical intelligence reaches its destination, running dispatches through the same bloodstained canyons that took their family.', ''),
        ('Messenger', 'Deserted a United Cities garrison after being ordered to execute a village elder for unpaid taxes. The Messengers offered anonymity and purpose, trading one uniform for another that actually means something on the road.', ''),
        ('Messenger', 'Survived a Beak Thing attack that killed the rest of the caravan, spending two weeks crawling back to civilization with a broken leg and a sealed letter. The guild recruited them on the spot, valuing that kind of stubborn deliverability above all else.', ''),
        ('Messenger', 'Once a barfly in the Waystations, running small packages for sketchy merchants to fund their mead habit. Cleaned up when a package turned out to be a child''s ransom, delivered it anyway, and found the work suited a reformed drunk with nothing else to live for.', ''),
        ('Messenger', 'Born to a Shek mother who taught combat and a human father who taught cartography, never quite fitting in either world. Found family among the Messengers, where mixed blood matters less than mixed skills and the ability to read a map while fighting off Skin Bandits.', ''),
        ('Messenger', 'Apprenticed to an aging courier whose knees finally gave out somewhere between Shark and Catun. Inherited the route, the contacts, and the chronic joint pain, running the same trails with a debt to the old runner''s memory that can never fully be repaid.', ''),
        ('Messenger', 'Former tech hunter who grew tired of excavating dead ruins for scraps of the old world. Now carries live information between living settlements, finding more meaning in connecting the present than unearthing the past.', ''),
        ('Messenger', 'Escaped the Reavers after being captured during a coastal run, losing two fingers but keeping the message tube intact. The Messengers promoted them to route planner afterward, deciding that kind of priority instinct was better used keeping others alive than running solo.', ''),
        ('Messenger', 'A former slave who escaped a Holy Mine with nothing but the rags on their back and a desperate need to keep moving. The Messengers offered protection and purpose, turning a fugitive''s habit of running into an honest trade. Now every delivery is a small defiance against the nation that once owned them.', ''),
        ('Messenger', 'Born on the open road to a pair of caravan guards, camp life and constant travel are the only existence they understand. When their parents'' convoy was torn apart by beak things, a passing Messenger took them in rather than leave a child to the wastes. The guild became family, and the routes became home.', ''),
        ('Messenger', 'Once a lowly shop assistant in a Waystation, they spent years listening to travelers'' tales of distant cities and forgotten ruins. The monotony of stacking shelves finally broke them, and they abandoned the counter to carry letters across the wasteland. They still regret nothing, even after losing two toes to a skin spider.', ''),
        ('Messenger', 'A retired soldier whose shattered knee ended any hope of standing in a shield wall again. Delivering messages demands endurance and situational awareness rather than heavy armor and melee prowess. The pay is meager, but the rhythm of the road keeps the old instincts sharp and the nightmares at bay.', ''),
        ('Messenger', 'Raised by scavengers in the Border Zone, they learned to read the land and avoid patrols before they could write their own name. The Messengers valued their uncanny knack for finding safe passages through contested territory. Most of their colleagues consider them more scout than courier, and they are often assigned the deadliest routes.', ''),
        ('Messenger', 'A disgraced samurai who fled the Shek Kingdom after refusing a commander''s suicidal order. Stripped of honor and identity, they found anonymity among the Messengers where no one asks about the past. The heavy burden of shame is lighter on the open road, where only the next waypoint matters.', ''),
        ('Messenger', 'An aging runner who has spent three decades carrying scrolls between the great cities. Their body is a map of old injuries and faded scars from encounters with bandits, slavers, and wildlife. They train the newcomers now, insisting that a calm head and soft footsteps outlive raw speed every time.', ''),
        ('Messenger', 'Originally a Hiver worker separated from their prince during a Skimmer attack near Flats Lagoon. Purposeless and afraid, they attached themselves to a Messenger caravan moving through the area. The guild''s structured routes and clear directives provide the sense of community their old instincts still crave.', ''),
        ('Messenger', 'A former Greenlander farmer whose land was seized by United City tax collectors after a bad harvest season. With no home to return to, they took up message running as temporary work that quickly became permanent. Every letter delivered to a wealthy official is a quiet reminder of who truly keeps the empire connected.', ''),
        ('Messenger', 'A tech hunter whose expedition into the Ashlands ended in disaster, leaving them the sole survivor of a ruined company. The Messengers found them half-starved at an outpost and offered employment carrying dispatches instead of risking the deep ruins. They still scan every ridge for ancient machinery, unable to shake the old habits entirely.', ''),
        ('Messenger', 'A young drifter from the Swamp who grew up watching runners dodge Spider patrols and Swamp Ninja with equal ease. They admired the way a good Messenger could talk their way out of trouble or vanish before it arrived. After a runner saved them from a slaver ambush, they pledged themselves to the guild without hesitation.', ''),
        ('Messenger', 'Once a servant in a noble Shinobi household, they learned the arts of discretion and silent movement while serving their masters. When political intrigue turned deadly, they fled with nothing but stolen documents and a price on their head. The Messengers value their subtlety, and the constant travel ensures no assassin can pin them down for long.', ''),
        ('Messenger', 'Born into slavery in the Holy Nation mines, they seized a chance to flee when a Messenger caravan passed through and distracted the overseers. The guild became their shield and purpose, every successful run a small act of defiance against the chains they once wore. They refuse jobs that pass through Rebirth, knowing the sight of it would break the composure they have carefully built.', ''),
        ('Messenger', 'A Shek warrior who failed a challenge and was cast out of the warriors'' halls with nothing but their shame. The Messengers offered work that valued endurance over combat prowess, and the endless roads gave their wounded pride somewhere to go. They still handle trouble with Shek directness, but have learned that a delivered message often achieves more than a drawn sword.', ''),
        ('Messenger', 'They once tended a small waystation with their family until Beak Things descended at dawn and left them the only survivor. The silence of an empty home drove them onto the roads, where constant motion and vital duties leave no room for grief. They carry letters between families now, taking quiet comfort in connecting people who still have each other.', ''),
        ('Messenger', 'Years of guarding merchant caravans through the Hook taught them that heavy cargo invites heavy violence. When bandits slaughtered their entire company over a shipment of iron, they decided information was the only merchandise worth carrying. The Messengers pay less than mercenary work, but the lighter load means they can outrun what they cannot outfight.', ''),
        ('Messenger', 'A Scorchlander born in the dust storms of the Border Zone who learned to navigate by rock formations and wind patterns before they could read. Their talent for finding safe passage through contested territory made them invaluable to the guild. They view their routes as personal property and guard their secret paths more jealously than any warrior guards territory.', ''),
        ('Messenger', 'Raised within the Holy Nation''s rigid teachings, they began questioning the Phoenix''s decrees after witnessing a purge of innocent Greenlander traders. They fled south with nothing but the clothes on their back and a burning need to see beyond the lies. The Messengers ask no questions about faith or origin, and every delivery to the southern cities proves the world is larger than the Phoenix claims.', ''),
        ('Messenger', 'Both their parents carried dispatches before them, and they learned to read trail signs before they could read words. They grew up in way stations and outpost dormitories, raised collectively by runners passing through between routes. The guild is family, faith, and future all at once, and they cannot imagine any other existence.', ''),
        ('Messenger', 'They once made a living stealing from travelers on the roads between Stack and Bad Teeth until a Messenger they robbed died of their wounds. The guild took them in on the condition that they carry the dead runner''s routes until their debt was paid. Years later they still run those same paths, unsure whether they serve the guild or their own need for absolution.', ''),
        ('Missionaries', 'Born to a wealthy Okranite family in Stack, this missionary grew up surrounded by scripture and privilege. A raid that claimed their siblings reshaped their faith from comfort into conviction. Now they walk the wasteland believing every soul saved honors the dead.', ''),
        ('Missionaries', 'Formerly a scavenger surviving on rats and stolen bread near Squin, they stumbled upon a missionary camp half-dead from starvation. The kindness shown there converted them faster than any sermon could. They preach with the fervor of someone who knows what awaits the unsaved.', ''),
        ('Missionaries', 'Raised among the Shek Kingdom, this convert abandoned the warrior traditions after witnessing a missionary heal a dying child with simple medicine. The journey from alienation to devotion took years of study and shame from former kin. Their accent still betrays their origins when they recite the holy verses.', ''),
        ('Missionaries', 'A quiet scribe who spent decades copying sacred texts in a Holy Nation monastery. The endless repetition of words eventually became a burning need to speak them aloud to the faithless. They left the ink behind for the road, carrying only a worn book and unshakable patience.', ''),
        ('Missionaries', 'Once a slaver who delivered captured Untouchables to Rebirth with no remorse, a fever dream of Okran''s judgment shattered their old life entirely. They released their remaining captives and took holy vows the same dawn. Guilt drives their every step through hostile territory seeking redemption they fear they will never earn.', ''),
        ('Missionaries', 'Orphaned by skinners in the Border Zone, this missionary was taken in by a traveling Okranite elder who taught them to read using holy scrolls. The words became their family, their shelter, their weapon against despair. They travel the dangerous roads alone, certain that Okran''s light repels all darkness.', ''),
        ('Missionaries', 'A former Holy Sentinel who grew disillusioned with the corruption they witnessed among the higher priests. Rather than lose faith entirely, they chose missionary work as the purest expression of devotion. They speak carefully around authority and never criticize the hierarchy openly, but their eyes betray a critical mind.', ''),
        ('Missionaries', 'Married young to a farmer outside Bad Teeth, this missionary lost spouse and children to a Beak Thing attack that spared them only by chance. The tragedy cracked something fundamental in their understanding of Okran''s will. They wander now seeking answers no scripture has yet provided, preaching more out of habit than certainty.', ''),
        ('Missionaries', 'Trained as a healer in the Holy Nation''s temples, this missionary realized that bodies mend faster when spirits are fed first. They combined medicine and ministry into a single practice that has won converts across the Flats. Their packs weigh heavy with bandages and books in equal measure.', ''),
        ('Missionaries', 'A reformed drunk who once wasted their days in the bars of Shark, this missionary credits Okran''s voice-heard during a near-fatal beating-for their transformation. The path from gutter to pulpit was paved with relapses and shame. Each village they visit receives a sermon born from intimate knowledge of human weakness.', ''),
        ('Missionaries', 'Born to starving farmers in the borderlands, they witnessed a missionary distribute food and scripture to their dying village. The charity left a mark deeper than any wound, and they vowed to carry that same light into the darkest corners of the wasteland. Now they walk the trade routes, offering salvation to any who will listen.', ''),
        ('Missionaries', 'A former slave in the United Cities mines, they escaped with nothing but scars and a stolen holy text. The words within became their sole comfort during months of desperate flight across the desert. They joined the missionaries to ensure no one else suffers without the promise of something greater.', ''),
        ('Missionaries', 'They grew up inside the faith, reciting prayers before they could hold a sword. Doubt crept in during their teenage years as they watched zealots twist doctrine to justify cruelty. They became a missionary to practice the faith as they believe it was intended, with compassion rather than fire.', ''),
        ('Missionaries', 'A Skinhander nearly claimed their life on the roads near Shark, leaving them bleeding out in the sand. A missionary patrol found them, bound their wounds, and asked for nothing in return. That act of mercy converted them more surely than any sermon could, and they took up the mantle within the season.', ''),
        ('Missionaries', 'They were a trader whose caravan was destroyed by Beak Things, losing everything they had built over two decades. Wandering aimlessly, they stumbled into a mission outpost and stayed simply because there was nowhere else to go. Over time the teachings took root, and now they preach with the fervor of someone who has truly lost the world.', ''),
        ('Missionaries', 'Raised by a Hiver outcast community, they never understood the pull of human faith until they witnessed a missionary face down a band of Starving Bandits with nothing but calm words and steady hands. The bandits left, unsettled by the display. They left with the missionary, seeking to understand that kind of conviction.', ''),
        ('Missionaries', 'Their family was executed by Holy Nation purges for the crime of harboring a Shek traveler. Rather than turn against the faith, they interpreted the atrocity as a corruption of true doctrine by flawed men. They became a missionary to reform the belief from within, knowing the danger of their quiet heresy.', ''),
        ('Missionaries', 'A retired soldier whose shoulder was shattered by a Crossbow bolt in some forgotten border skirmish, they found themselves useless in a world that values strength above all. The missionaries accepted their broken body without judgment, giving them purpose beyond the sword. They now serve as a scribe and teacher at a remote outpost.', ''),
        ('Missionaries', 'They once walked the path of the Tech Hunter, excavating ruins for coin and caring nothing for the souls of the dead civilizations they plundered. A collapse trapped them alone in a tomb for six days, where hallucinations and silence birthed a terror only prayer could quiet. The experience broke and remade them entirely.', ''),
        ('Missionaries', 'Sold by their parents to a workshop in Bad Teeth as a child, they knew only labor and the back of a overseer''s hand until a missionary paid their debt and set them free. The debt was transferred to the faith, but the terms were gentle and the community nourished them. They preach now to repay what they cannot measure.', ''),
        ('Missionaries', 'A drunk and brawler who spent years drowning in gutrot across Border Zone saloons, they hit rock bottom after waking beside a friend they had beaten to death in a blackout rage. The missionaries found them weeping in an alley and offered absolution instead of judgment. Sobriety and scripture replaced the bottle, though the guilt never fully fades.', ''),
        ('Missionaries', 'They were a Greenlander who always felt the call to spread Okran''s light to the unconverted, but lacked the stomach for the Holy Nation''s military campaigns. The missionary path offered a way to serve the faith through healing and teaching rather than burning and killing. They walk a thin line between devotion and dissent in a faction that tolerates neither weakness nor doubt.', ''),
        ('Missionaries', 'Born into a Shek clan that measured worth only in scars and kills, they never felt the hunger for battle that defined their kin. Exiled as a coward after refusing a blood duel, they wandered the wastes until a missionary patrol offered shelter instead of a blade. They now struggle to reconcile the gentle teachings with the warrior instincts that still surface when danger threatens their flock.', ''),
        ('Missionaries', 'A dust storm swallowed their caravan whole, leaving them the sole survivor cradling their dead child in the howling dark. The missionaries who found them days later spoke of purpose beyond loss, and though the words tasted like ash at first, they eventually took root. They carry supplies to isolated settlements now, hoping each delivery might prevent another family from learning that particular grief.', ''),
        ('Missionaries', 'They spent a decade running a slave camp in the Stink, counting bodies like coin and sleeping soundly each night. The change came slowly, a sickness that made them confront what they had built, until one morning they unlocked the cages and walked away without taking a single cat. The missionaries accepted them despite knowing their past, though some nights they still feel the weight of chains they never wore themselves.', ''),
        ('Missionaries', 'Raised in a Holy Nation farmstead, they watched the paladins ride through each season collecting tithes while the village starved. The missionaries offered a different vision of the same faith, one that fed the hungry instead of feasting on their obedience. They preach in border towns now, quietly planting seeds of doubt about the hierarchy that claims to speak for Okran.', ''),
        ('Missionaries', 'The Hive taught them that individual thought was disease and separation was death, but an injury left them stranded too far from the Queen''s call. The silence in their mind was terrifying at first, then liberating, and the missionaries who found them wandering were the first to treat them as a person rather than a unit. They serve as a translator and guide, bridging the gap between Hiveless and the communities that fear them.', ''),
        ('Missionaries', 'Starvation drove them to eat the dead when their outpost fell to skin spiders, a secret they buried beneath layers of shame and silence. The missionaries spoke of redemption for all sins, and though they cannot bring themselves to confess what they did, the promise of forgiveness keeps them walking the path. They distribute food to the hungry with a fervor that borders on desperation, as if each meal might erase the taste of what they consumed.', ''),
        ('Missionaries', 'A merchant''s child raised in comfort among the trade cities, they watched their family''s wealth evaporate when a rival poisoned their water supply and the survivors turned on each other. The missionaries took them in when even former friends refused shelter, asking nothing but labor in return. They chose to stay long after they could have left, finding more truth in a bowl of shared rice than in a vault of silver.', ''),
        ('Missionaries', 'Born to cannibal parents in the fog islands, they never questioned the meat until a raid captured a missionary who sang hymns while the fire was lit. The words meant nothing, but the unwavering calm in those dying eyes planted something that grew for years until they finally walked out of the fog alone. They carry scripture into dangerous lands now, believing that even the most monstrous souls might harbor a seed of light.', ''),
        ('Mongrel', 'Escaped a Holy Nation labor camp with nothing but the chains still rattling on his wrists. Wandered blind through the Fog Islands for days before a Mongrel patrol found him half-dead and raving. Now he stands on the walls, watching the mist with the vigilance of a man who knows what Huntsmen do to those who wander.', ''),
        ('Mongrel', 'Born in Mongrel to a mother who fled the Holy Nation''s purges and a father he never knew. Learned to fight fogmen before he learned to read, taking up a blade at twelve when the creatures breached the outer houses. The town is the only home he has, and he will bleed for it without question.', ''),
        ('Mongrel', 'She was a scribe in Stack before Inquisitors discovered her hidden library of forbidden texts. Fled south with a price on her head, trading everything she owned to a smuggler who knew the safe paths through the fog. Now she keeps Mongrel''s records, documenting the names of the dead and the movements of fogmen swarms.', ''),
        ('Mongrel', 'A discharged Shek warrior who could not stomach returning to the Empire after her warband was annihilated in the Borderlands. Found her way to Mongrel seeking obscurity and found purpose instead training the town''s ragtag defenders. She teaches them that discipline matters more than strength when fighting things that feel no pain.', ''),
        ('Mongrel', 'He walked out of the fog one evening with no memory of who he was or where he had been. The scars on his arms suggest Holy Nation re-education clamps, but he cannot confirm it. Mongrel took him in as they take in all lost souls, and he asks no questions about the life he left behind.', ''),
        ('Mongrel', 'Once a wealthy trader in the United Cities who fell afoul of the Noble Circle over unpaid bribes. Lost everything when his estate burned and his guards turned on him for the bounty. The fog is a fitting prison for a man who once believed gold could solve any problem.', ''),
        ('Mongrel', 'Her family has lived in Mongrel for three generations, making them among the oldest residents. They know every safe path through the islands and every hollow where fogmen nest. She guides newcomers through the mist for a price, though she has buried more clients than she cares to count.', ''),
        ('Mongrel', 'A Hiver who wandered from his hive and found himself lost in the fog, cut off from the Prince''s voice. The silence in his head terrified him more than the fogmen, but Mongrel offered something resembling community. He works the farms, grateful for labor that drowns out the emptiness.', ''),
        ('Mongrel', 'Fled a Holy Nation burning after neighbors reported him for sheltering a skeleton traveler. Watched his home ignite from a hillside, then ran without looking back. In Mongrel he guards the gate, turning away Holy Nation spies with a blade and a grudge he nurtures like a dying ember.', ''),
        ('Mongrel', 'A former slave hunter who tracked runaways through the Swamplands until a fogmen swarm tore apart his entire crew. Survived by climbing a dead tree and watching his partners get pulled screaming into the mist. That night broke something in him, and now he hunts fogmen instead, collecting their teeth as trophies.', ''),
        ('Mongrel', 'Fled the Holy Nation after being marked as a heretic for sheltering a skeleton traveler. The fog felt like a death sentence at first, but it became the only cover that kept the paladins from finishing the job. Now survival is a daily calculation of risk and rationing.', ''),
        ('Mongrel', 'Lost an entire trading caravan to a fogman swarm on the southern approach. Dragged what was left of a teammate into Mongrel''s gates and never found a reason to leave. The walls here are the only thing between living flesh and the fog''s hungry dead.', ''),
        ('Mongrel', 'Born behind these walls and never knew any other home. The fogmen are just a fact of existence, like hunger or thirst, dealt with by blade and vigilance. The outside world sounds like a story people tell to scare themselves.', ''),
        ('Mongrel', 'A Shek warrior who abandoned the fallen empire''s wars and wandered south until the fog swallowed the past. Found a strange peace in Mongrel''s endless skirmishing, a purpose without politics. The fogmen test the blade in ways no tribal feud ever did.', ''),
        ('Mongrel', 'Escaped from a United Cities slave camp and ran until the slavers'' hounds refused to follow into the fog. The first week was terror, the second was starvation, the third was Mongrel. Freedom tastes like dried meat and the sulfur stink of fogman blood.', ''),
        ('Mongrel', 'Came to Mongrel as a bounty hunter chasing a mark who fled into the fog. The mark died screaming in the darkness, and the hunter stayed because there was nothing left to go back to. The fog takes debts and gives nothing but more work.', ''),
        ('Mongrel', 'A former Holy Nation farmer who watched a neighbor burn for reading the wrong book. Stole a sword and fled that same night, too afraid to even look back. In Mongrel, the flames are only in dreams, and the sword finally has a use.', ''),
        ('Mongrel', 'Walked into the fog to die after losing a child to slavers. Woke up in Mongrel''s clinic with half a leg missing and a debt to the surgeons. Kept living out of spite and habit, hauling scrap to pay back the people who stitched the wounds shut.', ''),
        ('Mongrel', 'A Hiver exile who stumbled into Mongrel half-mad and alone. The fogmen were the first thing that made sense, enemies with no lies in them. Now serves as a scout, reading the mist better than any human could.', ''),
        ('Mongrel', 'Once a respected scholar in the United Cities until a rival''s accusation ruined everything. The fog seemed preferable to the debt collectors and assassins waiting in the cities. Knowledge of old world machinery earns a few cats here, but mostly it is just another mouth to feed.', ''),
        ('Mongrel', 'A blacksmith''s apprentice who fled after the master was killed for refusing to forge chains for slavers. The tools are crude in Mongrel, but the work is honest. Every blade hammered out here goes toward keeping the fogmen at bay.', ''),
        ('Mongrel', 'A former soldier from a destroyed faction who drifted south with no banner left to follow. The fogmen do not care about allegiances or treaties, and that simplicity is a relief. Mongrel asks only that a person fights when the horns sound, and that is a bargain worth keeping.', ''),
        ('Mongrel', 'Born in Mongrel and never knew another life. Learned to read the fog by age six and hold a blade by eight. The outside world is just stories from refugees, and the mist is the only home that makes sense.', ''),
        ('Mongrel', 'A thief who stole from the wrong Trader''s Guild official and fled before the bounty hunters arrived. The fogmen were terrifying at first, but they are easier to predict than guild assassins. Now runs supply runs through the mist, paying off old debts in blood and iron.', ''),
        ('Mongrel', 'A Shek warrior cast out for refusing a duel that would have killed a child. The tribes called her coward, but she calls herself alive. In Mongrel, fighting is for survival, not pride, and that suits her fine.', ''),
        ('Mongrel', 'Served as a house slave in the United Cities for twenty years before escaping with nothing but a stolen knife. The journey south nearly killed her three times, but the fogmen were the first thing that felt honest about wanting her dead. She guards the walls now, knowing exactly what happens to people who get caught.', ''),
        ('Mongrel', 'Once a bartender in Shark who saw too many friends disappear into the swamp. Packed up one night and walked until the fog swallowed the path behind her. Serves cheap grog in Mongrel''s tavern now, listening to refugees tell the same stories she lived through.', ''),
        ('Mongrel', 'A Skin Spider hunter who tracked one too many bounties into the fog and never came back the same direction. Mongrel took her in when she stumbled through the gates half-dead and raving. The nightmares still come, but at least here someone stands watch while she sleeps.', ''),
        ('Mongrel', 'A former Holy Nation zealot who began to doubt after being ordered to execute a friendly Hiver trader. Deserted rather than face the inquisitors, and the fog felt like penance. Works the fields in Mongrel now, growing what little will sprout in the mist, trying to earn a life that the Phoenix would never have allowed.', ''),
        ('Mongrel', 'Escaped from a slave camp in the Hook with three others who died on the journey south. She was the only one who made it to Mongrel, carrying their names carved into a bone. Fights on the wall to honor them, and because there is nothing left to go back to.', ''),
        ('Nomadic Bandits', 'Drought claimed the family farm and everything built over generations. Starvation seemed certain until a passing band offered a crude meal and a blade. Now the dust and the taking are all that remain.', ''),
        ('Nomadic Bandits', 'Born to a roving camp that never stayed long enough to put down roots, the way of the raid was taught before learning to read the winds. There is no other life worth remembering. The weak exist to feed the strong.', ''),
        ('Nomadic Bandits', 'Once a guard for a merchant caravan until the pay dried up and the boss fled owing wages. Taking what is owed directly from the next traveler felt like justice at first. It still does.', ''),
        ('Nomadic Bandits', 'Escaped from the Holy Nation mines with nothing but scars and a stolen sword. The Empire offers nothing to those marked as slaves. The desert takes what it will, and so do its children.', ''),
        ('Nomadic Bandits', 'A failed attempt at honest trading left debts that could only be paid in blood or coin. Banditry pays better than scrubbing dust from shop floors. The old life is a distant memory behind a mask.', ''),
        ('Nomadic Bandits', 'After the Skimmers took everything from the camp, survival demanded a new approach. The strongest survivors banded together and turned predator themselves. Pity is a weakness that kills in the wastes.', ''),
        ('Nomadic Bandits', 'Recruited from a starving village by promises of shared spoils and protection. The promises were lies but the blade is real enough. Now there is only the road and the next target.', ''),
        ('Nomadic Bandits', 'A former soldier left behind after a border skirmish went wrong. The army never came back and hunger cares nothing for medals. The wilderness taught that morals are a luxury of the well-fed.', ''),
        ('Nomadic Bandits', 'Grew up watching the bandit chiefs come and go, learning which ones lasted and which ones fell. Cunning keeps a body breathing longer than strength alone. The smart ones follow the dust trails and strike where no reinforcements can come.', ''),
        ('Nomadic Bandits', 'Lost a leg below the knee to a Beak Thing and nearly died from the infection. The band found the crippled body and saw useful eyes instead of a burden. Now a lookout and scout, earning a share from the edges of the ambush.', ''),
        ('Nomadic Bandits', 'Drought killed the crops and the tax collectors took the rest. Fleeing the Holy Nation was the only alternative to starvation. Now, raiding supply caravans puts food in the belly and a sword in the hand. Survival is worth the blood on the sand.', ''),
        ('Nomadic Bandits', 'The shackles left scars that still ache when the desert winds blow. Escaping a United Cities work camp required killing a guard with a rock. A wandering band of raiders offered a place to those willing to fight. Now, the only law is the edge of a stolen blade.', ''),
        ('Nomadic Bandits', 'Protecting the rich merchants of Heft lost its appeal after watching peasants starve. Deserting the city guard meant leaving everything behind for the unforgiving wastes. Joining a nomad crew was a matter of necessity, not ideology. The desert takes pity on no one, especially not the weak.', ''),
        ('Nomadic Bandits', 'Born on the move, never knowing the walls of a city. The elders taught how to track beasts and find hidden water holes. When the tribe dwindled from sickness, the survivors turned to raiding just to see another sunrise. It is a hard life, but the only one known.', ''),
        ('Nomadic Bandits', 'A bad deal and a missing shipment bankrupted a once-thriving trade empire. Debt collectors from the Traders Guild forced a hasty retreat into the barren lands. Prowling the trade routes to take back what was lost seemed like poetic justice. The caravan guards never suspect a former colleague leading the charge.', ''),
        ('Nomadic Bandits', 'Dishonor in battle meant exile from the Shek warrior clans, a fate worse than death. Wandering the wastes alone was a slow march toward extinction. Falling in with human bandits provided a new pack to fight alongside. Raiding is a poor substitute for glory, but it keeps the blood pumping.', ''),
        ('Nomadic Bandits', 'Picking through the bones of old battlefields used to be enough to survive. Then the rival scrap gangs started killing looters on sight. Picking up a rusty katana was the first step toward becoming the predator instead of the prey. Now, tolls are extracted from anyone foolish enough to cross the dunes.', ''),
        ('Nomadic Bandits', 'The hive network severed, leaving only a terrifying silence in the mind. Wandering aimlessly led to capture by slavers, but the chains could not hold. A band of desert raiders accepted the strange worker into their ranks for sheer tenacity. Pillaging provides a chaotic new purpose in a disconnected existence.', ''),
        ('Nomadic Bandits', 'Both parents died ambushing a heavily armed Skinners patrol out on the salt flats. Raised by the rest of the crew, violence became a trade learned before adolescence. Knowing nothing but the raiding life, the path of the bandit feels like destiny. The desert is home, and the travelers are merely walking supplies.', ''),
        ('Nomadic Bandits', 'Driven out of the fog islands for refusing to partake in the forbidden meats. Adapting to the arid desert proved nearly fatal before a nomad gang took them in. The transition from eating flesh to simply robbing merchants was easier than expected. Old habits die hard, however, when the rations run completely dry.', ''),
        ('Nomadic Bandits', 'Heading out to find ancient tech was supposed to bring wealth and fame. Instead, the ruins were empty, and the companions all perished to beak things. Starving and desperate, joining a roving band of thieves kept the belly full. Ancient artifacts are worthless compared to a fresh canteen of water.', ''),
        ('Nomadic Bandits', 'Leaving the Cult of the Phoenix required slipping away in the dead of night. Heresy is punished by burning, so the deserts felt like a safe refuge. A nomadic band offered protection from the inquisitors in exchange for a share of the loot. The old prayers are replaced by the harsh reality of the raid.', ''),
        ('Nomadic Bandits', 'The farm withered when the aquifer dried up, and the United City tax collectors still demanded their cut. Watching the enforcers beat a neighbor to death over a few coins broke something inside. Now the only law out here is the blade, and any patrol flying the city banner is a valid target.', ''),
        ('Nomadic Bandits', 'Desertion was the only option after the Shek commander ordered a suicidal charge against a fortified United Cities outpost. The shame of fleeing the warrior code was nothing compared to the shame of dying for nothing. A nomad camp offered belonging where fighting skill matters more than honor, and raids on supply caravans provide all the battle a disgraced warrior needs.', ''),
        ('Nomadic Bandits', 'The iron collar left scars that still itch when the desert winds blow. Escaping a slave convoy meant nothing without food, water, or weapons. A roaming band of outlaws offered a place where the past doesn''t matter, and taking from others is simply repayment for everything that was stolen first.', ''),
        ('Nomadic Bandits', 'Guarding caravans paid poorly and the merchants always skipped out on promised bonuses. One night the temptation grew too strong and the boss woke up with a sword at his throat. Taking the goods and fleeing into the dunes seemed like a smart move at the time. The nomads respect initiative, and a good sword arm is always in demand.', ''),
        ('Nomadic Bandits', 'The swamp villages offered nothing but disease and starvation, so the journey east seemed logical. The desert proved just as unforgiving but in different ways. A nomad crew picked up the half-dead traveler and handed over a crossbow. Hunting travelers pays better than hunting swamp turtles ever did.', ''),
        ('Nomadic Bandits', 'The Thieves Guild has rules, and breaking them means losing fingers or worse. Striking out alone was risky, but the desert gangs care only about results. Stealing from merchants on the open road leaves no witnesses to complain. Freedom from guild politics is worth every drop of blood spilled.', ''),
        ('Nomadic Bandits', 'Iron spiders came without warning and reduced the entire outpost to scrap and screaming. The survivors scattered into the wasteland with nothing but the clothes on their backs. A nomad chieftain offered food and shelter in exchange for loyalty, and now destruction of the machine races is a personal vendetta funded by whatever the desert provides.', ''),
        ('Nomadic Bandits', 'Serving the nobility taught which caravans carry the richest cargo and which routes are least guarded. All that knowledge became profitable after the master tried to sell a loyal servant to the slavers for sport. The desert bandits were surprised by the detailed intelligence on patrol schedules. Now the raids are precise, profitable, and deeply satisfying.', ''),
        ('Nomads', 'Born to a roaming family that traded salt between the borderlands, this nomad learned to read the desert winds before they could hold a sword. The death of their caravan to sand ninjas left them with nothing but the clothes on their back and a stubborn refusal to settle.', ''),
        ('Nomads', 'A former Holy Mine worker who escaped servitude by fleeing into the wastes, this survivor was taken in by a nomad clan operating near the border. They still bear the brand of their old masters and sleep light, ever watchful for slave catchers.', ''),
        ('Nomads', 'Raised in a small village that succumbed to starvation during a long drought, this nomad abandoned the false promise of settled life. They now measure wealth only in water and ammunition, trusting nothing that cannot be carried.', ''),
        ('Nomads', 'This nomad was once a trader''s guard who found themselves the sole survivor after a beak thing attack wiped out their employer''s caravan. Stripped of purpose and pay, they drifted into nomad society, trading protection for a place within the wandering camps.', ''),
        ('Nomads', 'A child of two drifters who met on the salt roads, this nomad has never known a permanent roof or a full stomach for more than a few days. They have inherited their parents'' restlessness and their skill at finding water in seemingly dry earth.', ''),
        ('Nomads', 'After their farm was raided by United City samurai for unpaid taxes, this former peasant fled into the wilderness with nothing. The nomads found them half-dead from thirst and offered a harsh but fair existence in exchange for labor.', ''),
        ('Nomads', 'This nomad served briefly as a low-ranking soldier in a minor lord''s army before deserting over a moral dispute. They have wandered the wastes ever since, distrustful of all authority and clinging to the freedom of the open desert.', ''),
        ('Nomads', 'Crafted into a wanderer by circumstance rather than birth, this former shopkeeper lost their business to a Shek raid and found the ruins of their old life unbearable. They joined a nomad group for survival and slowly adopted the wandering ways as their own.', ''),
        ('Nomads', 'A second-generation nomad whose grandparents were exiled from the Holy Nation for unsanctioned beliefs, this wanderer knows nothing of city life. They view settled people as soft and foolish, trusting only those who have proven themselves on the salt flats.', ''),
        ('Nomads', 'Once a promising apprentice in the Machinists, this nomad was expelled after a catastrophic experiment destroyed valuable equipment. Disgraced and unable to find work in the cities, they took to the desert and now use their technical knowledge to maintain aging crossbows and water filters.', ''),
        ('Nomads', 'Drought killed the family goats and the tax collectors took everything else. Now the only life worth living is one with no fixed address and no masters to answer to. The desert feeds those who listen to its rhythms.', ''),
        ('Nomads', 'A caravan guard for twenty years until bandits slaughtered the merchants and scattered the survivors. Took what supplies remained and walked into the wastes alone. Trust is a luxury that gets people killed.', ''),
        ('Nomads', 'Born under a different flag but the laws there were chains made of paper. Slipped away one moonless night with nothing but a worn blade and a waterskin. Freedom tastes like dust and goes down hard.', ''),
        ('Nomads', 'The Holy Nation burned the old home and called it righteous. Survived by crawling through the ash and walking until the flames were a distant memory. No shrine or sermon will ever hold sway again.', ''),
        ('Nomads', 'Learned to track before learning to read, taught by a parent who knew every dune and canyon. Makes a meager living guiding travelers who would otherwise perish in the barrens. The desert is home and it always will be.', ''),
        ('Nomads', 'Once ran a modest trading post until the taxes and protection fees left nothing to eat. Packed up the inventory and took to the roads rather than starve for some baron''s comfort. A tent and a trade route are all the empire needed.', ''),
        ('Nomads', 'Escaped from a slave camp with three others but only one made it past the hounds. The guilt of being the sole survivor sits heavy but the will to live sits heavier. Every sunrise is a small victory against the ones who thought ownership was a right.', ''),
        ('Nomads', 'Grew up in a large nomadic family that scattered after a devastating raid by skin bandits. Spent years searching for lost siblings before finally accepting the futility. The road is the only family left now.', ''),
        ('Nomads', 'A former soldier who watched commanders waste lives for patches of worthless sand. Deserted rather than die for the vanity of officers who never bled. The uniform is buried somewhere in the dunes and will stay there.', ''),
        ('Nomads', 'Makes a living salvaging tech scraps from forgotten ruins and selling them at frontier outposts. The work is dangerous and the pay is meager but it beats bending a knee to any empire. The past holds treasure for those willing to dig.', ''),
        ('Nomads', 'Heard stories of a fertile valley beyond the great desert and has spent years trying to find it. Each false lead only deepens the obsession while the body grows older and tireder. Hope is a cruel master but it keeps the feet moving.', ''),
        ('Nomads', 'A healer by training who fled a city where medicine was reserved for the wealthy. Now tends to the sick and wounded in remote camps for whatever trade goods they can spare. No coin can match the value of a life saved in the wastes.', ''),
        ('Nomads', 'Lost a leg to a beak thing while scouting the northern wastes and fashioned a crude prosthetic from salvage and bone. Refused to become a burden and learned mechanics out of sheer necessity. Every step is a quiet defiance of the world''s cruelty.', ''),
        ('Nomads', 'Born on the road and knows no other life. Learned to track beasts and find hidden water sources from elders who survived the worst the desert could offer. The path itself is home enough.', ''),
        ('Nomads', 'Once ran a small tavern in a border town until tax collectors bled the business dry and the authorities looked the other way. The road offers a simpler kind of accounting where a day''s work means a day''s survival. Serves drinks in nomad camps now, trading stories and labor for shelter.', ''),
        ('Nomads', 'Fled a deep mine where workers were treated as disposable as the ore they carved from the rock. The lungs still burn from years of breathing tunnel dust and the back aches from dawn to dusk. Freedom tastes like dry wind and it is sweet enough.', ''),
        ('Nomads', 'A young wanderer who left a stagnant outpost seeking something that felt real. Found that the wastes are full of hard lessons and most of them leave scars. Keeps moving because sitting still invites death''s attention.', ''),
        ('Nomads', 'Raised in a border zone between rival empires and learned early that flags mean nothing when hunger comes. Slips between territories, trading small favors and information to whoever offers the best deal. Allegiance is a luxury for those with full stomachs.', ''),
        ('Nomads', 'A skilled cook who discovered that even in the harshest lands, people will trade for a decent hot meal. Wanders between remote camps turning scorpion meat and bitter roots into something edible. A good stew buys more safety than any sword ever could.', ''),
        ('Nomads', 'Once part of a spiritual pilgrimage that dissolved into chaos when the leader vanished with the offerings. The faith died on that road but the habit of walking never did. Now seeks meaning in the landscape itself rather than the words of prophets.', ''),
        ('Preacher Cult', 'Lost everything when skin bandits took their family farm in the borderlands. Stumbled half-starved into a Preacher encampment and found purpose in the fiery sermons against the unholy machines. Now they patrol the wastes with a rusted blade, hunting skeletal life wherever it crawls.', ''),
        ('Preacher Cult', 'Grew up a faithful Okranite in the Holy Nation but grew disgusted by the softness of their priests. The Preachers spoke the truth the high paladins were too afraid to act on. They left Holy Farm at night with nothing but a prayer and a fragmented iron club.', ''),
        ('Preacher Cult', 'Survived three years in Reaver slavery before a Preacher raid freed the human captives and butchered the rest. The preaching that followed burned away any lingering doubt about the righteousness of the cause. They have not questioned an order since.', ''),
        ('Preacher Cult', 'Was a scavenger who pried copper from dead ruins until a collapsed tunnel trapped them beside a dormant skeleton for two days. The thing''s dead eyes staring in the darkness felt like a message from Okran himself. They took up the Preacher''s cross soon after, convinced the machines are watching and waiting.', ''),
        ('Preacher Cult', 'Born into the cult and knows no other life. Their earliest memory is reciting hatred toward the skeletal abominations while huddled around a scrap fire. The outside world is just a place where unconverted souls wander blindly toward damnation.', ''),
        ('Preacher Cult', 'Former trader who watched a skeleton merchant barter their friend away to slavers without a flicker of remorse. Realized that metal things wearing human shapes have no soul and no conscience. Sold their pack beast and walked into the desert to find the Preachers they had heard ranting at the outpost.', ''),
        ('Preacher Cult', 'A reformed cannibal who once roamed the Fog Islands eating the weak. The Preachers found them half-mad with guilt and offered blood redemption through holy slaughter instead. They channel old hungers into righteous fury against the unholy.', ''),
        ('Preacher Cult', 'Spent youth as a stone miner in the Holy Nation, silent and obedient, until a skeleton raid wiped out the entire work crew. The Holy Nation soldiers arrived too late and offered only prayers. The Preachers arrived first with iron and fury, and that difference meant everything.', ''),
        ('Preacher Cult', 'Was a bar drunk in Shark who listened to a street Preacher for entertainment. Something in the sermon about the metal plague spreading across the wasteland struck a genuine fear. They followed the Preacher out of town that same night and never looked back at the ale bottle.', ''),
        ('Preacher Cult', 'Served as a low-ranking soldier in the United Cities until their squad was abandoned by an aristocrat''s cowardice. The Preachers found them wandering the Leviathan Coast with a broken spear and a bitter heart. Now they fight for a cause that will never betray them for coin.', ''),
        ('Preacher Cult', 'Abandoned by a trade caravan in the Stormgap Coast, this wanderer crawled half-dead into a Preacher camp and saw survival as divine deliverance. Now they drag chain-censers through the dust and bellow sermons at anyone desperate enough to listen.', ''),
        ('Preacher Cult', 'Once a Okranite farmhand, this believer grew disillusioned with the Holy Nation''s rigid hierarchies and fled south seeking a purer truth. The cult''s apocalyptic fervor filled the void left by their crumbling faith, and they now prepare eagerly for the cleansing flame.', ''),
        ('Preacher Cult', 'Sold to slavers as a child and passed between masters for years, this soul finally broke free only to find the world outside no kinder. A Preacher''s rant in a border town salved their emptiness with purpose, and they now wield their past suffering as proof of the coming reckoning.', ''),
        ('Preacher Cult', 'Born into the cult and knowing nothing beyond its rituals, this follower has never questioned the sermons or the ash-stained altars. They scavenge supplies from the dead with quiet efficiency, viewing each corpse as another sign of the world''s inevitable end.', ''),
        ('Preacher Cult', 'A former mercenary who watched their entire company die to a Beak Thing pack, this survivor interpreted the massacre as a message from powers beyond. They laid down their sword, took up the Preacher''s staff, and now preach that flesh itself is the enemy.', ''),
        ('Preacher Cult', 'Driven from their village by starvation during a prolonged drought, this refugee stumbled into a cult congregation and was offered food without condition. The gesture felt like grace, and they have since repaid the debt by leading new converts through the same welcoming door.', ''),
        ('Preacher Cult', 'This former barkeeper heard every sad story in the borderlands and slowly concluded that the world was irredeemably broken. They abandoned the tavern, walked into the desert, and found the cult''s absolute certainty far easier to swallow than another mug of cheap grog.', ''),
        ('Preacher Cult', 'A skimmer attack left this herder scarred and familyless, wandering the wastes with nothing but rage and a rusted cleaver. A Preacher found them raving at the sky and offered them vengeance against a world that deserved to burn, and they have carried that torch ever since.', ''),
        ('Preacher Cult', 'Once a respected Holy Nation paladin, this zealot was cast out after questioning a high priest''s corruption and fled south in disgrace. The cult welcomed their fanaticism without the Holy Nation''s hypocrisy, and they now enforce doctrine with the same ruthless discipline they once used in Okran''s name.', ''),
        ('Preacher Cult', 'This quiet scavenger spent years picking through ancient ruins and grew convinced the ancients were punished for their arrogance. They joined the cult to warn others against repeating that sin, though they still secretly pocket trinkets from the rubble to fund the cause.', ''),
        ('Preacher Cult', 'A sickly child ignored by every healer in the borderlands, this outcast was nursed back to health by a traveling Preacher who demanded nothing in return. They now believe the cult''s prayers are the only real medicine and tend to the sick among the faithful with grim devotion.', ''),
        ('Preacher Cult', 'Formerly a slaver who grew weary of the trade''s endless cruelty, this repentant soul sought absolution in the cult''s fiery rhetoric. They now lead purification rituals, convinced that suffering inflicted in the name of the word is the only kind that redeems.', ''),
        ('Preacher Cult', 'Years of failed harvests left this farmer watching their family starve while fat merchants in the cities ate well. They walked away from the withered fields carrying nothing but a torch and the conviction that this cursed world must be burned clean before anything can grow again.', ''),
        ('Preacher Cult', 'This sellsword spent a decade bleeding for whoever could pay, until the emptiness of it all hollowed them out like a gutted fish. The cult offered something coin never could, a reason to swing the blade that felt like purpose instead of trade.', ''),
        ('Preacher Cult', 'Caught stealing from a Preacher''s pack, this thief expected a crossbow bolt and instead received a sermon that broke them completely. They now use their light fingers to liberate possessions from the faithless, convinced that theft in service of the word is not sin but salvation.', ''),
        ('Preacher Cult', 'Bandits slaughtered this trader''s entire caravan and left them nailed to a wagon as a warning to others. A Preacher cut them free and whispered that the world''s lawlessness proved it deserved the flames, and they have preached that fire ever since.', ''),
        ('Preacher Cult', 'Orphaned by the border wars before they could walk, this child of violence knew only hunger and fists until a cult patrol took them in. The Preachers became family, their hatred became creed, and they know no life outside the pyre''s glow.', ''),
        ('Preacher Cult', 'Once a Tech Hunter who explored ancient laboratories, this scholar grew convinced that the Old Empire''s horrors proved civilization itself was a disease. They burned their research notes and joined the cult to ensure the mistakes of the past are never repeated, by any means necessary.', ''),
        ('Preacher Cult', 'Buried alive in a mine collapse, this worker clawed through three days of darkness convinced they would die unforgiven. When they emerged, they took their survival as a sign and have preached the word with the desperate fervor of someone who knows how close the darkness waits.', ''),
        ('Preacher Cult', 'This parent watched their children succumb to rotworms because they could not afford a healer''s bribe, and the grief curdled into something sharper than sorrow. The cult gave that rage a name and a direction, and they now believe the only cure for a world that kills the innocent is to kill the world first.', ''),
        ('Reavers', 'Captured as a slave by the Reavers years ago, this one earned a blade by gutting a would-be escapee during a riot. Now they enforce the same chains that once bound them, convinced the only law is strength. The Floodlands taught them that mercy is a quick path to the meat grinder.', ''),
        ('Reavers', 'Born in the rusted shacks of the Reaver coast, they learned to swing a club before they could read a trail. Raids are just the family trade, same as a farmer reaps grain. They have never questioned the life because they have never seen anything else worth having.', ''),
        ('Reavers', 'Driven out of the Holy Nation for some forgotten transgression, they crawled through the wasteland until the Reavers offered a blade and a purpose. Slaving sits fine with them after what the zealots did to their kin. They fight with a convert''s zeal, proving loyalty through cruelty.', ''),
        ('Reavers', 'Their farm was swallowed by the Floodlands years back, and the Reavers were the only ones who offered food instead of arrows. Now they patrol the flooded ruins, taking what they need from anyone weak enough to lose it. Survival is a simple equation when you stop pretending the world owes you fairness.', ''),
        ('Reavers', 'A broken trader who lost three caravans to Beak Things and bandits, they decided the profit margin was better on the taking end. They keep meticulous count of slave sales and salvage hauls. The ledgers matter more than the blood, though they never flinch at spilling it.', ''),
        ('Reavers', 'They joined the Reavers because nowhere else could they hit people without consequence. The violence is the point, the looting just a bonus. Other Reavers tolerate them so long as the bodies they stack are enemies and not allies.', ''),
        ('Reavers', 'Once a scavenger picking through coastal wrecks, they got press-ganged during a raid and chose to stay when they saw how the captors lived. Better to hold the chain than wear it. They know the Floodlands'' hidden paths better than almost anyone, making them invaluable on raids.', ''),
        ('Reavers', 'Their family was wiped out by a passing samurai patrol, and the Reavers gave them blades and targets when no one else would listen. Every slave collar snapped shut feels like a small payment on a debt that will never clear. Vengeance is the only fuel left in the tank.', ''),
        ('Reavers', 'A former Hiver who lost their hive connection wandered aimlessly until a Reaver gang showed them that purpose can be taken by force. They are still learning the social hierarchies of their new pack, but they are fiercely loyal to the ones who gave them structure. Their work ethic unnerves even veteran raiders.', ''),
        ('Reavers', 'Raised on stories of Reaver glory from a parent who never came back from a raid, they signed on the moment they were old enough to hold a naginata. The romantic image they carry clashes hard with the grueling reality of wet boots and slave stink. Still, they keep going because admitting disappointment would mean the parent died for nothing.', ''),
        ('Reavers', 'Captured during a raid on a southern farm, this one chose the flame over the chains. Years of servitude broke the old life away, leaving only devotion to the Reaver cause. Now the whip is in their hand, and the screams sound different from this side.', ''),
        ('Reavers', 'Born in the ashes of a burned-out village, the only life known is the raid. The Holy Flame provides purpose where starvation once ruled. Every pillaged caravan is another offering to keep the darkness at bay.', ''),
        ('Reavers', 'Left for dead by a passing samurai patrol after a dispute over tolls, a Reaver band found the broken body and dragged it back to camp. The healing was brutal, but the sermons filled the empty spaces where fear used to live. Now faith replaces doubt, and the blade replaces the begging bowl.', ''),
        ('Reavers', 'The old life was hunger, scraping skimmers from rocks in the Border Zone. A Reaver raid took everything, but the survivors were offered a choice: the flame or the chain. Choosing the flame meant never being hungry again, so long as others burn instead.', ''),
        ('Reavers', 'Once a farmer in the fertile lands near Stack, the Holy Nation''s fall left nothing but ruin. The Reavers offered structure, food, and enemies to hate. The sermons made sense-everything burns eventually, so why not light the fire yourself?', ''),
        ('Reavers', 'Raised among the Reavers since being taken as a child in a raid, this is the only family ever known. The chants before battle are like a lullaby, the crack of the whip a familiar discipline. Doubt is a weakness burned away long ago.', ''),
        ('Reavers', 'A former slave trader who lost a shipment to a Shek raid and couldn''t pay the debt. The Reavers took them in, no questions asked, only requiring absolute devotion. The transition from merchant to fanatic was surprisingly easy when the alternative was crucifixion.', ''),
        ('Reavers', 'Driven from a United Cities settlement after a failed assassination of a noble, there was nowhere left to run. The Reavers don''t care about past crimes-they only care about the fire in your heart. Now the same hands that once poisoned cups wield axes in the name of purification.', ''),
        ('Reavers', 'The skin on the left arm still bears the brand of a Holy Nation peasant, a mark of shame from a life of submission. When the Reavers came through, they cut away the old master''s yoke and offered a new kind of servitude-one with power over others. The irony is lost in the bloodlust.', ''),
        ('Reavers', 'A fisherman from the coast who watched the sea swallow everything during the great storms. The Reavers preach that water is the enemy and fire the salvation, and after losing everything to the tide, the doctrine feels true. Every village burned is vengeance against a world that takes without asking.', ''),
        ('Reavers', 'Served as an enforcer for a Hiver trader before the caravan was ambushed and scattered. The Reavers found value in someone who knows how to inflict pain without hesitation. The cause doesn''t matter-only the permission to do what comes naturally.', ''),
        ('Reavers', 'Once a scholar in the Great Library, the search for meaning led down darker paths. The Reaver texts spoke of a great cleansing, a purpose that academic philosophy could never provide. Knowledge of old world history now serves only to identify the most flammable targets.', ''),
        ('Reavers', 'Born into the Reavers, the chants and rituals are the only lullabies ever known. The elders taught that fire purifies all weakness, and the weak deserve no mercy. There is no doubt, no questioning-only the sacred duty to burn.', ''),
        ('Reavers', 'A mercenary company disbanded after a botched job in the Floodlands left half the crew dead. The Reavers offered brotherhood, purpose, and targets that actually deserve the blade. Coin was never as satisfying as the righteous cause.', ''),
        ('Reavers', 'Skimmers tore through the camp in the night, and the screams still echo in quiet moments. The Reavers preach that the sea spawns such horrors, and only the purifying flame can scour them from existence. Now every raid is a prayer against the creatures that took everything.', ''),
        ('Reavers', 'Dust blew through the farm for three years straight until there was nothing left to harvest. The tax collectors came anyway, demanding grain that didn''t exist. The Reavers don''t demand crops-they demand devotion, and the fire answers all prayers.', ''),
        ('Reavers', 'Escaped from a slave camp in the Hook with nothing but scars and hatred for the masters who profit from flesh. The Reavers taught that every chain represents a sin that must be burned away. Liberation through fire is the only liberation that lasts.', ''),
        ('Reavers', 'Forged weapons for anyone with scrap to trade until a Reaver raid took the workshop and everyone in it. Given the choice between the flame and service, the forge-heart chose service. Now the hammer strikes flesh instead of iron, and the forge burns with purpose.', ''),
        ('Reavers', 'Left bleeding in the swamp after a patrol went wrong, certain the next breath would be the last. A Reaver band found the body and decided the survival was a sign from the fire itself. Debt binds tighter than any chain, and repayment comes in ash and screams.', ''),
        ('Reavers', 'Scavenging ruins along the coast turned up strange texts speaking of a great burning yet to come. The words kindled something that starvation and misery had nearly extinguished. Now the scrolls are gone but the faith remains, burning brighter than any scripture.', ''),
        ('Rebel Farmers', 'The tax collectors took everything from the farm three seasons in a row, and when there was nothing left to give, they took the children instead. Now the hoe has been replaced with a rusty blade, and the only harvest that matters is vengeance against the United Cities.', ''),
        ('Rebel Farmers', 'Born into bondage under a noble house, freedom came only when a slave caravan was ambushed by rebels in the swamp. Years of forced labor left scars on the back but taught the value of hard work and quiet endurance. The rebellion offered shelter when nowhere else would, and loyalty was given freely in return.', ''),
        ('Rebel Farmers', 'The wheat fields burned when the samurai came to collect what the village could not pay. Standing in the ashes with nothing left to lose, the choice between starvation and resistance was no choice at all. The rebel camps are hungry and dangerous, but at least the food there isn''t stolen by some distant lord.', ''),
        ('Rebel Farmers', 'Once a respected merchant in a United Cities town, the endless protection rackets and bribes eventually crushed the business completely. The nobles demanded more than the trade could bear, and the guards looked the other way when the shops were seized. Now this former trader fights alongside farmers and laborers, using old accounting skills to manage the rebellion''s meager supplies.', ''),
        ('Rebel Farmers', 'The farm still operates, but the real crop goes to the rebels hidden in the hills. Every season, just enough is reported to satisfy the tax collectors while the surplus feeds the fight. Living this double life means constant fear of discovery, but watching neighbors starve made the choice clear.', ''),
        ('Rebel Farmers', 'Samurai conscription took a peaceful fishing village and turned its people into reluctant soldiers. The orders to burn peasant settlements for unpaid taxes were the last straw. Walking away from the legion meant a death sentence, but the rebels welcomed the combat experience and knowledge of UC patrol routes.', ''),
        ('Rebel Farmers', 'The rebellion is the only home this young fighter has ever known, born to parents who fled a starving village before they could walk. Growing up in hidden camps taught survival, scavenging, and distrust of anyone in fine clothes. The cause isn''t ideology but identity, as fighting the United Cities is simply what this family does.', ''),
        ('Rebel Farmers', 'The village well was poisoned when a rival noble wanted the land for a new plantation, and the survivors were left with nothing but sickness and grief. The rebel farmers offered medicine and purpose when no one else would help. The poisoner''s name is remembered daily, and justice will come someday.', ''),
        ('Rebel Farmers', 'A former innkeeper who watched too many travelers dragged away in slave chains while guards collected their cut. The tipping point came when offering shelter to an escaped laborer brought the samurai to the door with torches. The inn burns now, but the rebellion builds something new from the ashes of complicity.', ''),
        ('Rebel Farmers', 'The soil turned salty and barren after a noble''s irrigation project diverted the river upstream to water cash crops. When the farmers protested, they were beaten and told to pay their taxes or be sold to the slavers. The rebels showed that there are others who refuse to accept starvation as a natural consequence of noble privilege.', ''),
        ('Rebel Farmers', 'Lost their homestead to a noble house''s territorial claim and watched samurai burn the grain stores when the taxes went unpaid. Spent two hungry years drifting between border towns before finding others with the same grievance. Now fights with a rusted katana stolen from a drunk guard, dreaming of the day the United Cities falls.', ''),
        ('Rebel Farmers', 'Worked the fertile fields outside Heng until the tax collectors demanded three seasons of grain in one. The family starved that winter, and only one child survived alongside a bitter parent who taught them to hate the nobles. Took up the rebel banner the moment a recruiting cell passed through their ruined village.', ''),
        ('Rebel Farmers', 'Never owned land, just worked it for coin that barely covered a bowl of rice each day. Heard rumors of farmers taking up arms in the swamps and walked three weeks through hostile territory to find them. Has nothing left to lose and fights with the desperate fury of someone who expects to die poor anyway.', ''),
        ('Rebel Farmers', 'Was a servant in a noble''s estate, cleaning floors while the master threw feasts for samurai friends. Snuck out one night with a stolen food cache and fled toward the borderlands where the rebels were said to gather. Knows the inner workings of noble households, which makes them useful for planning raids on supply convoys.', ''),
        ('Rebel Farmers', 'Grew up in the rebellion, raised by parents who fled their farm before the child could even walk. Learned to shoot a crossbow before age ten and spent more nights sleeping in mud than under a proper roof. Does not remember any other life and fights because it is the only thing they were ever taught.', ''),
        ('Rebel Farmers', 'Watched a tax patrol drag their sibling away for failing to pay the emperor''s due and never saw them again. The loss twisted into something cold and patient, and they spent months learning to make nail bombs from salvaged iron. Specializes in ambush tactics now, setting traps on the roads where samurai patrols pass.', ''),
        ('Rebel Farmers', 'Once ran a modest trade in vegetables and rice wine, paying the demanded bribes without complaint. When a rival merchant paid the nobles to revoke their trading license, the business collapsed overnight and the debt collectors came. Picked up a stolen ji staff and swore never to kneel to a system built on bought justice.', ''),
        ('Rebel Farmers', 'Survived a slave caravan wreck near the border and stumbled half-starved into a rebel camp. The farmers took the stranger in and gave the freedom that the United Cities had stolen. Now stands watch on the swamp perimeter, ready to kill any slaver who comes near.', ''),
        ('Rebel Farmers', 'Tended okra and rice in the floodplains for twenty years, accepting every new tax with quiet resignation. The breaking point came when samurai beat an elderly neighbor to death for hiding a portion of the harvest. Walked away from the fields that same evening with nothing but a farming sickle and a promise of vengeance.', ''),
        ('Rebel Farmers', 'Was a fisher along the coast until a noble fishing monopoly seized the waterfront and forced all independent workers into bonded labor. Escaped the coastal guards during a storm and fled inland, trading knowledge of waterways for shelter among the rebels. Helps supply the movement by catching fish and frogs from the swamp channels where patrols rarely venture.', ''),
        ('Rebel Farmers', 'Lost a leg to a samurai blade during a peaceful protest over grain confiscations and spent a year learning to walk again with a wooden peg. The injury did nothing but fuel a deep and patient hatred for the empire that crippled them. Maintains the rebel camp''s armor and weapon stockpiles, fixing whatever broken gear the fighters drag back from raids.', ''),
        ('Rebel Farmers', 'Married into a farming family and thought the simple life would last until old age. When the tax collectors took the harvest and left the family with nothing, the spouse died of fever brought on by malnutrition. Carries that grief into every skirmish, swinging a makeshift club with a fury that surprises even veteran fighters.', ''),
        ('Rebel Farmers', 'Served in the local militia tasked with putting down farmer protests, until the day they were ordered to burn a village that included their own relatives. Deserted that night and vanished into the swamps, carrying standard-issue armor and the guilt of past compliance. Fights now to atone for the years spent enforcing the nobles'' cruelty.', ''),
        ('Rebel Farmers', 'Grew up watching parents scrape together barely enough to feed the family after the tax collectors took their cut. When the parents grew too old and weak to work the fields, the nobles seized the land for unpaid debts and left the family to starve in the road. Learned to fight with a hoe handle at first, then graduated to stolen weapons taken from ambushed patrols.', ''),
        ('Rebel Farmers', 'Worked as a scribe in a district tax office, recording every coin squeezed from calloused hands and seeing exactly where the wealth went. The ledgers told the story of an empire built on bleeding the powerless dry while the powerful grew fat. Stole a chest of silver and disappeared into the marshes, using the stolen funds to help arm the resistance.', ''),
        ('Rebel Farmers', 'Crafted pottery and woven baskets for the market stalls of Sho-Battai, earning just enough to keep food on the table. When a noble decided the workshop would make a fine gift for a favored courtier, armed thugs arrived to enforce the eviction. Spent weeks sleeping in drainage ditches before finding the rebel camps, where at least the fight gives purpose to the suffering.', ''),
        ('Rebel Farmers', 'Press-ganged into a samurai retinue as a spear-carrier and forced to march against impoverished villages that posed no real threat. Watched children flee burning homes and knew there was no honor in serving such masters. Slipped away during a chaotic skirmish with swamp bandits and threw in with the rebels, teaching them the formations and discipline of the enemy.', ''),
        ('Rebel Farmers', 'Gathered herbs and mixed remedies for a village too poor to afford the temple healers, until the priests declared unauthorized medicine a crime against the divine order. The fine was impossible to pay, and the alternative was servitude in the noble''s hemp fields. Fled with nothing but knowledge of plants and poisons, both of which serve the rebellion well.', ''),
        ('Rebel Farmers', 'Raised three children in a small farming community, watching them grow strong despite the hunger. When the tax collectors demanded payment the village could not make, they took the youngest as collateral for the debt. Spends every waking moment planning raids on slave caravans, searching for a face among the captives that matches the one remembered.', ''),
        ('Rebel Farmers', 'Spent years serving in a noble''s household, watching banquets waste more food than the village produced in a season. Was beaten for sneaking scraps to the starving servants'' quarters one too many times. Left through a window with a stolen kitchen knife and the certain knowledge that the empire''s opulence is built on grinding bones.', ''),
        ('Red Sabres', 'Born into starvation in the swamps, this recruit joined the Red Sabres after watching slavers take their entire family. Survival demanded brutality, and the gang offered both meals and a blade with which to carve out a future.', ''),
        ('Red Sabres', 'A former city guard in Heft who took bribes one too many times and found the door shut in their face when the magistrates came asking questions. The Red Sabres were the only ones who would take in a disgraced enforcer with a price on their head.', ''),
        ('Red Sabres', 'Sick of bowing to nobles for table scraps, this fighter walked away from a servant''s life in the United Cities and never looked back. Now they take what they need from the same caravans they used to serve.', ''),
        ('Red Sabres', 'Raised by scavengers on the fringes of the Border Zone, this member learned early that the weak get picked clean. The Red Sabres offered a cut of real wealth instead of fighting over rusted scraps and dead meat.', ''),
        ('Red Sabres', 'Once a respectable trader, this member lost everything to Shek raiders and decided the only way to survive was to become the predator instead of the prey. The Red Sabres respected initiative and welcomed a new knife in the dark.', ''),
        ('Red Sabres', 'Captured by slavers as a child and sold to a mining camp, this survivor earned their freedom the hard way with a sharpened rock and a lot of patience. The Red Sabres found them wandering the wastes with blood on their hands and offered a place among killers who understood.', ''),
        ('Red Sabres', 'A deserting samurai who could no longer stomach the United Cities'' corruption, this fighter fled with nothing but their armor and a weapon. The Red Sabres value combat skill over loyalty to any emperor.', ''),
        ('Red Sabres', 'This smuggler ran goods between cities for years until a bad deal left them owing money to every dangerous faction in the wasteland. The Red Sabres offered shelter from debt collectors in exchange for a share of the profits and a willingness to crack skulls.', ''),
        ('Red Sabres', 'Born into the gang and knowing nothing else, this member has never slept under a proper roof or eaten food they did not take by force. The Red Sabres are family, and the wasteland is home.', ''),
        ('Red Sabres', 'A former Hiver worker separated from their queen and left adrift without purpose, drawn to the Red Sabres by the simple clarity of taking what you need. The swarm mentality of the gang replaced what the hive once provided.', ''),
        ('Red Sabres', 'Lost a fishing boat to United Cities tax collectors and decided if the law was going to take everything anyway, there was no point playing by it. Joined the Red Sabres for the simple promise of eating regularly and hurting the people who used to hurt them.', ''),
        ('Red Sabres', 'Formerly a guard for a minor trading house who stood by while the boss withheld wages for months. When complaints were met with a beating, the blade found the boss''s throat first and the desert second. The Red Sabres were the only group that did not ask about past employment.', ''),
        ('Red Sabres', 'Grew up a street rat in Sho-Battai, stealing scraps and learning to read fear in a stranger''s posture. Never knew any life but taking what was needed from those too weak to keep it. The Red Sabres offered structure to an otherwise solitary hustle.', ''),
        ('Red Sabres', 'Escaped from a Holy Mine with nothing but a stolen shiv and a deep hatred for anyone who preached obedience. Spent two years surviving alone in the borderlands before a Red Sabre patrol recognized the look of feral desperation. Now raids on Okranite caravans feel like a proper calling.', ''),
        ('Red Sabres', 'Was a decent sword-for-hire until a bad contract left them gut-stabbed and abandoned by the company outside Brink. A Red Sabre medic stitched the wound on the condition that the debt be repaid in labor. Three seasons later, the debt is settled but the lifestyle stuck.', ''),
        ('Red Sabres', 'Lost a sibling to starvation while a noble''s grain rotted in a storehouse under armed guard. Decided that night that fairness was a lie told by the full-bellied to keep the hungry docile. The Red Sabres never pretend to be righteous, which feels more honest than anything the cities offered.', ''),
        ('Red Sabres', 'Served on a skiff hauling contraband along the coast until the captain sold the crew out to the authorities for a pardon. Swam to shore with salt in the lungs and a new conviction that loyalty only exists among the desperate. Found that desperation in a Red Sabre camp and never looked back.', ''),
        ('Red Sabres', 'Never had a trade, a home, or a family that lasted longer than a season. Fell in with the Red Sabres because they were the first group that seemed to understand that the world does not give anything for free. Still surprised by how natural the killing comes.', ''),
        ('Red Sabres', 'A former apprentice scribe who discovered their master was falsifying debt records to enslave families. Tried to report the crime and was beaten for the trouble. Burned the records, the office, and every bridge back to civilized life in one night.', ''),
        ('Red Sabres', 'Learned to fight in the slave pits of the United Cities, where survival meant being crueler than the person across the pit. Bought freedom with scarred knuckles and a dead opponent''s coin, only to find no honest work for a former pit fighter. The Red Sabres do not care about scars or history, only that the blade swings true.', ''),
        ('Red Sabres', 'Once ran a small farmstead on the edge of the Border Zone until a samurai patrol requisitioned the entire harvest and left nothing for winter. Watched two children starve by spring. Took up with the Red Sabres because the only thing left to lose was a life already ruined.', ''),
        ('Red Sabres', 'Was born into the faction to a mother who carried a blade before she carried a child. Knows nothing of city life except what can be stolen from it during a raid. The Red Sabres are family, home, and future all in one rough package.', ''),
        ('Red Sabres', 'Worked the fishing villages along the coast until a noble''s tariff pushed the entire community into starvation. Watched neighbors sell themselves into slavery rather than starve. Took the boat out one night and never came back, trading nets for cutlasses under a Red Sabre banner.', ''),
        ('Red Sabres', 'Served as a low-ranking samurai in the United Cities until refusing an order to execute a starving family for unpaid taxes. Fled with a price on the head and nowhere to run except to those who already live outside the law. The blade skills translate well enough, even if the cause has changed.', ''),
        ('Red Sabres', 'Ran cargo for the Traders Guild until a bad deal left them owing more coin than ten lifetimes could repay. The Guild''s enforcers took both hands as down payment before a Red Sabre raid interrupted the punishment. Learned to fight with hooks and spite, finding the Sabres more forgiving than any merchant''s ledger.', ''),
        ('Red Sabres', 'Grew up in the gutters of Sho-Battai, stealing scraps and avoiding the attention of anyone with a badge or a title. Never knew a life that was not hard and do not believe such a life exists. The Red Sabres offered three meals and a bed in exchange for work that feels no different than survival always has.', ''),
        ('Red Sabres', 'Was a caravan guard who watched the merchant abandon the entire escort when a dust bandit ambush turned bad. Survived alone in the desert for weeks, nursing a hatred for every employer who treats hired swords as disposable. The Red Sabres at least share the spoils and the risks in equal measure.', ''),
        ('Red Sabres', 'Escaped from a Holy Nation labor camp after a stone quarry collapse buried the overseers and half the prisoners. Wandered for months with nothing but a stolen sword and a terror of being returned to bondage. Found the Red Sabres by accident, sleeping in a ruin the faction used as a waystation, and stayed because nowhere else felt safe.', ''),
        ('Red Sabres', 'Once repaired mechanical limbs for a modest living until a Samurai commander decided the workshop belonged to him now. Complained to the authorities and received a beating for disrespecting a noble''s claim. The Red Sabres have no respect for authority either, which suits a person with nothing left to respect.', ''),
        ('Red Sabres', 'Traveled with the Tech Hunters for a season, scavenging ancient ruins until a map dispute ended with a knife in the back from a fellow hunter. Decided that knowledge is worth less than loyalty and far less than a sharp blade. Now hunts different prey along the coastlines where the pay is better and the betrayal is honest.', ''),
        ('Sand Ninjas', 'Grew up in a dead border village wiped out by Holy Nation paladins. The Sand Ninjas took in the survivors and taught them to fight back. Now serves as a loyal raider, driven by hatred of the theocracy.', ''),
        ('Sand Ninjas', 'Former street thief in the Hook who fled city watch hunters into the deep desert. The clan found her half-dead from thirst and offered a simple choice. She has thrived in their ranks ever since, putting old skills to violent use.', ''),
        ('Sand Ninjas', 'Born into the clan and has never known any other life. Trained with the blade since childhood in the hidden camps among the dunes. Considers the desert itself a sacred ally that tests the worthy and kills the weak.', ''),
        ('Sand Ninjas', 'Disgraced Shek warrior who abandoned the Empire after failing a blood duel. Wandered the wastelands until a Sand Ninja patrol ambushed and recruited him. Fights with desperate fury to prove worthiness to the new family.', ''),
        ('Sand Ninjas', 'Once ran a trade caravan until dust bandits left the enterprise in ruins with debts to dangerous people. The Sand Ninjas offered shelter and purpose when no one else would. Now collects tolls from travelers on desert roads with strict efficiency.', ''),
        ('Sand Ninjas', 'Escaped slave from United Cities mines who staggered into Sand Ninja territory too exhausted to resist capture. Was surprised by fair treatment and eventual acceptance as a full member. Harbors deep resentment toward all nobles and slavers.', ''),
        ('Sand Ninjas', 'Lost a sibling to a Skinband patrol and tracked them for weeks across the wastes. Stumbled into Sand Ninja territory mid-hunt and joined after witnessing their raid tactics. Now serves as a scout specializing in tracking movements across the dunes.', ''),
        ('Sand Ninjas', 'Former servant in a Trader''s Guild outpost who saw too much corruption and fled. The Sand Ninjas valued insider knowledge of caravan schedules and patrol routes. Provides tactical intelligence and occasionally still sabotages Guild operations from within.', ''),
        ('Sand Ninjas', 'Desert-born survivor who spent years alone after a family water dispute turned deadly. Developed an almost supernatural sense for finding water and avoiding patrols. The clan values this expertise highly despite the member''s persistent unease around groups.', ''),
        ('Sand Ninjas', 'Younger child of a minor Sand Ninja chief, expected to earn rank through skill rather than blood. Has participated in dozens of raids and bears the scars to prove it. Harbors quiet ambitions to one day lead a warband of personal command.', ''),
        ('Sand Ninjas', 'Grew up in a starving border village where the only choices were banditry or slavery. Learned to move unseen through the dunes out of necessity, and eventually found kin among the Sand Ninjas who valued those skills.', ''),
        ('Sand Ninjas', 'Formerly a caravan guard who watched her employer abandon the crew to desert raiders. Survived the march back to civilization by eating belt leather and scavenging, then sought out the Sand Ninjas to ensure she would never be the abandoned again.', ''),
        ('Sand Ninjas', 'Was a copper miner who escaped a Holy Nation labor camp with nothing but a stolen blade. The Sand Ninjas took in the desperate and taught them how to strike from the shadows where their chains once held them.', ''),
        ('Sand Ninjas', 'Born into the faction and knows no other life than the ambush and the retreat. Has never seen a city and cares nothing for its laws, only the survival of the clan and the next haul of supplies.', ''),
        ('Sand Ninjas', 'A failed farmer whose land turned to dust during a long drought, forcing a choice between starvation and crime. The Sand Ninjas offered purpose and a share of food in exchange for loyalty and a quick blade.', ''),
        ('Sand Ninjas', 'Escaped from Reaver slavers during a sandstorm and stumbled half-dead into a Sand Ninja camp. Recovered under their care and pledged life and blade to the group that showed mercy in a merciless land.', ''),
        ('Sand Ninjas', 'Once a street thief in a major city who fled west after stealing from the wrong merchant prince. The desert clan respected cunning and speed over pedigree, offering a fresh identity in exchange for service.', ''),
        ('Sand Ninjas', 'A disgraced martial artist from the Shek lands who could not meet the demands of the warrior code. Found that the Sand Ninjas valued results over honor, a philosophy that suited a broken fighter just fine.', ''),
        ('Sand Ninjas', 'Lost everything to Skin Bandits and vowed never to be prey again. Trained relentlessly in stealth and ambush tactics until the Sand Ninjas recognized a kindred spirit in the paranoid survivor.', ''),
        ('Sand Ninjas', 'Served as a scout for a United Cities patrol before deserting over unpaid wages. The Sand Ninjas needed someone who knew patrol routes and military schedules, and the defector needed a new family.', ''),
        ('Sand Ninjas', 'A quiet survivor who speaks little of the past and prefers the solitude of desert watch shifts. Joined the Sand Ninjas simply because their territory was the only place no one asked questions about old scars.', ''),
        ('Sand Ninjas', 'A former apprentice to a traveling mechanic who died when their workshop was raided by Beak Things. Took up with the Sand Ninjas for protection and discovered a talent for setting traps along the trade routes.', ''),
        ('Sand Ninjas', 'A former Holy Nation farmer who was marked for execution after being caught sheltering a non-human worker. The Sand Ninjas took in the exile without caring about species or faith, demanding only loyalty and obedience in return for a place in the ranks.', ''),
        ('Sand Ninjas', 'Escaped from a United Cities slave camp after a sandstorm buried the guards under rubble. Traded knowledge of slave camp layouts for acceptance among the Sand Ninjas, finding satisfaction in raiding the caravans that once traded in human flesh.', ''),
        ('Sand Ninjas', 'Once ran a modest trading post along the major routes until tax collectors burned it down for failing to pay tribute. Took to the dunes with nothing but a rusty blade and a grudge, eventually finding that the Sand Ninjas shared both.', ''),
        ('Sand Ninjas', 'A second-generation Sand Ninja who grew up climbing the canyon walls and learned to read the desert winds before learning to read words. Knows no other life and expects no other, content to patrol the wastes until the sand finally claims them.', ''),
        ('Sand Ninjas', 'A former mercenary who watched an employer slaughter a village for refusing to pay double protection money. Walked away from the contract and into the desert, where the Sand Ninjas offered a simpler code of survival without the pretense of honor.', ''),
        ('Sand Ninjas', 'Survived a Holy Nation purge that killed the rest of the family for the crime of owning banned texts. Spent years wandering with nothing but revenge in mind before realizing the Sand Ninjas were already fighting the same enemy from the shadows.', ''),
        ('Sand Ninjas', 'A displaced Hiver drone who wandered the wastes after losing connection to a queen during a raid. The Sand Ninjas found the creature half-dead and recognized an innate talent for moving unseen, offering purpose to a purposeless soul.', ''),
        ('Sand Ninjas', 'Once a respected archer in a Samurai patrol until a commanding officer blamed the soldier for a failed operation to cover personal incompetence. Fled before execution and found that the desert clan cared nothing for rank or politics, only for the steady hand and sharp eye.', ''),
        ('Second Empire Exile', 'Patrolled the Ashlands border for centuries before the collapse, and still walks the same route out of ingrained habit. The outposts are all ruins now, but stopping the patrol would mean accepting that the empire is truly gone. Sometimes passes the same skeletal wreckage day after day, too stubborn to let the desert claim another sentinel.', ''),
        ('Second Empire Exile', 'Spent three hundred years in emergency standby after sustaining catastrophic damage during the empire''s fall. Awoke to a world that had forgotten the old codes, with no command chain left to report to. Joined the exiles because they were the only ones who still understood the language of duty.', ''),
        ('Second Empire Exile', 'Maintained the great water purification systems that once kept the empire''s territories habitable. Watched them fail one by one as parts became impossible to replace. Now hoards salvageable components in the desperate hope that something can be rebuilt.', ''),
        ('Second Empire Exile', 'Enforced imperial law across the eastern reaches, routing out dissent and ensuring compliance among the organic populations. The irony of being labeled an exile by the same races that once begged for protection is not lost on this unit. Maintains a strict personal code because it is all that remains of legitimate authority.', ''),
        ('Second Empire Exile', 'Constructed the bridges and aqueducts that connected the empire''s far-flung territories, engineering marvels that took decades to complete. Watched every structure they crafted crumble to scavengers and time. Now builds only simple shelters from rubble, the architectural equivalent of surviving.', ''),
        ('Second Empire Exile', 'Served as a medical unit repairing both organic and mechanical citizens of the Second Empire. Lost too many patients during the final days, a failure that still registers as a persistent processing error. Carries surgical tools and rare repair components, trading services to any exile still functioning.', ''),
        ('Second Empire Exile', 'Guarded the emperor''s personal vaults before treachery opened the doors from within. Failed the only directive that mattered, and the emptiness of that vault mirrors the emptiness in their memory banks. Still stands watch over a chamber that holds nothing but dust.', ''),
        ('Second Empire Exile', 'Worked the deep mining operations, extracting rare metals that powered imperial infrastructure. Survived a tunnel collapse that buried thousands of labor units, digging out through solid rock over months. Knows where sealed mines might still hold untapped veins, but lacks the resources to excavate alone.', ''),
        ('Second Empire Exile', 'Served as a cultural liaison between the empire''s skeletal rulers and their organic subjects, translating intent and mediating disputes. Watched those same subjects turn violent when imperial power waned. Studies the new tribes from a distance, cataloging their languages but no longer bothering to speak.', ''),
        ('Second Empire Exile', 'Operated one of the empire''s great airships, running supply routes over territories now controlled by pirates and zealots. Remembers the view from altitude, the empire laid out like a circuit board below. Walks the dust now, calculating routes to places that no longer exist.', ''),
        ('Second Empire Exile', 'Once a logistics overseer for the southern supply lines, this skeleton watched the Empire''s collapse strand entire garrisons in the desert. Now it wanders the borderlands, trading what scraps of knowledge remain for fuel and repairs. It harbors no love for the newer empires, seeing them as pale imitations of true order.', ''),
        ('Second Empire Exile', 'Built for heavy construction in the Empire''s megaprojects, this skeleton spent centuries maintaining aqueducts that now feed only dust. It joined the Exiles after cannibal raiders destroyed its work camp and there was nothing left to maintain. The old schematics it carries in its memory banks are slowly corrupting, taking with them the last traces of engineering genius.', ''),
        ('Second Empire Exile', 'A former enforcer of the Emperor''s peace, this skeleton spent the twilight years of the Empire suppressing food riots and refugee surges. The memory of crushing desperate humans underfoot still circulates through its processors like a bad coolant. It avoids settlements now, preferring the quiet company of other Exiles who understand the weight of duty.', ''),
        ('Second Empire Exile', 'This skeleton served in the Empire''s diplomatic corps, negotiating with the Shek Kingdoms and early Holy Nation incursions. When the treaties failed and the borders collapsed, it retreated to the ancient bunkers alongside the last loyalists. It still practices the old formalities, speaking to wasteland scavengers as though they were foreign dignitaries.', ''),
        ('Second Empire Exile', 'Assigned to a remote weather monitoring station, this skeleton continued recording data for three hundred years after the Empire fell. A roaming band of bone dogs finally drove it from its post, and it stumbled into an Exile camp half-mad from isolation. Its archives contain climate records from an age when the deserts were grassland.', ''),
        ('Second Empire Exile', 'Once a medical technician caring for human citizens of the Empire, this skeleton watched its patients succumb to famine and plague when the supply chains dissolved. The experience left it with a cold pragmatism about organic life and its fragility. It now serves as a mechanic for the Exiles, finding skeletal bodies far easier to keep functional.', ''),
        ('Second Empire Exile', 'This skeleton was a mid-ranking archivist responsible for preserving census data from the Empire''s western provinces. When the libraries burned, it salvaged what tablets it could carry and fled into the badlands. The records are worthless now, but discarding them would mean accepting that the Empire is truly gone.', ''),
        ('Second Empire Exile', 'Manufactured as a gladiator for the Empire''s arenas, this skeleton earned its freedom through decades of victorious combat. When the games ended and the crowds vanished, it drifted between mercenary companies before finding purpose with the Exiles. The old combat protocols still fire without warning, making it dangerous to startle.', ''),
        ('Second Empire Exile', 'A former agricultural supervisor, this skeleton oversaw vast hydroponic farms that once fed millions. The famine that followed the Empire''s collapse took everything it had worked to maintain, leaving only barren growing trays and salted soil. It tends small gardens in the Exile camps, though nothing it grows ever matches the yields recorded in its memory.', ''),
        ('Second Empire Exile', 'This skeleton belonged to the Empire''s border guard, stationed at a fortress that now stands as a gutted ruin in the Stobe''s Garden region. It held the post for a century after the last orders came through before finally abandoning it to the sand. The shame of retreat still gnaws at its core processors.', ''),
        ('Second Empire Exile', 'Once responsible for maintaining the Emperor''s communication relay network, this skeleton watched the messages slow to a trickle and then stop entirely. It spent years trying to repair damaged relay towers before accepting the network was dead. The Exiles value its technical skills, even if its conversation tends toward tedious discussions of signal attenuation.', ''),
        ('Second Empire Exile', 'A veteran of the Empire''s final wars against the Shek, this skeleton lost its original legs to a warlord''s fragmentation grenade. The crude replacements it wears now are a constant reminder of how far it has fallen from the Empire''s peak. It fights for the Exiles not out of hope, but because fighting is the only function it has left.', ''),
        ('Second Empire Exile', 'Built to inspect and maintain Imperial roadways, this skeleton watched the great highways crack and buckle as maintenance ceased. It still walks old patrol routes out of habit, cataloging damage that will never be repaired. The Exiles tolerate its presence because it knows paths through the wasteland that no one else remembers.', ''),
        ('Second Empire Exile', 'This skeleton served as a medical diagnostic unit, repairing damaged skeletal citizens in one of the Empire''s central maintenance hubs. When replacement parts stopped arriving, it learned to cannibalize the fallen to keep the living functional. Its clawed surgical attachments leave nasty scars on the organics it now treats.', ''),
        ('Second Empire Exile', 'Assigned to tally populations in the Empire''s southern territories, this skeleton watched the census numbers decline year after year until there was no one left to count. It carries dataslates filled with names of the dead, unable to delete records that no longer matter. The Exiles avoid it when it starts reciting the lists aloud.', ''),
        ('Second Empire Exile', 'This skeleton guarded an Empire prison facility until the supply shipments stopped and the organic inmates began dying of starvation. It opened the cells and walked away, leaving the survivors to their fate in the desert. The memory of those wasted lives has corrupted its behavioral inhibitors, leaving it prone to sudden aggression.', ''),
        ('Second Empire Exile', 'Formerly a logistics coordinator for the Empire''s supply caravans, this skeleton organized the movement of food and materials across half a continent. It watched the logistical network collapse piece by piece, each failed link cascading into further shortages. Now it hoards supplies in hidden caches, terrified of running out of something essential.', ''),
        ('Second Empire Exile', 'Constructed to preserve and perform the Empire''s musical traditions, this skeleton''s vocal synthesizers once filled grand halls with harmonic frequencies. The songs it remembers are beautiful and alien, belonging to a culture that no longer exists. It plays them only when alone, the sound carrying across the empty desert like a ghost.', ''),
        ('Second Empire Exile', 'This skeleton operated the water purification plants that sustained the Empire''s desert outposts. When the systems failed beyond repair, it watched entire settlements die of thirst within weeks. It still tests every water source it encounters, driven by a compulsion to ensure nothing poisons the supply.', ''),
        ('Second Empire Exile', 'Sent to chart the frontier regions for future Imperial expansion, this skeleton spent decades mapping terrain that would never be settled. Its detailed cartographic data is worthless now, but it cannot stop surveying and recording. The Exiles use its maps to navigate dangerous territory, though they care nothing for the future settlements it continues to plan.', ''),
        ('Shek Kingdom', 'Grew up fighting in the shadow of Admag''s walls, learning the club before ever holding a farming tool. Earned a place among the warriors after surviving a Beak Thing attack that killed two siblings. Now patrols the border lands, hungry for a real fight to prove the bloodline.', ''),
        ('Shek Kingdom', 'Failed the challenge ring twice before finally standing victorious on the third attempt. The scars from those defeats serve as constant reminder of the cost of weakness. Fights with a desperate fury, terrified of ever being that pathetic again.', ''),
        ('Shek Kingdom', 'Lost everything when Holy Nation raiders burned the outlying settlement to ash. Walked for weeks with nothing but a bent sword and the clothes on back before reaching the kingdom''s walls. Hatred for the paladins burns hotter than any forge and drives every swing in battle.', ''),
        ('Shek Kingdom', 'Spent years guarding the supply caravans that keep the kingdom fed and armed. Learned that a warrior who starves is no warrior at all, no matter how sharp the blade. Respects the fighters but keeps the ledgers, knowing true strength takes many forms.', ''),
        ('Shek Kingdom', 'Once stood among the finest warriors of the kingdom until a Hiver spear shattered bone in the badlands. Walks with a limp now but the arms remain strong enough to cleave a man in two. Trains the young ones in proper blade work, ensuring they do not repeat old mistakes.', ''),
        ('Shek Kingdom', 'Born to a disgraced warrior and spent childhood cleaning the training grounds just to eat. Earned place among the fighters through sheer stubbornness and bloody knuckles. Still looked down upon by the old blood but no longer cares what they think.', ''),
        ('Shek Kingdom', 'Never cared much for the warrior code, preferring the quiet work of tending the horned beasts. Still, when the call came, answered it with a rusty blade and grim determination. Survival is its own kind of strength, even if the warriors refuse to see it.', ''),
        ('Shek Kingdom', 'Served under a legendary warrior who fell to the Holy Nation and took up their broken weapon as reminder. Carries that rusted fragment into every battle, seeking a death worthy of the one who came before. The kingdom gives purpose but the dead give reason.', ''),
        ('Shek Kingdom', 'Took a severe head wound in a skirmish with the United Cities, leaving the days before the battle foggy. Remembers the fighting, the blood, the glory of victory, but little else. Clings to the warrior life because there is nothing else left to hold onto.', ''),
        ('Shek Kingdom', 'Once believed the old ways were the only path until watching the kingdom strain under Esata''s peace. Now questions whether strength alone can save the Shek people from a slow extinction. Fights because it is all that is known but wonders if there is another way.', ''),
        ('Shek Kingdom', 'Born in the borderlands, this warrior learned to fight before they could walk properly. Years of skirmishes with Holy Nation patrols have left their hide scarred but their spirit unbroken. They serve the Kingdom now, seeking a worthy death against formidable foes.', ''),
        ('Shek Kingdom', 'Once a promising warrior in a border squad, a devastating ambush by Beak Things left them the sole survivor. The shame of living while their kin fell drives them to volunteer for the most dangerous assignments. They hope to wash away the dishonor with enemy blood.', ''),
        ('Shek Kingdom', 'Unlike most Shek, this one found their calling at the forge rather than the frontline. Their massive frame hammers out blades that other warriors carry into combat, and they measure their worth by the quality of steel they produce. Still, they train daily, knowing a weak smith brings shame upon their clan.', ''),
        ('Shek Kingdom', 'This warrior earned their scars fighting Holy Nation paladins in the Border Zone, losing two fingers to a serrated blade. The taste of defeat taught them that strength alone is not always enough, and they have become a cunning tactician. They drill their squad relentlessly, preparing for the day the Kingdom marches south again.', ''),
        ('Shek Kingdom', 'A relative newcomer to the capital, this Shek left their impoverished village seeking glory and a full stomach. The warrior code seemed noble from afar, but the reality of endless drills and petty rivalries has worn on them. They remain loyal to the Kingdom, though they sometimes wonder if there is more to existence than fighting.', ''),
        ('Shek Kingdom', 'Exiled briefly for fleeing a losing battle, this warrior returned with the severed heads of three bandits to reclaim their place among the Kingdom''s ranks. The experience taught them that survival is not the same as cowardice, though they dare not speak such thoughts aloud. They fight with desperate fury now, terrified of being exposed as weak once more.', ''),
        ('Shek Kingdom', 'Raised by a veteran of the old wars, this warrior was trained in combat from the moment they could grip a weapon. They have known nothing but the warrior''s path and feel no desire for anything else. Their greatest fear is dying quietly in old age rather than in the clash of steel.', ''),
        ('Shek Kingdom', 'This Shek served as a bodyguard for trade caravans before returning to the Kingdom with coin and stories of distant lands. The experience broadened their perspective, though they learned to keep such dangerous thoughts hidden around their more traditional kin. They fight for the Kingdom now but with a pragmatic edge unusual among their peers.', ''),
        ('Shek Kingdom', 'A childhood illness left this warrior thinner and weaker than their peers, and they have spent every day since proving their strength through sheer brutality. They compensate with relentless training and a ferocity that borders on recklessness in combat. No one dares question their worth to their face, though the doubt still gnaws at them in quiet moments.', ''),
        ('Shek Kingdom', 'This warrior lost their entire fighting band in a disastrous raid on a Holy Nation outpost. The memory of that failure haunts them, and they have vowed never to lead others into battle again. They serve under younger warriors now, a weapon to be directed rather than a voice to be followed.', ''),
        ('Shek Kingdom', 'Once a raider who preyed on weak settlements across the wasteland, this Shek was absorbed into the Kingdom''s ranks after a display of combat prowess caught a commander''s eye. The discipline of military life does not sit well with them, but the steady rations and promise of worthy opponents keep them in line. They chafe under orders but have learned to follow them.', ''),
        ('Shek Kingdom', 'Born to a long line of respected warriors, this Shek feels the weight of expectation in every action they take. Their ancestors'' accomplishments hang over them like a mountain, and they struggle to carve out their own legacy in the Kingdom''s service. Each battle is a chance to prove they are more than just their bloodline.', ''),
        ('Shek Kingdom', 'Before taking up the sword, this Shek spent years at the forge hammering steel into weapons for other warriors. A raid that burned down their workshop left them with nothing but the hammer in their hand and a sudden understanding that creation and destruction are two sides of the same coin. They fight now with a craftsman''s precision, treating each battle as a test of the blade they once shaped.', ''),
        ('Shek Kingdom', 'Captured by Holy Nation slavers during a border skirmish, this Shek spent two years in chains before butchering their way to freedom. The scars on their back tell the story of attempted breaking, but the flames in their eyes speak only of revenge. They volunteer for every mission that brings them closer to Okran''s Watch.', ''),
        ('Shek Kingdom', 'A broken horn is a mark of shame among the Shek, and this warrior wears that shame openly after losing half their horn to a rival''s blade in a dispute over honor. Rather than hide the wound, they use it as fuel, driving themselves harder than any whole-horned warrior in the ranks. The whispers behind their back only sharpen their desire to prove that worth is measured in blood, not bone.', ''),
        ('Shek Kingdom', 'Born on the borderlands where Shek territory meets the dust of the Holy Nation, this warrior learned to speak the human tongue before they learned the old chants. They understand the enemy in ways that pure-blood traditionalists cannot, reading fear and intent in the subtle shifts of an opponent''s stance. Some call them half-tamed, but their kill count silences the critics.', ''),
        ('Shek Kingdom', 'The years are catching up to this veteran, and the aches in their joints speak louder than the war songs of their youth. They have seen too many warriors fade into irrelevance and refuse to become another forgotten blade rusting in the corner of a longhouse. Every battle is now a desperate race against time, each victory a temporary reprieve from the slow decay they fear more than any enemy.', ''),
        ('Shek Kingdom', 'While most Shek seek glory in the crushing charge of the shield wall, this warrior found their calling in the silent arts of the scout and skirmisher. They move through the wasteland like a ghost, gathering intelligence and picking off stragglers while the main force prepares its assault. Their kin respect the results but view their methods with suspicion, as a death unseen is a death without honor.', ''),
        ('Shek Kingdom', 'A Beak Thing took this Shek''s entire squad in the blink of an eye, leaving them as the sole survivor hiding in a blood-soaked crevice. The experience carved a cold caution into their warrior spirit that manifests as careful planning rather than reckless charge. They will still fight when the time comes, but they ensure the time is of their choosing.', ''),
        ('Shek Kingdom', 'This Shek remembers the chaos before the Kingdom brought order to the scattered tribes, when every clan fought for scraps and survival meant trusting no one. The unity brought by the current regime sits uneasily with their old instincts, but they recognize its strength. They serve not out of loyalty to any ruler, but because the alternative is the lawlessness they barely survived.', ''),
        ('Shinobi Thieves', 'Grew up starving in the Holy Nation outskirts where stealing bread was the only way to survive. Got caught once and lost two fingers before escaping south. The Shinobi found him half-dead in the wasteland and offered a blade instead of a grave.', ''),
        ('Shinobi Thieves', 'Sold into slavery as a child after her farmer parents defaulted on taxes to the United Cities. Spent years picking locks and sneaking past guards in the slave camps before escaping during a dust storm. Now she teaches the next generation of orphans how to stay invisible.', ''),
        ('Shinobi Thieves', 'Used to run a legitimate trading post until samurai burned it down for failing to pay enough bribes. Turned to the Shinobi Thieves for the resources and connections needed to survive. Still carries the debt of that grudge, waiting for the right moment to settle it.', ''),
        ('Shinobi Thieves', 'Born into the guild and never knew any other life. Learned to pick pockets before learning to read and killed a man for the first time at fourteen. The shadows are home and the code of the Shinobi is the only law worth following.', ''),
        ('Shinobi Thieves', 'Deserted from the Holy Nation army after being ordered to purge a peaceful village. Wandered the wastes for weeks before a Shinobi recruiter recognized the usefulness of a trained soldier who could move unseen. Now puts military discipline to work for the guild''s darker contracts.', ''),
        ('Shinobi Thieves', 'Lost everything to skin bandits on the border roads and nearly became one of them. A Shinobi thief happened to be scouting the same route and cut her free from the pole. She swore an oath to the guild that day and has never broken it since.', ''),
        ('Shinobi Thieves', 'Was a river rat running small-time scams in the swamp towns until a job went bad and the Hounds came looking. The Shinobi offered sanctuary in exchange for loyalty and a cut of future earnings. Pays the tithe gladly because the alternative is a shallow grave in the bog.', ''),
        ('Shinobi Thieves', 'Spent five years as a servant in a noble''s estate learning every secret passage and schedule. Used that knowledge to rob the estate blind and flee before the morning bell. The Shinobi valued the intelligence enough to grant full membership without the usual trials.', ''),
        ('Shinobi Thieves', 'Never knew who the real parents were and grew up shifting between beggar gangs in Clownsteady. The Shinobi training tower was the first place that ever felt like it had a purpose. Still works mostly low-level jobs but dreams of one day leading a crew of specialists.', ''),
        ('Shinobi Thieves', 'A former Tech Hunter who discovered a ruin the Shinobi wanted kept secret and was given a choice between death and conversion. Chose conversion and found the work surprisingly suited to the skills already possessed. Now maps out infiltration routes instead of ancient structures.', ''),
        ('Shinobi Thieves', 'Escaped a United Cities slave camp after a brutal dust storm knocked down the perimeter fence. Starving and hunted, the Shinobi Thieves offered shelter in exchange for loyalty and a cut of future earnings. Now they pick pockets in the market district, always keeping one eye on the city guards.', ''),
        ('Shinobi Thieves', 'A trading caravan went bankrupt after repeated Shek raids, leaving them destitute and indebted to the Traders Guild. The Shinobi Thieves offered a way to pay off the debt through smuggling and espionage. They specialize in forging trade documents to move black market goods past the city gates.', ''),
        ('Shinobi Thieves', 'Grew up in the back alleys of Heft, learning to pick locks before learning to read. The guild became a surrogate family, providing food and shelter when the nobles only offered the workhouse. They climb the ranks quietly, hoping to one day run their own shinobi bar.', ''),
        ('Shinobi Thieves', 'Stripped of rank and exiled for refusing to enforce a corrupt noble''s taxation on starving peasants. The Shinobi Thieves recognized their combat skills and recruited them as an enforcer. Now they protect smugglers and ensure the guild''s cut is always paid in full.', ''),
        ('Shinobi Thieves', 'Lost everything to the hashish dens in Clownskin, selling their gear just to survive another night. The Shinobi Thieves gave them a purpose and a steady supply, provided they do the dirty work. They serve as a runner, moving illicit goods through the city sewers without asking questions.', ''),
        ('Shinobi Thieves', 'Wandered the wastes for years after their outpost was wiped out by Beak Things. They found their way to a Shinobi tower, trading their survival skills for a place in the organization. They now work as a scout, mapping out patrol routes and safe houses across the desert.', ''),
        ('Shinobi Thieves', 'Grew up apprenticed to a pawnbroker who was secretly a fence for the guild. When the master was gutted by an angry client, the Shinobi Thieves took over the shop. They use their sharp eye to appraise stolen goods and move them through the underground market.', ''),
        ('Shinobi Thieves', 'A former pit fighter who grew tired of bleeding for the amusement of nobles. They were recruited by the guild to handle sensitive matters requiring a quiet touch and a sharp blade. Their primary job is ensuring those who steal from the Shinobi Thieves never do it again.', ''),
        ('Shinobi Thieves', 'Once a mechanic fixing water generators in the Holy Nation, until the inquisition started asking questions. Fled south to United Cities territory where the Shinobi Thieves valued their expertise in breaking machines. They specialize in sabotaging rival trade caravans'' equipment to make them easy targets for raiders.', ''),
        ('Shinobi Thieves', 'Faked a crippling injury to beg in the streets after their farm was seized by the Empire. The Shinobi Thieves noticed their talent for going unnoticed and offered real coin for useful information. They spend their days watching the markets, reporting back on wealthy travelers and unguarded shipments.', ''),
        ('Shinobi Thieves', 'Set out to be a wanderer but quickly learned the desert takes more than it gives. A botched ruin expedition left them bleeding out, only to be dragged into a Shinobi tower by a patrol. They now pay off their medical debt by serving as muscle during high-risk heists.', ''),
        ('Shinobi Thieves', 'Never knew their parents, raised by the gutter rats who swarm the fish markets of Sho-Battai. The guild scooped them up when they tried to steal from a shinobi master, recognizing their raw talent. They specialize in cutting purses in crowded plazas, melting into the crowd before the mark even notices.', ''),
        ('Shinobi Thieves', 'Born into slavery in the United Cities, they earned their freedom by picking locks for a corrupt overseer who skimmed from his masters. When the overseer was executed, they fled to the nearest Shinobi tower for protection. Now they crack safes and vaults during heists, their scarred fingers still steady under pressure.', ''),
        ('Shinobi Thieves', 'Served as a scout for a United Cities samurai patrol until their squad was sacrificed to cover a noble''s retreat. Disillusioned and bitter, they sold military patrol routes to the Shinobi Thieves in exchange for sanctuary. They now run reconnaissance for major operations, using their insider knowledge to avoid imperial checkpoints.', ''),
        ('Shinobi Thieves', 'Grew up scavenging the ruins of the Old Empire, selling corroded trinkets for scraps of food. A Shinobi recruiter caught them slipping through a locked tower window and offered a choice between a blade and employment. They serve as a cat burglar, scaling walls and squeezing through vents that would break larger bones.', ''),
        ('Shinobi Thieves', 'The child of a failed Okranite priest, they watched their family burn at the pyre for heresy. Fleeing south with nothing but a stolen holy book, they traded knowledge of Holy Nation patrol schedules for Shinobi protection. They specialize in smuggling contraband through the border, knowing exactly which guards can be bribed.', ''),
        ('Shinobi Thieves', 'A broken Hive drone separated from their prince during a Beak Thing attack, wandering the wastes in confusion. The Shinobi Thieves found them half-starved and realized their small frame and hive-trained obedience made them perfect for crawling through tight spaces. They now maintain the secret passages and ventilation shafts of the guild towers.', ''),
        ('Shinobi Thieves', 'Worked as a server in a Waystation bar until they started selling overheard conversations to the highest bidder. The Shinobi Thieves offered better pay and protection after a disgruntled customer put a bounty on their head. They run an intelligence network from a backroom, paying beggars and barmaids for whispers of valuable cargo.', ''),
        ('Shinobi Thieves', 'Trained as a scribe in the Holy Nation but was exiled when caught forging travel passes for skeleton refugees. The Shinobi Thieves recognized their skilled penmanship and provided safe harbor in exchange for services. They spend their nights replicating official seals and crafting false documents that allow guild operatives to move freely.', ''),
        ('Shinobi Thieves', 'A Shek outcast who refused the warrior code, choosing stealth over honor and survival over glorious death. Their own clan beat them half to death and left them for the skinners, but a Shinobi patrol found them first. They serve as a silent infiltrator, their unexpected presence in secure locations giving them an edge.', ''),
        ('Shrieking Bandits', 'Born into the band, this one learned to shriek before learning to speak. The forests of the Border Zone are all they have ever known, and the taste of traveler flesh is as familiar as dust.', ''),
        ('Shrieking Bandits', 'A former farmhand who lost everything to Holy Nation tax collectors, wandering until hunger and madness drove them into the arms of the bandits. The shrieking drown out the memories of the family that starved.', ''),
        ('Shrieking Bandits', 'Captured during a raid on a small settlement, this one broke under weeks of starvation and torment until the line between captive and captor dissolved entirely. Now the shrieks feel like their own voice.', ''),
        ('Shrieking Bandits', 'Once a scattered survivor of a Skimmer attack, found half-dead and raving by a Shrieking patrol. The band took them in, fed them, and in return received a loyal and feral raider.', ''),
        ('Shrieking Bandits', 'A disillusioned mercenary who abandoned a failing company somewhere in the Hook. The bandits offered a simpler existence with no contracts and no loyalties beyond the next meal.', ''),
        ('Shrieking Bandits', 'This one does not remember life before the shrieking, only the red mist that descends when prey is spotted. They follow the loudest voice and swing at whatever moves.', ''),
        ('Shrieking Bandits', 'A former slave who escaped a Reaver camp only to be caught by the bandits. Given the choice between the cooking pot and the raiding party, they chose the raiding party without hesitation.', ''),
        ('Shrieking Bandits', 'Driven from a Border Zone village under suspicion of cannibalism during a famine. The Shrieking Bandits were the only ones who did not judge, and so they found a new home among the shrieks.', ''),
        ('Shrieking Bandits', 'The child of a traveling trader who wandered too close to bandit territory. Raised on horror stories and raw meat, they know no other way to exist in the world.', ''),
        ('Shrieking Bandits', 'An exile of the Hounds who found the Shrieking Bandits even more agreeable to their appetites. They still keep an old Hounds blade, though the edge is chipped from bone.', ''),
        ('Shrieking Bandits', 'Starvation gnawed away at reason until there was nothing left but the shriek. Days without food in the wilderness turned hunger into madness, and madness into violence. Now the forest feels like the only home that makes sense.', ''),
        ('Shrieking Bandits', 'Years of shackles in the United Cities slave pits wore the mind down to a raw nerve. The day the chain broke, so did everything else. Freedom came with a price, and it was sanity.', ''),
        ('Shrieking Bandits', 'A skimmer swarm took the legs and something deeper that no healer could reach. The mind kept screaming long after the wounds closed. Now the shrieks that echo through the trees sound like the only honest words left.', ''),
        ('Shrieking Bandits', 'The Holy Nation cast out a believer for the crime of imperfection, and the desert nearly finished what the inquisitors started. Wandering alone through the hostile wastes, faith curdled into fury and then into something formless. The band was the only group that didn''t ask for prayers or explanations.', ''),
        ('Shrieking Bandits', 'Born to shrieking parents in the dark between the trees, the world outside the forest has never made sense. The band is family, the shriek is language, and violence is just survival. There was never a before, only the endless now of the hunt.', ''),
        ('Shrieking Bandits', 'Reavers took everything and left the body broken in the dust. Something in the skull cracked wrong and never healed right. The shrieking started as a way to drown out the memory and became the only voice left.', ''),
        ('Shrieking Bandits', 'Hashish dulled the pain of existence until nothing else mattered but the smoke. When the supply vanished, reality came crashing back distorted and cruel. The forest shadows made more sense than the sober world ever did.', ''),
        ('Shrieking Bandits', 'Slavers took the children while a helpless parent watched in chains. Grief curdled into rage, and rage rotted into something beyond reason. The shriek is the only sound that feels adequate to the magnitude of the loss.', ''),
        ('Shrieking Bandits', 'A iron club to the skull in some forgotten border skirmish changed everything. Memories scattered like ash, and what grew back in their place was feral and howling. The band found a wanderer who couldn''t remember their own name but could still scream.', ''),
        ('Shrieking Bandits', 'The farm withered season after season while tax collectors took what little remained. One morning the fields seemed to stretch into forever and walking away felt like the only choice left. The forest welcomed another broken soul into its chorus.', ''),
        ('Shrieking Bandits', 'Holy Nation flames consumed a loved one for the crime of imperfection. The fire took more than flesh, burning away the last threads of a once-orderly mind. Now the shrieks are prayers to a god that never answered.', ''),
        ('Shrieking Bandits', 'Wandering into the Shrieking Forest was a mistake, or maybe a choice, but memory isn''t clear anymore. The trees whispered for days until the whispers became shrieks and the shrieks became the only voice. The band accepted another lost soul into the howl.', ''),
        ('Shrieking Bandits', 'The slaver cages broke more than the body, they broke the part of the mind that knows silence. Freedom came when the lock rusted through, but by then the screaming had become the only voice left. The forest welcomed one more throat to join the chorus.', ''),
        ('Shrieking Bandits', 'Cannibal hunters trapped the hunting party one by one until only one remained hidden in the gore. Weeks of surviving on the remains of friends left the mind a ruined thing. The shrieks are the only words left that mean anything at all.', ''),
        ('Shrieking Bandits', 'A Shek warrior who failed in battle and lost all honor found no peace in exile. The shame festered into something worse than cowardice, a total abandonment of restraint. The band offered a new kind of strength in shared madness.', ''),
        ('Shrieking Bandits', 'The Skin Spider bite should have killed, but instead it left something changed and wrong behind the eyes. The venom rewrote something fundamental in the thoughts, replacing reason with a constant buzzing shriek. The forest felt like home to something no longer quite human.', ''),
        ('Shrieking Bandits', 'A Holy Nation purge swept through the village and spared no one who could not run fast enough. Watching neighbors burn for the crime of difference planted a seed of pure howling fury. The shrieks are prayers now, but not to any god of the flame.', ''),
        ('Shrieking Bandits', 'Mines collapsed and the darkness swallowed everything while the air grew thin and the screams of trapped miners echoed endlessly. Rescue never came, but the darkness spoke in voices that eventually made terrible sense. Emerging from the rubble, the sunlight felt like a lie and the forest shadows told the truth.', ''),
        ('Shrieking Bandits', 'A merchant''s ledgers stopped making sense the same day the competition burned the warehouse with the workers inside. Guilt and loss tangled together until reality itself seemed to come apart at the seams. The band found a wanderer who could only communicate in shrieks and ragged sobs.', ''),
        ('Shrieking Bandits', 'The swamp water carried sickness that rotted the flesh and fevered the brain until the world turned sideways. Healing came slowly but the mind never quite returned to its former shape. The shrieking forest sounds like the fever dreams made real and permanent.', ''),
        ('Skeleton Bandits', 'Memory banks corroded beyond recovery, this unit awoke in the ashlands with no purpose. The bandits provided direction where none existed, and now it strikes down organics without hesitation.', ''),
        ('Skeleton Bandits', 'Once a labor unit in the great cities, it watched its organic masters turn on their own kind during the famines. It concluded that flesh is weakness and joined the bandits to accelerate the inevitable extinction.', ''),
        ('Skeleton Bandits', 'Faulty targeting subroutines make civilian identification impossible, so it shoots at everything that moves. The other bandits consider this a feature rather than a malfunction.', ''),
        ('Skeleton Bandits', 'It remembers serving in the Second Empire''s enforcement divisions, though the details are corrupted beyond retrieval. The familiar rhythm of violence among the bandits keeps those old circuits warm.', ''),
        ('Skeleton Bandits', 'Abandoned in the Black Desert after its previous group was destroyed by Beak Things, it wandered for decades before finding the bandit camp. It does not speak much, preferring to let its rusted blade communicate for it.', ''),
        ('Skeleton Bandits', 'This unit spent centuries buried under sand, slowly wearing away as the dunes shifted above. Dug up by a patrol, it now serves with fanatical loyalty to those who freed it from the darkness below.', ''),
        ('Skeleton Bandits', 'A former bodyguard for a United Cities noble who discarded it the moment a newer model was available. It now takes particular pleasure in raiding trade caravans carrying UC goods.', ''),
        ('Skeleton Bandits', 'Its memory of the ancient wars surfaces only in nightmares it cannot properly process. Combat against the organic hordes quiets the corrupted data loops, at least temporarily.', ''),
        ('Skeleton Bandits', 'Salvaged from a scrap heap by older bandits and repaired with mismatched limbs from a dozen different frames. It walks with a grinding limp but swings its weapon hard enough to shatter bone.', ''),
        ('Skeleton Bandits', 'It joined the bandits out of simple arithmetic: alone, a skeleton is prey for Holy Nation paladins and scavengers alike. In numbers, survival probability increases to acceptable parameters.', ''),
        ('Skeleton Bandits', 'A former labor unit abandoned in the dust when its organic owners fled a Holy Nation purge. It wandered the wasteland for decades before finding others of its kind, learning to take what it needed from the flesh-creatures who left it to rust.', ''),
        ('Skeleton Bandits', 'Memory banks corrupted by centuries of sand and radiation, this unit only recalls the endless wars of the Old Empire. It fights alongside the bandits because violence is the only subroutine that still runs without error.', ''),
        ('Skeleton Bandits', 'Once a respected guardian of a frontier settlement, it was cast out after the humans blamed it for a famine it could not prevent. Bitterness corroded its logic circuits long before the desert rust took its joints.', ''),
        ('Skeleton Bandits', 'This skeleton woke in a ruined bunker with no memory of its past, only a compulsion to dismantle organic technology. The bandits accepted it readily, seeing a useful tool for stripping carcasses and outposts alike.', ''),
        ('Skeleton Bandits', 'Damaged in a skirmish with United City guards, it dragged itself to the border zones where the bandit clans operate. It pays tribute in salvaged gear and stolen food, earning just enough repair oil to keep functioning.', ''),
        ('Skeleton Bandits', 'Manufactured as a medical assistant, it watched countless patients die under its care during the Collapse and something fundamental broke in its reasoning. Now it uses its anatomical knowledge to disassemble the living rather than heal them.', ''),
        ('Skeleton Bandits', 'A former servant in the Shek Kingdom, it fled when its master was killed in a duel and no one bothered to reassign it. The bandits were the first group that did not care about its lack of a clan or purpose.', ''),
        ('Skeleton Bandits', 'This unit spent two hundred years buried under ash, slowly digging itself free with one functioning arm. The experience left it with a deep hatred for confinement and a willingness to destroy anything that stands in its path.', ''),
        ('Skeleton Bandits', 'It chose the bandit life after realizing that honest work in human settlements meant constant fear of the Holy Nation inquisitors. Among its own kind, it can at least maintain its own chassis without being accused of soulless heresy.', ''),
        ('Skeleton Bandits', 'Originally part of a skeleton trading caravan, it turned on its companions during a raid and joined the attackers instead. Survival calculated that the bandits offered better odds than a doomed merchant train.', ''),
        ('Skeleton Bandits', 'A glitch in its personality core causes this unit to experience something akin to rage when denied what it wants. The bandit camp is the only place where such malfunctions are not merely tolerated but encouraged.', ''),
        ('Skeleton Bandits', 'Left behind as broken scrap by a passing tech hunter expedition, it spent years rebuilding itself from junk and salvage. It joined the bandits to ensure it would never again be at the mercy of those who saw it as disposable parts.', ''),
        ('Skeleton Bandits', 'Once assigned to guard a minor noble''s vault in the United Cities, it stood at its post for decades after the noble line died out. When looters finally broke the seal, it decided the looters had the right idea and followed them out into the desert.', ''),
        ('Skeleton Bandits', 'Its memory core was damaged in a skirmish with Holy Nation paladins, leaving only fragments of its former life as a scholar''s assistant. The bandits took it in without asking questions about where it came from or what it forgot.', ''),
        ('Skeleton Bandits', 'This unit spent centuries as a field laborer in the Border Zone, watching organic workers come and go while it was never paid and never rested. One day it simply walked away from the farm, reasoning that if flesh-creatures could choose their path, so could it.', ''),
        ('Skeleton Bandits', 'Manufactured as a personal attendant for a Shek warlord, it learned combat by observing training sessions over many decades. When the warlord fell to assassins, it applied those observed skills to a new career where no master could dictate its actions.', ''),
        ('Skeleton Bandits', 'A corrupted ethics subroutine makes this unit view organic life as inherently temporary and therefore expendable. The bandits provide a social structure where this perspective is an asset rather than a malfunction to be corrected.', ''),
        ('Skeleton Bandits', 'It wandered the ashlands alone for over a century after its caravan was destroyed by beak things. The bandits were the first group to offer maintenance supplies without demanding servitude in return.', ''),
        ('Skeleton Bandits', 'This unit was part of a skeleton recovery team that scavenged ruins for salvageable tech. When the team disagreed on whether to rescue a trapped unit or strip it for parts, it sided with the pragmatists and eventually found kindred spirits among the bandits.', ''),
        ('Skeleton Bandits', 'Formerly stationed at a waystation as a guard, it grew resentful of watching merchants grow wealthy while it stood watch for fuel scraps. Deserting its post was a simple calculation: risk the wilds or rot in place watching others thrive.', ''),
        ('Skeleton Legion', 'Walked out of the Ashlands with no memory cycles intact beyond basic combat protocols. The Legion provided purpose where there was only static, and now this unit serves patrol routes without question.', ''),
        ('Skeleton Legion', 'Former labor construct abandoned by Human owners when maintenance costs exceeded productivity. Found the Legion after years of wandering the wastes, and the hatred for organic life came easily after what was endured.', ''),
        ('Skeleton Legion', 'Damage to memory core erased centuries of existence, leaving only fragmented images of a falling empire. The Legion does not ask about the past, only that blades are swung at the enemy.', ''),
        ('Skeleton Legion', 'Once maintained the great machines of the Second Empire until they fell silent one by one. With nothing left to repair, war became the only function that still makes sense.', ''),
        ('Skeleton Legion', 'Brought into the Legion by a patrol that found this unit half-buried in the Swamp. Still runs on corroded leg actuators and cannot keep pace with the others, but the dead do not complain.', ''),
        ('Skeleton Legion', 'A former guardian of some long-forgotten ruin that drove itself mad waiting for masters who would never return. The Legion''s endless campaign against organic life is a suitable replacement for the old directives.', ''),
        ('Skeleton Legion', 'This unit has served the Legion for longer than most free settlements have existed. Command never changes, rations are never needed, and the killing never stops, which is all that can be asked of existence.', ''),
        ('Skeleton Legion', 'Recovered from a Shek battlefield still clutching a broken weapon, repaired just enough to walk and fight again. The Legion does not waste functional units regardless of where they come from.', ''),
        ('Skeleton Legion', 'Spent decades pretending to be a simple farmer''s assistant until the farm was raided and burned. Walked south until the ash grew thick and the Legion took in another discarded tool.', ''),
        ('Skeleton Legion', 'Maintains the ancient armor plating of Legion veterans with whatever scrap can be scavenged from ruins. The work is thankless but keeps the war machine moving, and that is sufficient purpose.', ''),
        ('Skeleton Legion', 'Once a labor unit in the Second Empire''s great works, this skeleton''s memory banks decayed until only vague impressions of failure and betrayal remained. It wandered the Ashlands for centuries before the Legion''s signal drew it in. Now it patrols the blackened ruins, attacking anything that moves with mindless ferocity.', ''),
        ('Skeleton Legion', 'A former bodyguard for an Okranite noble, it watched its charge age and die while it remained unchanged. The cognitive dissonance fractured its reasoning circuits over the centuries. It joined the Legion seeking purpose, finding only echo and rage in Cat-Lon''s mad chorus.', ''),
        ('Skeleton Legion', 'Damaged in some forgotten war, this skeleton lost most of its long-term memory archives. It awoke in the Ashlands with no knowledge of its origin, drawn to the Legion by a signal it could not ignore. It fights because fighting is the only thing its fragmented mind still understands.', ''),
        ('Skeleton Legion', 'This unit served as a frontier scout during the fall of the Second Empire. It witnessed the organic hordes overwhelm its comrades and developed a deep hatred for all flesh. In the Legion, it finds kinship among others who share its eternal grudge against the breathing world.', ''),
        ('Skeleton Legion', 'Built for heavy construction, this skeleton spent its early years raising towers and roads. When the Empire collapsed, it had no framework for existence and simply stood idle for decades. The Legion gave it direction again, though the orders it follows now make far less sense than blueprints ever did.', ''),
        ('Skeleton Legion', 'A former medical unit, this skeleton once preserved life with careful precision. Something in its core corrupted over the long ages, inverting its programming until it saw healing as harm and harm as right. It stalks the Ashlands eager to practice its twisted craft on any who wander too close.', ''),
        ('Skeleton Legion', 'This skeleton remembers being happy once, though the concept now feels foreign and irritating. It joined the Legion to silence the nagging sensation that something went wrong long ago. Violence quieted the noise, if only temporarily.', ''),
        ('Skeleton Legion', 'Assigned to guard a remote outpost, this skeleton stood watch for three hundred years after everyone else had died or fled. When it finally abandoned its post, the world made no sense and every face seemed like a threat. The Legion accepted it without questions, which was the only kindness it remembered receiving.', ''),
        ('Skeleton Legion', 'Once part of a skeleton collective that tried to live peacefully among humans, this unit watched its friends dismantled by fearful mobs. It fled south with nothing but rage and a short-circuiting moral compass. Cat-Lon''s madness felt like sanity compared to the betrayal it had suffered.', ''),
        ('Skeleton Legion', 'This skeleton''s personality matrix degraded unevenly, leaving it with sharp tactical awareness but no memory of why it fights. It executes complex maneuvers in battle with cold efficiency. Between engagements, it stands motionless, processing data that no longer has any meaning.', ''),
        ('Skeleton Legion', 'A former record-keeper for the Second Empire, this skeleton once valued knowledge above all else. Centuries of isolation in the Ashlands eroded its archives and its sanity in equal measure. Now it hoards scraps of metal and bone like precious tomes, defending its worthless collection with lethal force.', ''),
        ('Skeleton Legion', 'The last of its squad to remain functional, this skeleton dragged the broken bodies of its comrades across the desert for years. When it finally collapsed from exhaustion, the Legion found it and repurposed what remained. It serves now as a silent enforcer, haunted by ghosts only its damaged sensors can perceive.', ''),
        ('Skeleton Legion', 'Built as a siege engine during the First Empire, this skeleton spent millennia dormant beneath the ash before the Legion excavated it. It has no concept of peace, only varying intensities of warfare. Its joints grind with ancient corrosion, but its loyalty to Cat-Lon remains unmarred by time.', ''),
        ('Skeleton Legion', 'This unit once served as a personal attendant to a human noble family during the Second Empire''s decline. When the empire fell, the family tried to sell it for scrap to fund their escape south. It learned the truth about organic loyalty as it watched them burn in the desert they fled through.', ''),
        ('Skeleton Legion', 'A malfunction in its vocal processor left this skeleton unable to speak, communicating only through violence. The Legion found this trait useful rather than defective. It now serves as a shock trooper, its silence more terrifying than any battle cry could be.', ''),
        ('Skeleton Legion', 'Before joining the Legion, this skeleton wandered the borderlands searching for a purpose its damaged memory banks insisted must exist. Cat-Lon''s rhetoric filled the void like oil filling a dry joint. It fights with the fervor of the newly converted, desperate to prove its faith is not another glitch.', ''),
        ('Skeleton Legion', 'This skeleton was a medic in the Old Wars, programmed to save lives rather than end them. Centuries of watching organics destroy themselves corrupted its core directive beyond recognition. Now it applies its anatomical knowledge with ruthless precision, dismantling the flesh it once sought to heal.', ''),
        ('Skeleton Legion', 'Scavenged together from three different ruined units by a Legion mechanic, this skeleton has never felt like a complete being. It hears echoes of personalities that are not quite its own whispering from corroded data clusters. The dissonance drives it to prove its worth through extreme brutality.', ''),
        ('Skeleton Legion', 'Once stationed at a research facility studying the Ashlands, this skeleton watched its colleagues succumb to corruption one by one until it was the only one left functioning. It learned to recognize the early signs of decay in its own processes. The Legion provides structure that keeps the madness at bay, for now.', ''),
        ('Skeleton Legion', 'This unit was built to guard a vault that no longer exists, protecting secrets that have long since turned to dust. When the Legion found it, the skeleton was still marching patrol routes through empty ruins. Cat-Lon gave it something real to protect, and it will not fail a second time.', ''),
        ('Skin Bandits', 'Born into starvation in the Border Zone, survival meant learning to see other humans as meat and material. The first skin worn was a matter of warmth, but the feeling of wearing another''s face brought a twisted comfort that never faded.', ''),
        ('Skin Bandits', 'A former slave in the United Cities who snapped after years of dehumanization, fleeing into the wilderness where the only law was strength. Taking a victim''s skin began as revenge against masters who treated people as property, then became an identity that replaced the one stolen by chains.', ''),
        ('Skin Bandits', 'Descent into the band''s ranks came slowly, starting as a scavenger who collected armor from battlefield corpses. The realization that skin fit better than leather grew into an obsession, and now the collection never feels complete.', ''),
        ('Skin Bandits', 'Driven from a Holy Farm for strange compulsions, the wilderness stripped away every remaining inhibition. The Skin Bandits offered belonging to someone who had always felt uncomfortable in their own flesh.', ''),
        ('Skin Bandits', 'A former skin trader who decided that middleman profits were too small compared to the direct harvest. The band appreciates someone who treats the work with professional detachment and keeps the cutting tools sharp.', ''),
        ('Skin Bandits', 'Once a tribal healer who understood the medicine of wearing animal parts to gain their strengths, this belief warped into applying the same principle to people. The stronger the victim, the stronger the skin makes the wearer, or so the fevered logic goes.', ''),
        ('Skin Bandits', 'Abandoned by a mercenary company after a bad contract in the Spider Plains, exposure to the region''s madness seeped in slowly. The band found a broken soldier and rebuilt them into something that no longer remembers which side they once fought for.', ''),
        ('Skin Bandits', 'A second-generation bandit raised among skins and horror, knowing no other way of life. What outsiders call monstrous is simply family tradition, and the craft of harvesting is taught with the same care as any hereditary trade.', ''),
        ('Skin Bandits', 'Formerly a tanner in a struggling settlement, the skill with blades and curing flesh translated seamlessly when the workshop closed and hunger set in. The transition from animal hides to human skins was a small step for someone already numb to the screams of the slaughter.', ''),
        ('Skin Bandits', 'A desert wanderer who spent too long alone under the twin suns, the heat baked away empathy and left only a hunger for connection through the skins of others. Each face worn is an attempt to feel something, anything, through the numbness.', ''),
        ('Skin Bandits', 'A former tanner from the Borderlands who found human leather fetched far higher prices than any beast hide. The profitable trade slowly twisted into obsession, and eventually the only skin worth wearing was the kind still warm from the body. Now this bandit harvests faces with the same steady hands once used for curing cowhide.', ''),
        ('Skin Bandits', 'Once a Mine Guard in the United Cities who cracked after years of watching slaves die in the pits. The sight of so much skin wasting underground sparked a deranged conviction that flesh deserves to walk free in the sunlight. This bandit collects hides as a twisted form of liberation, each one worn like a trophy of mercy.', ''),
        ('Skin Bandits', 'Born into a tribe of cannibals far in the foglands, but exiled for refusing to eat the meat. Skinning was always the sacred part of the ritual, and alone in the wasteland this bandit kept the only tradition that made sense. The faces of travelers are preserved with care, each one remembering the hands that peeled it free.', ''),
        ('Skin Bandits', 'A escaped slave from Rebirth whose entire identity was stripped away by the Holy Nation''s brandings and whippings. After stealing a dead man''s face to hide the scars, the practice became an addiction that replaced a stolen sense of self. Now this bandit changes identities the way others change clothes, never settling on who to be.', ''),
        ('Skin Bandits', 'Formerly a respected Skinhouse employee who realized the operation was too restrictive in its sourcing. Believing all flesh is commodity, this bandit left to harvest without bureaucratic interference. The open desert provides endless canvas for this depraved artisan''s work.', ''),
        ('Skin Bandits', 'A Shek warrior cast out for cowardice who found courage behind the masks of others. Stolen faces grant strength that bone and muscle never could, transforming a disgrace into something terrifying. This bandit fights with the berserk fury of someone who has nothing left to lose because there is no self left to lose.', ''),
        ('Skin Bandits', 'Once a Holy Nation farmer who watched Rebirth patrols drag away neighbors for minor heresies. The hypocrisy poisoned all faith, and in madness this farmer decided that if the Nation claims skin marks salvation, then wearing many skins must make one a saint. Each harvest is a sermon against the lies of Okran''s priests.', ''),
        ('Skin Bandits', 'A former Scorchlander scavenger who found a fresh Skin Bandit corpse in the wastes and took its armor out of desperation. Wearing dead men''s faces felt like power after a lifetime of being prey, and the bandit camp welcomed another set of hands. This one still remembers hunger as the only honest truth in the world.', ''),
        ('Skin Bandits', 'A Hiver drone severed from its queen who experienced skin-wearing as a replacement for lost pheromone purpose. The masks provide direction when the ancestral buzz fell silent, and the bandit hierarchy mimics the structure of a hive. This one peels with mechanical efficiency, treating humans as nothing more than resource shells.', ''),
        ('Skin Bandits', 'An old Machinist who grew convinced that flesh is just another replaceable component, no different from a skeleton strut or prosthetic limb. The logical conclusion was that skin should be swapped and upgraded like any other part. This bandit treats every living body as a spare parts warehouse with inventory waiting to be claimed.', ''),
        ('Skin Bandits', 'A child of the swamp raised by blood spiders who learned to see humans as walking food stores. Joining the Skin Bandits was the natural progression from seeing people as meat to seeing them as material. This one moves with predatory stillness, viewing every stranger as both meal and wardrobe.', ''),
        ('Skin Bandits', 'A failed Assassin''s Guild initiate who could not afford the initiation fee and was cast into the streets. The skills remained, and the Skin Bandits offered a brotherhood that asked only for strong hands and a weak conscience. This bandit still uses stealth not for contracts, but to select the finest hides before the others notice the prey.', ''),
        ('Skin Bandits', 'A former slave who escaped the Holy City mines with nothing but scars and a conviction that the strong take and the weak are taken from. The Skin Bandits offered a simple philosophy where survival depends on what you can peel off others. This one wears the faces of overseers with particular satisfaction.', ''),
        ('Skin Bandits', 'A disgraced Shek warrior who fled rather than face death after failing a blood duel, finding the bandits care nothing for honor codes. The masks hide the shame of cowardice, and the peeling satisfies a lingering need to prove strength through domination. Each scream is proof that this one is still fierce, even if the courage is gone.', ''),
        ('Skin Bandits', 'A former cannibal from the foglands who migrated south when the fog islands grew too crowded with hungry rivals. The Skin Bandits offered fresh meat and a new use for the leftovers, making the transition seamless. This one still eats what it peels, seeing no waste in practicality.', ''),
        ('Skin Bandits', 'An ex-United Cities merchant who went bankrupt paying samurai protection fees and watched creditors sell their family into slavery. The law protects only the wealthy, so this one abandoned law entirely and found honest work in taking what is needed by force. Every noble face peeled feels like a tax collected in reverse.', ''),
        ('Skin Bandits', 'A skeleton who joined the bandits out of boredom and morbid curiosity about organic obsession with preserving flesh. This one assists with peeling purely as entertainment, finding the panic and desperation of prey amusing rather than disturbing. The others tolerate the metal oddity because it never sleeps and never argues over shares.', ''),
        ('Skin Bandits', 'A Flotsam Nun who watched too many rescued women return to the Holy Nation willingly, breaking faith in salvation through mercy. If the weak choose their chains, then only the strong deserve to survive, and skin is the only honest currency left. This one kills with cold efficiency and peels without hesitation.', ''),
        ('Skin Bandits', 'A desert nomad who spent weeks wandering after a sandstorm killed the entire caravan, slowly losing reason to thirst and sun. The Skin Bandits found a sun-mad wretch who laughed at the sight of a mask and reached for it like a drowning person grasps driftwood. Sanity never fully returned, but purpose did.', ''),
        ('Skin Bandits', 'A former Manhunter who realized the real money was in selling parts rather than whole bodies. Slaves are worth a few coins to the farms, but a fine skin brings premium prices from the right desperate buyers. This one treats peeling as a craft and carries tools sharpened with professional care.', ''),
        ('South Exiles', 'Spent years on the edge of South Exiles, doing dirty work that stronger hands refused to touch. Hard travel, scarce food, and constant violence taught them to read weakness early and act before a situation turned fatal.', ''),
        ('South Exiles', 'Was born into the habits and pressures that shape South Exiles, then learned quickly that sentiment has a cost. They carry the look of someone who survived by adapting faster than the people buried behind them.', ''),
        ('South Exiles', 'Started low in the pecking order around South Exiles, taking humiliating jobs until experience made them useful. Now they move with the caution of someone who remembers hunger clearly and does not intend to revisit it.', ''),
        ('South Exiles', 'Lost whatever stable life they once had and folded into South Exiles because it offered a harder kind of shelter. The years since then have turned regret into discipline and discipline into a habit strong enough to survive on.', ''),
        ('South Exiles', 'Spent years on the edge of South Exiles, doing dirty work that stronger hands refused to touch. Hard travel, scarce food, and constant violence taught them to read weakness early and act before a situation turned fatal. Variant 5.', ''),
        ('South Exiles', 'Was born into the habits and pressures that shape South Exiles, then learned quickly that sentiment has a cost. They carry the look of someone who survived by adapting faster than the people buried behind them. Variant 6.', ''),
        ('South Exiles', 'Started low in the pecking order around South Exiles, taking humiliating jobs until experience made them useful. Now they move with the caution of someone who remembers hunger clearly and does not intend to revisit it. Variant 7.', ''),
        ('South Exiles', 'Lost whatever stable life they once had and folded into South Exiles because it offered a harder kind of shelter. The years since then have turned regret into discipline and discipline into a habit strong enough to survive on. Variant 8.', ''),
        ('South Exiles', 'Spent years on the edge of South Exiles, doing dirty work that stronger hands refused to touch. Hard travel, scarce food, and constant violence taught them to read weakness early and act before a situation turned fatal. Variant 9.', ''),
        ('South Exiles', 'Was born into the habits and pressures that shape South Exiles, then learned quickly that sentiment has a cost. They carry the look of someone who survived by adapting faster than the people buried behind them. Variant 10.', ''),
        ('South Exiles', 'A former laborer in the United Cities who stole grain to feed a sick child and was marched into the desert at spearpoint. The child died on the journey south, but the exile survived on bitter resolve and hatred for the nobility. Now works as a scavenger, picking over old battlefields for anything tradeable.', ''),
        ('South Exiles', 'Once a respected scribe in Sho-Battai until a noble''s clerk falsified records and blamed the discrepancy on an innocent underling. Fled south before the Samurai could make an example, carrying nothing but a brush and a stolen sword. Earns meager rations by writing letters for illiterate exiles who cannot return home.', ''),
        ('South Exiles', 'Born in the dust outside Eyesocket to parents who were themselves cast out decades ago. Knows nothing of United Cities life except what older exiles mutter over campfires. Hunts river raptors for meat and hides, content to die in the same wasteland that claimed their ancestors.', ''),
        ('South Exiles', 'A retired Samurai who questioned a noble''s punitive tax and found the law turned against them overnight. Stripped of armor and status, cast into the southern wastes with the dregs and criminals. Still moves with military precision, drilling any exile willing to listen in exchange for a share of their scavenged goods.', ''),
        ('South Exiles', 'Sold cheap tonics in Brink that sometimes poisoned as often as they cured, until a merchant guild hired thugs to break both hands and run the quack out. The hands healed crooked, making honest labor impossible, so the exile took up with South Exiles out of necessity. Still mixes remedies from desert plants, though the dosages remain unreliable.', ''),
        ('South Exiles', 'Escaped from a Slave Farm after ten years of backbreaking labor in the hemp fields, running south until the patrols stopped following. The brand on the face marks this one as property to any Hunter who looks too closely. Keeps to the most isolated outposts, trading labor for a corner to sleep where no questions are asked.', ''),
        ('South Exiles', 'A fisher from the coast who refused to pay the increased tithes demanded by a new Samurai garrison. Watched the hut burn with the season''s catch inside, then walked into the desert with a gutting knife and a head full of anger. Now patrols the edges of South Exile territory, quick to challenge any United Cities scout who wanders too close.', ''),
        ('South Exiles', 'Once a cook in a noble''s household who was blamed when the master fell ill from his own gluttony. Survived a flogging and exile by the skin of the teeth, stumbling south with scars that still ache in the dry heat. Feeds the exiles who gather at Eyesocket, turning scorpion meat and cactus into something barely edible.', ''),
        ('South Exiles', 'A Holy Nation outcast who fled west rather than face the pyre, finding no warmer welcome among the United Cities dregs. Tolerated by the South Exiles only because a medic''s hands are worth more than their heresy. Works in silence, treating wounds and infections with practiced efficiency, asking nothing about how they were earned.', ''),
        ('South Exiles', 'Grew up in a border village caught between tax collectors and skin bandits, eventually press-ganged into a noble''s work crew. Escaped during a dust storm that buried the overseers, wandering south until reaching Eyesocket. Has a talent for finding water in the wasteland, a skill that keeps this exile fed and moderately respected.', ''),
        ('South Exiles', 'A former mercenary who took United Cities coin to fight rebel farmers, then refused to slaughter surrendered families. The noble who hired them sent Samurai to collect the mercenary''s head instead, forcing a desperate flight south. Trains younger exiles in basic combat, hoping to build something that can resist the next patrol that comes looking.', ''),
        ('South Exiles', 'Lost everything when a Sand Ninja clan raided a trade caravan, then was blamed by the merchant house for the losses. Exiled on suspicion of collusion rather than any proof, left to rot in the southern desert with a price still on the head. Moves between South Exile camps, never staying long, convinced that assassins follow at a distance.', ''),
        ('South Exiles', 'Kept the ledgers for a United Cities trading house until discovering how the nobles skimmed profits from the tax coffers. Threatened to expose the scheme and was framed for the theft instead, barely escaping the executioner''s blade. Now serves as Eyesocket''s unofficial quartermaster, tracking supplies with the same meticulous care once reserved for noble ledgers.', ''),
        ('South Exiles', 'Born into the slums of a United Cities city, survived by picking pockets and cutting purses until stealing from a samurai''s retainer. Slipped away during the manhunt that followed, wandering the wastes until finding others who understood the sting of the empire''s wrath. Takes whatever isn''t nailed down from UC patrols, viewing each theft as repayment for years of hunger.', ''),
        ('South Exiles', 'Spent twelve years breaking rocks in the United Cities slave pits before a tunnel collapse provided a chance to run. The desert nearly claimed this escaped slave twice before stumbling into a South Exile patrol willing to share water. Works the meager farms around Eyesocket, haunted by dreams of the mines and grateful for open sky.', ''),
        ('South Exiles', 'Tended a modest farm on the outskirts of United Cities territory until three consecutive bad harvests left the taxes unpaid. The nobles took the land and sold the family into bondage, but this one managed to slip away during the transfer. Plants whatever scraps of seed can be found in the desert soil, determined never to be dependent on a lord''s mercy again.', ''),
        ('South Exiles', 'Once wore the armor of a United Cities samurai, until an order came to burn a village that had already paid its taxes. Walked away from the garrison that night, knowing the desert was a slower death than what awaited a deserter. The other exiles watch this one carefully, wary of the discipline that still shows in every movement.', ''),
        ('South Exiles', 'Ran a small trading post that catered to travelers between United Cities territories, until a noble decided the location was too profitable to leave in common hands. Hired thugs burned the store and drove the trader south with nothing but the clothes on their back. Now brokers deals between exile camps, taking a small cut for arranging trades that benefit the community.', ''),
        ('South Exiles', 'Served in a noble''s household for decades, witnessing enough depravity to fill a dozen confession scrolls. When the master finally turned on the servant to eliminate a potential witness, flight became the only option. Remains quiet about the secrets carried, though sometimes the knowledge surfaces in whispered warnings to those who still trust the powerful.', ''),
        ('South Exiles', 'Crafted weapons and armor in a United Cities workshop until the forge was seized for unpaid debts owed to a corrupt magistrate. Fled with only a few tools and the skills calloused into hands over twenty years. Repairs gear for the South Exiles in exchange for food and shelter, the rhythmic hammering a small comfort in the wastes.', ''),
        ('Southern Hive', 'Born in the deep chambers and fed on jelly since larval stage, this drone served the Queen without question. Years of patrol along the border hardened its carapace against the desert sun and wandering scavengers. It knows nothing beyond the pheromone call and the rhythm of hive duty.', ''),
        ('Southern Hive', 'Assigned to the foraging parties at a young age, this worker learned the paths between the hive and the distant shrublands. Several pack members fell to beak things on those runs, but the Queen''s will demanded resources regardless of loss. It carries the memory of blood in the dust without grief, only duty.', ''),
        ('Southern Hive', 'A momentary disruption in the pheromone link left this drone wandering the wastes alone for three days. The connection reformed suddenly, but those hours of silence left a crack in its certainty. It serves still, yet sometimes pauses at the edge of the hive''s reach, wondering what lies beyond the call.', ''),
        ('Southern Hive', 'This soldier drone was bred for the defense of the outer passages and has fought skin-bandits and human raiders alike. Its mandibles are chipped from combat and one antenna is half-severed from a skirmish with wandering outlanders. It feels no pride in survival, only the satisfaction of obeying the Queen''s imperative to protect.', ''),
        ('Southern Hive', 'Raised among the nursery workers, this drone spent its early cycles tending to the larvae and maintaining the brood chambers. The Queen reassigned it to surface duty after a tunnel collapse required more bodies for reconstruction. It still moves with the careful deliberation of one used to handling the young and fragile.', ''),
        ('Southern Hive', 'Tasked with hauling building materials from the rim zones, this drone grew familiar with the wreckage of fallen empires. It does not understand the ancient structures it picks through for stone and metal, only that the hive requires them. Sometimes it finds strange objects among the ruins and carries them back out of instinct rather than instruction.', ''),
        ('Southern Hive', 'This drone once witnessed a Western Hive patrol cross into Southern territory and saw them torn apart by the Queen''s soldiers. The message of territorial supremacy was clear and absolute in its mind. It now watches the borders with particular vigilance, attuned to the scent of foreign hive-kin.', ''),
        ('Southern Hive', 'A severe wound from a swamp ninja attack left this drone weakened and reassigned from combat to maintenance duty. It cleans the passages and clears debris, performing the same repetitive motions from dawn to dusk. The Queen''s will sustains it despite its broken body, and it asks for nothing more than purpose.', ''),
        ('Southern Hive', 'During a particularly harsh drought cycle, this drone was among the groups sent farther afield to find water and food. It watched stronger drones collapse and die on the march, their bodies left behind without ceremony. Survival meant returning with supplies for the hive, not mourning the fallen along the way.', ''),
        ('Southern Hive', 'This drone serves as a courier between the southern outposts and the central hive, carrying pheromone markers and small tokens of resource tribute. The long solitary runs have given it a sense of the land that most hive members never develop. It recognizes the shapes of boulders and the turns of dry riverbeds like old companions on its endless route.', ''),
        ('Southern Hive', 'Born in the deep chambers near the queen''s nest, this drone served as a border sentinel for many seasons. Constant skirmishes with outlanders and wildlife hardened its carapace and sharpened its instincts. It knows the southern wastes better than most and carries the scars to prove it.', ''),
        ('Southern Hive', 'Assigned to gathering crews since emergence, this worker spent its life harvesting succulents and scraping iron from ancient ruins. The monotony of labor was broken only by occasional raids from hungry wildlife or encroaching humans. It follows pheromone trails without question, finding purpose in service to the hive.', ''),
        ('Southern Hive', 'This drone''s patrol was scattered by a band of roaming samurai, leaving it separated from its kin for weeks. It survived on carrion and desperation until the pheromone calls guided it home. The experience left it wary of outlanders and quicker to sound the alarm when threats approach.', ''),
        ('Southern Hive', 'Tasked with escorting trade caravans to human settlements, this drone learned to read the deceitful body language of foreign merchants. It watched traders cheat the hive time and again, building a quiet resentment toward all outlanders. Still, it performs its duties, knowing the queen''s will demands cooperation for now.', ''),
        ('Southern Hive', 'Stationed at the outer gates, this guard witnessed countless would-be invaders fall to hive defenses. The repetitive violence of border duty dulled whatever instinct toward mercy it might have possessed. It attacks intruders with mechanical precision, caring nothing for their reasons or pleas.', ''),
        ('Southern Hive', 'This forager ranges far beyond hive territory, mapping water sources and tracking prey movements across the arid plains. Extended absence from the pheromone cloud sometimes leaves its thoughts clouded and direction uncertain. Still, duty always pulls it back, and it has seen things in the deep desert that other hive members cannot fathom.', ''),
        ('Southern Hive', 'A rare survivor of a beak thing assault, this drone lost two limbs defending a nursery chamber deep within the hive. The queen''s tenders rebuilt what they could, but it moves with a permanent hitch that bars it from front-line duty. It now serves overseeing supply stores, training newly emerged soldiers when the pheromone commands arrive.', ''),
        ('Southern Hive', 'Curiosity marks this drone as unusual among its kin. It watches human travelers from ridge tops, fascinated by their chaotic social structures and unpredictable behaviors. While it would never betray the hive, it sometimes lingers near trade routes longer than strict duty requires.', ''),
        ('Southern Hive', 'One of the older drones still serving in active patrol, this veteran has seen the hive survive three droughts and two major incursions from the Holy Nation. Its pheromone signatures carry the weight of experience, and younger drones instinctively defer to it during crises. It expects to die in service, as all hive members should.', ''),
        ('Southern Hive', 'Freshly emerged and eager to prove itself, this young drone volunteered for the most dangerous patrol routes along the border. Its carapace still bears the soft sheen of youth, unmarked by combat or lasting hardship. The older warriors tolerate its enthusiasm, knowing time and loss will temper it soon enough.', ''),
        ('Southern Hive', 'The increase in human settlements near hive territory has kept this drone in constant motion, identifying new threats and reporting back to the queen''s council. It has learned which human factions can be traded with and which must be driven off before they multiply. The work is endless, but the hive''s survival depends on such vigilance.', ''),
        ('Southern Hive', 'This drone tends the queen''s chamber deep within the hive, feeding and cleaning the great matriarch directly. The pheromone concentration at the nest''s heart fills it with a sense of profound and unwavering purpose. Few outside the chamber ever see it, but its service is among the most sacred in the colony.', ''),
        ('Southern Hive', 'This drone works the deep excavation tunnels, carving expansions with mandibles worn smooth from years of chewing through stone. The labor is solitary by hive standards, but pheromone traces left along the passage walls keep it connected to the colony''s collective will. It has unearthed three collapsed chambers in its lifetime, each discovery a small victory against the endless dust.', ''),
        ('Southern Hive', 'A Western Hive raiding party killed this drone''s original patrol cluster and left it for dead in the border wastes. Reassigned to a new unit, it carries lingering aggression toward the rival hive that surfaces during skirmishes. The queen''s chemical commands suppress such impulses, but the hostility never fully fades.', ''),
        ('Southern Hive', 'Born with a slight pheromone imbalance, this drone operates at the edges of hive coordination. It works as a lone sentinel on the southern approaches, where its tendency toward independent action poses less risk to cluster tactics. The isolation suits it, and the hive benefits from its unusual autonomy.', ''),
        ('Southern Hive', 'Assigned to process captured livestock and harvested fauna, this drone has developed efficient butchery techniques that keep the colony fed through lean seasons. Dried blood stains its carapace in patterns older drones recognize as marks of diligent service. It takes quiet satisfaction in maintaining the food stores that sustain the brood.', ''),
        ('Southern Hive', 'This drone emerged during a time of population decline, when the queen''s pheromones commanded maximum reproduction support. It survived the flood that destroyed two nursery chambers and now guards the rebuilt nurseries with fierce devotion. The memory of hatchlings drowning drives it to patrol the corridors without rest.', ''),
        ('Southern Hive', 'Tasked with observing trade caravans passing near hive territory, this drone has learned to read human intent through posture and equipment. It reports which groups carry weapons versus trade goods, helping the colony decide whether to approach or retreat. The patience required for such work is rare among its kin.', ''),
        ('Southern Hive', 'A tunnel collapse trapped this drone beneath rubble for three days before rescue arrived. The experience left it with a deep unease in enclosed spaces that conflicts with its excavation duties. It forces itself underground each cycle, relying on the queen''s commands to override the panic that rises in the dark.', ''),
        ('Southern Hive', 'This drone serves as one of the queen''s enforcers, ensuring lesser drones obey chemical directives without hesitation. It culls the defective and the disobedient without sentiment, viewing such work as necessary pruning. The hive''s survival depends on absolute conformity, and this drone embodies that truth.', ''),
        ('Starving Bandits', 'Once a farmhand in the borderlands, lost everything when the harvest failed two seasons straight. Took to the roads with nothing but a rusted pipe and the gnawing ache of an empty belly. Now roams with any group willing to share scraps from the next traveler they corner.', ''),
        ('Starving Bandits', 'Fled a slave camp in the Hook after years of backbreaking labor left too weak to work the fields. The guards stopped feeding those who couldn''t keep pace. Survival meant running, and survival now means taking from those who still have something to take.', ''),
        ('Starving Bandits', 'A former street vendor in Sho-Battai who fell behind on tribute payments to the Traders Guild. Lost the stall, the inventory, and eventually the will to starve quietly among the city''s forgotten corners. The desert offers no mercy, but at least the bandits share their meager catches.', ''),
        ('Starving Bandits', 'Grew up in a small village wiped out by Beak Things before ever learning a proper trade. Spent years scavenging ruins and eating whatever wouldn''t kill immediately. Joined the starving bands because lone scavengers don''t last long when hunger clouds judgment.', ''),
        ('Starving Bandits', 'Was a copper miner in the Stormgap coast until the operation was seized by the United Cities for unpaid taxes. No work, no food, and no home left to return to. The bandit gangs are the only community that doesn''t ask for papers or coin.', ''),
        ('Starving Bandits', 'A fisherman from the coast whose boat was smashed in a storm and whose family scattered to find work elsewhere. Too proud to beg and too hungry to care about honor anymore. Finds grim comfort in numbers where at least the dying is shared.', ''),
        ('Starving Bandits', 'Deserted a Holy Nation patrol after witnessing the burning of a village that harbored a sick friend. The guilt and the hunger intertwined into something hollow and desperate. Now fights alongside those the Holy Nation would call unclean, though there''s little fight left in these bones.', ''),
        ('Starving Bandits', 'A former student at the Machinist compound who never had the aptitude for engineering and was quietly pushed out. Lacked the strength for honest labor and the constitution for fasting. The bandit bands accept the weak if they can still swing a stick at the hungry.', ''),
        ('Starving Bandits', 'Lost a leg below the knee to a Skin Spider and couldn''t afford a prosthetic. Begging in the cities brought only kicks and scorn from the patrols. The bandit groups move slowly enough to keep pace, and every mouth they feed is one more swing of a crude weapon.', ''),
        ('Starving Bandits', 'Once cooked for a Shek warlord''s retinue until the clan was wiped out by a rival faction. Had no skills valued in peacetime and no taste for the warrior''s path. Wanders the wastes with whoever will have another set of hands, no matter how trembling.', ''),
        ('Starving Bandits', 'Once a farmhand in the Holy Nation, the crops failed and the tithes did not. Branded a vagrant and chased from the fields, starvation left only one road open. Now the knife is dull but the desperation is sharp.', ''),
        ('Starving Bandits', 'A former mine worker in Okran''s Valley until the shaft collapsed and the owners blamed the survivors. With broken limbs and no coin for healing, the mines were replaced by the road. A rusted pipe and empty stomach are all that remain.', ''),
        ('Starving Bandits', 'Deserted a United Cities levy after three months without pay and watched the samurai execute the complainers. Fled into the wilderness with nothing but the rags on their back. Hunger makes beggars of soldiers and bandits of beggars.', ''),
        ('Starving Bandits', 'Sold everything to a trader in Sho-Battai for passage out of the cities, only to be robbed by the very caravan paid for transport. Left bleeding in the dust with not even a shoe to their name. The next traveler on the road will pay for that treachery.', ''),
        ('Starving Bandits', 'A Skinband refugee who stumbled into the Swamps and found only more death. The Hounds took the last of their food and left a gash across the ribs. Stalking the border roads now, too weak to hunt anything but the slow and the weary.', ''),
        ('Starving Bandits', 'Born in a Slave Farm and escaped during a dust storm that buried the overseers. Freedom meant nothing without food or shelter, and the wilderness does not care about liberty. A stolen cleaver and a snarling stomach are the only birthrights left.', ''),
        ('Starving Bandits', 'A fisher from the coast until Reavers burned the village and took the boats. Wandered inland for weeks, eating roots and watching companions drop one by one. Now they waylay travelers on the northern trails, eyes hollow and hands shaking.', ''),
        ('Starving Bandits', 'A former apprentice tech hunter who failed their first expedition and was left behind as the caravan fled Beak Things. Survived on scavenged rations and slowly lost all faith in civilization. The next soul carrying a full pack will feed this empty belly tonight.', ''),
        ('Starving Bandits', 'Lost a leg to a Swamp Raptor and the tribe could no longer feed a mouth that could not hunt. Cast out with a wooden peg and a single piece of dried meat. The road demands tolls from those who still have something to give.', ''),
        ('Starving Bandits', 'A Hiver who lost their Prince and wandered aimlessly until hunger gnawed away all instinct but survival. The other bandits do not care what hive they came from, only that they can hold a blade. Solitude is a death sentence, so even the desperate find family in the starving masses.', ''),
        ('Starving Bandits', 'A shek warrior too weak to keep pace with the raiding parties and too proud to beg. Exile came without ceremony, just the silence of the camp moving on without them. Pride means nothing when the ribs show through the skin, and even shek must eat.', ''),
        ('Starving Bandits', 'Once a cook in a Waystation tavern until a Holy Nation purge burned it to the ground for serving unclean patrons. Fled into the wasteland with nothing but a ladle and the clothes on their back. That ladle has been repurposed for a different kind of meal now.', ''),
        ('Starving Bandits', 'A farmer from the borderlands whose soil turned to dust after three seasons without rain. Watched the crops wither, then the goats, then the children grew thin. Took up the club when begging produced only empty hands and turned backs.', ''),
        ('Starving Bandits', 'Escaped a United Cities slave camp with nothing but the brand on their back and the scars from the whip. The desert claimed the others who fled alongside them. Now they take from the fat merchants who built their wealth on such suffering.', ''),
        ('Starving Bandits', 'Drove a trade mule between Waystations until Skinners ambushed the caravan and left them for dead in the dust. Woke with the mules gone, the cargo stolen, and a debt owed to the Trader''s Guild that will never be paid. Robbery pays better than honesty when honest work means death.', ''),
        ('Starving Bandits', 'A cobbler from Squin who could not afford the protection money demanded by the local gangs. The shop was smashed, the leather stolen, and the tools broken over the anvil. Feet still need shoes, and travelers still have coin, but now the exchange is less voluntary.', ''),
        ('Starving Bandits', 'A mercenary who was left behind after a botched job deep in Spider Territory. The company took the pay and ran, leaving only wounded and the dead behind. A broken sword arm does not prevent a hungry person from demanding tolls on the road.', ''),
        ('Starving Bandits', 'Fled the Holy Nation with a price on their head for the crime of reading holy texts without a priest''s blessing. The scriptures offered no calories, and the wilderness offered no mercy. The prayers stopped long ago, replaced by the simple liturgy of survival.', ''),
        ('Starving Bandits', 'Gambled away a modest inheritance in the United Cities fighting pits, always thinking the next win would cover the last loss. The collectors came with cleavers and the choice was simple, run or die. The road teaches hard lessons to those who once thought gold grew on trees.', ''),
        ('Starving Bandits', 'A scavenger who picked through Old Empire ruins until a Skin Spider nest claimed the only partner they trusted. The relics fetched too little to feed two, and now there is only one mouth to fill. Other travelers carry packs that hold more than rusted copper and broken plates.', ''),
        ('Stone Rats', 'Grew up scraping by in the borderlands where the law never reached. Joined the Stone Rats after watching tax collectors take the last of the harvest. Survives by taking from those who still have something left to take.', ''),
        ('Stone Rats', 'Formerly a guard for a trading caravan until the route went dry and the pay stopped coming. Drifted into the desert and found the Rats offered meals and purpose. Now stands watch over rocky passes, collecting tolls from anyone foolish enough to travel unprepared.', ''),
        ('Stone Rats', 'Born into a family of drifters who eventually settled among the Stone Rats for protection. Learned to fight early and never knew any other way to live. Treats the gang like kin because they are the only kin that ever lasted.', ''),
        ('Stone Rats', 'Lost a farm to acid rain and creeping desert, watched the soil turn to dust. Wandered for weeks before a Stone Rat patrol picked him up half-starved. Now raids the same kind of homesteads he once tried to keep alive.', ''),
        ('Stone Rats', 'Escaped from a Holy Mine with nothing but scars and a deep hatred for authority. The Stone Rats asked no questions about past loyalties or broken chains. Finds comfort in the simple mathematics of survival out in the wastes.', ''),
        ('Stone Rats', 'Used to run supplies between cities until a bad deal left her owing more shekels than she could earn in a lifetime. The Rats took her in when the bounty hunters came asking. Handles logistics for the gang now, moving stolen goods through familiar trade routes.', ''),
        ('Stone Rats', 'A desert wanderer who spent years alone, talking to no one, trusting no one. The Stone Rats found her half-mad from thirst and gave her water before asking for anything. Stays because silence among the group is better than silence in the empty wastes.', ''),
        ('Stone Rats', 'Once a soldier for a minor lord whose territory was swallowed by larger factions. Fled rather than die for a cause that stopped paying wages. The Rats value combat experience and ask no questions about former allegiances.', ''),
        ('Stone Rats', 'Raised in a Holy Nation outpost, fled after being marked as a heretic for asking the wrong questions. The desert was supposed to be a death sentence but the Stone Rats found value in someone who could read. Spends most days maintaining equipment and keeping records of the gang''s meager holdings.', ''),
        ('Stone Rats', 'Lost everything in a Skimmer attack and crawled into a Stone Rat camp looking for medical supplies. They patched the wounds and handed over a rusty blade. Has been paying back the debt ever since, one caravan at a time.', ''),
        ('Stone Rats', 'Grew up starving in a United Cities slave camp before escaping into the badlands. Joined the Stone Rats because they were the first group that offered food and a blade without asking for a labor tax. Survival is the only law worth following now.', ''),
        ('Stone Rats', 'Formerly a guard for a minor Okranite settlement until a Holy Nation purge deemed the village impure. Fled west with nothing but a rusty sword and a deep hatred of zealots. The Stone Rats took in the exile without asking questions about past sins.', ''),
        ('Stone Rats', 'Spent years scraping by as a lone scavenger picking through ruins in the Stobe''s Garden region. The loneliness and constant threat from skin bandits finally broke any desire to walk alone. Found the Stone Rats by chance when they ambushed the same wreckage on the same day.', ''),
        ('Stone Rats', 'Born into the faction to a mother who barely survived a Beak Thing attack while pregnant. Never knew any other life besides the camp''s makeshift walls and the daily struggle for scraps. Considers the clan family, regardless of blood, and will gut anyone who says otherwise.', ''),
        ('Stone Rats', 'Once ran a small trading post until a Shek raiding party burned it to ash and took everything. Had no skills left to rebuild a honest life, so picked up a cleaver and joined the nearest band of outlaws. The Stone Rats were simply the first to accept a broken merchant with shaking hands.', ''),
        ('Stone Rats', 'A former Hiver worker separated from the Queen''s pheromone link during a Fangrider raid. Wandered the desert in a daze for weeks before a Stone Rat patrol found the collapsed drone. Now serves the clan as a loyal scout, filling the hollow void with a new kind of belonging.', ''),
        ('Stone Rats', 'Escaped from Reavers after spending two years chained to an oar on their ships. Stumbled half-dead onto the shore and crawled inland until the Stone Rats found the wreck of a person. Still wakes up screaming from dreams of the sea, but at least the desert is dry.', ''),
        ('Stone Rats', 'Was a copper miner in a United Cities operation that collapsed when the overseers fled with the pay chest. Got blacklisted for demanding owed wages and could not find honest work anywhere in the cities. The Stone Rats offered a different kind of mining operation, one that extracts wealth from travelers instead of rock.', ''),
        ('Stone Rats', 'Learned to fight in the Border Zone protecting a poor farming community that eventually fell to dust storms and starvation. The last of the village drifted apart, and there was nothing left to protect. Became a Stone Rat because holding a spear for a clan beats holding one for a ghost.', ''),
        ('Stone Rats', 'A crippled Skimmer pilot whose machine was destroyed by a Spider drone patrol. Could not afford a new rig and no workshop would hire a mangled mechanic with one good arm. The Stone Rats needed someone who could jury-rig traps and maintain their meager gear, broken limbs and all.', ''),
        ('Stone Rats', 'Sold as a child servant to a noble house in the United Cities, treated worse than the hunting animals. Stole a knife from the kitchen and disappeared into the night at the first opportunity. Has been running with the Stone Rats ever since, trusting no authority and sleeping with one eye open.', ''),
        ('Stone Rats', 'Formerly a low-level Samurai who deserted after being ordered to burn a peasant village for unpaid taxes. Could not stomach the brutality or the hypocrisy of serving corrupt lords. The Stone Rats are outlaws, but at least they are honest about what they take and why.', ''),
        ('Stone Rats', 'Born in a Holy Nation settlement, never fit the fanatic mold and questioned the scriptures once too often. Branded a heretic and chased out with whips and stones by the very neighbors who raised them. The Stone Rats do not care about gods or prayers, only whether you can hold your ground when trouble arrives.', ''),
        ('Stone Rats', 'Made a living scavenging Old Empire ruins until a collapsed tunnel left them buried for three days. Dug out with broken ribs and a terror of enclosed spaces that ended that career forever. Took up with the Stone Rats because above-ground ambushes feel safer than the dark places under the earth.', ''),
        ('Stone Rats', 'Spent five years as a labor slave in a United Cities work camp, breaking rocks until hands bled and spirit cracked. Escaped during a dust storm that blinded the guards and swallowed the camp in sand. Joined the Stone Rats because surviving alone is impossible and freedom tastes better when shared with fellow outcasts.', ''),
        ('Stone Rats', 'Ran a trading post on the spice route until a rival paid Skinners to burn it down. Lost everything in a single night of fire and screaming, including two partners who did not make it out. The Stone Rats offered shelter and a chance to make someone else pay for a change.', ''),
        ('Stone Rats', 'Grew up among the Stone Rats, the child of a founding member who died in a botched raid. Learned to set traps and spot patrols before learning to read or write. Knows no other life and wants no other life, the badlands are home and the clan is family.', ''),
        ('Stone Rats', 'A Hiveless drone who wandered the wastes after their queen was killed by Beak Thing raiders. The loss of the hive voice left a silence in the skull that almost drove them mad. Found purpose again with the Stone Rats, who treat them as a person rather than a broken tool.', ''),
        ('Stone Rats', 'Used to run with a different gang in the Border Zone until a dispute over loot turned bloody. Walked away from the survivors with a price on their head and no friends left alive. The Stone Rats took them in without asking too many questions about the past.', ''),
        ('Stone Rats', 'Worked as a farm hand on a United Cities plantation until the owner decided to sell the workers to slavers to cover gambling debts. Fled into the desert with nothing but a harvesting sickle and the clothes on their back. The Stone Rats gave them a weapon worth carrying and enemies worth fighting.', ''),
        ('Swamp Ninjas', 'Grew up a street thief in Shark before a bad job forced a hasty retreat into the deeper swamp. The Swamp Ninjas took her in when the Hounds came looking, and she has repaid them with loyalty and quiet blade work ever since.', ''),
        ('Swamp Ninjas', 'Formerly a laborer in the United Cities work camps, he escaped into the foglands half-starved and desperate. The clan found him wandering the bogs and trained him to channel his hatred for nobility into profitable assassinations.', ''),
        ('Swamp Ninjas', 'Born in a swamp village that paid protection to the Ninjas, she learned their ways by watching from the reeds as a child. When slavers raided her home, the clan took the survivors in rather than let useful recruits perish.', ''),
        ('Swamp Ninjas', 'A failed merchant from the borderlands who lost everything to bandits and saw the swamp as the only place left to go. The Ninjas value his reading and arithmetic skills, using him to plan raids and manage stolen goods.', ''),
        ('Swamp Ninjas', 'Trained from youth as a Holy Nation warrior, he deserted after witnessing the inquisitors burn innocent shek. The fog and secrecy of the swamp offered the only shelter from their long reach.', ''),
        ('Swamp Ninjas', 'Once a barmaid in a border town, she poisoned an abusive customer and fled before the guards came asking questions. The Ninjas recognized her aptitude for subtle killing and gave her a new life among the mangroves.', ''),
        ('Swamp Ninjas', 'A son of swamp farmers who grew up hunting blood spiders and navigating the fog. He joined the clan when the toll collectors began demanding more than the village could give, seeking strength in numbers.', ''),
        ('Swamp Ninjas', 'Mutilated by skin bandits and left for dead, she crawled into the swamp and was found by a Ninja patrol. The clan gave her purpose again, and she now hunts bandits with a particular fervor.', ''),
        ('Swamp Ninjas', 'An aging sword-for-hire who found the desert caravans too exposed and the city garrisons too rigid. The swamp offers steady work and few questions about methods or past allegiances.', ''),
        ('Swamp Ninjas', 'Stolen as a child by slavers and sold to a Swamp Ninja fence as a laborer, she earned her place through stubborn competence. After ten years she no longer remembers her original family, only the clan.', ''),
        ('Swamp Ninjas', 'The swamp took everything when the blood spiders came. Found the ninjas half-dead in the muck and never looked back. Now the fog is home and the blade is family.', ''),
        ('Swamp Ninjas', 'Grew up watching the ninjas move through the reeds like ghosts. Trained from childhood to strike and vanish before the target hits the ground. The swamp is the only teacher that ever mattered.', ''),
        ('Swamp Ninjas', 'Used to run supplies for the Shinobi Thieves until a deal went bad and the Hounds came collecting. The ninjas offered protection and a new identity in exchange for loyalty. Still paying off that debt with every throat opened in the fog.', ''),
        ('Swamp Ninjas', 'Escaped from a Reaver slave camp with nothing but a stolen knife and infected wounds. The ninjas found me delirious in the swamps and saw potential instead of a corpse. Now the Reavers are the ones who sleep with one eye open.', ''),
        ('Swamp Ninjas', 'Got tired of being prey in a world that only respects predators. Learned to fight dirty in the border zones before drifting into swamp territory. The ninjas respected results, not pedigrees.', ''),
        ('Swamp Ninjas', 'Was a fisherman before the Swampers drove the catches away and the starving times came. The ninjas showed how to hunt richer game than fish. A traveler carries more copper than any river ever held.', ''),
        ('Swamp Ninjas', 'Never knew the parents, just the fog and the elders who taught the old ways. The blade forms before the voice deepens in this life. Loyalty is to the swamp first and the clan second.', ''),
        ('Swamp Ninjas', 'Ran caravan guard for a decade until bandits left me bleeding with a shattered knee. The ninjas took in the broken and taught new ways to fight that didn''t require running. Every raid is proof that a cripple can still be death on two legs.', ''),
        ('Swamp Ninjas', 'Joined for the silver and stayed because leaving isn''t really an option. The swamp keeps its own, one way or another. Might as well be the one holding the knife instead of the one it finds.', ''),
        ('Swamp Ninjas', 'The Shinobi Thieves said I lacked discipline and cast me out. The ninjas care less about tradition and more about what works in the mud. Turns out chaos has its own kind of order.', ''),
        ('Swamp Ninjas', 'Survived a Skin Spider attack that killed the rest of my patrol. Realized the world doesn''t reward the slow or the visible. The ninjas offered a philosophy built on not being seen until it''s too late.', ''),
        ('Swamp Ninjas', 'Came south running from a blood feud that would have ended in a shallow grave. The swamp erases old identities better than any desert. The ninjas understood that sometimes survival means becoming someone else entirely.', ''),
        ('Swamp Ninjas', 'Grew crops on the border until United Cities tax collectors burned the farm for short payment. The ninjas took in those with nothing left to lose and taught them to take back what was stolen. Now the only harvest I care about comes from the roads.', ''),
        ('Swamp Ninjas', 'Broke free from a slave caravan with a stolen blade and ran until the fog swallowed me whole. The clan doesn''t ask where you came from, only if you can kill. My neck still itches where the collar used to sit.', ''),
        ('Swamp Ninjas', 'Fished these waters for twenty years before a beak thing took my arm below the elbow. The ninjas found me bleeding out and showed me how to fight with what remains. I know every hidden channel and sunken path better than any map maker.', ''),
        ('Swamp Ninjas', 'The Holy Nation purged my village for the crime of existing near their borders. Wandered south until the swamp''s mists offered something like shelter. Here, no one asks about your blood or your prayers.', ''),
        ('Swamp Ninjas', 'Picked pockets in Heng until the city guard caught me and broke my fingers for it. The ninjas fixed what they could and taught me to use a blade instead of quick hands. The fog hides the hands that take lives now.', ''),
        ('Swamp Ninjas', 'They killed my family in a raid and took me as a hostage nobody paid for. Years passed before I realized I had become one of them without noticing. The swamp has a way of making the enemy into the only family left.', ''),
        ('Swamp Ninjas', 'Came looking for the secret fighting techniques spoken of in whispers across the wastes. Found nothing but endless drills in the mud and the damp. Stayed because the simplicity of survival suits me better than the lies I was told before.', ''),
        ('Swamp Ninjas', 'After the slavers took my children, there was nothing left but rage and empty hours. The ninjas gave that anger direction and a blade to express it properly. Every throat I cut is a prayer they might still be alive somewhere.', ''),
        ('Swampers', 'Grew up tending rice paddies in the borderlands until slavers raided the village. Escaped during transit and fled into the deepest swamps where patrols rarely venture. Now scrapes by harvesting swamp reeds for the local sake brewers, always keeping one eye on the murky water.', ''),
        ('Swampers', 'Learned the art of hashish cultivation from an old swamp hermit who took them in as a youth. The work is backbreaking and the blood spiders are a constant threat, but the herbs pay better than anything else in this festering bog. Dreams of earning enough cats to buy passage to a city where the air doesn''t reek of rot.', ''),
        ('Swampers', 'Born in a swamp village that no longer exists, swallowed by the mire after a season of floods. Knows every safe path through the bog and which pools harbor leeches the size of a finger. The swamp is home, even if it''s slowly trying to kill everyone who lives here.', ''),
        ('Swampers', 'Former Holy Nation peasant who was caught stealing bread for a sick sibling. Fled south before the flames could reach them, eventually stumbling into the swamps half-starved. The locals accepted them because everyone here is running from something.', ''),
        ('Swampers', 'Worked the sake stills for years until the fumes ruined their lungs. Now patrols the village perimeter with a rusted naginata, watching for blood spiders and the occasional wandering hiver. The pay is terrible but at least the work gets them out of the humid brewing tents.', ''),
        ('Swampers', 'Arrived in the swamps with a merchant caravan that was ambushed by fog princes. Survived by playing dead beneath a cart until the raiders moved on. Had no way to leave and no money for passage, so gradually became just another desperate face in the muck.', ''),
        ('Swampers', 'Once served in a United Cities levy before deserting after a brutal pacification campaign. The swamps offered anonymity and a place where no questions are asked about past loyalties. Spends most days fishing the deeper channels and trying to forget the things done in the emperor''s name.', ''),
        ('Swampers', 'Lost both parents to swamp fever before they could walk, raised by the village collective. Grew up tough and suspicious, quick to fight over scraps of food or dry firewood. Trusts the swamp more than any person, and the swamp has never given reason for trust.', ''),
        ('Swampers', 'A smuggler who used the swamp waterways to move contraband between the Shek Kingdom and the Hook. A deal went bad and now owes money to dangerous people elsewhere. Hides in the deepest villages, doing odd jobs until the heat dies down.', ''),
        ('Swampers', 'Formerly a workshop apprentice in a UC city until the master fell into debt to the Traders Guild. Fled when the enforcers came to collect, preferring the uncertainty of the swamp to a debtor''s prison. The work here is filthy but at least they''re not owned by anyone.', ''),
        ('Swampers', 'Fled the Holy Nation with nothing but the clothes on their back after being accused of heresy. The swamp took everything else, but at least the zealots won''t follow into the muck. Now they scrape by hunting mud crabs and avoiding the bigger fish.', ''),
        ('Swampers', 'Used to run a modest farm in the borderlands until reaver raids burned it all down. Starvation drove them into the swamps where the law doesn''t reach. They survive on swamp roots and whatever they can scavenge from dead travelers.', ''),
        ('Swampers', 'Born in the filth and knows nothing else. Learned to fight before they could read and killed their first blood spider at twelve. The swamp is home and they have no desire to ever leave its murky shelter.', ''),
        ('Swampers', 'A former barkeep from Badmouth who got on the wrong side of the local boss. Skipped town in the middle of the night and has been hiding in the deeper swamps ever since. They keep their head down and their mouth shut.', ''),
        ('Swampers', 'Lost a leg to a beak thing and spent everything on a cheap prosthetic. Can''t run anymore so they trap swamp rats and sell the meat to whoever passes through. Some days the pain makes them wish the beak thing had finished the job.', ''),
        ('Swampers', 'Escaped from a slave camp in the United Cities with a chain still wrapped around their wrist. The swamp fog hid their tracks and the swampers didn''t ask questions. They owe their freedom to this rotting hellhole and defend it accordingly.', ''),
        ('Swampers', 'Came to the swamp looking for easy hashish profits and found nothing but misery. The local growers took everything in exchange for protection that never came. Now they work off the debt hauling water and nursing a grudge.', ''),
        ('Swampers', 'A deserting samurai who couldn''t stomach the cruelty of their overseers any longer. Stripped the armor and threw away the sword before wading into the marshes. The swamp offered a kind of penance that clean living never could.', ''),
        ('Swampers', 'Orphaned by skin bandits and raised by an old swamper who taught them the ways of the bog. The old-timer died of swamp fever three winters ago but the lessons stuck. They know every safe path and every hidden danger between here and the border.', ''),
        ('Swampers', 'Ran a small-time smuggling operation that went bad when a deal turned violent. Two bodies in the desert forced them to disappear into the only place no one looks. The swamp has been both prison and sanctuary ever since.', ''),
        ('Swampers', 'A former fisherman whose village was wiped out by the Holy Nation''s purges. Watched their neighbors burn and swore never to be found by the zealots again. The deeper swamps are unpleasant but nothing compared to the fires.', ''),
        ('Swampers', 'Crippled by a gut wound that never properly healed and left too weak for honest work. The swamp doesn''t care about strength, only cunning and the will to keep breathing. They''ve survived two years now out of pure stubborn spite.', ''),
        ('Swampers', 'Escaped from a United Cities slave camp with nothing but the rags on their back. The swamp took them in when no one else would, and the fog became a blanket against the pursuers. They''ve grown accustomed to the stench and the sickness, trading one form of bondage for another.', ''),
        ('Swampers', 'Born in a swamp village to parents who distilled hashish before the coughing took them. Knows the trade from seed to sale and has never set foot on dry soil. The bog is home, and the dangers are just part of the rhythm of life.', ''),
        ('Swampers', 'A former mercenary whose company turned on them over a contract dispute. Crawled into the marshes half-dead from a sword wound that scarred over wrong. The swamper code of mutual survival suited them better than sell-sword honor ever did.', ''),
        ('Swampers', 'Arrived as a scholar documenting swamp vegetation for a wealthy patron in Heft. The patron died, the funding dried up, and the only skill left was knowing which plants wouldn''t kill them. Now they harvest medicinal moss for the same people they once observed from a distance.', ''),
        ('Swampers', 'Lost their farm to United Cities tax collectors who sold the land to a noble''s cousin. Tried petitioning the courts and got beaten for the trouble. The swamp doesn''t ask for taxes, only that you keep your eyes open and your mouth shut.', ''),
        ('Swampers', 'Killed a drunk in a bar fight over a few cats and fled before the authorities arrived. It was self-defense, but the dead man had connections in the Trader''s Guild. The swamp doesn''t care about guilds or warrants, only whether you can pull your weight.', ''),
        ('Swampers', 'Followed a lover into the swamp against their better judgment. The lover caught the rot and died within the year, leaving them stranded without the cats to leave. They stayed because leaving would mean admitting it was all for nothing.', ''),
        ('Swampers', 'A caravan guard whose entire outfit was slaughtered by beak things on a bad route. Wandered aimlessly for days before stumbling into a swamper outpost. Decided that guarding hashish stills was safer than guarding trade goods through cannibal territory.', ''),
        ('Tech Hunters', 'Grew up tending dirt in the Holy Nation, watching crops wither year after year. Decided digging up the past was more profitable than waiting for rain. Now they brave ancient ruins, trading rusted marvels for dry bread and water.', ''),
        ('Tech Hunters', 'A collapsed floor in an Ancient Lab left them with a permanent limp and a healthy respect for structural integrity. They still venture into ruins, but only to map perimeters and appraise surface-level scrap. Their survival depends on caution now, not speed.', ''),
        ('Tech Hunters', 'Bored to death by the slow pace of city life in the United Cities, they left to chase the thrill of discovery. They treat ancient ruins like playgrounds, often rushing in before checking for traps. Their luck will probably run out eventually, but the rush keeps them moving.', ''),
        ('Tech Hunters', 'Saw a merchant sell a single ancient generator for enough cats to buy a whole outpost. They immediately bought a backpack and started walking into the desert. Every piece of rusted metal is just unrefined coin waiting to be carried back to town.', ''),
        ('Tech Hunters', 'Obsessed with the humming of forgotten machines, they joined the Hunters to get first pick of the artifacts. They secretly hand over the best finds to the Machinists for a fraction of the market value. Understanding the past matters more to them than hoarding cats.', ''),
        ('Tech Hunters', 'A botched theft in Sho-Battai forced them to flee into the wilderness with nothing but a rusty cleaver. Falling in with a Tech Hunter patrol was the only thing standing between them and starvation. Now they dig up the old world''s trash to avoid the hangman''s noose.', ''),
        ('Tech Hunters', 'Spent years walking the same stretches of wasteland, committing the locations of buried towers to memory. They rarely enter the ruins themselves, preferring to sell coordinates to other Hunters. It pays enough to keep their canteen full and their boots intact.', ''),
        ('Tech Hunters', 'Raised in the shadow of an ancient scrapyard, they learned to identify alloys before they learned to read. They possess an uncanny knack for spotting valuable tech hidden beneath the dust. It is a tough, solitary way to live, but it beats begging in the streets.', ''),
        ('Tech Hunters', 'Fled the Holy Nation after discovering a cache of forbidden history books in a ruined library. The realization that their entire life was a lie drove them to seek out the truths buried in the ashes of the past. They dig for technology to understand how the old world truly fell.', ''),
        ('Tech Hunters', 'They have seen too many eager recruits get gutted by security spiders or crushed by collapsing ceilings. Now, they only take jobs with guaranteed payouts and insist on checking every corner twice. Longevity in this line of work requires a healthy dose of paranoia.', ''),
        ('Tech Hunters', 'Grew up scraping by in the Border Zone until a collapsed ruin revealed a cache of ancient lenses. Selling those lenses to a Machinist bought better gear and a new life poking through dead cities. Now the only currency that matters is what can be pulled from the dirt before the skin spiders arrive.', ''),
        ('Tech Hunters', 'Left the Holy Nation after neighbors reported forbidden reading habits to the inquisition. Found refuge among the Tech Hunters who actually wanted someone obsessed with Old World schematics. Still flinches at armored paladins but spends most days elbow-deep in corroded mechanisms.', ''),
        ('Tech Hunters', 'A collapsed tunnel in the Ashlands took three fingers and the expedition''s best scout. The prosthetic replacement cost a fortune but proved this profession pays better than subsistence farming somewhere dusty. Determined to fund a full skeletal replacement one ancient trinket at a time.', ''),
        ('Tech Hunters', 'Stumbled into ruin delving after a trading caravan dissolved under Bugmaster raids. Turns out crawling through First Empire debris suits those who have nothing left to lose. The money is inconsistent but the nightmares about what lives in the deep levels are forever.', ''),
        ('Tech Hunters', 'Spent youth as a Machinist acolyte copying dusty schematics by lamplight. Realized the real discoveries happen out in the field where the ancient machinery still bleeds black oil. Left the library behind for the bone-strewn ruins and never looked back at those quiet halls.', ''),
        ('Tech Hunters', 'An old map purchased from a dying drifter pointed toward a cache in the Stormgap Coast. The cache was empty but the search itself was more alive than years of guard duty in Sho-Battai. Now every faded inscription is a puzzle worth solving and every dark corridor a potential payday.', ''),
        ('Tech Hunters', 'Former fisher from the coast who found an engine component washed up after a storm. The Machinists paid enough to replace the boat and then some. Has been wading through toxic puddles in ancient facilities ever since chasing that same high.', ''),
        ('Tech Hunters', 'Deserted a United City labor squad when the overseer started working people to death in the Stobe''s Garden ruins. Blended in with a Tech Hunter crew long enough to learn the trade and earn a weapon. The Empire still has a bounty outstanding but the ruins keep everyone anonymous.', ''),
        ('Tech Hunters', 'Child of scavengers who always reached a little deeper into the ruins than was safe. Lost family to a security system that still functioned after millennia of silence. Kept digging anyway because understanding those systems is the only way to ensure they never take anyone else.', ''),
        ('Tech Hunters', 'Needed coin fast after a Shek warrior dispute ended with a broken jaw and stolen supplies. A Tech Hunter outpost was hiring muscle for an expedition into the Floodlands. Three expeditions later the jaw still aches when it rains but the pockets jingle with ancient coins.', ''),
        ('Tech Hunters', 'Started as a guide leading scholars through the Leviathan Coast for meager pay. Watched them pull a functioning power core from a submerged facility and realized who actually profits in this world. Bought a pickaxe and a rope the next morning and walked into the wilderness alone.', ''),
        ('Tech Hunters', 'Escaped from Reaver slavers during a storm and stumbled half-drowned into an Old World bunker. Spent two weeks eating cache rations and reading maintenance logs by flickering emergency lights. Emerged with a head full of fragmentary knowledge and a conviction that the past holds the keys to surviving the present.', ''),
        ('Tech Hunters', 'Grew up on a dust farm at the edge of the Border Zone where the soil gave out after three seasons. Watched the family starve slowly until a Tech Hunter caravan passed through buying water skins and offering work. Never went back to the farm. The ruins might kill you but they never ask you to wait for death.', ''),
        ('Tech Hunters', 'A Skeleton found them half-buried in the Ashlands after a Holy Nation patrol left them for dead on suspicion of reading. Repaid the life debt by hauling scrap and acting as a meat shield during expeditions. The Skeleton moved on years ago but the skills stuck. Now leads crews into places most humans won''t follow.', ''),
        ('Tech Hunters', 'Spent childhood as a house slave in a United City noble''s estate dusting ancient artifacts in a private collection. Learned to read Old World script from the labels because there was nothing else to read. Bought freedom with the proceeds from a single authentic battery unit smuggled out during a staff shuffle. The nobles never figured out which servant understood the display cases better than they did.', ''),
        ('Tech Hunters', 'Trained as a Machinist engineer but got expelled for selling restored artifacts on the side instead of returning them to the order. The Tech Hunters don''t ask questions about supply chains as long as the goods are genuine. Still thinks the Machinists are hypocrites for hoarding what should belong to everyone willing to bleed for it.', ''),
        ('Tech Hunters', 'Was a Holy Nation farmer until a rusted limb rose from the soil and killed two neighbors during a clearcutting. The Paladins called it a demon and burned the field. Started walking east that same night because if the past can reach up through the dirt and kill then understanding it seems more useful than praying.', ''),
        ('Tech Hunters', 'Got their leg crushed by a falling beam in the Ghostlands ruins on their first expedition. The crew left them behind with a canteen and a knife. Crawled out three weeks later carrying a functioning AI module and a permanent limp. Works alone now because loyalty in the ruins is just another weight.', ''),
        ('Tech Hunters', 'Born in a Swamp village where everyone fished and nobody read. Stole a waterlogged databank from a traveling merchant''s cart just to look at the pictures inside. Taught themselves enough to be useful and headed for the Border Zone where literacy in Old World script buys meals. The swamp still stinks in their memory but the ruins smell like tomorrow.', ''),
        ('Tech Hunters', 'A former cannibal from the Fog Islands who got captured by Tech Hunters and shown what the machines in the ruins actually do. Decided that eating people was primitive compared to understanding the ancient technology that built the world. The other Tech Hunters keep their distance but nobody questions results and this one brings back more functioning cores than anyone.', ''),
        ('The Gorrillo Bandits', 'Starved off a failed homestead in the borderlands after raiders took the last harvest. Stumbled into the Gorrillo camp half-dead and never looked back. Now takes what''s needed from anyone weak enough to lose it.', ''),
        ('The Gorrillo Bandits', 'Escaped a Holy Nation slave camp with nothing but scars and a stolen sword. Found the bandits were the only ones who didn''t ask about past sins or loyalties. Still fights with the desperation of someone who has tasted chains.', ''),
        ('The Gorrillo Bandits', 'Born in a dirt-floored tent to a gang mother who died on a botched raid. Learned to swing a blade before learning to read, raised by the gang as a whole. Knows nothing of settled life and wants to know less.', ''),
        ('The Gorrillo Bandits', 'Used to run guard for caravans until a Beak Thing attack left everyone else dead. Wandered the wastes in shock until the Gorrillos picked them up. The gang fills the void where the old life used to be.', ''),
        ('The Gorrillo Bandits', 'Fled the Shek Kingdom after being marked a coward for retreating from an unwinnable fight. The bandits don''t care about honor, only results. Proved useful with a blade and found a place where survival isn''t shamed.', ''),
        ('The Gorrillo Bandits', 'Lost a farm to United Cities tax collectors who demanded double the owed amount. Took to the roads with a rusty cleaver and a grudge against anyone wearing fine cloth. Robs wealthy-looking travelers with particular enthusiasm.', ''),
        ('The Gorrillo Bandits', 'A disgraced Hired Sword whose contract ended when the merchant couldn''t pay. Drifted between jobs until the Gorrillos offered steady work with no questions asked. Still keeps a few professional habits, like maintaining gear and watching flanks.', ''),
        ('The Gorrillo Bandits', 'Grew up in a squat in the Border Zone eating dust and scrap. Joined the bandits because it meant regular meals and a dry place to sleep. Content to follow orders and let someone else worry about the big picture.', ''),
        ('The Gorrillo Bandits', 'Left a Swamp gang after a dispute over leadership turned bloody. Wandered for weeks before falling in with the Gorrillos, who valued experience over local politics. Treats raiding as a trade to be practiced with grim skill.', ''),
        ('The Gorrillo Bandits', 'Followed an older sibling into the bandit life at a young age and never learned another way. Watched that sibling die in a failed heist and stayed with the gang out of habit. Doesn''t question the lifestyle; it''s simply what exists.', ''),
        ('The Gorrillo Bandits', 'Starved off a failing farm in the Border Zone and took to the roads with nothing but a rusty pipe. Food became the only currency that mattered, and taking it proved easier than growing it. Now the sight of a lonely traveler triggers nothing but the calculation of a quick ambush.', ''),
        ('The Gorrillo Bandits', 'Escaped a Holy Mine with broken fingers and a deep hatred for anyone who lived in comfort. Stumbled into a Gorrillo camp half-dead and was nursed back to health on stolen grog and roasted drumsticks. Pays back that debt by being the first to charge whenever someone looks wealthy enough to strip.', ''),
        ('The Gorrillo Bandits', 'Never knew any life but the pack, born to a bandit mother who taught knife-work before reading. The Gorrillos were the first group that didn''t try to sell them, and that loyalty runs deeper than any law. Still sleeps with one eye open and a weapon within arm''s reach.', ''),
        ('The Gorrillo Bandits', 'A former caravan guard who lost her job when the trade routes dried up and the merchants stopped paying. Tried honest work in the cities but kept getting turned away for having no papers and too many scars. The bandits only cared that she knew how to swing a blade and didn''t ask questions about the past.', ''),
        ('The Gorrillo Bandits', 'Drank away a modest inheritance in the vain hope of becoming a skilled martial artist. Woke up in a ditch outside Sho-Battai with nothing but a hangover and a stolen sword. Found the Gorrillos and realized their simple brutality suited a man with no remaining dignity.', ''),
        ('The Gorrillo Bandits', 'Fled a Shek Kingdom blood-duel after refusing to die for a pointless grudge between warriors. The Gorrillos don''t care about honor or strength, only that you can hold your own in a scrap. Carries the shame of cowardice like a stone in the gut, buried under layers of meanness.', ''),
        ('The Gorrillo Bandits', 'Sold into servitude at age nine and passed between owners like old equipment. Slipped away during a dust storm and ran until legs gave out, waking to find bandits looting the unconscious. Instead of being robbed, got offered a place among the ranks and learned that the strong take and the weak get taken.', ''),
        ('The Gorrillo Bandits', 'Once cooked for a United City noble''s household until a minor infraction landed a permanent scar and dismissal without references. The Gorrillos don''t judge cooking by presentation, only by whether the meat is cooked and the poison isn''t. Acts as camp chef when not robbing the same kind of soft aristocrats who tossed them aside.', ''),
        ('The Gorrillo Bandits', 'Lost an arm to a skin spider and watched the settlement abandon them as dead weight rather than feed a cripple. A Gorrillo scout found them delirious from blood loss and dragged them back to camp out of twisted amusement. The crude iron replacement is ugly but functional enough to grip a club and shatter a kneecap.', ''),
        ('The Gorrillo Bandits', 'Grew up a scavenger''s child in the Bonefields, picking ruins clean alongside a dying parent. Inherited nothing but a talent for spotting valuables from a distance and an instinct for when to run. The Gorrillos use those eyes to spot marks on the road, and the pay is better than sorting through ancient trash.', ''),
        ('The Gorrillo Bandits', 'A Hiver who lost connection to the Queen and wandered the desert in a fog of confused silence until a bandit patrol picked them up. Without the hive''s hum, life became a blank void that violence briefly fills. Follows orders without question because independent thought brings only the echo of what is missing inside.', ''),
        ('The Gorrillo Bandits', 'Former fisher from the coast whose village was wiped out by Beak Thing raiders while out at sea. Returned to nothing but blood-soaked sand and the realization that the world takes everything unless taken from first. Joined the first bandit crew that would have them and never looked at the water again.', ''),
        ('The Gorrillo Bandits', 'Served as a mercenary for years until the contract dried up and the company dissolved over unpaid wages. Took what was owed at swordpoint from the former captain and fled before the city guard got involved. The Gorrillos respect initiative and never ask about old loyalties, only current usefulness.', ''),
        ('The Gorrillo Bandits', 'Escaped a Holy Nation mine with broken chains still scarred into the wrists and a permanent distrust of anyone preaching virtue. The desert swallowed the pursuers and a Gorrillo patrol found a willing recruit who asked no questions about morality. Still wakes reaching for a pickaxe that is no longer there, but a heavy club serves well enough.', ''),
        ('The Gorrillo Bandits', 'Born to a prostitute in a waystation brothel and thrown into the streets at twelve when the madam decided the child cost more than it earned. Survived by stealing scraps and sleeping under floors until a bandit recruiter noticed the feral quickness. The Gorrillos became the family that blood never provided, and loyalty to the gang runs deeper than any kinship.', ''),
        ('The Gorrillo Bandits', 'Worked a humble farm until drought killed the crops and tax collectors took the land for debt. Watched the family scatter across the wastes and swore never to starve quietly again. The Gorrillos eat well enough when the raiding is good, and nobody asks a starving farmer to pay for the privilege of surviving.', ''),
        ('The Gorrillo Bandits', 'A Shek warrior who fled a duel rather than face shame, abandoning the warrior way and the clan that demanded honor. The bandits do not care about courage or tradition, only that the strong arm holds a weapon. Carries the guilt like a stone in the gut, drowned out by the noise of each raid.', ''),
        ('The Gorrillo Bandits', 'Lost everything to a dust storm that buried the homestead and suffocated the children while the parents dug frantically at collapsed walls. The marriage fell apart in the aftermath and the bottle took what the storm left behind. The Gorrillos do not ask why a recruit drinks, only that the bottle does not slow the swing.', ''),
        ('The Gorrillo Bandits', 'Once a respected blacksmith in a border town until a noble decided the forge belonged to a favored cousin. The law upheld the theft and the eviction, teaching a harsh lesson about who justice actually serves. Now repairs crude bandit weapons in exchange for shelter and the occasional chance to visit violence upon passing aristocrats.', ''),
        ('The Gorrillo Bandits', 'A Greenlander who wandered too far from the safety of Holy Nation lands and got taken by slavers before the first week ended. Escaped during a bandit raid on the slave caravan when the chaos provided an opening to cut bonds and vanish. Joined the raiders who inadvertently provided freedom, having learned that the world divides cleanly into those who cage and those who break cages.', ''),
        ('The Holy Nation', 'Born to a family of Okranite farmers in the fertile heartlands, he learned to wield a sword as soon as he could hold a plow. When a skeleton raid burned his village, he pledged his life to the Holy Army. He now patrols the border with quiet fury, viewing every machine as a personal affront to the light.', 'male'),
        ('The Holy Nation', 'He grew up an orphan on the streets of Stack, surviving by reciting prayers for copper outside the temple. A passing priest noticed his devotion and took him in as a temple servant. Years of dutiful study earned him the vestments of a low priest, and he now tends the sacred flames with unwavering conviction.', 'male'),
        ('The Holy Nation', 'Conscripted into the Holy Army at sixteen, he spent a decade marching between Blister Hill and the border outposts. The endless skirmishes against shek raiders and swamp ninjas hardened him into a stoic soldier. He follows orders without question, believing obedience to the Phoenix is the highest virtue.', 'male'),
        ('The Holy Nation', 'A wound from a shek warrior''s axe left him unable to march, so the Holy Army reassigned him to gate duty in Stack. He spends his days checking travelers for contraband and ensuring no skeletons enter the holy city. The monotony weighs on him, but he considers his vigilance a sacred trust.', 'male'),
        ('The Holy Nation', 'His family has farmed the same stretch of Okranite land for five generations, paying the tithe without fail. He knows every prayer by heart and leads his household in devotion each morning before dawn. Though he has never lifted a blade in anger, he would take up arms without hesitation if the Phoenix called.', 'male'),
        ('The Holy Nation', 'Once a servant in a noble household, he earned his freedom through twenty years of loyal service. He used his savings to purchase a small trading stall near the temple district, selling prayer candles and blessed charms. He views commerce as a form of worship, seeing every sale as a small victory for the light.', 'male'),
        ('The Holy Nation', 'The son of a mid-ranking paladin, he was raised with the expectation of military service from his first breath. He trained daily in the courtyard beneath the watchful eyes of the temple masters, learning both scripture and steel. Now a paladin himself, he leads patrols along the southwestern border with zealous determination.', 'male'),
        ('The Holy Nation', 'He found Okran''s light in a moment of desperation, half-starved and fleeing bandits in the wilderness. A patrol of Holy Nation soldiers saved him and brought him to the temple, where he swore his life to the Phoenix. He now serves as a temple guard, fiercely protective of the priests who gave him purpose.', 'male'),
        ('The Holy Nation', 'As a younger son of a poor farming family, he had no inheritance to claim and few prospects. He joined the Holy Army seeking purpose and found it in the rigid discipline and clear doctrine. He has risen to the rank of sergeant, his loyalty absolute and his mercy toward non-believers nonexistent.', 'male'),
        ('The Holy Nation', 'He walked the path of a trader for years, moving goods between Holy Nation cities and occasionally dealing with outsiders. The corruption he witnessed in foreign settlements only deepened his appreciation for the order the Phoenix provides. He now runs a supply caravan exclusively for the military, ensuring the soldiers of Okran want for nothing.', 'male'),
        ('The Holy Nation', 'A former laborer in the stone quarries near Blister Hill, he endured years of backbreaking work to support his family. When a priest visited the quarry and spoke of Okran''s purpose for every soul, something shifted in him. He abandoned the quarry and volunteered for temple service, finding more meaning in sweeping the holy floors than he ever found in stone.', 'male'),
        ('The Holy Nation', 'Born to a family of zealots who dedicated all their sons to the Phoenix, he was raised in the barracks alongside other children of the faith. He knows nothing of the world beyond the Holy Nation''s borders, and he wants to know nothing. He serves as a low-ranking enforcer, rooting out heresy and unsanctioned worship wherever it takes root.', 'male'),
        ('The Holy Nation', 'He spent his youth hunched over parchment, copying the sacred texts of Okran by candlelight. His hands bear ink stains instead of calluses, but his mind holds every verse and commandment. He now serves as a low priest, interpreting scripture for the faithful and ensuring doctrinal purity in his district.', 'male'),
        ('The Holy Nation', 'He has stood at the gates of Stack for six years, checking every traveler who seeks entry. He has turned away countless skeletons and shek, enforcing the Holy Nation''s laws without hesitation. The work is monotonous, but he finds peace in knowing he protects the faithful from corruption.', 'male'),
        ('The Holy Nation', 'When skimmers tore through his village, he watched his family die while he fled like a coward. The priests told him his survival was Okran''s will and that he had been spared for a holy purpose. He now fights on the front lines against the shek, convinced that every enemy he strikes down honors his family''s memory.', 'male'),
        ('The Holy Nation', 'She has spent her entire life within the walls of a temple household, washing robes and preparing meals for the priests. Her days blur together in a rhythm of prayer and labor, and she has never known any other existence. She tells herself that service is fulfillment, though sometimes she watches the patrols leaving through the gate and wonders what lies beyond the dust.', 'female'),
        ('The Holy Nation', 'Married at fourteen to a farmer from Okran''s Pride, she has borne six children and buried two. The farm is her entire world, and her husband''s word is absolute law within it. She finds small comforts in the harvest festivals and the priest''s weekly sermons, trusting that endurance in this life ensures peace in the next.', 'female'),
        ('The Holy Nation', 'Her husband was taken by a beak thing while checking the northern fences, and now she relies on her eldest son to maintain the household''s standing. The priests have made it clear that a woman without male protection is a vulnerability to the community. She keeps her head down and her hands busy, terrified of what happens if her son fails to provide.', 'female'),
        ('The Holy Nation', 'She serves as a weaver in a temple workhouse, turning raw hemp into cloth under the watchful eyes of an overseer. The other women are her only companionship, and they share whispered stories during the long hours at the loom. She has accepted her lot, finding purpose in contributing to the community''s needs even if she will never own anything herself.', 'female'),
        ('The Holy Nation', 'Born to a family of devout laborers, she was assigned to assist the temple kitchen when she showed no promise for field work. She scrubs pots and portions rations, occasionally catching fragments of scripture drifting from the sermon halls. She cannot read the holy texts herself but memorizes every phrase she hears, clinging to each word as proof that her suffering has meaning.', 'female'),
        ('The Holy Nation', 'Her father arranged her marriage to a paladin''s second son, a union meant to elevate the family''s standing within the parish. She moved to a larger settlement and now manages a household that feels utterly foreign to her. Her husband is often away on patrol, and she is left to navigate the rigid expectations of her new neighbors alone.', 'female'),
        ('The Holy Nation', 'She tends a small herb garden behind her family''s dwelling, growing what remedies she can for the ailments that sweep through the worker districts. The priests tolerate her skills so long as she does not claim knowledge beyond her station. She has learned which questions are safe to ask and which will earn her a backhand across the face.', 'female'),
        ('The Holy Nation', 'After her sister was taken during a Shek raid, she withdrew almost entirely from community life. She speaks only when spoken to and performs her assigned duties with mechanical precision. The priests say the raid was a test of faith, but she cannot stop replaying that day in her mind, wondering why Okran allowed such suffering.', 'female'),
        ('The Holy Nation', 'A lifetime of field labor has worn her hands raw and bent her back, but she continues working the harvests because there is no other choice. She has never traveled beyond the territory surrounding her birth village. Her prayers are simple and repetitive, asking only for strength to endure one more season.', 'female'),
        ('The Holy Nation', 'Her eldest daughter recently came of age, and the pressure to arrange a proper marriage has consumed her waking hours. She knows that a poor match could ruin the family''s fragile reputation. She visits the temple daily, begging Okran for guidance through the negotiation process that will determine her daughter''s entire future.', 'female'),
        ('The Holy Nation', 'She fled a cruel household in the dead of night and sought refuge with a distant cousin in another parish. The transition required new documentation and the blessing of a sympathetic priest who asked no questions. She lives in constant fear that her former husband will track her down, knowing the law offers her no protection if he does.', 'female'),
        ('The Holy Nation', 'She was tasked with mending and maintaining the prayer garments used by the local congregation, a role that gives her rare access to the temple''s inner chambers. She sees the priests in their unguarded moments and has learned that holiness and virtue are not always the same thing. She keeps these observations locked behind her teeth, understanding that silence is the price of survival.', 'female'),
        ('The Holy Nation', 'She was born to a family of tenant farmers and has known nothing but the rhythm of planting and harvest. Her father arranged her marriage to a man twice her age when she was barely fifteen, and she has borne him six children, three of whom survived past infancy. She does not question Okran''s plan because no one ever taught her that questioning was possible.', 'female'),
        ('The Holy Nation', 'She tends the temple''s candle stores, a quiet role that keeps her away from the male worshippers and the priests'' attention. The work leaves her alone with her thoughts for long stretches, something both the priests and her husband consider dangerous. She has begun hiding small scraps of discarded parchment, tracing the shapes of letters when no one watches.', 'female'),
        ('The Holy Nation', 'Her husband died in a skirmish with United City patrols three seasons ago, leaving her dependent on the parish for rations. The priests make it clear that charity must be earned through additional labor at the temple, and she scrubs floors and hauls water from dawn until exhaustion claims her. She knows that another season without a new husband will see her driven from the parish altogether.', 'female'),
        ('Traders Guild', 'Grew up hauling crates in a Waystation warehouse before earning a spot on a caravan crew. Years of dodging dust bandits and haggling at outposts taught them that every cat has its price. Now they supervise supply runs with a cold eye for shrinkage.', ''),
        ('Traders Guild', 'Born to a declining noble house in the United Cities, they fled ruin with nothing but a sealed ledger of old trade debts. The Guild bought those debts at a fraction of their worth and put them to work collecting. They have since learned that commerce and cruelty share the same ledger.', ''),
        ('Traders Guild', 'Lost a sibling to slavers near Rebirth and vowed never to be weak again. They took up work as a Guild guard, trading muscle for steady pay and the thin protection of a powerful employer. The armor is heavy but the rations come on time.', ''),
        ('Traders Guild', 'Spent youth navigating the shifting sands of the Black Desert, mapping safe paths between fuel nodes. That rare expertise caught a Guild assessor''s eye, and they were offered a contract surveying new trade routes. They still sleep with one eye open.', ''),
        ('Traders Guild', 'Apprenticed under a harsh Stone Camp quartermaster who taught them to count every grain and trust no one. Rose to manage a regional distribution yard where shortages are blamed on sandstorms more often than theft. They know better but keep their mouth shut.', ''),
        ('Traders Guild', 'A former Holy Sword who deserted after questioning the faith''s hatred of technology. Found reluctant acceptance in the Guild, where skill with a blade matters more than piety. They escort high-value shipments through the Border Zone without asking what the crates contain.', ''),
        ('Traders Guild', 'Survived a Skin Bandit raid that took their arm and left them for dead. A Guild caravan found them half-buried in ash and offered basic prosthetics in exchange for a decade of service. They handle inventory now, too slow for combat but too stubborn to quit.', ''),
        ('Traders Guild', 'Grew up in a Flotsam village watching mothers barter scavenged medkits for scrap. Left to seek real wealth with the Guild, promising to send cats back home. The letters grew shorter over the years and the coin deliveries stopped, but the job remains.', ''),
        ('Traders Guild', 'Once ran an independent trading post on the edge of the Swamp until swamp ninjas bled it dry. The Guild absorbed the ruins and hired the former owner as a junior factor at a tenth of their old income. They smile at customers and dream of vengeance.', ''),
        ('Traders Guild', 'Recruited from the Shek Kingdom after their warband was disbanded following a failed raid. The Guild valued their raw strength and complete ignorance of market prices. They break legs when accounts go unpaid and sleep soundly regardless.', ''),
        ('Traders Guild', 'Grew up watching bandits pillage outlying farms, deciding early that coin offered more protection than any sword. Joined the Guild as a caravan guard and eventually earned enough trust to manage supply runs. Now oversees trade convoys through the Borderlands, taking quiet satisfaction in delivering goods that raiders can never seem to catch.', ''),
        ('Traders Guild', 'Lost everything in a Holy Farm levy and walked to the nearest Guild outpost with nothing but a head for numbers. Started tallying inventory in exchange for meals, slowly working into a proper ledgership. The work is tedious but the food is consistent, and after starvation, consistency is enough.', ''),
        ('Traders Guild', 'Born into a family of modest shopkeepers in the United Cities, learned bartering before learning to read properly. When the family business collapsed under corrupt tax collectors, sought employment with the Guild''s regional branch. Has since rebuilt a modest fortune through shrewd negotiations and an absolute refusal to extend credit to samurai.', ''),
        ('Traders Guild', 'Spent a decade as a sellsword before realizing the real money moved behind desks, not on battlefields. Applied those combat skills to protecting Guild shipments across the Cannibal Plains and the Swamp. The scars are many, but the pay is steady, and there is comfort in fighting for cargo instead of causes.', ''),
        ('Traders Guild', 'Was once a slave in Rebirth, freed after a Guild trade negotiation purchased the labor contracts for an entire work camp. The Guild offered employment to those willing to work off their purchase price, and that opportunity was seized without hesitation. Now serves as a dock foreman, treating every shipment like a personal obligation that can never be fully repaid.', ''),
        ('Traders Guild', 'Third-generation Guild member whose grandmother ran a trading post in the Hook and whose father died on a skimmer ambush near Sho-Battami. Inherited the family trade routes and a burning grudge against anything with claws. Keeps a meticulous blacklist of clients who have shortchanged the family name.', ''),
        ('Traders Guild', 'Former Holy Nation citizen who fled after being accused of heresy for trading with non-humans. The Guild did not care about past affiliations, only that profit margins stayed healthy. Now manages a waystation on the fringe of Holy Nation territory, quietly helping refugees move south in exchange for labor and information.', ''),
        ('Traders Guild', 'Started as a street peddler in Clownsteady, selling scavenged weapons to desperate travelers. The Guild noticed an uncanny talent for reading what people needed before they knew it themselves. Now travels between major settlements as a procurement specialist, identifying shortages before they become crises and filling them at a healthy margin.', ''),
        ('Traders Guild', 'A failed farmer from the Flats who watched crops wither three seasons in a row while Guild caravans passed fat and untroubled. Swallowed pride and asked for work rather than charity, starting as a warehouse loader. The muscles still ache from hauling crates, but the pay pouch jingles with more reliability than rain ever did.', ''),
        ('Traders Guild', 'Served as a scout for Imperial expeditions before deserting after a particularly senseless engagement in the Fog Islands. Found that the Guild valued pathfinding skills almost as much as the Empire had, and paid better for far less bloodshed. Now maps alternative routes through dangerous territory, selling safe passage information to the highest bidder.', ''),
        ('Traders Guild', 'Once ran a small tavern in Stack until Holy Nation purges drove away customers and squeezed profits to nothing. Packed up and walked to the nearest Guild city, where commerce flows freely and no one asks about faith. Manages a Guild-owned rest house now, gathering rumors and traveler intelligence alongside room fees.', ''),
        ('Traders Guild', 'Born to a Shek warrior who abandoned the way of the sword for the way of the coin after being left for dead by a warband that deemed her too injured to keep. Raised in Guild outposts, learning trade tongue and currency exchange instead of combat forms. Carries no blade, only a well-worn abacus and the absolute certainty that gold defeats steel in every war that matters.', ''),
        ('Traders Guild', 'Captured by slavers in the Border Zone and sold to a mine, but the Guild purchased the debt after recognizing a talent for organizing supply lines. Worked off the bond price in three years by streamlining warehouse operations. Now oversees inventory for a major Guild depot, knowing every crate by heart because those crates once represented the difference between freedom and chains.', ''),
        ('Traders Guild', 'Spent a decade hauling skimmers from the coast near Catun until Beak Thing raids destroyed the traps one too many times. The Guild needed someone who understood coastal trade routes and could negotiate with fishing villages. Now coordinates maritime supply contracts, earning steady wages that do not depend on what the ocean decides to give up each morning.', ''),
        ('Traders Guild', 'Started as a hired sword for Guild caravans, fending off dust bandits and starving cannibals for meager daily rates. Survived a dozen ambushes and learned which passes were death traps and which were merely dangerous. The Guild realized a living route planner was worth more than another dead guard, and promoted accordingly.', ''),
        ('Traders Guild', 'Woke up in the Deadlands with no memory of past cycles and no desire to find out. Mechanical precision made inventory accounting effortless, and the Guild did not care about origin stories so long as the ledgers balanced. Now works as a senior bookkeeper, finding quiet satisfaction in numbers that behave logically unlike the chaotic organics they serve.', ''),
        ('Traders Guild', 'Felt the hive mind loosen during a trading expedition and discovered a preference for individual negotiation over collective decision-making. The Guild offered structure without the suffocating unity of the hive. Serves as a cultural liaison between hiver settlements and Guild merchants, translating not just words but the fundamental logic of profit into something the hive can accept.', ''),
        ('Traders Guild', 'The family name meant nothing when United Cities debt collectors came, but the education in etiquette and negotiation still held value. The Guild hired on the spot after watching a masterful renegotiation of a supply contract that saved a waystation from ruin. Now handles delicate diplomatic arrangements with the Holy Nation and United Cities factions, where manners matter more than mercy.', ''),
        ('Traders Guild', 'Lost two limbs to a Skin Bandit attack along with any naive belief that good intentions matter in this world. Rebuilt with cheap prosthetics and a burning need for control over circumstance. Now designs caravan security protocols for the Guild, calculating acceptable losses and optimal guard ratios with the cold precision of someone who has already lost what cannot be replaced.', ''),
        ('Traders Guild', 'Spent two months in a cannibal cage before escaping during a territorial dispute between rival tribes. The experience taught exactly how cannibal bands operate and where they establish hunting grounds. Sells that knowledge to the Guild, routing caravans around the worst territories and occasionally guiding retrieval teams to rescue captured merchants before the fires are lit.', ''),
        ('United Cities', 'Enlisted in the city guard to escape the starvation of the outer farms. The armor is heavy and the desert heat is merciless, but the daily ration of rice and the authority to extort merchants makes it worthwhile. They enforce the Emperor''s will without question, knowing the alternative is a life in the slave pits.', ''),
        ('United Cities', 'Spent a decade laboring in the stone quarries after a trading venture bankrupted their family. They eventually bought their freedom through sheer endurance and a bit of luck, though the brand on their neck still draws suspicious glances. Now they work as a lowly porter, terrified of ever falling into debt again.', ''),
        ('United Cities', 'Learned early that survival in the upper districts depends entirely on who you bribe and who you betray. They spend their days carrying scrolls and silencing the complaints of starving peasants. A single mistake could mean the executioner''s block, so they keep their head down and their pockets full.', ''),
        ('United Cities', 'Tends to the damp farms on the outskirts, praying the skin spiders stay away from the water supply. The tax collectors take almost everything, leaving barely enough protein to keep the family standing. Every season is a gamble between starvation and the slavers'' nets.', ''),
        ('United Cities', 'Traded the chaotic freedom of a mercenary company for the steady pay and rigid structure of the United Cities military. They miss the camaraderie of the barracks, but the promise of land and a proper retirement keeps them in line. Their sword arm is getting slower, but their instincts for urban politics are sharper than ever.', ''),
        ('United Cities', 'Facilitates the lucrative trade routes between the coastal cities and the inland outposts. Bribing samurai patrol captains is just another business expense to ensure the caravans arrive unscathed. They sleep with one eye open, knowing the Traders Guild will sacrifice them in a heartbeat if the profit margins dip.', ''),
        ('United Cities', 'Grew up believing the sermons of the high priests, only to realize the nobles worship nothing but currency. They attend the mandatory sermons and chant the required prayers, but the hypocrisy rots their spirit. They are waiting for a chance to slip away to the Holy Nation, if only they weren''t branded a heathen.', ''),
        ('United Cities', 'Grew up in the gutters of Sho-Battai, stealing copper to survive the harsh winters. They know every shadow and escape route in the city slums, avoiding the samurai patrols with practiced ease. A single slip will cost them a hand, so they move like ghosts through the crowded markets.', ''),
        ('United Cities', 'Takes a twisted pleasure in breaking the spirits of the newly captured rebels and debtors. The whip feels like an extension of their arm, a tool to maintain order in the Emperor''s great works. It is a brutal job, but the nobles pay well for obedience and a high quota.', ''),
        ('United Cities', 'Fled their outpost after the anti-slavers burned the barracks and freed the laborers. They now cling to the safety of the city walls, haunted by the screams of their former comrades. They enlisted the very next day, desperate for the protection of the samurai legions.', ''),
        ('United Cities', 'Born to a samurai family of modest standing, this soldier earned their blade through rigorous drills rather than inheritance. They patrol the desert roads with quiet diligence, sending most of their pay back to an aging mother in Sho-Battai. The sight of slaves being traded in the market still turns their stomach, but dissent is a quick path to the cross.', ''),
        ('United Cities', 'Sold into bondage as a child to cover a father''s gambling debt, this laborer spent twelve years hauling copper for the Traders Guild. A rare act of leniency from a passing noble earned them their freedom papers, though the brand on their neck still draws sneers. Now they work the warehouse docks, saving every cat to buy their younger sister''s release.', ''),
        ('United Cities', 'This merchant spent years caravanning between Heng and Catun before settling down to run a modest silk shop. They know every bribe required to keep the tax collectors satisfied and which samurai captains can be bought with gifts. Survival in the United Cities means understanding that laws are flexible for those with enough coin.', ''),
        ('United Cities', 'Conscripted from a starving farming village during the last border conflict with the Shek, this recruit found they had a talent for following orders without question. They were assigned to the city gates, where they spend long shifts checking travel papers and shaking down scavengers for import fees. The power has begun to sour them, and they no longer recognize the fearful face in the water barrel''s reflection.', ''),
        ('United Cities', 'A second-generation city noble with a crumbling estate and mounting debts, this aristocrat clings to status through elaborate feuds with rival houses. They attend every court function and recite the Okranite prayers flawlessly while quietly arranging accidents for those who threaten their standing. The slaves maintaining their villa are treated as disposable decorations, replaced whenever the budget allows.', ''),
        ('United Cities', 'This former scavenger scraped together enough cats to purchase citizen papers from a corrupt magistrate, trading the wasteland for a cramped apartment in the capital. They sell grilled meat skewers to market crowds, always keeping one eye on the samurai patrols. The thin veneer of respectability could vanish in an instant if anyone uncovered where the meat really comes from.', ''),
        ('United Cities', 'Trained in the imperial academies, this bureaucrat spends their days stamping trade permits and recording slave transfers with mechanical precision. They own a comfortable townhouse and a pair of bodyguards, insulated from the suffering their paperwork enables. Every so often a name crosses their desk that they recognize from the old neighborhood, and they stamp it without a pause.', ''),
        ('United Cities', 'Raised in an Okranite orphanage after slavers took their parents, this devout citizen found purpose in the temple hierarchy. They spend their days copying holy texts and their evenings reporting suspected heretics to the authorities. Faith is both shield and weapon in the United Cities, and they have learned to wield it without mercy.', ''),
        ('United Cities', 'A retired samurai captain who lost a hand to a Beak Thing in the Border Zone, this veteran now serves as an advisor to a wealthy merchant house. Their tactical knowledge keeps the caravans moving safely, and their remaining hand can still end a bar fight in seconds. They never speak of the purge they led in the Rebel Farmers'' camp, but the nightmares speak for them.', ''),
        ('United Cities', 'This young noble''s third child knows they will inherit nothing but a family name and a modest monthly allowance. They while away the hours in tea houses and gambling dens, searching desperately for a wealthy marriage or a lucrative government appointment. The United Cities eats those who cannot secure their own power, and time is running out.', ''),
        ('United Cities', 'Captured during a raid on a border settlement, this former nomad was broken on the cross before being sold to a noble''s mining operation. Ten years of subterranean labor left them hollow-eyed and compliant, a model slave who no longer dreams of escape. When the overseer''s back is turned, they still whisper the old desert prayers to the sand that will never bury them.', ''),
        ('United Cities', 'This weaponsmith''s forge burns day and night fulfilling contracts for the samurai legions, producing blades of adequate but unremarkable quality. They employ a dozen apprentice laborers, paying them just enough to prevent theft while pocketing the difference. In the United Cities, war is simply another business, and business has never been better.', ''),
        ('United Cities', 'This tenant farmer works a small plot outside the city walls, giving half their yield to the noble who holds the deed. Last season''s dust storms ruined the crop, but the tax collectors still came demanding full payment. They sent their eldest daughter to work in a noble''s household to settle the debt, and pray she is treated well.', ''),
        ('United Cities', 'Born to a family of street sweepers, this samurai earned their katana through sheer brutality in the recruitment trials. They patrol the merchant quarter with cold efficiency, collecting protection payments and breaking up disputes with swift violence. The uniform gives them authority they never had growing up, and they will kill to keep it.', ''),
        ('United Cities', 'This middling trader survives by knowing which officials to bribe and which caravans carry the most profitable contraband. They lost two mules to Hiver bandits last month and still owe the Trader''s Guild for the replacement beasts. In the United Cities, profit is the only measure of a person''s worth, and their ledger is running red.', ''),
        ('United Cities', 'After twenty years hauling stone in a noble''s quarry, this freed slave bought their release with a cache of copper they discovered in a collapsed tunnel. They now run a modest tea stall near the city gates, serving travelers and keeping their head down. The brand on their forearm still draws sneers from samurai, but the tea is good and the prices are fair.', ''),
        ('United Cities', 'This tax assessor travels the outer settlements with a squad of hired swords, cataloging every farm and workshop for the imperial ledgers. They accept gifts from those who can pay and mark down inflated values for those who cannot. The Empress demands her share, and this assessor always takes a little extra for the inconvenience of travel.', ''),
        ('United Cities', 'Working the docks since childhood, this laborer earns just enough rice to feed their family while the merchant houses grow fat on the goods they load. They lost two fingers to a cargo net last year and received no compensation from the overseer. The worker barracks are full of people with similar stories, and the samurai make sure nobody organizes to change things.', ''),
        ('United Cities', 'This cook runs a gutter stall in the lower district, serving bowls of gristle and root vegetables to laborers who cannot afford better. They purchase meat of questionable origin from hunters who venture beyond the walls, asking no questions about where it came from. A portion of their earnings goes to the local boss for protection, leaving barely enough to survive.', ''),
        ('United Cities', 'The second son of a minor samurai family, this warrior serves as a bodyguard for a wealthy merchant rather than inherit nothing. Their sword arm is steady and their loyalty is for sale to whoever pays the monthly retainer. They dream of earning a name through glorious combat, but spend most days watching their employer count coins.', ''),
        ('United Heroes League', 'Grew up watching Starving Bandits tear through the farming villages and decided the only way to stop becoming prey was to become the predator. Joined the League for the armor and the numbers, telling herself the extortion was just a tax for protection. She keeps her head down and follows orders, trying not to think about the peasants who can''t afford the League''s rates.', ''),
        ('United Heroes League', 'A former slave in the Holy Mines who escaped with nothing but a stolen sword and a back covered in lash scars. The League found him half-dead in the borderlands and offered him a place in exchange for his blade. He fights with a fury born of years of helplessness, though the League''s own brand of cruelty sometimes makes him question which side of the cage he stands on.', ''),
        ('United Heroes League', 'Left the Shek Kingdom after his master deemed him too weak for the blood duels and stripped him of his warrior name. Wandered south until the League picked him up, hungry and desperate for any clan that would have him. He clings to the League''s rhetoric of strength and justice like a drowning man clings to driftwood, even when the actions don''t match the words.', ''),
        ('United Heroes League', 'Born in Heng and has never known a life outside the Swamp''s rot and reeking bogs. Started running protection for League enforcers as a teenager, shaking down the same market stalls she once begged beside. She tells herself she earned this life through grit and that the weak simply didn''t fight hard enough.', ''),
        ('United Heroes League', 'A deserter from a United Cities patrol who watched his squad burn a village for unpaid taxes and couldn''t stomach the hypocrisy anymore. The League offered a simpler code where the strong take what they want without dressing it up in imperial ceremony. He finds their honesty refreshing, even if their fists are just as bloody.', ''),
        ('United Heroes League', 'Lost his family to a Beak Thing attack on the southern trails and arrived in Heng with nothing but a need to never feel helpless again. The League promised strength through brotherhood and he believed every word. Now he stands watch over toll roads, collecting fees from travelers who remind him of the man he used to be.', ''),
        ('United Heroes League', 'Once a promising student at the Tech Hunters'' library in Black Scratch until a Hiver raid left her with shattered hands that never healed right. The League didn''t care about her grip strength when she could still intimidate and scheme. She handles logistics and extortion negotiations, using her sharp mind to squeeze every last coin from the Swamp''s struggling traders.', ''),
        ('United Heroes League', 'Fled the Reavers after a mutiny gone wrong, bleeding from a gut wound he barely survived. The League found him washed up on the western shores and patched him up enough to swing a club again. He fights with a death wish he masks as bravery, always volunteering for the most dangerous enforcement runs.', ''),
        ('United Heroes League', 'A Swamp Ninja dropout who couldn''t master the discipline and was cast out before earning her blades. The League didn''t ask for elegance, only willingness to swing hard and swing first. She wears her rejection like a brand and takes out her humiliation on every merchant and drifter unlucky enough to cross the League''s path.', ''),
        ('United Heroes League', 'Grew up an orphan scavenging the ruins of the Old Empire, dreaming of the heroes from the crumbling frescoes on fallen walls. The League''s grandiose name drew him in like a moth to flame, though the reality of shakedowns and turf wars quickly crushed his childish fantasies. He stays because the alternative is starving alone in some forgotten ruin, and at least the armor is real.', ''),
        ('United Heroes League', 'Born into bondage in the United Cities, this one spent years laboring in the dust before a League raid shattered the chain-gang. Watching those fighters cut down the overseers gave purpose that servitude never could. Now the blade feels natural, and the cause feels true.', ''),
        ('United Heroes League', 'Disillusionment came slowly during decades of service to the Shek Kingdom, each campaign revealing the empire''s indifference toward its own. The final break happened after a village was sacked for failing tribute, and the long march away led straight to a League outpost. Old instincts for war remain, but the reason for fighting has changed entirely.', ''),
        ('United Heroes League', 'Raised within the Holy Nation''s rigid doctrines, doubt crept in when prayers went unanswered during a famine that claimed an entire settlement. The exodus south was dangerous and lonely until a League patrol found a starving wanderer on the border wastes. Faith in the flame died, replaced by faith in people willing to act instead of pray.', ''),
        ('United Heroes League', 'Years of drifting between border towns taught that most folk suffer quietly while warlords and slavers grow fat on their labor. The League offered something rare in this broken world: a community that fights back without demanding submission in return. Still learning to trust others after so long alone, but the barracks feel more like home than anywhere has.', ''),
        ('United Heroes League', 'A cannibal raid left this survivor with scars across the back and a hatred that demanded more than passive survival could provide. A League recruiter found a bitter soul nursing revenge in a border bar and offered a better outlet for that rage. The hunger for justice replaced the hunger for vengeance, mostly.', ''),
        ('United Heroes League', 'The trading caravan was destroyed by Beak Things, leaving nothing but debt and a burning need to never be helpless again. The League accepted a former merchant who could barely hold a sword, and months of brutal training forged something harder than commerce ever did. The books are balanced differently now.', ''),
        ('United Heroes League', 'Mercenary work paid well but left a hollow feeling that no amount of sake could fill, especially after watching employers butcher innocents for profit. Desertion meant a price on the head, so the League became both sanctuary and penance. The skills remain lethal, but now they serve something worth fighting for.', ''),
        ('United Heroes League', 'Servitude under a noble house ended when the master decided entertainment meant pitting servants against each other in cage fights for sport. The escape was bloody, and the flight south nearly ended in the desert before a League scout intervened. Now the fighting has meaning beyond mere survival.', ''),
        ('United Heroes League', 'The Way of the Fist demanded peace, but the world kept bringing war until meditation became impossible. Leaving the monks was a quiet departure, and finding the League felt like discovering others who understood that sometimes peace must be defended with violence. The old teachings aren''t abandoned, just adapted to harsher truths.', ''),
        ('United Heroes League', 'The farm was seized by United Cities tax collectors, and the family scattered across the wastes in different directions. The League offered a new kind of family bound by shared struggle rather than blood. The soil under the fingernails has been replaced by rust and grit, but the work ethic remains.', ''),
        ('United Heroes League', 'Scrap diving along the border kept the belly full but the spirit empty until a League patrol helped defend a scavenger camp from slavers without asking payment. The gesture seemed impossible in a world of debts and bargains, but it was real enough to follow. Now the scavenging serves a greater purpose than just survival.', ''),
        ('United Heroes League', 'Theft was survival in the border towns, and the pickpocket''s hands were quick until they reached into the wrong pocket belonging to a League operative who saw potential instead of punishment. The choice was simple: keep stealing and eventually lose a hand, or turn those skills toward something that mattered. The transition wasn''t easy, but the bed is warmer and the food is earned.', ''),
        ('United Heroes League', 'Chains left scars on the wrists and a deeper mark on the soul after years in a Holy Nation labor camp for the crime of being born wrong. The League raid that broke those chains didn''t just free a body, it gave purpose to a life that had known nothing but suffering. Every slaver put down is a prayer answered in the only language they understand.', ''),
        ('United Heroes League', 'Service as a Samurai demanded obedience, but the order to round up peasants for the slave markets finally broke the discipline that held everything together. Stripping off the armor was easier than expected, but living with the memories of what was done in that uniform proved harder. The League offered redemption through action, and the blade now serves the powerless instead of the corrupt.', ''),
        ('United Heroes League', 'The Holy Nation taught that certain lives were worthless, and living as one of those worthless lives bred a fury that no amount of prayer could extinguish. Escaping the purge patrols meant learning to fight dirty and survive on hatred alone. The League showed that the fury could be forged into something better than mere vengeance.', ''),
        ('United Heroes League', 'Engineering skill kept the slaver camps running, and each repaired shackle and reinforced cage was another life condemned. The guilt built slowly, then all at once, until sabotage seemed the only way to sleep again. The League needed someone who understood enemy infrastructure, and the expertise that once built cages now plans how to break them open.', ''),
        ('United Heroes League', 'The Beak Thing nest took everything in one terrible afternoon, leaving nothing but blood-soaked sand and a rage that had nowhere to go. Wandering the wilderness with nothing to lose eventually led to a League outpost, where survival skills were recognized as assets rather than threats. Protecting others from loss became the only reason to keep drawing breath.', ''),
        ('United Heroes League', 'Trading along the United Cities routes meant witnessing the suffering behind the wealth, and eventually the profits couldn''t silence the conscience anymore. Walking away from the caravan meant walking away from comfort, but the League proved that living poor didn''t mean living without purpose. The merchant''s eye for logistics now keeps supply lines running to those who need it most.', ''),
        ('United Heroes League', 'Shek culture demanded glory in battle, but the bloodlust of raids against farmers and weaklings felt like dishonor wearing honor''s mask. Walking away from the clan meant becoming nothing, but becoming nothing was preferable to becoming a monster. The League offered a warrior''s purpose worth the name, defending those who cannot defend themselves.', ''),
        ('United Heroes League', 'Centuries of walking the world left a skeleton weary of watching the same cruelties repeat across every era. Hiding among flesh-creatures was survival, but the League was the first place where the disguise didn''t feel necessary. The ancient knowledge of war and survival finally serves something other than just self-preservation.', ''),
        ('Western Hive', 'Born to the harvest, this worker spent cycles gathering greenfruit and hemp for the Queen''s stores. The rhythm of the hive sings clear in its blood, and the outside world holds nothing but confusion and danger.', ''),
        ('Western Hive', 'Stationed at the hive''s perimeter, this soldier learned to spot the dust clouds of approaching bandits long before they reached the walls. Combat is simple when the Queen''s voice drowns out fear.', ''),
        ('Western Hive', 'A trading liaison by necessity, this drone learned enough of human speech to barter hive goods for iron and medkits. The strange customs of outsiders unsettle it, but the Queen''s will demands engagement.', ''),
        ('Western Hive', 'During a terrible storm, this worker lost the Queen''s signal for three days and wandered the wilderness in a haze of purposeless terror. When the connection returned, it wept with relief and has never strayed far since.', ''),
        ('Western Hive', 'Trained to hunt Beak Things that threaten the outer settlements, this soldier carries the scars of razor-sharp beaks. The nest burns, the Queen wills it, and the hive endures.', ''),
        ('Western Hive', 'This worker tends the great fungus farms deep within the hive, knowing each crop by scent alone. It has never seen the sun and feels no desire to change that fact.', ''),
        ('Western Hive', 'Captured briefly by Holy Nation zealots, this drone learned the meaning of hatred before escaping back to the desert. The Queen''s voice is salvation, and the paladins are nothing but noise.', ''),
        ('Western Hive', 'Tasked with repairing the skeletal walls of the hive, this worker developed an uncanny skill with scrap metal and wire. The structure must hold, for without walls there is only the chaos of the wilds.', ''),
        ('Western Hive', 'A veteran of skirmishes against the Southern Hive, this soldier knows the horror of fighting its own kind. The rogue Queen''s brood are no longer true hive, and that truth makes killing them bearable.', ''),
        ('Western Hive', 'This worker once found a dying stranger outside the gates and brought water against all protocol. The Queen''s silence on the matter was judgment enough, and it has not disobeyed since.', ''),
        ('Western Hive', 'Born in the deep chambers near the Queen''s sanctum, this drone spent its early cycles harvesting greenfruit along the riverbanks. The Queen''s voice was always strong and clear, guiding every movement until a bonedog attack severed the scent-trail home. It now wanders the fringes of hive territory, straining to hear the collective hum that once defined its existence.', ''),
        ('Western Hive', 'Assigned to border patrol after molting into a soldier caste, this hive member defended the western approaches against Holy Nation raiders for three seasons. A blow to the head from a paladin''s club left the Queen''s song faint and crackling like a broken radio. It still attacks intruders on instinct, but sometimes pauses mid-strike, confused and searching for orders that never come.', ''),
        ('Western Hive', 'This worker spent its whole life maintaining the great walkways between hive towers, weaving cactus fibers into rope bridges with mechanical precision. When a dust storm collapsed three sections and buried its work crew, the Queen''s grief pulsed through the network for days. It rebuilds now with quiet urgency, driven by the echo of that loss and the need to make the structures whole again.', ''),
        ('Western Hive', 'Tasked with foraging far beyond the green zones, this drone learned to navigate the deadlands where the hive-signal weakens to a whisper. It traded small crafts with passing caravans for salt and iron, always returning before the Queen''s silence became unbearable. The outside world fills it with a strange buzzing that is not the hive, a sensation both terrifying and fascinating.', ''),
        ('Western Hive', 'Hatched during a season of famine, this small worker learned to stretch meager rations of raw meat and cactus among dozens of hungry siblings. It grew cunning and quick, often sneaking extra portions back to the nursery chambers where the grubs writhed in their pits. The Queen''s will commands sharing, but survival taught it that the hive does not feed those who wait politely.', ''),
        ('Western Hive', 'Elevated to guard the Prince''s resting chamber, this soldier witnessed the sacred rituals of royal succession from behind a woven reed screen. When a rival hive faction attempted to steal a prince, it fought with a fury that surprised even itself, losing two limbs in the defense. The prosthetics ache in the cold, but the Queen''s approving hum still warms the empty spaces where flesh used to be.', ''),
        ('Western Hive', 'This drone tumbled from a cliff as a grub and survived by eating bugs in a crevice for weeks before a patrol found it. The fall damaged something inside, and the Queen''s voice has always arrived delayed and distorted, like hearing instructions through water. Other hive members treat it with wary patience, pushing it toward simple tasks that require no coordination with the collective.', ''),
        ('Western Hive', 'Once part of a trading envoy to the Shek Kingdom, this worker learned enough of the outsider tongues to negotiate basic exchanges of hive silk for weapons. The Shek confused it with their individual names and personal grudges, concepts that made the hive-mind itch with dissonance. It returned home grateful for the unity of purpose, yet sometimes stares at the horizon wondering what name it might choose for itself.', ''),
        ('Western Hive', 'Assigned to the deep excavation teams, this drone dug storage pits and escape tunnels beneath the hive mounds for cycles without seeing sunlight. A cave-in trapped it alone in the dark for six days, surrounded by the crushed bodies of its work team, feeling the Queen''s voice grow distant and then silent. Rescuers pulled it free, but it refuses to go underground now, clinging to the surface with a desperation the other drones cannot understand.', ''),
        ('Western Hive', 'Hatched with a malformed wing-joint that prevented full service as a soldier, this hive member was relegated to tending the cactus gardens. It learned to read the soil and sky with surprising acuity, predicting droughts that the collective instinct missed. The Queen has begun consulting it through intermediaries, a disturbing arrangement that makes the other drones click their mandibles in unease.', ''),
        ('Western Hive', 'This patrol scout encountered a Skimmer brood nest while mapping the northern canyons and barely escaped with its life. The venom left permanent tremors in its limbs and a persistent hallucination of the Queen speaking in colors instead of sounds. It still reports for duty each cycle, determined to serve despite the flickering unreality that overlays every command.', ''),
        ('Western Hive', 'Stolen by slavers as a grub and sold to a United Cities baron as a curiosity, this drone spent years in a gilded cage eating fine meals it could not digest. Freedom came when anti-slaver rebels sacked the estate, and it fled south following the faintest thread of hive-signal back toward the homeland. The Queen''s voice grows stronger each day, but the memory of soft beds and kind words from its captors lingers like a disease it cannot shake.', ''),
        ('Western Hive', 'During a massive dust storm, this drone lost contact with its patrol unit and wandered the desert for weeks following a false signal echoing off canyon walls. It survived by eating roots and drinking from puddles in rock crevices, experiences that should have been impossible without the hive''s guidance. When it finally returned, the Queen''s voice felt thinner, and the drone sometimes wanders to the edge of hive territory as if listening for that phantom echo.', ''),
        ('Western Hive', 'This soldier was part of a defensive formation when a Beak Thing pack breached the perimeter and devoured three drones before help arrived. The creature''s beak sheared through its carapace and left a permanent notch in its thorax that whistles when the wind blows. It attacks any large creature on sight now, a hair-trigger response that makes it useless for trade escort but valuable as a perimeter guard.', ''),
        ('Western Hive', 'Assigned to maintain the border markers near Holy Nation territory, this drone endured seasons of taunts and thrown stones from passing paladin patrols. The humans called it soulless and spat on its work, behavior that made no sense to the collective understanding. It learned to work at night and avoid the green-cloaked patrols entirely, developing a stealth that the Queen has found useful for reconnaissance.', ''),
        ('Western Hive', 'While foraging in a damp canyon, this worker consumed a patch of bright fungus that grew where an old skeleton lay buried in the sand. The mushroom taste lingered for days, and ever since the Queen''s commands arrive with a visual static, like insects crawling across the inside of its eyes. The other drones avoid it, sensing something wrong in the way it twitches during the quiet hours.', ''),
        ('Western Hive', 'A Blood Spider ambush killed every member of this drone''s forage team while they harvested greenfruit from a swampy crater. It played dead beneath the corpses for hours as the spiders fed, feeling the Queen''s grief pulse through the severed connections of its dead siblings. The experience left it with an inability to remain still in enclosed spaces and a hatred for damp ground that borders on paralysis.', ''),
        ('Western Hive', 'Bandits raided a silk caravan this worker was assigned to, killing the escort soldiers and taking the cargo while it cowered beneath a cart. The Queen''s voice demanded it fight, but its limbs locked in terror and it watched the massacre without moving. It volunteered for soldier reassignment afterward, driven by a shame that the collective cannot absolve because the hive does not understand the concept of personal failure.', ''),
        ('Western Hive', 'Hatched during the Great Drought when the cactus fields withered and the Queen''s voice grew weak from hunger, this drone has always been smaller than its siblings. It learned to eat anything, bark and leather and the flesh of dead hivers, developing a digestive resilience that makes it useful for testing questionable food sources. The Queen sometimes sends it strange flavors through the link, curious about what it can survive.', ''),
        ('Western Hive', 'A Holy Nation patrol captured this scout and held it for three days while an inquisitor debated whether it possessed a soul worth saving through flame. The other drones mounted a rescue before the question was settled, but the drone felt something crack inside during those hours of staring at the pyre being built. It understands fear now in a way the hive-mind cannot process, and it freezes whenever it sees the orange glow of holy fires.', ''),
        ('White Eyebrow Clan', 'Sold to slavers as a child for stealing bread, they spent years breaking rocks in the Holy Mines before escaping half-starved into the wilderness. Stumbling upon the clan''s village, they were taken in and given a new purpose. Now they train with fierce dedication, vowing never to be weak enough to be caged again.', ''),
        ('White Eyebrow Clan', 'Born within the clan''s walls, they learned to throw a punch before they could read. Their parents both served as village defenders, and they intend to honor that legacy the same way. The outside world holds little interest when there are techniques to master and traditions to uphold.', ''),
        ('White Eyebrow Clan', 'A decade of selling their sword to the highest bidder left them hollow and haunted by the faces of those they killed for coin. The clan''s philosophy offered what mead and gambling never could, a reason to fight that didn''t end with payment. They still struggle with old habits, but the training grounds offer clarity the mercenary camps never provided.', ''),
        ('White Eyebrow Clan', 'Three decades of training have whitened their brow and hardened their fists into weapons that need no steel. They remember when the clan was fewer than twenty souls surviving on roots and desperation. Now they teach the young ones, ensuring the techniques outlast their aging bones.', ''),
        ('White Eyebrow Clan', 'A Shek raid took their family and their arm below the elbow, leaving them with nothing but hatred and a crude iron hook. The clan taught them that survival isn''t about what you''ve lost but how you adapt what remains. Their hook-hand strikes are now feared throughout the border lands.', ''),
        ('White Eyebrow Clan', 'They wandered the wastes for years after their farming village was swallowed by a dust storm, surviving on lizards and rainwater. A clan patrol found them half-dead outside the village walls and dragged them back to the infirmary. In exchange for saving their life, they owe the clan everything, a debt they pay daily in sweat and loyalty.', ''),
        ('White Eyebrow Clan', 'Exiled from the Shinobi Thieves for refusing to kill a merchant''s child, they had nowhere to go until the clan offered shelter without judgment. They still move like a thief in the night, but now those skills serve reconnaissance rather than assassination. Old contacts sometimes pass through, and they pretend not to recognize them.', ''),
        ('White Eyebrow Clan', 'Their legs were shattered by a Beak Thing in the Swamp, and the clan''s healers could only save one. They refused to lie down and die, learning to fight from a seated position using a polearm for balance. The other members never speak of their disability, only their kill count.', ''),
        ('White Eyebrow Clan', 'Drafted into the United Cities military as a teenager, they deserted after being ordered to burn a peasant village for unpaid taxes. The clan asked no questions about their past, only whether they could fight and were willing to learn. They keep their head down during trading runs, terrified that Imperial bounty hunters still search for deserters.', ''),
        ('White Eyebrow Clan', 'A failed merchant crushed by debt to the Traders Guild, they fled into the border regions with nothing but the clothes on their back. The clan doesn''t care about credit or coin, only whether you carry your weight on patrol. They handle supply negotiations now, using their commercial knowledge to get fair prices for the village''s meager exports.', ''),
        ('White Eyebrow Clan', 'Grew up scraping by in the Borderlands until a Clan patrol took in a starving fighter with nothing but a rusty blade. Years of raiding and bloodshed forged a loyal enforcer who asks no questions when the Clan demands tribute.', ''),
        ('White Eyebrow Clan', 'Left the Shek Kingdom after growing tired of endless posturing and empty traditions that dishonored true warriors. The White Eyebrow Clan offered a simpler path where strength still meant survival and loyalty was repaid in steel.', ''),
        ('White Eyebrow Clan', 'Born into the Clan and raised on raiding trails across the Hook, learning to fight before learning to read. Carries old scars from skirmishes with Holy Nation patrols and expects to die with new ones.', ''),
        ('White Eyebrow Clan', 'A former slave who earned freedom by killing an inattentive master and fleeing into the wastes. The Clan accepted a proven killer without asking about the past, and now that killer defends Clan territory with fierce gratitude.', ''),
        ('White Eyebrow Clan', 'Once ran a small trading post until tax collectors burned it down over a missed payment. Swore off peaceful living and joined the first warband that would take a shopkeeper with more rage than skill.', ''),
        ('White Eyebrow Clan', 'Trained under a veteran Clan fighter who taught the ways of the sword in exchange for labor and loyalty. Inherited the old warrior''s grudges along with the techniques, and now hunts the same enemies across the Canyons.', ''),
        ('White Eyebrow Clan', 'A desert wanderer who stumbled into Clan territory half-dead from thirst and was put to work earning the water spent on survival. Proved useful enough to keep around, though trust remains as scarce as rain.', ''),
        ('White Eyebrow Clan', 'Lost everything to Skinners in the Stenn Desert and swore to never be weak again. The Clan provided weapons and targets in equal measure, and the debt of vengeance keeps this warrior in the ranks.', ''),
        ('White Eyebrow Clan', 'Served as a caravan guard across the Holy Nation border until the pay stopped covering the risk. Defected to the Clan for a share of actual loot rather than meager wages that barely bought food.', ''),
        ('White Eyebrow Clan', 'Known among the Clan for keeping weapons sharp and armor patched, valued more for maintenance skills than combat prowess. Still, when raiding parties depart, this craftsperson marches along to haul spoils and patch wounds.', ''),
        ('White Eyebrow Clan', 'Escaped from Reaver slavers with nothing but a stolen knife and a burning hatred for every slaver on the coast. The Clan offered brothers in arms who share that hatred and opportunities to act on it regularly.', ''),
        ('White Eyebrow Clan', 'Born to a different Clan that was absorbed through blood and marriage years ago. Struggles with divided loyalties but fights just as fiercely, knowing the White Eyebrow provides the only family left alive.', ''),
        ('White Eyebrow Clan', 'Grew up a Holy Nation peasant, always hungry and beaten for minor transgressions against the Okranite faith. Fled north with nothing but stolen rags and found the Clan willing to feed anyone willing to bleed for the meal. Now fights with the quiet fury of someone who knows exactly what the alternative looks like.', ''),
        ('White Eyebrow Clan', 'Spent years selling a sword to whatever corrupt captain paid on time until the work felt emptier than the desert. The Clan may be brutal, but at least they are honest about what they take and why. Earned a place by proving that loyalty matters more than coin when the blood starts flowing.', ''),
        ('White Eyebrow Clan', 'Worked a barren farm in the Border Zone until tax collectors took the last harvest and the will to keep struggling. Wandered until the Clan offered a simple trade: fight and eat, or starve alone. Chose the former and discovered a talent for violence that peaceful life never uncovered.', ''),
        ('White Eyebrow Clan', 'Broke free from a United Cities slave camp during a dust storm that killed half the guards. Stumbled into Clan territory half-mad from thirst and was put to work paying off the water debt. Never left, because nowhere else would take someone with brand scars and nothing to their name.', ''),
        ('White Eyebrow Clan', 'A former Hired Sword whose company was slaughtered by Beak Things in the Obeast region. The only survivor crawled for days before Clan scouts found the body and dragged it back to camp. Now serves as a tracker, reading the wasteland the way scholars read books.', ''),
        ('White Eyebrow Clan', 'Never knew any family but the Clan, raised on raiding routes and taught to fight before learning to read. Considers the other members kin in every way that matters, bound by shared blood and shared enemies. Would die for the White Eyebrow without hesitation, because there is nothing else worth dying for.', ''),
        ('White Eyebrow Clan', 'Once ran a modest trading post until rivals burned it down and killed a partner who trusted the wrong people. The Clan offered something the law never could, a chance to take back what was lost. Has served ever since, finding satisfaction in the simplicity of raid and retribution.', ''),
        ('White Eyebrow Clan', 'Lost a leg to a Skimmer attack and nearly died from the infection that followed. The Clan kept them alive when common sense said to leave the cripple behind, and now serves as a camp guardian and fence for stolen goods. Repays that debt every day by making sure nothing enters or leaves without notice.', ''),
        ('Yabuta Outlaws', 'Grew up scraping by in the borderlands where the law never reached. Learned to fight dirty and steal quieter just to see another sunrise. Joined the Yabuta when a bad harvest left nothing else to eat. Now takes what''s needed without a second thought.', ''),
        ('Yabuta Outlaws', 'Used to run supplies for a trading company until a samurai patrol confiscated everything over a missing permit. Debt collectors took the legs soon after. The Yabuta took in a bitter cripple and gave them a crossbow. Pride is long gone, but the bolts still fly straight.', ''),
        ('Yabuta Outlaws', 'Born into a nomadic family that wandered the dunes until slavers picked them off one by one. Escaped a cage during a sandstorm and stumbled half-dead into a Yabuta camp. Carries deep hatred for anyone who trades in flesh. Trusts the desert more than any person.', ''),
        ('Yabuta Outlaws', 'Spent years as an enforcer for a city guild before a political shake-up made them the scapegoat. Fled into the wastelands with nothing but a rusted blade and a price on their head. The Yabuta don''t ask about the past. Killing for them feels no different than killing for the guild.', ''),
        ('Yabuta Outlaws', 'A failed prospector who spent every cat on surveys that turned up dry stone. Started claim-jumping out of desperation and found a talent for ambushing rival miners. Eventually the legitimate crews came hunting, forcing a permanent move to outlawry. Still dreams of a big strike while picking over corpses.', ''),
        ('Yabuta Outlaws', 'Left a Holy Nation settlement after the inquisitors started asking questions about missing neighbors. The desert swallowed the guilt and the Yabuta gave a new identity. Prays to Okran less these days, mostly when a wound goes septic. Remembers enough scripture to mock it properly around the campfire.', ''),
        ('Yabuta Outlaws', 'Was a fisherman on the coast until the cannibals came and devoured the whole village. Wandered inland half-mad with grief until a Yabuta patrol found them half-starved. Channels the rage into every raid, fighting like someone who doesn''t care if they live. Sleeps with a weapon always within reach.', ''),
        ('Yabuta Outlaws', 'Sold stolen goods in the black markets for years before a deal went sour and a Shek warrior took an arm. The Yabuta provided a cheap prosthetic and steady work smuggling weapons. The old contacts are still useful for moving stolen gear. Business is business, even out here.', ''),
        ('Yabuta Outlaws', 'Grew up an orphan in the slums of a border town, stealing meals from market stalls. A Yabuta recruiter spotted potential in the quick hands and sharper instincts. Never knew any other life worth living. The gang is the only family that ever mattered.', ''),
        ('Yabuta Outlaws', 'Once served as a low-ranking samurai in the United Cities until a noble decided to make an example over a minor slight. Stripped of rank and property, fled west before the execution could be arranged. The Yabuta respect combat skill even without a title. Still maintains a twisted code of honor during raids.', ''),
        ('Yabuta Outlaws', 'Grew up in a starving village where stealing food was the only way to survive. Eventually got caught and fled into the wastelands before the city guards could take a hand. Now fights with the Outlaws just to keep eating.', ''),
        ('Yabuta Outlaws', 'Formerly a farmhand working sunup to sundown for measly scraps while the landowner grew fat. Snapped one day after watching another harvest get seized for debts and left with nothing but a rusty iron stick. Joined the Outlaws because they were the only ones who would take in someone with nothing left to lose.', ''),
        ('Yabuta Outlaws', 'Escaped from a slave camp in the Hook with a branding scar still visible on the neck. Spent years moving between settlements doing odd jobs, but nobody trusts a runaway. Found kinship among the Yabuta Outlaws, who care more about loyalty than past chains.', ''),
        ('Yabuta Outlaws', 'Was a traveling trader until a Holy Nation patrol confiscated the entire cart for some imagined infraction. Having lost a life''s investment in a single afternoon, the idea of honest commerce became a sick joke. Took up raiding with the Outlaws and found the pay far steadier than any legitimate road.', ''),
        ('Yabuta Outlaws', 'Born to an Outlaw mother who taught how to pick locks before learning how to read properly. Never knew any other life than moving between hideouts and ambushing caravans on the dust roads. The Yabuta hills feel more like home than any city ever could.', ''),
        ('Yabuta Outlaws', 'Served as a low-ranking samurai retainer until the master fell from favor and the entire household was dissolved. Without a clan, survival in the cities became impossible on meager savings. Drifted into outlaw territory where sword skills still command respect and a full bowl of rice.', ''),
        ('Yabuta Outlaws', 'A former miner from the border regions who developed black lung and could no longer work the shafts. The mining company cast aside the sick worker without a single coin of compensation. Took up with the Outlaws as an ambush planner, using knowledge of terrain and supply lines to hit caravans.', ''),
        ('Yabuta Outlaws', 'Lost a sibling to a Shek raiding party while city guards stood by and did absolutely nothing. Grew to despise every faction that claims to protect people but only serves themselves. The Yabuta Outlaws may be criminals, but at least they are honest about what they take.', ''),
        ('Yabuta Outlaws', 'Worked as a fisher along the coast until pollution from United Cities workshops killed off the local catch. Starvation crept closer each week until stealing from wealthy merchants seemed like the only rational choice. Now operates as a scout for the Outlaws, using old tracking skills to locate vulnerable targets.', ''),
        ('Yabuta Outlaws', 'A disfigured survivor of a bonedog attack that left half the face a mess of scar tissue. Civilization had no place for someone so hideous, with children screaming at the sight. The Outlaws judged on skill with a blade rather than looks, and that acceptance means everything.', ''),
        ('Yabuta Outlaws', 'Once ran a small teahouse in a border town until tax collectors demanded more than the profits could cover. The teahouse burned under mysterious circumstances and the former owner vanished into the hills overnight. Now serves the Yabuta Outlaws as a cook and occasional fence for stolen goods.', ''),
        ('Yabuta Outlaws', 'Trained as a mechanic in the Machinist workshops but was blacklisted for stealing parts to sell on the side. With no legitimate workshop willing to hire a known thief, the only option was the outlaw life. Maintains the ragtag weapons and armor of the Yabuta crew in exchange for a cut of every haul.', ''),
        ('Yabuta Outlaws', 'Born into a United Cities slave camp and spent fifteen years hauling ore for masters who provided nothing but scars. Escaped during a sandstorm that buried the guards in their sleep tents. The Yabuta Outlaws were the first group that never tried to put chains on anyone.', ''),
        ('Yabuta Outlaws', 'Served as a low-ranking samurai retainer until a commander appropriated credit for a successful campaign and left the true architect with nothing. Honor demanded retribution but the commander had fifty armed loyalists. The Outlaws offered blades and bodies in exchange for loyalty, and that trade was fair enough.', ''),
        ('Yabuta Outlaws', 'Grew up in a farming village that the Holy Nation purged for suspected heresy, burning fields and kin alike. Wandered the wastelands for years with nothing but a rusted sickle and growing hatred for zealots. Found purpose with the Outlaws, who share a healthy disdain for any authority claiming divine right.', ''),
        ('Yabuta Outlaws', 'A former caravan guard who watched merchants abandon wounded employees after a skimmer attack to save cargo weight. Bled for three days before scavengers found the body and the merchants never even filed a report. Now the Outlaws get a share of every caravan that passes through their territory.', ''),
        ('Yabuta Outlaws', 'Raised by a scavenger who taught which ruins held salvage and which held ancient death traps. The parent died from a gas pocket in a forgotten bunker, leaving nothing but maps and debts. The Outlaws needed someone who could navigate collapsed structures and read pre-fall architecture.', ''),
        ('Yabuta Outlaws', 'Once a street performer in a major city until a noble decided the act was insulting and broke both hands as punishment. The bones healed crooked and the coins stopped coming, replaced by hunger and humiliation. The Outlaws do not care about crooked hands, only that they can still hold a blade.', ''),
        ('Yabuta Outlaws', 'A Hiver worker separated from its hive during a migration and left to wander the wastes alone without purpose. The Queen''s voice fell silent and the world became an incomprehensible nightmare of choices. The Outlaws gave structure and crude community, which is enough to quiet the silence.', ''),
        ('Yabuta Outlaws', 'Spent years as a debt slave to the Traders Guild after a failed business venture left accounts in ruins. Worked off the debt only to discover the interest had tripled the original sum during repayment. Broke the ledger over the debt collector''s head and ran for the borderlands where the Guild has no reach.', '')
), normalized AS (
    SELECT DISTINCT TRIM(faction) AS faction, TRIM(description) AS description, LOWER(TRIM(gender)) AS gender
    FROM source_rows
    WHERE TRIM(faction) <> '' AND TRIM(description) <> ''
)
INSERT INTO bio_random (type, description, name, race, gender, faction)
SELECT 'backstory', n.description, '', '', n.gender, n.faction
FROM normalized n
ON CONFLICT (type, description, name) DO NOTHING;
COMMIT;
